(67, 6, 'assistant', 'Shagor Assistant', 'I\'m active on GitHub, Facebook, LinkedIn, Twitter, Stack Overflow, and LeetCode. You can grab the direct links from my portfolio site, or just email me at smshagor.ru@gmail.com if that\'s easier.', '2026-05-10 13:22:17.952', '', ''),
