INSERT INTO `Education` (`id`, `title`, `duration`, `institution`, `sortOrder`, `createdAt`, `updatedAt`, `department`, `achievement`) VALUES
(1, 'Bachelor of Science', '2023 - Present', 'Voronezh State University of Foriestry and Technology, Russia', 1, '2026-04-26 15:16:05.519', '2026-04-26 15:16:05.519', 'Software Engineering', '<p><strong>Research Focus: UAV Systems &amp; Cybersecurity</strong></p><ul><li data-list-item-id=\"ec294ad921fb7a82561ef94670259a938\">Conducting research on <strong>secure UAV (drone) systems</strong>, focusing on decentralized swarm coordination</li><li data-list-item-id=\"edda28f2addcf5806aae7006b800cb6f3\">Exploring <strong>cybersecurity threats in UAV networks</strong>, including spoofing, jamming, and unauthorized control</li><li data-list-item-id=\"e101acbddf1997f134c90583f03250707\">Designing <strong>secure communication protocols</strong> using encryption (AES, secure key exchange) for drone-to-drone interaction</li><li data-list-item-id=\"e91dc64aed5cf29564ae226e6a5a48e88\">Working on <strong>GPS-denied navigation techniques</strong>, combining sensor fusion and vision-based approaches</li><li data-list-item-id=\"e0ec2cde055d96d31c5947c2fd1b28b34\">Studying <strong>real-time data integrity and authentication mechanisms</strong> to prevent malicious command injection</li><li data-list-item-id=\"ee69094217fd0ad387f11684ca64f6713\">Developing concepts for <strong>fault-tolerant and resilient drone systems</strong> under adversarial conditions</li></ul>'),
(2, 'Diploma In Engineering', '2018 - 2020', 'Dhaka Politechnic Institute, Bangladesh', 2, '2026-04-26 15:16:05.519', '2026-04-26 15:16:05.519', 'Computer Technology', '<ul><li data-list-item-id=\"e60cca501e40f25ea0ddb2f5497e8f521\">Built a strong foundation in <strong>programming, data structures, and algorithms</strong></li><li data-list-item-id=\"e9a79419a5997669a9366f59ea8f90a6f\">Learned core concepts of <strong>database systems, networking, and software engineering</strong></li><li data-list-item-id=\"e6b677d83ab6c3c447743b1cee17d2ade\">Developed academic projects using <strong>C, C++, and basic web technologies</strong></li><li data-list-item-id=\"edf9e0c5f01511bfcf89b182be583c085\">Gained hands-on experience in <strong>problem-solving and logical thinking</strong></li><li data-list-item-id=\"e7c316293dcd95dc09cab13d4565958e0\">Worked on small-scale systems involving <strong>database design and application flow</strong></li><li data-list-item-id=\"ecf17a66b52776e5d8a22ea3fec89dc78\">Collaborated on team-based projects, improving <strong>communication and development workflow skills</strong></li></ul>');
