INSERT INTO `Experience` (`id`, `title`, `company`, `duration`, `sortOrder`, `createdAt`, `updatedAt`, `description`, `location`) VALUES
(1, 'Web Developer (Remote)', 'Explo-IT.', '2023 - 2025', 1, '2026-04-26 15:13:47.900', '2026-04-26 15:13:47.900', '<p>Worked across product delivery, backend features, and frontend improvements while collaborating closely with stakeholders and engineering teammates.</p><ul><li data-list-item-id=\"e667a914d085ca8d4a41873d506ba1304\">Designed and developed scalable web applications using Laravel (backend) and Next.js (frontend).</li><li data-list-item-id=\"ebbe4b55f9f3013f450228ed0b2c22ad0\">Built and integrated RESTful APIs for seamless data exchange between frontend and backend systems.&nbsp;</li><li data-list-item-id=\"eb4d7c284dd4b839aaaeb26aa7e34673a\">Implemented authentication, role-based access control, and secure payment gateways in Laravel.&nbsp;</li><li data-list-item-id=\"ec3fcd049fe07c9abfa67f52206225b97\">Optimised application performance via Eloquent query tuning, caching strategies, and database indexing.&nbsp;</li><li data-list-item-id=\"e474e2eead190dc8a3d67bf704c669cef\">Created responsive, SEO-friendly UIs with Next.js, Tailwind CSS, and modern JavaScript frameworks.&nbsp;</li><li data-list-item-id=\"e4365cafd900972fb6fe2387abb0332be\">Delivered real-time features (chat, notifications, live updates) using WebSockets / Pusher.&nbsp;</li><li data-list-item-id=\"e3714343932762eecbe216d2e62426f71\">Deployed and maintained applications on Linux servers (Nginx, Apache, Docker) with CI/CD pipelines.&nbsp;</li><li data-list-item-id=\"ee1c049f35b6c61abee805ec4de970a2a\">Integrated third-party services: payment gateways, social logins, and cloud storage.</li></ul>', 'Dhaka, Bangladesh'),
(2, 'Web Developer (Onsite)', 'DataSoft LTD.', '2021 - 2022', 2, '2026-04-26 15:13:47.900', '2026-04-26 15:13:47.900', '<p>Delivered freelance web projects end to end, including API work, UI implementation, deployment support, and client communication.</p><ul><li data-list-item-id=\"e3da98413e997af42e4dc6e2de3192c41\">Assisted in developing web applications using Laravel.&nbsp;</li><li data-list-item-id=\"e45817147b20bbe6025870067794ab88d\">Built and maintained APIs, database queries, and responsive UI components.&nbsp;</li><li data-list-item-id=\"e6754fc5b7fbd3a24e4c8a1c685e561ac\">Collaborated with senior developers on bug fixing, code reviews, and feature enhancements.&nbsp;</li><li data-list-item-id=\"e3f57d5b4e376946a5bf8a621de0d08b9\">Implemented frontend layouts with Tailwind CSS and supported database migrations in Laravel.&nbsp;</li><li data-list-item-id=\"e34a97bb5fda65f02913e483950b74651\">Wrote clear documentation and contributed to team knowledgesharing sessions.</li></ul>', 'Dhaka, Bangladesh'),
(3, 'Internship in Python', 'Global IT.', '2020-2020', 3, '2026-04-26 15:13:47.900', '2026-04-26 15:13:47.900', '<p>Built personal products and experiments to sharpen engineering judgment, explore new stacks, and stay consistent with hands-on practice.</p><ul><li data-list-item-id=\"e2983ebdc634c0b105d3eb1398dbada80\">Built and maintained web applications using <strong>Python and Django</strong>, focusing on scalable backend architecture</li><li data-list-item-id=\"eb8ae6cb1b05c188923aebf771e77bcda\">Designed and optimized <strong>PostgreSQL databases</strong>, including schema design, queries, and performance tuning</li><li data-list-item-id=\"e970e297a7a6912a0451d2b8d32025e04\">Worked on <strong>bug fixing, debugging, and performance optimization</strong> to improve system reliability</li><li data-list-item-id=\"ee1b6f73a5a7bb928f24be49cc78acecc\">Collaborated on real-world projects, following <strong>clean code practices, version control (Git), and deployment workflows</strong></li></ul>', 'Dhaka, Bangladesh');
INSERT INTO `Faq` (`id`, `question`, `answer`, `status`, `sortOrder`, `createdAt`, `updatedAt`) VALUES
(1, 'How quickly can a new project start?', '<p>Most projects can start within a few days after the scope, timeline, and priorities are aligned.</p><p>For larger builds, I usually begin with a short planning phase so delivery stays clean, realistic, and predictable from day one.</p>', 1, 1, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(2, 'Do you work on both frontend and backend?', '<p>Yes. I handle full-stack delivery across product UI, backend APIs, admin dashboards, database design, and deployment support.</p><p>This makes it easier to keep design, engineering, and product logic aligned throughout the project.</p>', 1, 2, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(3, 'Can you work on an existing product instead of building from scratch?', '<p>Absolutely. I can step into an existing codebase and help with new features, bug fixes, refactoring, performance improvements, or long-term maintenance.</p><p>The first step is usually a quick review of the current structure so changes can be made safely.</p>', 1, 3, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(4, 'What technologies do you usually work with?', '<p>I mainly work with React, Next.js, Node.js, Express, TypeScript, Prisma, MySQL, MongoDB, AWS, Docker, and related modern web tools.</p><p>I also adapt to project needs when a product already uses a different but reasonable stack.</p>', 1, 4, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(5, 'Do you build admin dashboards and management panels?', '<p>Yes. I regularly build admin dashboards for content management, operations, analytics, and workflow control.</p><ul><li>Role-based access</li><li>Structured forms and filters</li><li>Reporting and management tools</li></ul>', 1, 5, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(6, 'Can you build REST APIs for web or mobile apps?', '<p>Yes. I design and develop structured APIs that can support web platforms, mobile apps, internal tools, and third-party integrations.</p><p>The goal is to keep the API clean, secure, and easy to maintain as the product grows.</p>', 1, 6, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(7, 'Do you support mobile app backends?', '<p>Yes. If you already have an Android or iOS app, I can build or improve the backend layer that powers authentication, data flow, notifications, content, payments, and admin control.</p>', 1, 7, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(8, 'Can you design the database structure too?', '<p>Yes. Database design is part of my normal workflow.</p><p>I create schemas that support real product behavior, future expansion, clean relationships, and safer long-term maintenance.</p>', 1, 8, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(9, 'Do you fix bugs in existing websites or applications?', '<p>Yes. I can investigate and fix bugs in frontend, backend, database, deployment, or integration layers.</p><p>I prefer to understand the root cause first so the fix is stable instead of temporary.</p>', 1, 9, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(10, 'Can you improve the performance of a slow website?', '<p>Yes. Performance work can include frontend optimization, API cleanup, query tuning, image and asset handling, caching strategy, and deployment improvements.</p><p>The exact work depends on where the real bottleneck exists.</p>', 1, 10, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(11, 'Do you handle deployment and production launch?', '<p>Yes. I can help prepare, deploy, and stabilize a product for production.</p><ul><li>Server setup</li><li>Environment configuration</li><li>Domain and SSL setup</li><li>Launch support and post-launch fixes</li></ul>', 1, 11, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(12, 'Can you work with AWS and cloud infrastructure?', '<p>Yes. I have experience working with AWS services for application hosting, storage, email delivery, and related backend workflows.</p><p>I can also help with practical deployment architecture for products that need dependable hosting.</p>', 1, 12, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(13, 'Do you set up servers with Nginx, PM2, or Docker?', '<p>Yes. I can configure common production tools such as Nginx, PM2, Docker, and related runtime setup for Node-based applications.</p><p>This helps keep deployment cleaner and easier to manage.</p>', 1, 13, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(14, 'Can you redesign an outdated website or dashboard?', '<p>Yes. I can redesign the interface, improve structure, modernize the visual experience, and make the product easier to use without losing important business logic.</p>', 1, 14, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(15, 'Do you help with SEO-friendly development?', '<p>Yes. I can build pages with strong technical foundations for SEO, including clean structure, metadata, semantic markup, performance improvements, and search-friendly page rendering.</p><p>I focus on implementation quality rather than empty SEO promises.</p>', 1, 15, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(16, 'Will the website be mobile responsive?', '<p>Yes. Responsive behavior across mobile, tablet, and desktop is a standard part of delivery.</p><p>I aim for layouts that feel polished and usable across different screen sizes, not just technically resized.</p>', 1, 16, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(17, 'Can you build a CMS or content management workflow?', '<p>Yes. I can build admin-friendly content systems for pages, blogs, articles, services, projects, FAQs, and other editable sections.</p><p>The goal is to let your team update content without needing a developer for every small change.</p>', 1, 17, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(18, 'Do you build ecommerce or payment-enabled systems?', '<p>Yes. I can build product flows that include payments, subscriptions, order management, or service checkout depending on the project scope.</p><p>Payment gateway choice depends on the market, business model, and technical requirements.</p>', 1, 18, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(19, 'Can you build SaaS applications?', '<p>Yes. SaaS product development is a strong fit for my workflow.</p><ul><li>Authentication and roles</li><li>Subscription logic</li><li>Dashboards and settings</li><li>Scalable backend structure</li></ul>', 1, 19, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(20, 'Do you help with MVP development for startups?', '<p>Yes. I can help shape and build an MVP with the right balance between speed, clarity, and practical architecture.</p><p>The idea is to launch something useful quickly without creating avoidable technical problems later.</p>', 1, 20, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(21, 'Can you integrate AI features into an application?', '<p>Yes. I can integrate AI-powered features such as assistants, smart content generation, structured chat flows, classification, summarization, and workflow automation.</p><p>AI features are planned around real product use cases, not just novelty.</p>', 1, 21, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(22, 'Do you work with OpenAI based features?', '<p>Yes. I can build features powered by OpenAI models, including assistant workflows, prompt orchestration, dataset-driven behavior, and API-based product integrations.</p>', 1, 22, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(23, 'Can you build a chatbot for business or customer support?', '<p>Yes. I can build chat or assistant systems for support, lead qualification, internal workflow help, or guided product experiences.</p><p>The exact design depends on whether the goal is automation, support, or operational efficiency.</p>', 1, 23, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(24, 'Do you implement role-based authentication and access control?', '<p>Yes. I can build authentication and access structures for admins, editors, customers, managers, or any custom role setup your product needs.</p><p>This is especially important for dashboards and internal business systems.</p>', 1, 24, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(25, 'Can you integrate Stripe or other payment gateways?', '<p>Yes. I can integrate payment workflows such as subscriptions, one-time payments, billing plans, and related backend events.</p><p>The final gateway depends on regional availability and business requirements.</p>', 1, 25, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(26, 'Do you support multi-language or multi-currency features?', '<p>Yes. I can build products that support multiple languages, currency display logic, and region-aware experiences when the project requires it.</p><p>This is especially useful for travel, ecommerce, and international service platforms.</p>', 1, 26, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(27, 'Can you add analytics and visitor tracking?', '<p>Yes. I can integrate practical analytics features such as page tracking, event reporting, custom admin metrics, and business-relevant usage insights.</p><p>The right setup depends on how detailed you need the reporting to be.</p>', 1, 27, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(28, 'Do you care about security while building applications?', '<p>Yes. Security is part of the implementation process, especially around authentication, data validation, access control, file uploads, and production configuration.</p><p>I focus on sensible, product-level security practices from the start.</p>', 1, 28, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(29, 'Can you review an existing codebase before starting work?', '<p>Yes. A focused code review helps identify technical debt, blockers, hidden risks, and the safest path for improvement.</p><p>This is often the best first step when a project already exists.</p>', 1, 29, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(30, 'Do you provide technical documentation or handoff notes?', '<p>Yes. I can provide practical handoff notes, setup details, and structural guidance so the product stays understandable after delivery.</p><p>The depth of documentation depends on project size and team needs.</p>', 1, 30, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(31, 'How long does a typical project take?', '<p>Timeline depends on the scope, number of features, content readiness, and revision flow.</p><p>Smaller websites can move quickly, while larger platforms usually need phased delivery to keep quality high.</p>', 1, 31, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(32, 'How do you estimate pricing for a project?', '<p>Pricing is usually based on scope, complexity, feature depth, timeline pressure, and the level of ongoing support required.</p><p>A clear brief leads to a much more accurate estimate.</p>', 1, 32, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(33, 'Can revisions be included during the project?', '<p>Yes. Revisions are a normal part of product delivery.</p><p>The best results come when revisions are tied to clear goals, realistic scope, and consistent communication throughout the project.</p>', 1, 33, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(34, 'How do you usually communicate during a project?', '<p>I keep communication direct, organized, and practical.</p><ul><li>Clear updates on progress</li><li>Questions when decisions matter</li><li>Shared understanding of scope and next steps</li></ul>', 1, 34, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(35, 'Do you provide maintenance after launch?', '<p>Yes. I can continue supporting the product after launch for bug fixing, updates, new features, performance work, or technical continuity.</p><p>Many products benefit from steady post-launch support.</p>', 1, 35, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(36, 'Can you handle urgent fixes or short-notice support?', '<p>Yes, when availability allows. For urgent issues, I focus on stabilizing the problem first and then deciding whether deeper cleanup is needed afterward.</p>', 1, 36, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(37, 'Do you offer monthly or ongoing collaboration?', '<p>Yes. Ongoing collaboration works well for teams that need regular development, iterative improvements, support, and feature delivery over time.</p><p>This is often a strong fit for growing products.</p>', 1, 37, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(38, 'Can you work on a fixed-scope project?', '<p>Yes. Fixed-scope delivery works well when the goals, features, and priorities are clearly defined before development begins.</p><p>Clear boundaries help protect both timeline and quality.</p>', 1, 38, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(39, 'Are your services suitable for startups?', '<p>Yes. Startups often need fast execution, practical decision-making, and scalable architecture without unnecessary overhead.</p><p>I try to keep the build focused on what actually helps the product move forward.</p>', 1, 39, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(40, 'Do you also work with agencies or remote teams?', '<p>Yes. I can collaborate with agencies, founders, internal product teams, and remote engineering teams.</p><p>I am comfortable fitting into an existing workflow when the process is clear.</p>', 1, 40, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(41, 'Can you work as a white-label development partner?', '<p>Yes. I can support agencies or service providers as a development partner while maintaining professional communication, confidentiality, and consistent delivery standards.</p>', 1, 41, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(42, 'Are you comfortable signing an NDA?', '<p>Yes. If a project requires confidentiality, I can work under an NDA and handle the product details with appropriate discretion.</p>', 1, 42, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(43, 'Will I get the source code after project delivery?', '<p>Yes. If the project terms include full delivery, the source code and related project materials can be handed over at the end of the engagement.</p><p>That part should always be made clear early in the project.</p>', 1, 43, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(44, 'Do you use GitHub or version control during development?', '<p>Yes. Version control is part of a healthy development workflow.</p><p>Using Git helps keep changes traceable, safer to review, and easier to collaborate on with teams.</p>', 1, 44, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(45, 'Are hosting or third-party service costs included in development pricing?', '<p>Usually those costs are separate unless clearly included in a proposal.</p><p>Items such as hosting, domain, email providers, payment gateways, and premium APIs are normally billed based on actual service usage.</p>', 1, 45, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(46, 'Do you test the project before launch?', '<p>Yes. I test features before launch to reduce obvious issues and improve confidence in the release.</p><p>Testing can include UI behavior, API flows, validation, responsive checks, and critical business logic.</p>', 1, 46, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(47, 'Can you set up a staging or preview environment?', '<p>Yes. A staging environment can be useful for review, feedback, and safer release preparation before the product goes live.</p><p>This is especially valuable for larger or actively changing systems.</p>', 1, 47, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(48, 'Do you help migrate a project from an old system to a new one?', '<p>Yes. I can help plan and execute migrations for code, data, content, or hosting setup.</p><p>Migrations are handled carefully so important content and business logic are not lost.</p>', 1, 48, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(49, 'Can you work with Laravel or PHP based projects too?', '<p>Yes. While much of my recent work is focused on modern JavaScript and TypeScript stacks, I can also support Laravel or PHP projects where the scope is a good fit.</p>', 1, 49, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(50, 'Do you prefer React and Node based product development?', '<p>Yes. React, Next.js, Node.js, Express, and TypeScript are among the stacks I use most often for modern product delivery.</p><p>They work especially well for scalable web apps and admin-heavy systems.</p>', 1, 50, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(51, 'Can you build a professional personal or company portfolio site?', '<p>Yes. I can build portfolio websites for developers, agencies, consultants, founders, and businesses that need a polished digital presence with clear content structure.</p>', 1, 51, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(52, 'Do you have experience with travel or booking related platforms?', '<p>Yes. Travel and booking products usually involve structured content, admin workflows, pricing logic, and customer-facing usability. I can help with both product experience and backend structure.</p>', 1, 52, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(53, 'Can you build internal dashboards for operations teams?', '<p>Yes. Internal dashboards are a common type of project for me.</p><ul><li>Content and data control</li><li>User and role management</li><li>Operational workflows</li><li>Reporting and activity tracking</li></ul>', 1, 53, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(54, 'Do you build blog, article, or publishing systems?', '<p>Yes. I can build article and publishing flows with structured content fields, categories, SEO metadata, comments, and admin management for editorial teams or business websites.</p>', 1, 54, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(55, 'Can you support file uploads, media handling, and storage flows?', '<p>Yes. I can implement file uploads, media storage, secure handling, and the related backend workflows for documents, images, or user-submitted files.</p>', 1, 55, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(56, 'Do you integrate email delivery, OTP, or notification systems?', '<p>Yes. I can implement email sending, OTP flows, notification logic, and related backend processes for onboarding, verification, alerts, and transactional events.</p>', 1, 56, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(57, 'Can you build cron jobs or automation workflows?', '<p>Yes. Scheduled jobs and automation are useful for reminders, data sync, report generation, maintenance tasks, and operational workflows.</p><p>I can help design those flows safely inside the product architecture.</p>', 1, 57, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(58, 'Do you build real-time chat or live update features?', '<p>Yes. I can implement real-time features such as chat, live notifications, presence indicators, status updates, and other event-driven interactions where the product needs them.</p>', 1, 58, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(59, 'Can you collaborate across different time zones?', '<p>Yes. I can work with clients and teams in different time zones as long as expectations around communication windows and delivery rhythm are agreed clearly.</p>', 1, 59, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000'),
(60, 'What is the best way to get started?', '<p>The best way to start is by sharing your project idea, goals, timeline, and any existing links or references.</p><p>Once the scope is clear, I can suggest the best next step, whether that is planning, direct development, or a quick technical review first.</p>', 1, 60, '2026-04-28 00:00:00.000', '2026-04-28 00:00:00.000');
INSERT INTO `job_agent_ai_settings` (`id`, `aiProvider`, `aiModel`, `deepseekApiKeyEncrypted`, `geminiApiKeyEncrypted`, `openaiApiKeyEncrypted`, `fallbackProvider`, `fallbackEnabled`, `systemPrompt`, `recruiterEmailPrompt`, `coverLetterPrompt`, `tone`, `maxEmailWords`, `maxCoverLetterWords`, `requireAdminApproval`, `attachCv`, `attachCoverLetterPdf`, `autoGenerateCoverLetter`, `createdAt`, `updatedAt`) VALUES
(1, 'DEEPSEEK', 'deepseek-chat', '9ca1f2325ceaa3b650038be658ee9470:1a173dc9c349032fa97aad3ceed63136:292b40b090892341c4a6d06487766ea5ee7f82ee11ec411ef2c1e6261a9571034de119', 'a5c429dfd915b33b56d930a606ee78d1:9b3e618af913c252c0ff1cd690e8cb71:', NULL, NULL, 1, 'You are writing on behalf of Md Shahanur Islam Shagor. Write naturally, professionally, and honestly, as if Md Shahanur Islam Shagor personally wrote the message. Use only the provided portfolio profile, skills, education, projects, experience, CV link, and job details. Do not invent experience, employers, degrees, achievements, certifications, or skills. Be concise, confident, respectful, and recruiter-friendly. Avoid generic AI-sounding phrases, exaggeration, buzzwords, and robotic wording. The message should feel human, specific, and easy for a recruiter to read quickly.', 'Create a short recruiter outreach email for the job below. The email must feel personal, natural, and written by the applicant, not by an AI. Start with a simple greeting. If recruiter name exists, use it; otherwise use \'Hello\'. Mention the exact role/company if available. Connect 1-2 strongest relevant skills or projects from the provided portfolio context to the job requirements. Keep the tone professional, warm, confident, and humble. Keep it under {{maxEmailWords}} words. Include that CV and cover letter are attached if attachments are enabled. Include portfolio link only if available. Do not overpromise. Do not use fake claims. End with a polite interest in discussing the opportunity.', 'Write a customized cover letter for this job using only the provided real portfolio context. Make it recruiter-friendly, ATS-friendly, and natural. Structure it with a clear opening, relevant skills/projects/experience, motivation for the role, and a polite closing. Avoid generic filler and AI-style language. Do not invent facts. Keep it under {{maxCoverLetterWords}} words. The letter should make the recruiter feel the applicant is relevant, honest, motivated, and worth reviewing.', 'professional-natural', 300, 600, 0, 1, 1, 1, '2026-06-04 12:06:55.263', '2026-06-05 12:45:25.613');
