(265, NULL, 'api', NULL, 'Handy Person', 'Hawaiian', 'Cable Beach,', 'https://remoteOK.com/remote-jobs/remote-handy-person-hawaiian-1132933', 'Cable Beach Club Resort &amp; Spa is located on the world famous Cable Beach in Broome, far north Western Australia. Broome is easily accessible by plane to all major Australian cities and offers a relaxed lifestyle with all the conveniences of shops, restaurants, cinemas, hospital and schools. Our property has 225 rooms of varying styles, 4 restaurants, pool side bars, tour desk, resort shop and a full service Day Spa and Hair Salon, Chahoya.<br><br>We are currently seeking to appoint a casual/full-time <strong>Handyperson</strong> to undertake basic repairs as well as preventative maintenance in guest rooms and other Resort areas such as restaurants and offices. This position is available to commence now and will suit a candidate who enjoys undertaking a variety of duties.<br><br><strong>The key duties and responsibilities for this position include, but are not limited to the following:<br><br></strong><ul><li>Responding to guest requests for assistance with room maintenance issues;</li><li>Changing of light globes and fixtures;</li><li>Smoke alarm maintenance;</li><li>Basic plumbing including washer replacements, filter replacements to ice machines and water coolers, toilet cistern repairs such as replacing valves, ball cocks etc;</li><li>Repairing or replacing shutters and security screens;</li><li>Relocation of existing and new furniture and fittings across the property;</li><li>Maintaining the cleanliness of the workshop, department vehicles and carts.<br><br></li></ul><strong>The Required Skills And Experience For This Role Include<br><br></strong><ul><li>A minimum of 2 years experience undertaking a similar range of duties;</li><li>The ability to communication effectively with other Resort departments and guests;</li><li>Basic admin skills;</li><li>Proactive team approach to work;</li><li>Availability to work a rotating fortnightly roster that includes weekends and evening shifts;</li><li>A current manual driver\'s license</li><li>Previous experience working in a hotel/resort will be viewed favourably.<br><br></li></ul>Only shortlisted candidates will be contacted.<br><br>Only applicants with full Australian work rights should apply. We request that only individuals apply and ask may agencies please refrain from applying.<br/><br/>Please mention the word **MASTERPIECE** and tag RNjkuNTcuMTYyLjE0 when applying to show you read the job post completely (#RNjkuNTcuMTYyLjE0). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', 'Cable Beach Club Resort &amp; Spa is located on the world famous Cable Beach in Broome, far north Western Australia. Broome is easily accessible by plane to all major Australian cities and offers a relaxed lifestyle with all the conveniences of shops, restaurants, cinemas, hospital and schools. Our property has 225 rooms of varying styles, 4 restaurants, pool side bars, tour desk, resort shop and a full service Day Spa and Hair Salon, Chahoya.<br><br>We are currently seeking to appoint a casual/full-time <strong>Handyperson</strong> to undertake basic repairs as well as preventative maintenance in guest rooms and other Resort areas such as restaurants and offices. This position is available to commence now and will suit a candidate who enjoys undertaking a variety of duties.<br><br><strong>The key duties and responsibilities for this position include, but are not limited to the following:<br><br></strong><ul><li>Responding to guest requests for assistance with room maintenance issues;</li><li>Changing of light globes and fixtures;</li><li>Smoke alarm maintenance;</li><li>Basic plumbing including washer replacements, filter replacements to ice machines and water coolers, toilet cistern repairs such as replacing valves, ball cocks etc;</li><li>Repairing or replacing shutters and security screens;</li><li>Relocation of existing and new furniture and fittings across the property;</li><li>Maintaining the cleanliness of the workshop, department vehicles and carts.<br><br></li></ul><strong>The Required Skills And Experience For This Role Include<br><br></strong><ul><li>A minimum of 2 years experience undertaking a similar range of duties;</li><li>The ability to communication effectively with other Resort departments and guests;</li><li>Basic admin skills;</li><li>Proactive team approach to work;</li><li>Availability to work a rotating fortnightly roster that includes weekends and evening shifts;</li><li>A current manual driver\'s license</li><li>Previous experience working in a hotel/resort will be viewed favourably.<br><br></li></ul>Only shortlisted candidates will be contacted.<br><br>Only applicants with full Australian work rights should apply. We request that only individuals apply and ask may agencies please refrain from applying.<br/><br/>Please mention the word **MASTERPIECE** and tag RNjkuNTcuMTYyLjE0 when applying to show you read the job post completely (#RNjkuNTcuMTYyLjE0). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', 'new', NULL, '2026-06-06 15:19:32.138', '2026-06-06 15:19:32.138', '', '', 'Remote', 'Europe', '', 'RemoteOK', 'API', 'READY', '', '', '', 'api', 'https://remoteOK.com/remote-jobs/remote-handy-person-hawaiian-1132933', '', '[]', 'pending', '', NULL),
(266, NULL, 'api', NULL, 'TEAM MEMBER COLD END', 'Saint-Gobain Group in India', 'Bhiwadi,', 'https://remoteOK.com/remote-jobs/remote-team-member-cold-end-saint-gobain-group-in-india-1132910', '<ul><li>Ensure Safety aspects in shop floor and in all cold end activities in Float Line 1.</li><li>Responsible to achieve the Plan actualization and minimize deviations in all products.</li><li>Responsible to maximize quality products and claim reduction in mainline.</li><li>Responsible to minimize Cold end Related losses and Breakdowns.</li><li>Responsible for 5S improvements in Cold End.</li></ul><br/><br/>Please mention the word **COOL** and tag RNjkuNTcuMTYyLjE0 when applying to show you read the job post completely (#RNjkuNTcuMTYyLjE0). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', '<ul><li>Ensure Safety aspects in shop floor and in all cold end activities in Float Line 1.</li><li>Responsible to achieve the Plan actualization and minimize deviations in all products.</li><li>Responsible to maximize quality products and claim reduction in mainline.</li><li>Responsible to minimize Cold end Related losses and Breakdowns.</li><li>Responsible for 5S improvements in Cold End.</li></ul><br/><br/>Please mention the word **COOL** and tag RNjkuNTcuMTYyLjE0 when applying to show you read the job post completely (#RNjkuNTcuMTYyLjE0). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', 'new', NULL, '2026-06-06 15:19:40.173', '2026-06-06 15:19:40.173', '', '', 'Remote', 'Europe', '', 'RemoteOK', 'API', 'READY', '', '', '', 'api', 'https://remoteOK.com/remote-jobs/remote-team-member-cold-end-saint-gobain-group-in-india-1132910', '', '[]', 'pending', '', NULL),
