adow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ;  cursor: text; padding: 0px; counter-reset: list-1 0 list-2 0 list-3 0 list-4 0 list-5 0 list-6 0 list-7 0 list-8 0 list-9 0;\"><br style=\"border-color: rgb(229, 231, 235); --tw-shadow: 0 0 #0000; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ;\"></p>\n<img src=\"https://remotive.com/job/track/2090944/blank.gif?source=public_api\" alt=\"\"/>', 'new', NULL, '2026-06-06 15:21:48.171', '2026-06-06 15:21:48.171', '', 'part_time', 'Remote', 'United States', '', 'Remotive', 'API', 'READY', 'Web%20Developer', '', '', 'api', 'https://remotive.com/remote-jobs/all-others/online-data-analyst-canada-2090944', '', '[]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(284, NULL, 'api', NULL, 'Senior Digital Marketing Consultant & Teamlead (Hamburg, hybrid) *', 'Ilias Vassiliou & Team / headhunter.digital / Recruiting für Digital, Sales, IT, KI, Automation', 'Hamburg', 'https://www.arbeitnow.com/jobs/companies/ilias-vassiliou-team-headhunterdigital-recruiting-fur-digital-sales-it-ki-automation/senior-digital-marketing-consultant-teamlead-hamburg-hybrid-440540', '<p>Strategie &#x26; Beratung • Digital Marketing von A-Z • KI • Teamführung</p>\n<p>📍 Hamburg | Hybrid | Vollzeit | €70.000 – €90.000 Jahresgehalt</p>\n<p>--</p>\n<p>Marketing ist nicht das Problem. Schlechtes Marketing schon.</p>\n<p>Hinter dem Job steht eine ausgezeichnete Digital-Beratungs-Boutique (20 MA), die Unternehmen dabei unterstützt, Marketing, Vertrieb und digitale Geschäftsmodelle wirksamer zu gestalten.</p>\n<p>Dabei geht es nicht um Kampagnen um ihrer selbst willen, sondern um die Frage:</p>\n<p><strong>Wie entsteht messbarer Geschäftserfolg durch digitales Marketing?</strong></p>\n<p>Genau an dieser Stelle setzt diese Rolle an.</p>\n<p>Wir suchen eine Persönlichkeit, die Digital Marketing ganzheitlich denkt, Verantwortung übernimmt und Menschen führen kann. Jemanden, der:die Kunden strategisch beraten kann, operative Exzellenz mitbringt und den Anspruch hat, Ergebnisse zu liefern statt PowerPoint-Folien zu produzieren.</p>\n<p>Eine Rolle für Menschen, die lieber Wirkung erzeugen als Buzzwords zu verwalten.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Mission ...</strong></p>\n<ul>\n<li>Du übernimmst die <strong>fachliche</strong> (und optional disziplinarische) <strong>Führung</strong> eines Digital Marketing-Teams und arbeitest direkt mit der Geschäftsführung zusammen.</li>\n<li>Gleichzeitig <strong>berätst du Kunden</strong> auf Augenhöhe bei der Entwicklung und Umsetzung moderner Marketing- und Wachstumsstrategien.</li>\n<li>Du bist dabei weder reine:r Strateg:in noch reine:r Operative:r. Du verbindest beides.</li>\n<li>Du erkennst die entscheidenden Hebel im Marketing, entwickelst daraus tragfähige Strategien und sorgst anschließend dafür, dass diese auch erfolgreich umgesetzt werden.</li>\n</ul>\n<p>Was du konkret machst ...</p>\n<p><strong>Kunden beraten, statt nur Maßnahmen zu verkaufen</strong></p>\n<ul>\n<li>Du analysierst Geschäftsmodelle, Marketing-Setups und Wachstumshebel.</li>\n<li>Du entwickelst Strategien, die auf Unternehmensziele einzahlen, nicht auf kurzfristige Trendthemen oder Eitelkeitsmetriken.</li>\n<li>Dabei wirst du zur zentralen Vertrauensperson für deine Kunden.</li>\n</ul>\n<p><strong>Performance und Kampagnen aktiv steuern</strong></p>\n<ul>\n<li>Du bleibst weiterhin nah an der Praxis.</li>\n<li>Ob Google, Meta, LinkedIn oder andere relevante Plattformen: Du verstehst die Mechaniken moderner Kampagnen und kannst bei Bedarf selbst operativ eingreifen.</li>\n<li>Du optimierst nicht nur Kampagnen, sondern die gesamte Customer Journey.</li>\n</ul>\n<p><strong>Marketing in Geschäftswirkung übersetzen</strong></p>\n<ul>\n<li>Leads, Umsatz, Customer Lifetime Value, Profitabilität.</li>\n<li>Du verstehst die Zusammenhänge zwischen Marketing und Geschäftserfolg und kannst diese auch gegenüber Geschäftsführungen und Entscheidern verständlich darstellen.</li>\n</ul>\n<p><strong>Ein Team führen und weiterentwickeln</strong></p>\n<ul>\n<li>Du übernimmst die Verantwortung für ein Team von etwa vier bis sechs Marketing-Spezialist:innen am Standort Hamburg.</li>\n<li>Du gibst Orientierung, Feedback und Unterstützung.</li>\n<li>Du entwickelst Menschen weiter, schaffst Klarheit und sorgst dafür, dass das Team gemeinsam wächst.</li>\n</ul>\n<p><strong>KI sinnvoll in Marketing-Prozesse integrieren</strong></p>\n<ul>\n<li>KI ist hier kein Marketing-Gag. Du nutzt moderne KI-Tools für Analyse, Recherche, Content-Erstellung, Effizienzsteigerung und neue Arbeitsweisen.</li>\n<li>Du hilfst deinem Team dabei, produktiver und wirksamer zu arbeiten, ohne dabei kritisches Denken zu ersetzen.</li>\n</ul>\n<p><strong>Projekte erfolgreich zusammenführen</strong></p>\n<ul>\n<li>Du koordinierst die Zusammenarbeit zwischen Kunden, Strateg:innen, Marketing-Spezialist:innen und weiteren Projektbeteiligten.</li>\n<li>Du sorgst dafür, dass Ideen nicht in Konzepten stecken bleiben, sondern erfolgreich umgesetzt werden.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringst du idealerweise mit ...</strong></p>\n<ul>\n<li>Mindestens 7 Jahre relevante Berufserfahrung im digitalen Marketing</li>\n<li>Erfahrung in einer Agentur, Beratung, Digitalberatung, im E-Commerce oder einem vergleichbaren Umfeld</li>\n<li>Nachweisbare Erfolge in der Entwicklung und Umsetzung digitaler Marketingstrategien</li>\n<li>Sehr gutes Verständnis von Performance Marketing, Customer Journeys und Funnel-Logiken.</li>\n<li>Fähigkeit, Marketing in Geschäftsergebnisse zu übersetzen</li>\n<li>Operative Erfahrung mit relevanten Marketing-Plattformen und Kampagnensystemen (Meta, Google, LinkedIn ...)</li>\n<li>Erfahrung in der fachlichen Führung von Mitarbeitenden (optional auch disziplinarische Führungserfahrung)</li>\n<li>Starkes Interesse an KI und modernen Technologien</li>\n<li>Sehr gute Kommunikationsfähigkeiten auf Deutsch und Englisch</li>\n</ul>\n<p><strong>Besonders gut passt die Rolle zu dir, wenn ...</strong></p>\n<ul>\n<li>du Marketing nicht kanalzentriert, sondern unternehmerisch denkst</li>\n<li>du Strategie und Umsetzung gleichermaßen spannend findest</li>\n<li>du Verantwortung für Menschen übernehmen möchtest</li>\n<li>du lieber Ergebnisse als Präsentationen produzierst</li>\n<li>du moderne Technologien und KI als Chance begreifst</li>\n<li>du Lust hast, aktiv an der Weiterentwicklung eines ambitionierten Teams mitzuwirken</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Echte Führungsverantwortung</strong></p>\n<p>Du übernimmst ein bestehendes Team und arbeitest direkt mit der Geschäftsführung zusammen.</p>\n<p><strong>Anspruchsvolle Kunden und Projekte</strong></p>\n<p>Von etablierten Mittelständlern bis zu bekannten Marken – die Fragestellungen sind vielfältig und strategisch relevant.</p>\n<p><strong>Hoher Gestaltungsspielraum</strong></p>\n<p>Kurze Entscheidungswege, wenig Politik und viel Vertrauen in Eigenverantwortung.</p>\n<p><strong>Moderne Arbeitsweise</strong></p>\n<p>KI, Automatisierung und neue Technologien gehören zum Arbeitsalltag und werden aktiv weiterentwickelt.</p>\n<p><strong>Attraktives Gesamtpaket:</strong></p>\n<ul>\n<li>70.000–90.000 € Jahresgehalt, je nach Hintergrund und Erfahrung</li>\n<li>Hybrid-Modell mit Homeoffice-Anteil am Standort Hamburg</li>\n<li>Individuelles Weiterbildungsbudget</li>\n<li>Interne Academy</li>\n<li>Mentor beim Onboarding</li>\n<li>Flexible Arbeitsmodelle</li>\n<li>JobRad</li>\n<li>Unbefristete Festanstellung</li>\n<li>Teamevents</li>\n<li>Weitere Corporate Benefits</li>\n</ul>\n<p>Ganz unabhängig davon, ob dein aktueller Titel heute <strong>Teamlead Digital Marketing</strong>, <strong>Head of Performance Marketing</strong>, <strong>Growth Marketing Lead</strong>, <strong>Senior Marketing Consultant</strong>, <strong>Digital Marketing Manager</strong> oder <strong>Performance Marketing Lead</strong> lautet.</p>\n<p>Entscheidend ist nicht dein Titel. Entscheidend ist, dass du Marketing als Wachstumstreiber verstehst, Menschen entwickeln kannst und Lust hast, gemeinsam mit Kunden und Team echte Wirkung zu erzielen.</p>\n<p>--</p>\n<p><strong>Klingt nach deinem nächsten Schritt?</strong></p>\n<p>Dann freuen wir uns auf deine Bewerbung! Schick uns gerne:</p>\n<ol>\n<li><strong>Deinen Lebenslauf:</strong> Was hast du gemacht, was hast du bewirkt?</li>\n<li><strong>Ein konkretes Beispiel (3–5 Sätze):</strong> Eine Kampagne, ein Projekt oder eine Entscheidung, auf die du stolz bist und warum sie gewirkt hat.</li>\n<li><strong>Deine ehrliche Einschätzung:</strong> Was ist das größte Problem im digitalen Marketing heute und was würdest du anders machen? (kurz &#x26; knapp)</li>\n<li><strong>Deine letzten Arbeitszeugnisse.</strong> Sie vermitteln einen ersten Eindruck deines bisherigen Wegs.</li>\n</ol>\n<p>--</p>\n<p>Du kannst einen professionellen Prozess und zeitnahe Reaktionen von uns erwarten. Auch unterstützen wir dich dabei, dich optimal zu präsentieren und begleiten dich mit Rat &#x26; Tat im Prozess inkl. der Vertragsverhandlungen.</p>\n<p>Wir freuen uns schon sehr über deine Kontaktaufnahme!</p>\n<p>--</p>\n<p>* Diese Stelle steht allen Menschen offen, unabhängig von Geschlecht, Alter und anderen Merkmalen: m/w/d +</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Strategie &#x26; Beratung • Digital Marketing von A-Z • KI • Teamführung</p>\n<p>📍 Hamburg | Hybrid | Vollzeit | €70.000 – €90.000 Jahresgehalt</p>\n<p>--</p>\n<p>Marketing ist nicht das Problem. Schlechtes Marketing schon.</p>\n<p>Hinter dem Job steht eine ausgezeichnete Digital-Beratungs-Boutique (20 MA), die Unternehmen dabei unterstützt, Marketing, Vertrieb und digitale Geschäftsmodelle wirksamer zu gestalten.</p>\n<p>Dabei geht es nicht um Kampagnen um ihrer selbst willen, sondern um die Frage:</p>\n<p><strong>Wie entsteht messbarer Geschäftserfolg durch digitales Marketing?</strong></p>\n<p>Genau an dieser Stelle setzt diese Rolle an.</p>\n<p>Wir suchen eine Persönlichkeit, die Digital Marketing ganzheitlich denkt, Verantwortung übernimmt und Menschen führen kann. Jemanden, der:die Kunden strategisch beraten kann, operative Exzellenz mitbringt und den Anspruch hat, Ergebnisse zu liefern statt PowerPoint-Folien zu produzieren.</p>\n<p>Eine Rolle für Menschen, die lieber Wirkung erzeugen als Buzzwords zu verwalten.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Mission ...</strong></p>\n<ul>\n<li>Du übernimmst die <strong>fachliche</strong> (und optional disziplinarische) <strong>Führung</strong> eines Digital Marketing-Teams und arbeitest direkt mit der Geschäftsführung zusammen.</li>\n<li>Gleichzeitig <strong>berätst du Kunden</strong> auf Augenhöhe bei der Entwicklung und Umsetzung moderner Marketing- und Wachstumsstrategien.</li>\n<li>Du bist dabei weder reine:r Strateg:in noch reine:r Operative:r. Du verbindest beides.</li>\n<li>Du erkennst die entscheidenden Hebel im Marketing, entwickelst daraus tragfähige Strategien und sorgst anschließend dafür, dass diese auch erfolgreich umgesetzt werden.</li>\n</ul>\n<p>Was du konkret machst ...</p>\n<p><strong>Kunden beraten, statt nur Maßnahmen zu verkaufen</strong></p>\n<ul>\n<li>Du analysierst Geschäftsmodelle, Marketing-Setups und Wachstumshebel.</li>\n<li>Du entwickelst Strategien, die auf Unternehmensziele einzahlen, nicht auf kurzfristige Trendthemen oder Eitelkeitsmetriken.</li>\n<li>Dabei wirst du zur zentralen Vertrauensperson für deine Kunden.</li>\n</ul>\n<p><strong>Performance und Kampagnen aktiv steuern</strong></p>\n<ul>\n<li>Du bleibst weiterhin nah an der Praxis.</li>\n<li>Ob Google, Meta, LinkedIn oder andere relevante Plattformen: Du verstehst die Mechaniken moderner Kampagnen und kannst bei Bedarf selbst operativ eingreifen.</li>\n<li>Du optimierst nicht nur Kampagnen, sondern die gesamte Customer Journey.</li>\n</ul>\n<p><strong>Marketing in Geschäftswirkung übersetzen</strong></p>\n<ul>\n<li>Leads, Umsatz, Customer Lifetime Value, Profitabilität.</li>\n<li>Du verstehst die Zusammenhänge zwischen Marketing und Geschäftserfolg und kannst diese auch gegenüber Geschäftsführungen und Entscheidern verständlich darstellen.</li>\n</ul>\n<p><strong>Ein Team führen und weiterentwickeln</strong></p>\n<ul>\n<li>Du übernimmst die Verantwortung für ein Team von etwa vier bis sechs Marketing-Spezialist:innen am Standort Hamburg.</li>\n<li>Du gibst Orientierung, Feedback und Unterstützung.</li>\n<li>Du entwickelst Menschen weiter, schaffst Klarheit und sorgst dafür, dass das Team gemeinsam wächst.</li>\n</ul>\n<p><strong>KI sinnvoll in Marketing-Prozesse integrieren</strong></p>\n<ul>\n<li>KI ist hier kein Marketing-Gag. Du nutzt moderne KI-Tools für Analyse, Recherche, Content-Erstellung, Effizienzsteigerung und neue Arbeitsweisen.</li>\n<li>Du hilfst deinem Team dabei, produktiver und wirksamer zu arbeiten, ohne dabei kritisches Denken zu ersetzen.</li>\n</ul>\n<p><strong>Projekte erfolgreich zusammenführen</strong></p>\n<ul>\n<li>Du koordinierst die Zusammenarbeit zwischen Kunden, Strateg:innen, Marketing-Spezialist:innen und weiteren Projektbeteiligten.</li>\n<li>Du sorgst dafür, dass Ideen nicht in Konzepten stecken bleiben, sondern erfolgreich umgesetzt werden.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringst du idealerweise mit ...</strong></p>\n<ul>\n<li>Mindestens 7 Jahre relevante Berufserfahrung im digitalen Marketing</li>\n<li>Erfahrung in einer Agentur, Beratung, Digitalberatung, im E-Commerce oder einem vergleichbaren Umfeld</li>\n<li>Nachweisbare Erfolge in der Entwicklung und Umsetzung digitaler Marketingstrategien</li>\n<li>Sehr gutes Verständnis von Performance Marketing, Customer Journeys und Funnel-Logiken.</li>\n<li>Fähigkeit, Marketing in Geschäftsergebnisse zu übersetzen</li>\n<li>Operative Erfahrung mit relevanten Marketing-Plattformen und Kampagnensystemen (Meta, Google, LinkedIn ...)</li>\n<li>Erfahrung in der fachlichen Führung von Mitarbeitenden (optional auch disziplinarische Führungserfahrung)</li>\n<li>Starkes Interesse an KI und modernen Technologien</li>\n<li>Sehr gute Kommunikationsfähigkeiten auf Deutsch und Englisch</li>\n</ul>\n<p><strong>Besonders gut passt die Rolle zu dir, wenn ...</strong></p>\n<ul>\n<li>du Marketing nicht kanalzentriert, sondern unternehmerisch denkst</li>\n<li>du Strategie und Umsetzung gleichermaßen spannend findest</li>\n<li>du Verantwortung für Menschen übernehmen möchtest</li>\n<li>du lieber Ergebnisse als Präsentationen produzierst</li>\n<li>du moderne Technologien und KI als Chance begreifst</li>\n<li>du Lust hast, aktiv an der Weiterentwicklung eines ambitionierten Teams mitzuwirken</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Echte Führungsverantwortung</strong></p>\n<p>Du übernimmst ein bestehendes Team und arbeitest direkt mit der Geschäftsführung zusammen.</p>\n<p><strong>Anspruchsvolle Kunden und Projekte</strong></p>\n<p>Von etablierten Mittelständlern bis zu bekannten Marken – die Fragestellungen sind vielfältig und strategisch relevant.</p>\n<p><strong>Hoher Gestaltungsspielraum</strong></p>\n<p>Kurze Entscheidungswege, wenig Politik und viel Vertrauen in Eigenverantwortung.</p>\n<p><strong>Moderne Arbeitsweise</strong></p>\n<p>KI, Automatisierung und neue Technologien gehören zum Arbeitsalltag und werden aktiv weiterentwickelt.</p>\n<p><strong>Attraktives Gesamtpaket:</strong></p>\n<ul>\n<li>70.000–90.000 € Jahresgehalt, je nach Hintergrund und Erfahrung</li>\n<li>Hybrid-Modell mit Homeoffice-Anteil am Standort Hamburg</li>\n<li>Individuelles Weiterbildungsbudget</li>\n<li>Interne Academy</li>\n<li>Mentor beim Onboarding</li>\n<li>Flexible Arbeitsmodelle</li>\n<li>JobRad</li>\n<li>Unbefristete Festanstellung</li>\n<li>Teamevents</li>\n<li>Weitere Corporate Benefits</li>\n</ul>\n<p>Ganz unabhängig davon, ob dein aktueller Titel heute <strong>Teamlead Digital Marketing</strong>, <strong>Head of Performance Marketing</strong>, <strong>Growth Marketing Lead</strong>, <strong>Senior Marketing Consultant</strong>, <strong>Digital Marketing Manager</strong> oder <strong>Performance Marketing Lead</strong> lautet.</p>\n<p>Entscheidend ist nicht dein Titel. Entscheidend ist, dass du Marketing als Wachstumstreiber verstehst, Menschen entwickeln kannst und Lust hast, gemeinsam mit Kunden und Team echte Wirkung zu erzielen.</p>\n<p>--</p>\n<p><strong>Klingt nach deinem nächsten Schritt?</strong></p>\n<p>Dann freuen wir uns auf deine Bewerbung! Schick uns gerne:</p>\n<ol>\n<li><strong>Deinen Lebenslauf:</strong> Was hast du gemacht, was hast du bewirkt?</li>\n<li><strong>Ein konkretes Beispiel (3–5 Sätze):</strong> Eine Kampagne, ein Projekt oder eine Entscheidung, auf die du stolz bist und warum sie gewirkt hat.</li>\n<li><strong>Deine ehrliche Einschätzung:</strong> Was ist das größte Problem im digitalen Marketing heute und was würdest du anders machen? (kurz &#x26; knapp)</li>\n<li><strong>Deine letzten Arbeitszeugnisse.</strong> Sie vermitteln einen ersten Eindruck deines bisherigen Wegs.</li>\n</ol>\n<p>--</p>\n<p>Du kannst einen professionellen Prozess und zeitnahe Reaktionen von uns erwarten. Auch unterstützen wir dich dabei, dich optimal zu präsentieren und begleiten dich mit Rat &#x26; Tat im Prozess inkl. der Vertragsverhandlungen.</p>\n<p>Wir freuen uns schon sehr über deine Kontaktaufnahme!</p>\n<p>--</p>\n<p>* Diese Stelle steht allen Menschen offen, unabhängig von Geschlecht, Alter und anderen Merkmalen: m/w/d +</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-07 03:14:29.559', '2026-06-07 03:14:29.559', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/ilias-vassiliou-team-headhunterdigital-recruiting-fur-digital-sales-it-ki-automation/senior-digital-marketing-consultant-teamlead-hamburg-hybrid-440540', '', '[]', 'pending', '', NULL),
(285, NULL, 'api', NULL, 'Senior Construction Quality Manager', 'ILOS Projects GmbH & Co. KG', 'Karlsruhe', 'https://www.arbeitnow.com/jobs/companies/ilos-projects-gmbh-co-kg/senior-construction-quality-manager-karlsruhe-5043', '<p>Senior Construction Quality Manager</p>\n<p>Location: Germany, Ireland, UK, Italy</p>\n<p>Company: ILOS</p>\n<p>Scope: Full-time/hybrid - Travel to our sites across Europe</p>\n<p>WHO ARE ILOS?</p>\n<p>ILOS is a fast-growing renewable energy company with a strong presence across Europe, backed by BNP Paribas Alts and committed to accelerating the energy transition. Since 2018, we have developed, built, and operated large-scale solar PV projects across seven core markets.</p>\n<p>THE ROLE OVERVIEW</p>\n<p>As Lead Construction Quality Manager, you will lead and scale the quality management system across ILOS’ portfolio of utility-scale solar PV and BESS construction projects in Europe.</p>\n<p>This is a senior role with responsibility for quality strategy, governance and delivery across multiple live construction sites. You will ensure standards are applied consistently, defects are prevented, and contractors are held accountable for delivering high-quality assets.</p>\n<p>Acting as the central quality lead within the construction organisation, you will also drive standardisation, continuous improvement and cross-project learning, while supporting and developing project-based quality teams.</p>\n<p>TASKS</p>\n<ul>\n<li>Lead and continuously improve ILOS’ Quality Management System (QMS) across engineering, construction, testing and handover.</li>\n<li>Define and implement standard QA/QC procedures, ITPs, checklists and reporting frameworks across all projects.</li>\n<li>Oversee quality performance across multiple solar PV and BESS construction sites in different European markets.</li>\n<li>Ensure robust site quality assurance across key scopes including civil works, ramming, mounting structures, and PV module installation.</li>\n<li>Drive NCR management, defect tracking, snagging and punch-list closure, including root cause analysis and corrective actions.</li>\n<li>Act as the senior quality interface for EPC contractors, subcontractors and suppliers, challenging poor-quality delivery where required.</li>\n<li>Monitor quality KPIs, digital QA tools and reporting to identify recurring issues, trends and improvement opportunities.</li>\n<li>Support project handover readiness, ensuring quality documentation, as-builts, and test records are complete and accurate.</li>\n<li>Lead, mentor and develop project-level quality managers, QA/QC engineers and site inspectors.</li>\n</ul>\n<p>PROFILE</p>\n<ul>\n<li>Degree in Engineering, Construction Management, or a related field.</li>\n<li>Strong experience in QA/QC management within EPC or major construction projects, ideally in utility-scale solar PV; BESS experience is an advantage.</li>\n<li>Proven experience overseeing quality across multiple sites or projects simultaneously.</li>\n<li>Strong understanding of construction processes, materials and applicable technical standards.</li>\n<li>Experience with Inspection &#x26; Test Plans, NCR processes, quality documentation systems and handover readiness.</li>\n<li>Able to challenge contractors, drive accountability and maintain standards in fast-paced site environments.</li>\n<li>Strong reporting, organisation and stakeholder management capability.</li>\n<li>Comfortable working both strategically and hands-on where required.</li>\n<li>Fluent English required; additional European languages are an advantage.</li>\n<li>Willingness to travel regularly to project sites across Europe</li>\n</ul>\n<p>Become part of a committed team shaping the future of clean energy, together.</p>\n<p>CONTACT</p>\n<p>Do you have questions about your career at ILOS? We’re here for you!<br>\nWhether it\'s about open positions, the application process, or our work environment – our HR team will be happy to support you.</p>\n<p>Contact our Talent Acquisition Manager, Toby Barbieri – <a ----------\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Senior Construction Quality Manager</p>\n<p>Location: Germany, Ireland, UK, Italy</p>\n<p>Company: ILOS</p>\n<p>Scope: Full-time/hybrid - Travel to our sites across Europe</p>\n<p>WHO ARE ILOS?</p>\n<p>ILOS is a fast-growing renewable energy company with a strong presence across Europe, backed by BNP Paribas Alts and committed to accelerating the energy transition. Since 2018, we have developed, built, and operated large-scale solar PV projects across seven core markets.</p>\n<p>THE ROLE OVERVIEW</p>\n<p>As Lead Construction Quality Manager, you will lead and scale the quality management system across ILOS’ portfolio of utility-scale solar PV and BESS construction projects in Europe.</p>\n<p>This is a senior role with responsibility for quality strategy, governance and delivery across multiple live construction sites. You will ensure standards are applied consistently, defects are prevented, and contractors are held accountable for delivering high-quality assets.</p>\n<p>Acting as the central quality lead within the construction organisation, you will also drive standardisation, continuous improvement and cross-project learning, while supporting and developing project-based quality teams.</p>\n<p>TASKS</p>\n<ul>\n<li>Lead and continuously improve ILOS’ Quality Management System (QMS) across engineering, construction, testing and handover.</li>\n<li>Define and implement standard QA/QC procedures, ITPs, checklists and reporting frameworks across all projects.</li>\n<li>Oversee quality performance across multiple solar PV and BESS construction sites in different European markets.</li>\n<li>Ensure robust site quality assurance across key scopes including civil works, ramming, mounting structures, and PV module installation.</li>\n<li>Drive NCR management, defect tracking, snagging and punch-list closure, including root cause analysis and corrective actions.</li>\n<li>Act as the senior quality interface for EPC contractors, subcontractors and suppliers, challenging poor-quality delivery where required.</li>\n<li>Monitor quality KPIs, digital QA tools and reporting to identify recurring issues, trends and improvement opportunities.</li>\n<li>Support project handover readiness, ensuring quality documentation, as-builts, and test records are complete and accurate.</li>\n<li>Lead, mentor and develop project-level quality managers, QA/QC engineers and site inspectors.</li>\n</ul>\n<p>PROFILE</p>\n<ul>\n<li>Degree in Engineering, Construction Management, or a related field.</li>\n<li>Strong experience in QA/QC management within EPC or major construction projects, ideally in utility-scale solar PV; BESS experience is an advantage.</li>\n<li>Proven experience overseeing quality across multiple sites or projects simultaneously.</li>\n<li>Strong understanding of construction processes, materials and applicable technical standards.</li>\n<li>Experience with Inspection &#x26; Test Plans, NCR processes, quality documentation systems and handover readiness.</li>\n<li>Able to challenge contractors, drive accountability and maintain standards in fast-paced site environments.</li>\n<li>Strong reporting, organisation and stakeholder management capability.</li>\n<li>Comfortable working both strategically and hands-on where required.</li>\n<li>Fluent English required; additional European languages are an advantage.</li>\n<li>Willingness to travel regularly to project sites across Europe</li>\n</ul>\n<p>Become part of a committed team shaping the future of clean energy, together.</p>\n<p>CONTACT</p>\n<p>Do you have questions about your career at ILOS? We’re here for you!<br>\nWhether it\'s about open positions, the application process, or our work environment – our HR team will be happy to support you.</p>\n<p>Contact our Talent Acquisition Manager, Toby Barbieri – <a ----------\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-07 03:14:36.980', '2026-06-07 03:14:36.980', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/ilos-projects-gmbh-co-kg/senior-construction-quality-manager-karlsruhe-5043', '', '[]', 'pending', '', NULL),
(286, NULL, 'api', NULL, 'Shopware Entwickler Fullstack (m/w/d)', 'Aurivian GmbH', 'Karlsruhe', 'https://www.arbeitnow.com/jobs/companies/aurivian-gmbh/shopware-entwickler-fullstack-karlsruhe-62007', '<h2>Über uns</h2>\n<p>Aurivian ist eine Shopware-Agentur aus Karlsruhe. Wir entwickeln, betreiben und optimieren eCommerce-Lösungen auf Basis von Shopware 6 für mittelständische Händler im DACH-Raum. Wir sind ein kleines Team und wollen weiterwachsen, daher suchen wir für den Bereich Entwicklung Verstärkung.</p>\n<h2>Deine Rolle</h2>\n<p>Als Shopware Entwickler (m/w/d) bist Du Teil unseres Entwicklerteams und setzt Kundenprojekte auf Basis von Shopware 6 um. Schwerpunkt ist Backend-Entwicklung in PHP und Symfony. Storefront-Anpassungen in Twig, SCSS und JavaScript sowie die Integration externer Systeme gehören dazu.</p>\n<p>Du arbeitest eigenverantwortlich an Deinen Themen, bringst Deine technische Perspektive aktiv in Architektur- und Technologieentscheidungen ein und entwickelst im Austausch mit Team und Entwicklungsleitung gemeinsam passende Lösungen weiter.</p>\n<h2>Deine Aufgaben</h2>\n<ul>\n<li>Entwicklung von Shopware-Plugins und individuellen Erweiterungen</li>\n<li>Umsetzung kundenspezifischer Anforderungen mit Schwerpunkt Backend</li>\n<li>Storefront-Anpassungen in Twig, SCSS und JavaScript</li>\n<li>Integration externer Systeme und Services über REST-APIs</li>\n<li>Code Reviews und technische Dokumentation</li>\n<li>Technische Rückkopplung mit Projektmanagement und Kunden</li>\n<li>Mitgestaltung interner Dev-Prozesse, CI/CD-Workflows und Standards</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>2 bis 5 Jahre Erfahrung in der objektorientierten PHP-Entwicklung</li>\n<li>Fundierte Kenntnisse in Symfony, Twig, MySQL und Git</li>\n<li>Praxiserfahrung mit Shopware 6 (eigene Plugins, Customizing oder Zertifizierungen)</li>\n<li>Grundkenntnisse in Frontend-Technologien (HTML, CSS, JavaScript)</li>\n<li>Erfahrung mit API-Design und Systemintegration</li>\n<li>Vertraut mit modernen Dev-Setups (Docker, GitHub, Testing, CI/CD)</li>\n<li>Strukturierte, eigenverantwortliche Arbeitsweise</li>\n<li>Gutes Deutsch in Wort und Schrift (Level B2+)</li>\n</ul>\n<h2>Bonuspunkte gibt’s für</h2>\n<ul>\n<li>Shopware-Zertifikate (Backend Developer, Frontend Developer)</li>\n<li>Erfahrung mit Vue.js oder vergleichbaren Frontend-Frameworks</li>\n<li>Erfahrung mit weiteren PHP Backend-Frameworks</li>\n<li>Erfahrung mit Performance-Optimierung und Caching im eCommerce</li>\n<li>Erfahrung in Headless-Architekturen oder mit der Shopware Store API</li>\n<li>Erste Berührungspunkte mit DevOps-Themen (Deployment, Monitoring)</li>\n</ul>\n<h2>Was Dich bei uns erwartet</h2>\n<ul>\n<li>Technische Verantwortung mit Gestaltungsspielraum. Du gestaltest unsere Entwicklungsstandards und Tooling-Entscheidungen mit.</li>\n<li>Kurze Entscheidungswege.</li>\n<li>Konkrete Tools: PhpStorm, GitHub, Docker und die Shopware Dev Tools. Die Wahl der Hardware gestalten wir gemeinsam nach Deinen Bedürfnissen.</li>\n<li>55.000 bis 65.000 € brutto/Jahr bei Vollzeit, je nach Erfahrung.</li>\n<li>30 Tage Urlaub.</li>\n<li>Weiterbildung nach Bedarf: Online-Kurs, Zertifizierung, Messebesuch, je nachdem worauf Du Lust hast und was zur Rolle passt.</li>\n<li>Arbeitsplatz im SteamWork Karlsruhe, einem CoWorking Space mit regelmäßigen Tech-Events und Netzwerkmöglichkeiten.</li>\n<li>Vollzeit oder Teilzeit möglich.</li>\n</ul>\n<h2>Bewerbung</h2>\n<p>Schick uns Deinen Lebenslauf und ein paar Sätze zu Dir. Ein klassisches Anschreiben brauchen wir nicht. Schreib uns kurz, was Dich an der Rolle interessiert und worauf Du aus Deiner letzten Position aufbauen willst. Wenn Du eigene Plugins, GitHub-Profile oder ähnliches hast, freuen wir uns über einen Link dazu.</p>\n<p>Fragen vorab? Dann melde Dich gerne direkt bei mir.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<h2>Über uns</h2>\n<p>Aurivian ist eine Shopware-Agentur aus Karlsruhe. Wir entwickeln, betreiben und optimieren eCommerce-Lösungen auf Basis von Shopware 6 für mittelständische Händler im DACH-Raum. Wir sind ein kleines Team und wollen weiterwachsen, daher suchen wir für den Bereich Entwicklung Verstärkung.</p>\n<h2>Deine Rolle</h2>\n<p>Als Shopware Entwickler (m/w/d) bist Du Teil unseres Entwicklerteams und setzt Kundenprojekte auf Basis von Shopware 6 um. Schwerpunkt ist Backend-Entwicklung in PHP und Symfony. Storefront-Anpassungen in Twig, SCSS und JavaScript sowie die Integration externer Systeme gehören dazu.</p>\n<p>Du arbeitest eigenverantwortlich an Deinen Themen, bringst Deine technische Perspektive aktiv in Architektur- und Technologieentscheidungen ein und entwickelst im Austausch mit Team und Entwicklungsleitung gemeinsam passende Lösungen weiter.</p>\n<h2>Deine Aufgaben</h2>\n<ul>\n<li>Entwicklung von Shopware-Plugins und individuellen Erweiterungen</li>\n<li>Umsetzung kundenspezifischer Anforderungen mit Schwerpunkt Backend</li>\n<li>Storefront-Anpassungen in Twig, SCSS und JavaScript</li>\n<li>Integration externer Systeme und Services über REST-APIs</li>\n<li>Code Reviews und technische Dokumentation</li>\n<li>Technische Rückkopplung mit Projektmanagement und Kunden</li>\n<li>Mitgestaltung interner Dev-Prozesse, CI/CD-Workflows und Standards</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>2 bis 5 Jahre Erfahrung in der objektorientierten PHP-Entwicklung</li>\n<li>Fundierte Kenntnisse in Symfony, Twig, MySQL und Git</li>\n<li>Praxiserfahrung mit Shopware 6 (eigene Plugins, Customizing oder Zertifizierungen)</li>\n<li>Grundkenntnisse in Frontend-Technologien (HTML, CSS, JavaScript)</li>\n<li>Erfahrung mit API-Design und Systemintegration</li>\n<li>Vertraut mit modernen Dev-Setups (Docker, GitHub, Testing, CI/CD)</li>\n<li>Strukturierte, eigenverantwortliche Arbeitsweise</li>\n<li>Gutes Deutsch in Wort und Schrift (Level B2+)</li>\n</ul>\n<h2>Bonuspunkte gibt’s für</h2>\n<ul>\n<li>Shopware-Zertifikate (Backend Developer, Frontend Developer)</li>\n<li>Erfahrung mit Vue.js oder vergleichbaren Frontend-Frameworks</li>\n<li>Erfahrung mit weiteren PHP Backend-Frameworks</li>\n<li>Erfahrung mit Performance-Optimierung und Caching im eCommerce</li>\n<li>Erfahrung in Headless-Architekturen oder mit der Shopware Store API</li>\n<li>Erste Berührungspunkte mit DevOps-Themen (Deployment, Monitoring)</li>\n</ul>\n<h2>Was Dich bei uns erwartet</h2>\n<ul>\n<li>Technische Verantwortung mit Gestaltungsspielraum. Du gestaltest unsere Entwicklungsstandards und Tooling-Entscheidungen mit.</li>\n<li>Kurze Entscheidungswege.</li>\n<li>Konkrete Tools: PhpStorm, GitHub, Docker und die Shopware Dev Tools. Die Wahl der Hardware gestalten wir gemeinsam nach Deinen Bedürfnissen.</li>\n<li>55.000 bis 65.000 € brutto/Jahr bei Vollzeit, je nach Erfahrung.</li>\n<li>30 Tage Urlaub.</li>\n<li>Weiterbildung nach Bedarf: Online-Kurs, Zertifizierung, Messebesuch, je nachdem worauf Du Lust hast und was zur Rolle passt.</li>\n<li>Arbeitsplatz im SteamWork Karlsruhe, einem CoWorking Space mit regelmäßigen Tech-Events und Netzwerkmöglichkeiten.</li>\n<li>Vollzeit oder Teilzeit möglich.</li>\n</ul>\n<h2>Bewerbung</h2>\n<p>Schick uns Deinen Lebenslauf und ein paar Sätze zu Dir. Ein klassisches Anschreiben brauchen wir nicht. Schreib uns kurz, was Dich an der Rolle interessiert und worauf Du aus Deiner letzten Position aufbauen willst. Wenn Du eigene Plugins, GitHub-Profile oder ähnliches hast, freuen wir uns über einen Link dazu.</p>\n<p>Fragen vorab? Dann melde Dich gerne direkt bei mir.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-07 03:14:44.820', '2026-06-07 03:14:44.820', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/aurivian-gmbh/shopware-entwickler-fullstack-karlsruhe-62007', '', '[]', 'pending', '', NULL),
(287, NULL, 'api', NULL, 'Platform & Infrastructure Engineer (m/w/d)', 'Aurivian GmbH', 'Karlsruhe', 'https://www.arbeitnow.com/jobs/companies/aurivian-gmbh/platform-infrastructure-engineer-karlsruhe-156449', '<h2>Über uns</h2>\n<p>Aurivian ist eine Shopware-Agentur aus Karlsruhe. Wir entwickeln, betreiben und optimieren eCommerce-Lösungen auf Basis von Shopware 6 für mittelständische Händler im DACH-Raum. Wir sind ein kleines Team und wollen weiterwachsen, daher suchen wir für unseren Infrastrukturbereich Verstärkung.</p>\n<h2>Deine Rolle</h2>\n<p>Als Platform &#x26; Infrastructure Engineer verantwortest Du Aufbau und Betrieb unserer technischen Plattform. Du sorgst dafür, dass unsere Kundenshops stabil, performant und sicher laufen, baust unsere CI/CD-Strukturen aus und entlastest das Entwicklerteam von Infrastruktur- und Security-Themen.</p>\n<p>Heute laufen unsere Kundenshops auf Hetzner und anderen Cloudhosting Partnern. Mittelfristig wollen wir zusätzlich Shopware PaaS (auf Upsun-Basis) und Shopware PaaS Native (auf AWS-Basis) anbieten. Diesen Aufbau treibst Du gemeinsam mit uns.</p>\n<p>Unser Infrastrukturbereich ist aktuell noch Greenfield. Das gibt Dir die Möglichkeit, Architektur, Prozesse und Tooling aktiv mitzugestalten, statt bestehende Strukturen nur zu verwalten. Du arbeitest eigenverantwortlich und stimmst Dich bei strategischen Themen direkt mit Geschäftsführung und Entwicklungsleitung ab.</p>\n<h2>Deine Aufgaben</h2>\n<ul>\n<li>Konfiguration und Betrieb unserer Cloud- und Server-Infrastruktur für Kundenshops</li>\n<li>Aufbau eines Shopware-PaaS-Angebots auf Upsun-Basis (mittelfristig auch AWS möglich)</li>\n<li>Administration und Optimierung von Hosting-Umgebungen, Clustern und Deployments</li>\n<li>Aufbau und Weiterentwicklung von CI/CD-Workflows</li>\n<li>Monitoring, Logging und Reporting der System Health</li>\n<li>Performance-Optimierung im eCommerce-Kontext</li>\n<li>Umsetzung und Weiterentwicklung von IT-Sicherheitsmaßnahmen (z.B. DNS, Zero Trust, Zugriffskonzepte)</li>\n<li>Verwaltung interner IT-Systeme (MDM, Entra ID, Hardware, Software)</li>\n<li>Automatisierung wiederkehrender Prozesse</li>\n<li>Enge Abstimmung mit dem Entwicklerteam bei Architektur- und Infrastrukturentscheidungen</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>2 bis 5 Jahre Erfahrung im Betrieb von Web- und Cloud-Infrastrukturen</li>\n<li>Solide Linux-Server-Administration</li>\n<li>Praxis mit Docker und CI/CD-Tools (GitHub Actions, GitLab CI oder vergleichbar)</li>\n<li>Erfahrung mit Git-basierten Workflows</li>\n<li>Verständnis für Web-Performance, Security und Skalierung</li>\n<li>Idealerweise Erfahrung im eCommerce- oder SaaS-Umfeld</li>\n<li>Strukturierte, eigenverantwortliche Arbeitsweise</li>\n<li>Gutes Deutsch in Wort und Schrift (Level B2+)</li>\n</ul>\n<h2>Bonuspunkte gibt\'s für</h2>\n<ul>\n<li>Erfahrung mit Shopware 6 oder einem vergleichbaren PHP-eCommerce-System</li>\n<li>Kenntnisse in Infrastructure as Code (Terraform, Ansible)</li>\n<li>Erfahrung mit Upsun, <a href=\"http://Platform.sh\">Platform.sh</a> oder Kubernetes</li>\n<li>AWS-Zertifizierungen</li>\n</ul>\n<h2>Was Dich bei uns erwartet</h2>\n<ul>\n<li>Technische Verantwortung mit Gestaltungsspielraum. Du baust unseren Infrastrukturbereich von Grund auf mit.</li>\n<li>Kurze Entscheidungswege.</li>\n<li>Moderne Hardware und freie Toolauswahl.</li>\n<li>55.000 bis 65.000 € brutto/Jahr bei Vollzeit, je nach Erfahrung.</li>\n<li>30 Tage Urlaub.</li>\n<li>Weiterbildung nach Bedarf: Online-Kurs, Zertifizierung, Messebesuch, je nachdem worauf Du Lust hast und was zur Rolle passt.</li>\n<li>Arbeitsplatz im SteamWork Karlsruhe, einem CoWorking Space mit regelmäßigen Tech-Events und Netzwerkmöglichkeiten.</li>\n<li>Vollzeit oder Teilzeit möglich.</li>\n</ul>\n<h2>Bewerbung</h2>\n<p>Schick uns Deinen Lebenslauf und ein paar Sätze zu Dir. Ein klassisches Anschreiben brauchen wir nicht. Schreib uns kurz, was Dich an der Rolle interessiert und worauf Du aus Deiner letzten Position aufbauen willst.</p>\n<p>Fragen vorab? Dann melde Dich gerne direkt bei uns!</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>Über uns</h2>\n<p>Aurivian ist eine Shopware-Agentur aus Karlsruhe. Wir entwickeln, betreiben und optimieren eCommerce-Lösungen auf Basis von Shopware 6 für mittelständische Händler im DACH-Raum. Wir sind ein kleines Team und wollen weiterwachsen, daher suchen wir für unseren Infrastrukturbereich Verstärkung.</p>\n<h2>Deine Rolle</h2>\n<p>Als Platform &#x26; Infrastructure Engineer verantwortest Du Aufbau und Betrieb unserer technischen Plattform. Du sorgst dafür, dass unsere Kundenshops stabil, performant und sicher laufen, baust unsere CI/CD-Strukturen aus und entlastest das Entwicklerteam von Infrastruktur- und Security-Themen.</p>\n<p>Heute laufen unsere Kundenshops auf Hetzner und anderen Cloudhosting Partnern. Mittelfristig wollen wir zusätzlich Shopware PaaS (auf Upsun-Basis) und Shopware PaaS Native (auf AWS-Basis) anbieten. Diesen Aufbau treibst Du gemeinsam mit uns.</p>\n<p>Unser Infrastrukturbereich ist aktuell noch Greenfield. Das gibt Dir die Möglichkeit, Architektur, Prozesse und Tooling aktiv mitzugestalten, statt bestehende Strukturen nur zu verwalten. Du arbeitest eigenverantwortlich und stimmst Dich bei strategischen Themen direkt mit Geschäftsführung und Entwicklungsleitung ab.</p>\n<h2>Deine Aufgaben</h2>\n<ul>\n<li>Konfiguration und Betrieb unserer Cloud- und Server-Infrastruktur für Kundenshops</li>\n<li>Aufbau eines Shopware-PaaS-Angebots auf Upsun-Basis (mittelfristig auch AWS möglich)</li>\n<li>Administration und Optimierung von Hosting-Umgebungen, Clustern und Deployments</li>\n<li>Aufbau und Weiterentwicklung von CI/CD-Workflows</li>\n<li>Monitoring, Logging und Reporting der System Health</li>\n<li>Performance-Optimierung im eCommerce-Kontext</li>\n<li>Umsetzung und Weiterentwicklung von IT-Sicherheitsmaßnahmen (z.B. DNS, Zero Trust, Zugriffskonzepte)</li>\n<li>Verwaltung interner IT-Systeme (MDM, Entra ID, Hardware, Software)</li>\n<li>Automatisierung wiederkehrender Prozesse</li>\n<li>Enge Abstimmung mit dem Entwicklerteam bei Architektur- und Infrastrukturentscheidungen</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>2 bis 5 Jahre Erfahrung im Betrieb von Web- und Cloud-Infrastrukturen</li>\n<li>Solide Linux-Server-Administration</li>\n<li>Praxis mit Docker und CI/CD-Tools (GitHub Actions, GitLab CI oder vergleichbar)</li>\n<li>Erfahrung mit Git-basierten Workflows</li>\n<li>Verständnis für Web-Performance, Security und Skalierung</li>\n<li>Idealerweise Erfahrung im eCommerce- oder SaaS-Umfeld</li>\n<li>Strukturierte, eigenverantwortliche Arbeitsweise</li>\n<li>Gutes Deutsch in Wort und Schrift (Level B2+)</li>\n</ul>\n<h2>Bonuspunkte gibt\'s für</h2>\n<ul>\n<li>Erfahrung mit Shopware 6 oder einem vergleichbaren PHP-eCommerce-System</li>\n<li>Kenntnisse in Infrastructure as Code (Terraform, Ansible)</li>\n<li>Erfahrung mit Upsun, <a href=\"http://Platform.sh\">Platform.sh</a> oder Kubernetes</li>\n<li>AWS-Zertifizierungen</li>\n</ul>\n<h2>Was Dich bei uns erwartet</h2>\n<ul>\n<li>Technische Verantwortung mit Gestaltungsspielraum. Du baust unseren Infrastrukturbereich von Grund auf mit.</li>\n<li>Kurze Entscheidungswege.</li>\n<li>Moderne Hardware und freie Toolauswahl.</li>\n<li>55.000 bis 65.000 € brutto/Jahr bei Vollzeit, je nach Erfahrung.</li>\n<li>30 Tage Urlaub.</li>\n<li>Weiterbildung nach Bedarf: Online-Kurs, Zertifizierung, Messebesuch, je nachdem worauf Du Lust hast und was zur Rolle passt.</li>\n<li>Arbeitsplatz im SteamWork Karlsruhe, einem CoWorking Space mit regelmäßigen Tech-Events und Netzwerkmöglichkeiten.</li>\n<li>Vollzeit oder Teilzeit möglich.</li>\n</ul>\n<h2>Bewerbung</h2>\n<p>Schick uns Deinen Lebenslauf und ein paar Sätze zu Dir. Ein klassisches Anschreiben brauchen wir nicht. Schreib uns kurz, was Dich an der Rolle interessiert und worauf Du aus Deiner letzten Position aufbauen willst.</p>\n<p>Fragen vorab? Dann melde Dich gerne direkt bei uns!</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-07 03:14:52.657', '2026-06-07 03:14:52.657', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/aurivian-gmbh/platform-infrastructure-engineer-karlsruhe-156449', '', '[]', 'pending', '', NULL),
(288, NULL, 'api', NULL, 'Buchhalter (m/w/d) in Teilzeit (mind. 20 Std./Woche) gesucht!', 'Roos Vehicle Logistics GmbH', 'Ingolstadt', 'https://www.arbeitnow.com/jobs/companies/roos-vehicle-logistics-gmbh/buchhalter-in-teilzeit-mind-20-std-woche-gesucht-ingolstadt-385588', '<p>Für unsere Hauptverwaltung in Ingolstadt suchen wir ab sofort einen Buchhalter (m/w/d) in Teilzeit mind. 20 Std./Woche (mit Aufstockungsoption)</p>\n<p><strong>Ihre Aufgaben:</strong></p>\n<p>In dieser Position übernehmen Sie die kaufmännische Betreuung mehrerer Unternehmen. Ihr Fokus liegt dabei auf der Abwicklung des Tagesgeschäfts von Immobilienverwaltungsgesellschaften.</p>\n<ul>\n<li><strong>Finanzbuchhaltung</strong><br>\nEigenverantwortliche Durchführung der Kreditoren-, Debitoren-, Sachkonten- und Bankbuchhaltung.</li>\n<li><strong>Monats- und Jahresabschlüsse</strong><br>\nMitwirkung bzw. eigenständige Erstellung der Monatsabschlüsse (inkl. Umsatzsteuer-Voranmeldungen), sowie vorbereitende Tätigkeiten für den Jahresabschluss nach HGB.</li>\n<li><strong>Kostenrechnung und Reporting</strong><br>\nErstellung von monatlichen Managementreports. Weiterentwicklung der Kostenrechnung. Durchführung der laufenden Immobilienbuchhaltung.</li>\n<li><strong>Prozessoptimierung</strong><br>\nAktive Mitarbeit bei der Digitalisierung und Optimierung bestehender Buchhaltungsprozesse.</li>\n</ul>\n<p><strong>Damit überzeugen Sie uns:</strong></p>\n<ul>\n<li>Erfolgreich abgeschlossene kaufmännische Ausbildung mit Weiterbildung zum Bilanzbuchhalter (m/w/d) oder eine vergleichbare Qualifikation</li>\n<li>Kenntnisse in den gängigen MS-Office Produkten</li>\n<li>Grundkenntnisse in der Umsatzsteuer</li>\n<li>Grundkenntnisse in DATEV wünschenswert</li>\n</ul>\n<p><strong>Was wir Ihnen bieten:</strong></p>\n<ul>\n<li>\n<p>Einstiegsgehalt 25.000,- € Bruttojahresgehalt (bei 20 Std./Woche), abhängig von der Qualifikation und Berufserfahrung</p>\n</li>\n<li>\n<p>ein familiäres und wertschätzendes Arbeitsumfeld</p>\n</li>\n<li>\n<p>flache Hierarchien, kurze Entscheidungswege</p>\n</li>\n<li>\n<p>ein sicherer und unbefristeter Arbeitsplatz in einem wachsenden Unternehmen</p>\n</li>\n<li>\n<p>moderner Arbeitsplatz und optimale Arbeitsbedingungen</p>\n</li>\n<li>\n<p>planbare und flexible Arbeitszeiten, Möglichkeit zur Aufstockung der Stunden</p>\n</li>\n<li>\n<p>Mitarbeiter Benefits (wie z.B. Corporate Benefits, Jobrad, Sachbezugskarte, Zuschüsse zur VWL, betr. AV,..)</p>\n</li>\n<li>\n<p>regelmäßige Teamevents und Aktivitäten</p>\n</li>\n</ul>\n<p><strong>Haben wir Ihr Interesse geweckt?</strong></p>\n<p>Dann freuen wir uns auf ihre aussagekräftigen Bewerbungsunterlagen, unter Angabe Ihres frühestmöglichen Eintrittstermins, sowie Ihrer Gehaltsvorstellung.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Für unsere Hauptverwaltung in Ingolstadt suchen wir ab sofort einen Buchhalter (m/w/d) in Teilzeit mind. 20 Std./Woche (mit Aufstockungsoption)</p>\n<p><strong>Ihre Aufgaben:</strong></p>\n<p>In dieser Position übernehmen Sie die kaufmännische Betreuung mehrerer Unternehmen. Ihr Fokus liegt dabei auf der Abwicklung des Tagesgeschäfts von Immobilienverwaltungsgesellschaften.</p>\n<ul>\n<li><strong>Finanzbuchhaltung</strong><br>\nEigenverantwortliche Durchführung der Kreditoren-, Debitoren-, Sachkonten- und Bankbuchhaltung.</li>\n<li><strong>Monats- und Jahresabschlüsse</strong><br>\nMitwirkung bzw. eigenständige Erstellung der Monatsabschlüsse (inkl. Umsatzsteuer-Voranmeldungen), sowie vorbereitende Tätigkeiten für den Jahresabschluss nach HGB.</li>\n<li><strong>Kostenrechnung und Reporting</strong><br>\nErstellung von monatlichen Managementreports. Weiterentwicklung der Kostenrechnung. Durchführung der laufenden Immobilienbuchhaltung.</li>\n<li><strong>Prozessoptimierung</strong><br>\nAktive Mitarbeit bei der Digitalisierung und Optimierung bestehender Buchhaltungsprozesse.</li>\n</ul>\n<p><strong>Damit überzeugen Sie uns:</strong></p>\n<ul>\n<li>Erfolgreich abgeschlossene kaufmännische Ausbildung mit Weiterbildung zum Bilanzbuchhalter (m/w/d) oder eine vergleichbare Qualifikation</li>\n<li>Kenntnisse in den gängigen MS-Office Produkten</li>\n<li>Grundkenntnisse in der Umsatzsteuer</li>\n<li>Grundkenntnisse in DATEV wünschenswert</li>\n</ul>\n<p><strong>Was wir Ihnen bieten:</strong></p>\n<ul>\n<li>\n<p>Einstiegsgehalt 25.000,- € Bruttojahresgehalt (bei 20 Std./Woche), abhängig von der Qualifikation und Berufserfahrung</p>\n</li>\n<li>\n<p>ein familiäres und wertschätzendes Arbeitsumfeld</p>\n</li>\n<li>\n<p>flache Hierarchien, kurze Entscheidungswege</p>\n</li>\n<li>\n<p>ein sicherer und unbefristeter Arbeitsplatz in einem wachsenden Unternehmen</p>\n</li>\n<li>\n<p>moderner Arbeitsplatz und optimale Arbeitsbedingungen</p>\n</li>\n<li>\n<p>planbare und flexible Arbeitszeiten, Möglichkeit zur Aufstockung der Stunden</p>\n</li>\n<li>\n<p>Mitarbeiter Benefits (wie z.B. Corporate Benefits, Jobrad, Sachbezugskarte, Zuschüsse zur VWL, betr. AV,..)</p>\n</li>\n<li>\n<p>regelmäßige Teamevents und Aktivitäten</p>\n</li>\n</ul>\n<p><strong>Haben wir Ihr Interesse geweckt?</strong></p>\n<p>Dann freuen wir uns auf ihre aussagekräftigen Bewerbungsunterlagen, unter Angabe Ihres frühestmöglichen Eintrittstermins, sowie Ihrer Gehaltsvorstellung.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-07 03:14:59.241', '2026-06-07 03:14:59.241', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/roos-vehicle-logistics-gmbh/buchhalter-in-teilzeit-mind-20-std-woche-gesucht-ingolstadt-385588', '', '[]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(289, NULL, 'api', NULL, 'Mediengestalter (m/w/d)', 'BUZIL-WERK Wagner GmbH & Co. KG', 'Memmingen', 'https://www.arbeitnow.com/jobs/companies/buzil-werk-wagner-gmbh-co-kg/mediengestalter-memmingen-223473', '<p>Wir sind der kompetente Problemlöser und zuverlässige Partner für erstklassige und gleichzeitig effiziente Reinigungslösungen für professionelle Anwender. Über 130 Spezialisten unter einem Dach entwickeln, produzieren und vertreiben Reinigungs‑ und Pflegeprodukte. Am Standort Memmingen werden alle Buzil und Planta Produkte hergestellt, gelagert und kommissioniert. Die Lieferung an Großhändler erfolgt von hier über Speditionen in über 35 Länder. Uns gibt es in der professionellen Gebäudereinigung, der Industrie, Hotellerie und Gastronomie sowie in Alten‑ und Pflegeeinrichtungen. Im Geschäftsfeld Private Label werden individuelle Kundenwünsche von der ersten Idee bis zum fertigen Produkt entwickelt und produziert. Neben einer Tochtergesellschaft in Polen und einer Niederlassung in den Vereinigten Arabischen Emiraten gibt es auch Verkaufsbüros in den Balkanstaaten. Das Unternehmen wurde 1907 von Julius Wagner gegründet und ist seitdem im Familienbesitz.</p>\n<p><strong>Ihre Aufgaben</strong></p>\n<p>Als Mediengestalter (m/w/d) sind Sie Teil unseres Marketingteams und gestalten den visuellen und inhaltlichen Marken auftritt – von Print‑ und Produktmedien bis hin zu digitalen Anwendungen.</p>\n<p><strong>Print &#x26; Digital Design</strong></p>\n<ul>\n<li>Gestaltung und Überarbeitung von Printmedien (z. B. Broschüren, Flyer, Etiketten sowie Messe‑ und Präsentationsunterlagen)</li>\n<li>Umsetzung und Pflege von digitalen Inhalten für unsere Website und Marketingkampagnen</li>\n<li>Erstellung druckfertiger Daten sowie Abstimmung mit externen Dienstleistern</li>\n</ul>\n<p><strong>Content &#x26; Produktkommunikation</strong></p>\n<ul>\n<li>Erstellung und Überarbeitung von produktbezogenen Texten (z. B. One‑Pager &#x26; Datenblätter) nach bestehenden Strukturen</li>\n<li>Unterstützung bei Newsletter‑ und Social‑Media‑Inhalten (LinkedIn, Facebook und Instagram)</li>\n</ul>\n<p><strong>Produktdaten &#x26; Corporate Design</strong></p>\n<ul>\n<li>Pflege von Produktdaten, Bildern und Downloads im PIM‑System sowie Sicherstellung, dass die Inhalte stets aktuell und konsistent sind</li>\n<li>Umsetzung von Artwork‑ und Etikettenanpassungen auf Basis bestehender Templates</li>\n<li>Mitarbeit bei der Anwendung und Weiterentwicklung des Corporate Designs sowie Pflege bestehender Vorlagen</li>\n</ul>\n<p><strong>Ihr Profil:</strong></p>\n<ul>\n<li>Abgeschlossene Ausbildung als Mediengestalter Digital &#x26; Print oder eine vergleichbare Qualifikation</li>\n<li>Sehr gute Kenntnisse in der Adobe Creative Cloud (InDesign, Illustrator, Photoshop)</li>\n<li>Kenntnisse in Premiere Pro und After Effects sind von Vorteil</li>\n<li>Sicherer Umgang mit Layout, Typografie und Druckdaten</li>\n<li>Strukturierte, sorgfältige Arbeitsweise und ein gutes Auge für Details</li>\n<li>Interesse an produktnaher Kommunikation und klaren Markenauftritten im B2B‑Umfeld</li>\n<li>Teamfähigkeit und selbstständiges Arbeiten</li>\n<li>Sehr gute Deutschkenntnisse, gute Englischkenntnisse</li>\n</ul>\n<p><strong>Wir bieten Ihnen:</strong></p>\n<ul>\n<li>Das zukünftige Gehalt wird im 1. Vorstellungsgespräch erörtert</li>\n<li>Flache Hierarchien und kurze Entscheidungswege</li>\n<li>Moderne Arbeitsmittel (Laptop, Handy usw.)</li>\n<li>Great Place To Work Auszeichnung</li>\n<li>Umfassendes Onboarding &#x26; Teambuilding Events</li>\n<li>30 Tage Jahresurlaub</li>\n<li>Betriebliche Altersversorgung &#x26; Buzil Gesundheitsprogramm</li>\n<li>Gruppenunfallversicherung</li>\n</ul>\n<h2><strong>Interesse:</strong></h2>\n<p>Einfach Bewerbung inkl. Lebenslauf, Zeugnissen sowie relevanten Arbeitsproben bzw. einem Portfolio über das Bewerbungsformular unter „Jetzt bewerben“ zusenden.</p>\n<p><strong>Adresse:</strong><br>\nBUZIL-WERK Wagner GmbH &#x26; Co. KG.<br>\nPersonalabteilung<br>\nFraunhoferstraße 17<br>\n87700 Memmingen</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Wir sind der kompetente Problemlöser und zuverlässige Partner für erstklassige und gleichzeitig effiziente Reinigungslösungen für professionelle Anwender. Über 130 Spezialisten unter einem Dach entwickeln, produzieren und vertreiben Reinigungs‑ und Pflegeprodukte. Am Standort Memmingen werden alle Buzil und Planta Produkte hergestellt, gelagert und kommissioniert. Die Lieferung an Großhändler erfolgt von hier über Speditionen in über 35 Länder. Uns gibt es in der professionellen Gebäudereinigung, der Industrie, Hotellerie und Gastronomie sowie in Alten‑ und Pflegeeinrichtungen. Im Geschäftsfeld Private Label werden individuelle Kundenwünsche von der ersten Idee bis zum fertigen Produkt entwickelt und produziert. Neben einer Tochtergesellschaft in Polen und einer Niederlassung in den Vereinigten Arabischen Emiraten gibt es auch Verkaufsbüros in den Balkanstaaten. Das Unternehmen wurde 1907 von Julius Wagner gegründet und ist seitdem im Familienbesitz.</p>\n<p><strong>Ihre Aufgaben</strong></p>\n<p>Als Mediengestalter (m/w/d) sind Sie Teil unseres Marketingteams und gestalten den visuellen und inhaltlichen Marken auftritt – von Print‑ und Produktmedien bis hin zu digitalen Anwendungen.</p>\n<p><strong>Print &#x26; Digital Design</strong></p>\n<ul>\n<li>Gestaltung und Überarbeitung von Printmedien (z. B. Broschüren, Flyer, Etiketten sowie Messe‑ und Präsentationsunterlagen)</li>\n<li>Umsetzung und Pflege von digitalen Inhalten für unsere Website und Marketingkampagnen</li>\n<li>Erstellung druckfertiger Daten sowie Abstimmung mit externen Dienstleistern</li>\n</ul>\n<p><strong>Content &#x26; Produktkommunikation</strong></p>\n<ul>\n<li>Erstellung und Überarbeitung von produktbezogenen Texten (z. B. One‑Pager &#x26; Datenblätter) nach bestehenden Strukturen</li>\n<li>Unterstützung bei Newsletter‑ und Social‑Media‑Inhalten (LinkedIn, Facebook und Instagram)</li>\n</ul>\n<p><strong>Produktdaten &#x26; Corporate Design</strong></p>\n<ul>\n<li>Pflege von Produktdaten, Bildern und Downloads im PIM‑System sowie Sicherstellung, dass die Inhalte stets aktuell und konsistent sind</li>\n<li>Umsetzung von Artwork‑ und Etikettenanpassungen auf Basis bestehender Templates</li>\n<li>Mitarbeit bei der Anwendung und Weiterentwicklung des Corporate Designs sowie Pflege bestehender Vorlagen</li>\n</ul>\n<p><strong>Ihr Profil:</strong></p>\n<ul>\n<li>Abgeschlossene Ausbildung als Mediengestalter Digital &#x26; Print oder eine vergleichbare Qualifikation</li>\n<li>Sehr gute Kenntnisse in der Adobe Creative Cloud (InDesign, Illustrator, Photoshop)</li>\n<li>Kenntnisse in Premiere Pro und After Effects sind von Vorteil</li>\n<li>Sicherer Umgang mit Layout, Typografie und Druckdaten</li>\n<li>Strukturierte, sorgfältige Arbeitsweise und ein gutes Auge für Details</li>\n<li>Interesse an produktnaher Kommunikation und klaren Markenauftritten im B2B‑Umfeld</li>\n<li>Teamfähigkeit und selbstständiges Arbeiten</li>\n<li>Sehr gute Deutschkenntnisse, gute Englischkenntnisse</li>\n</ul>\n<p><strong>Wir bieten Ihnen:</strong></p>\n<ul>\n<li>Das zukünftige Gehalt wird im 1. Vorstellungsgespräch erörtert</li>\n<li>Flache Hierarchien und kurze Entscheidungswege</li>\n<li>Moderne Arbeitsmittel (Laptop, Handy usw.)</li>\n<li>Great Place To Work Auszeichnung</li>\n<li>Umfassendes Onboarding &#x26; Teambuilding Events</li>\n<li>30 Tage Jahresurlaub</li>\n<li>Betriebliche Altersversorgung &#x26; Buzil Gesundheitsprogramm</li>\n<li>Gruppenunfallversicherung</li>\n</ul>\n<h2><strong>Interesse:</strong></h2>\n<p>Einfach Bewerbung inkl. Lebenslauf, Zeugnissen sowie relevanten Arbeitsproben bzw. einem Portfolio über das Bewerbungsformular unter „Jetzt bewerben“ zusenden.</p>\n<p><strong>Adresse:</strong><br>\nBUZIL-WERK Wagner GmbH &#x26; Co. KG.<br>\nPersonalabteilung<br>\nFraunhoferstraße 17<br>\n87700 Memmingen</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-07 03:15:05.506', '2026-06-07 03:15:05.506', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/buzil-werk-wagner-gmbh-co-kg/mediengestalter-memmingen-223473', '', '[]', 'pending', '', NULL),
(290, NULL, 'api', NULL, 'SEO Nerd gesucht | Senior | 100% remote | Festangestellt / Freelance (m/w/d)', 'SichtbarerWerden GmbH', 'Nürnberg', 'https://www.arbeitnow.com/jobs/companies/sichtbarerwerden-gmbh/seo-nerd-gesucht-senior-100-remote-festangestellt-freelance-nurnberg-382517', '<p>Täglich ins Büro fahren, an langweiligen Projekten arbeiten, eingestaubte Agentur, in der kein frischer Wind weht? Wir verstehen dich – das ist kein Umfeld, in dem man wachsen kann.</p><p>Wir bei SichtbarerWerden machen es anders! Als aufstrebende Webdesign- und SEO-Agentur erstellen wir Websites, die unseren Kunden stetig mehr Kundenanfragen liefern und bei Google &amp; KI-Tools gefunden werden. So helfen wir ihnen dabei, langfristig zu skalieren und ihre ambitionierten Ziele zu erreichen.</p><p>Um unser Wachstum weiter voranzutreiben, suchen wir <strong>ab sofort eine/n SEO-Manager/in in Teilzeit/Vollzeit</strong>, die unsere Kundenprojekte betreut und für hohe Zufriedenheit sorgt.</p><p><br /></p><h3>Deine Aufgaben</h3><ul><li><p>Contentstrategien erstellen, Keywords recherchieren, Suchintention &amp; Zusammenhänge verstehen, Briefings schreiben: Du bist dafür verantwortlich, dass wir die richtigen Themen zur richtigen Zeit schreiben, um unsere Kunden auf Platz 1 zu bringen.</p></li><li><p>Du hast unsere Rankings - und die unserer Kunden im Blick und findest Optimierungspotenziale, um die Sichtbarkeit und Traffic + Conversions kontinuierlich zu verbessern.</p></li><li><p>Anforderungsmanagement zusammen mit dem Kunden</p></li><li><p>Entwicklung und Umsetzung von innovativen Konzepten und SEO-Strategien</p></li><li><p>Durchführung von Website Audits (primär auf Content-Ebene), Konkurrenzanalysen sowie Aufzeigen von Optimierungspotential</p></li><li><p>Monitoring und Controlling von laufenden SEO-Kampagnen</p></li></ul><ul><li><p>Du bringst praktische Erfahrungen im Bereich Suchmaschinenoptimierung mit (egal ob angestellt oder freiberuflich)</p></li><li><p>Dein SEO-Wissen ist aktuell und du arbeitest nutzerorientiert</p></li><li><p>Du hast ein gutes technisches Grundverständnis und interessierst dich für neue technische Entwicklungen, die Einfluss auf die Suchmaschinenoptimierung haben</p></li><li><p>Du beherrschst die gängigen SEO-Analyse-Tools (Search Console, Analytics - Sistrix, ahrefs &amp; Co.)</p></li><li><p>Du arbeitest gerne selbstständig und entwickelst eigene Konzepte, die du mit Zahlen belegst</p></li><li><p>Du verstehst es, dich in andere hineinzudenken und verfügst über sehr gute Deutschkenntnisse</p></li><li><p>Du bleibst gerne auf dem Laufenden und kannst dich für neue Themen begeistern</p></li><li><p>Deine Arbeitsweise ist strukturiert und ergebnisorientiert</p></li></ul><p><br /></p><h3><strong>WICHTIG, bitte beachten: </strong></h3><ul><li><p>Wir werden dich nach deiner Bewerbung <strong>unter deiner Nummer in Whatsapp</strong> kontaktieren für eine einfache und direkte Kommunikation. <strong>Wenn du dies nicht wünschst, sehe bitte von einer Bewerbung bei uns ab.</strong></p></li><li><p>Durch die Anzahl an Anfragen und dem Tagesgeschäft können wir keine Anrufe zu Fragen annehmen. Bitte sende uns bei Interesse eine aussagekräftige Bewerbung zu, wir melden uns dann bei dir zurück.</p></li></ul><p style=\";\"></p><p><strong>Wenn du bis hierhin gelesen hast, sollten wir unbedingt sprechen.</strong> Also bewirb dich jetzt und werde Teil unseres motivierten Teams bei SichtbarerWerden!</p><p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Täglich ins Büro fahren, an langweiligen Projekten arbeiten, eingestaubte Agentur, in der kein frischer Wind weht? Wir verstehen dich – das ist kein Umfeld, in dem man wachsen kann.</p><p>Wir bei SichtbarerWerden machen es anders! Als aufstrebende Webdesign- und SEO-Agentur erstellen wir Websites, die unseren Kunden stetig mehr Kundenanfragen liefern und bei Google &amp; KI-Tools gefunden werden. So helfen wir ihnen dabei, langfristig zu skalieren und ihre ambitionierten Ziele zu erreichen.</p><p>Um unser Wachstum weiter voranzutreiben, suchen wir <strong>ab sofort eine/n SEO-Manager/in in Teilzeit/Vollzeit</strong>, die unsere Kundenprojekte betreut und für hohe Zufriedenheit sorgt.</p><p><br /></p><h3>Deine Aufgaben</h3><ul><li><p>Contentstrategien erstellen, Keywords recherchieren, Suchintention &amp; Zusammenhänge verstehen, Briefings schreiben: Du bist dafür verantwortlich, dass wir die richtigen Themen zur richtigen Zeit schreiben, um unsere Kunden auf Platz 1 zu bringen.</p></li><li><p>Du hast unsere Rankings - und die unserer Kunden im Blick und findest Optimierungspotenziale, um die Sichtbarkeit und Traffic + Conversions kontinuierlich zu verbessern.</p></li><li><p>Anforderungsmanagement zusammen mit dem Kunden</p></li><li><p>Entwicklung und Umsetzung von innovativen Konzepten und SEO-Strategien</p></li><li><p>Durchführung von Website Audits (primär auf Content-Ebene), Konkurrenzanalysen sowie Aufzeigen von Optimierungspotential</p></li><li><p>Monitoring und Controlling von laufenden SEO-Kampagnen</p></li></ul><ul><li><p>Du bringst praktische Erfahrungen im Bereich Suchmaschinenoptimierung mit (egal ob angestellt oder freiberuflich)</p></li><li><p>Dein SEO-Wissen ist aktuell und du arbeitest nutzerorientiert</p></li><li><p>Du hast ein gutes technisches Grundverständnis und interessierst dich für neue technische Entwicklungen, die Einfluss auf die Suchmaschinenoptimierung haben</p></li><li><p>Du beherrschst die gängigen SEO-Analyse-Tools (Search Console, Analytics - Sistrix, ahrefs &amp; Co.)</p></li><li><p>Du arbeitest gerne selbstständig und entwickelst eigene Konzepte, die du mit Zahlen belegst</p></li><li><p>Du verstehst es, dich in andere hineinzudenken und verfügst über sehr gute Deutschkenntnisse</p></li><li><p>Du bleibst gerne auf dem Laufenden und kannst dich für neue Themen begeistern</p></li><li><p>Deine Arbeitsweise ist strukturiert und ergebnisorientiert</p></li></ul><p><br /></p><h3><strong>WICHTIG, bitte beachten: </strong></h3><ul><li><p>Wir werden dich nach deiner Bewerbung <strong>unter deiner Nummer in Whatsapp</strong> kontaktieren für eine einfache und direkte Kommunikation. <strong>Wenn du dies nicht wünschst, sehe bitte von einer Bewerbung bei uns ab.</strong></p></li><li><p>Durch die Anzahl an Anfragen und dem Tagesgeschäft können wir keine Anrufe zu Fragen annehmen. Bitte sende uns bei Interesse eine aussagekräftige Bewerbung zu, wir melden uns dann bei dir zurück.</p></li></ul><p style=\";\"></p><p><strong>Wenn du bis hierhin gelesen hast, sollten wir unbedingt sprechen.</strong> Also bewirb dich jetzt und werde Teil unseres motivierten Teams bei SichtbarerWerden!</p><p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-07 03:15:12.777', '2026-06-07 03:15:12.777', '', '', 'Remote', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/sichtbarerwerden-gmbh/seo-nerd-gesucht-senior-100-remote-festangestellt-freelance-nurnberg-382517', '', '[]', 'pending', '', NULL),
(291, NULL, 'api', NULL, 'Operations Manager Sportevents (m/w/d) Organisation & Marketing in Teilzeit', 'TF Wettkampfservices GmbH', 'Pfullingen', 'https://www.arbeitnow.com/jobs/companies/tf-wettkampfservices-gmbh/operations-manager-sportevents-organisation-marketing-in-teilzeit-pfullingen-411350', '<p>Die <strong>TF Wettkampfservices GmbH</strong> steht für professionelle Zeitmessung, innovative Eventtechnologie und perfekte Wettkampforganisation. Ob regionale Laufveranstaltung oder Deutsche Meisterschaft – wir sorgen dafür, dass Ergebnisse präzise erfasst und Veranstaltungen professionell umgesetzt werden. Wir wachsen – und suchen jemanden, der mit uns als <strong>Operations Manager in Teilzeit (15-20 Stunden)</strong> Strukturen ausbaut und Dinge voranbringt.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Mission</strong></p>\n<p>Du sorgst dafür, dass unser Tagesgeschäft läuft und hilfst gleichzeitig dabei, unsere Sichtbarkeit und unser Geschäft weiter auszubauen. Du bist die Schnittstelle zwischen Organisation, Kunden und Marketing. Du hältst Themen zusammen, schaffst Ordnung und setzt Dinge eigenständig um.</p>\n<p><strong>Deine Aufgaben</strong></p>\n<ul>\n<li>Unterstützung der Geschäftsführung im operativen und kaufmännischen Tagesgeschäft</li>\n<li>Kundenbetreuung und Kundenkommunikation</li>\n<li>Unterstützung bei der Organisation unserer Sportevents</li>\n<li>Pflege und Weiterentwicklung unserer Social-Media-Kanäle und unserer Onlineauftritte</li>\n<li>Unterstützung bei der Bearbeitung von Anfragen und Akquise</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Das bringst du mit</p>\n<ul>\n<li>Du arbeitest selbstständig, strukturiert und zuverlässig</li>\n<li>Du hast Lust, Verantwortung zu übernehmen und Prozesse zu entwickeln</li>\n<li>Du bist kommunikativ und gehst gerne auf Menschen zu</li>\n<li>Du bist bereit, gelegentlich am Wochenende auf unserer Veranstaltungen mitzuarbeiten</li>\n<li>Du hast Erfahrung im kaufmännischen Bereich und CSS-Grundkenntnisse (optional)</li>\n</ul>\n<h2>Benefits</h2>\n<p>Das bieten wir dir</p>\n<ul>\n<li>Eine zentrale Rolle mit echtem Einfluss auf unser Tagesgeschäft</li>\n<li>Direkte Zusammenarbeit mit der Geschäftsführung und damit kurze Entscheidungsprozesse</li>\n<li>Viel Verantwortung statt starre Aufgabenbereiche</li>\n<li>Flexible Arbeitszeiten mit 100 % Homeoffice</li>\n<li>Ein wachsendes Unternehmen, in dem Du wirklich etwas bewegen kannst</li>\n</ul>\n<p>Du musst nicht alles perfekt können. Unsere Philosophie: \"Hire for attitude, train for skill\". Schicke uns Deinen Lebenslauf mit ein paar ehrlichen Sätzen zu Dir und Deiner Gehaltsvorstellung.</p>\n<p>Die Stelle ist zunächst auf zwei Jahre befristet. Da diese Position eine wichtige Rolle für die weitere Entwicklung unseres Unternehmens spielt, bieten sich bei erfolgreicher Zusammenarbeit und positiver Geschäftsentwicklung attraktive Perspektiven für eine langfristige, unbefristete Beschäftigung.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Die <strong>TF Wettkampfservices GmbH</strong> steht für professionelle Zeitmessung, innovative Eventtechnologie und perfekte Wettkampforganisation. Ob regionale Laufveranstaltung oder Deutsche Meisterschaft – wir sorgen dafür, dass Ergebnisse präzise erfasst und Veranstaltungen professionell umgesetzt werden. Wir wachsen – und suchen jemanden, der mit uns als <strong>Operations Manager in Teilzeit (15-20 Stunden)</strong> Strukturen ausbaut und Dinge voranbringt.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Mission</strong></p>\n<p>Du sorgst dafür, dass unser Tagesgeschäft läuft und hilfst gleichzeitig dabei, unsere Sichtbarkeit und unser Geschäft weiter auszubauen. Du bist die Schnittstelle zwischen Organisation, Kunden und Marketing. Du hältst Themen zusammen, schaffst Ordnung und setzt Dinge eigenständig um.</p>\n<p><strong>Deine Aufgaben</strong></p>\n<ul>\n<li>Unterstützung der Geschäftsführung im operativen und kaufmännischen Tagesgeschäft</li>\n<li>Kundenbetreuung und Kundenkommunikation</li>\n<li>Unterstützung bei der Organisation unserer Sportevents</li>\n<li>Pflege und Weiterentwicklung unserer Social-Media-Kanäle und unserer Onlineauftritte</li>\n<li>Unterstützung bei der Bearbeitung von Anfragen und Akquise</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Das bringst du mit</p>\n<ul>\n<li>Du arbeitest selbstständig, strukturiert und zuverlässig</li>\n<li>Du hast Lust, Verantwortung zu übernehmen und Prozesse zu entwickeln</li>\n<li>Du bist kommunikativ und gehst gerne auf Menschen zu</li>\n<li>Du bist bereit, gelegentlich am Wochenende auf unserer Veranstaltungen mitzuarbeiten</li>\n<li>Du hast Erfahrung im kaufmännischen Bereich und CSS-Grundkenntnisse (optional)</li>\n</ul>\n<h2>Benefits</h2>\n<p>Das bieten wir dir</p>\n<ul>\n<li>Eine zentrale Rolle mit echtem Einfluss auf unser Tagesgeschäft</li>\n<li>Direkte Zusammenarbeit mit der Geschäftsführung und damit kurze Entscheidungsprozesse</li>\n<li>Viel Verantwortung statt starre Aufgabenbereiche</li>\n<li>Flexible Arbeitszeiten mit 100 % Homeoffice</li>\n<li>Ein wachsendes Unternehmen, in dem Du wirklich etwas bewegen kannst</li>\n</ul>\n<p>Du musst nicht alles perfekt können. Unsere Philosophie: \"Hire for attitude, train for skill\". Schicke uns Deinen Lebenslauf mit ein paar ehrlichen Sätzen zu Dir und Deiner Gehaltsvorstellung.</p>\n<p>Die Stelle ist zunächst auf zwei Jahre befristet. Da diese Position eine wichtige Rolle für die weitere Entwicklung unseres Unternehmens spielt, bieten sich bei erfolgreicher Zusammenarbeit und positiver Geschäftsentwicklung attraktive Perspektiven für eine langfristige, unbefristete Beschäftigung.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-07 03:15:20.227', '2026-06-07 03:15:20.227', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/tf-wettkampfservices-gmbh/operations-manager-sportevents-organisation-marketing-in-teilzeit-pfullingen-411350', '', '[]', 'pending', '', NULL),
(292, NULL, 'api', NULL, 'Vertriebsleiter:in / Head of Sales im Bereich Sachwert- & Finanzanlagen *', 'Ilias Vassiliou & Team / headhunter.digital / Recruiting für Digital, Sales, IT, KI, Automation', 'Rottweil', 'https://www.arbeitnow.com/jobs/companies/ilias-vassiliou-team-headhunterdigital-recruiting-fur-digital-sales-it-ki-automation/vertriebsleiterin-head-of-sales-im-sachwert-finanzhandel-villingen-schwenningen-390366', '<p>Für unseren Mandanten, ein wachstumsstarkes, inhabergeführtes Handelsunternehmen im Bereich <strong>Sachwerte &#x26; Finanzanlagen</strong>, suchen wir eine vertriebsstarke Führungspersönlichkeit, die nicht nur Teams verwaltet, sondern Vertriebssysteme baut.</p>\n<p>Diese Rolle ist nichts für Menschen, die gern fertige Strukturen übernehmen. Hier geht es darum, ein junges Sales-Team auf das nächste Level zu bringen, Inbound und Outbound sauber zu trennen, klare Prozesse zu schaffen, Gesprächsführung zu professionalisieren und aus einer sehr großen Lead-Basis planbar mehr Umsatz zu machen.</p>\n<p>Das Unternehmen verfügt über eine <strong>starke und bekannte Marke</strong>, eine <strong>große Kundenbasis</strong>, moderne <strong>digitale Marketingkanäle</strong> und ein <strong>enormes Lead-Potenzial</strong>. Was jetzt gebraucht wird: Jemand, der:die daraus ein skalierbares, datengetriebenes Sales-System formt und an vorderster Vertriebs-Front als Vorbild punktuell mitwirkt.</p>\n<p><strong>Was diese Rolle besonders macht ...</strong></p>\n<p>Hier gibt es keine Lead-Knappheit. Im Gegenteil: Das Unternehmen verfügt über einen eigenen Kunden- und Kontaktstamm von rund <strong>280.000 Kontakten,</strong> darunter Website-Besucher, Warenkorbabbrecher, Bestandskunden und Interessenten mit konkretem Kaufinteresse.</p>\n<p>Die Herausforderung liegt nicht darin, Leads zu finden. Die Herausforderung liegt darin, aus dieser Masse die richtigen Potenziale zu identifizieren, die Lead-Qualität systematisch zu erhöhen und Outbound so aufzubauen, dass daraus ein wiederholbares, skalierbares Umsatzsystem entsteht.</p>\n<p>Die Kundensegmente sind sehr unterschiedlich: Vom Einzelkunden mit einem Kaufvolumen von einmalig 200.000 € bis hin zu Kunden, die regelmäßig monatlich kleinere Beträge investieren. Genau deshalb braucht es eine saubere Segmentierung, passende Gesprächsstrategien und ein Team, das je nach Kundentyp sicher, verbindlich und abschlussorientiert agiert.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Du übernimmst die <strong>operative und strategische Verantwortung</strong> für ein aktuell vierköpfiges Vertriebsteam mit zwei Inbound- und zwei Outbound-Mitarbeitenden.</li>\n<li>Das Team ist noch jung, besteht teils aus entwicklungsfähigen Junior-Profilen, bringt aber bereits starke Einzelperformer mit. <strong>Deine Aufgabe ist es, diese Basis auszubauen</strong>: Durch klare Führung, bessere Prozesse, konsequentes Coaching und ein Performance-Verständnis, das sich an Zahlen, Qualität und Abschlüssen orientiert.</li>\n<li>Du arbeitest <strong>vor Ort</strong> eng mit dem Team, Marketing und der Geschäftsführung zusammen und hast direkten Einfluss auf die Weiterentwicklung des gesamten Vertriebsbereichs.</li>\n<li>Du baust den Vertrieb nicht theoretisch, sondern praktisch weiter aus. Dazu gehört, dass du <strong>Inbound und Outbound klar strukturierst</strong>, Verantwortlichkeiten schärfst und das bestehende Team in eine echte Performance-Einheit entwickelst.</li>\n<li><strong>Du entwickelst skalierbare Vertriebsprozesse</strong>, von der Lead-Priorisierung über Gesprächsleitfäden bis hin zu CRM-Workflows, KPI-Dashboards und Reporting-Strukturen. Aktuell ist die Gesprächsführung noch stark individuell geprägt. Deine Aufgabe ist es, daraus ein professionelles, messbares und trainierbares System zu machen.</li>\n<li><strong>Du coachst dein Team eng im Tagesgeschäft</strong>, hörst Gespräche mit, gibst direktes Feedback, entwickelst Trainingsformate und sorgst dafür, dass aus Junior-Profilen verlässliche Vertriebspersönlichkeiten werden.</li>\n<li><strong>Du optimierst kontinuierlich die Lead-Qualität</strong> und arbeitest eng mit Marketing und Geschäftsführung zusammen, um aus Website-Traffic, Bestandskunden, Warenkorbabbrechern und weiteren Datenquellen bessere Vertriebschancen zu machen.</li>\n<li>Und wichtig: <strong>Du bist selbst verkaufsstark</strong>. Du kannst regelmäßig selbst den Hörer in die Hand nehmen, Gespräche führen, Abschlüsse erzielen und deinem Team zeigen, wie exzellenter Vertrieb klingt.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Was du mitbringen solltest ...</strong></p>\n<ul>\n<li>Du hast <strong>Erfahrung in der Führung von Vertriebsteams</strong> und kannst nachweisen, dass du Vertriebsstrukturen nicht nur genutzt, sondern selbst aufgebaut oder skaliert hast.</li>\n<li>Besonders wichtig ist <strong>Erfahrung im Outbound Sales</strong>. Du weißt, wie man aus bestehenden Leads, Kundendaten und Kontaktlisten echte Verkaufschancen entwickelt. Du verstehst, welche KPIs zählen, wie man Gesprächsqualität messbar macht und wie ein Team täglich auf Aktivität, Pipeline, Conversion und Abschlussstärke geführt wird.</li>\n<li>Du bringst eine <strong>starke IT-, CRM- und Prozessaffinität</strong> mit. Tools, Dashboards, Telefonie-Systeme, Automatisierung und idealerweise <strong>auch KI-gestützte Ansätze</strong> sind für dich keine Fremdwörter, sondern geübte Hebel für besseren Vertrieb.</li>\n<li>Du bist <strong>analytisch</strong> genug, um <strong>datenbasiert</strong> zu steuern, und gleichzeitig <strong>vertriebsnah</strong> genug, um Menschen im Gespräch wirklich besser zu machen.</li>\n<li><strong>Du führst klar, direkt und leistungsorientiert,</strong> ohne dabei den Blick für Entwicklung, Motivation und Teamdynamik zu verlieren.</li>\n<li><strong>Erfahrung im Vertrieb von Finanzprodukten</strong>, Sachwerten, Premiumprodukten oder vergleichbarer beratungsintensiver Angebote ist ein Plus.</li>\n<li>Optional ist Erfahrung mit Webinar-, Online-Event- oder Community-getriebenem Vertrieb ebenso ein Vorteil.</li>\n<li>Du solltest <strong>bereit sein, vor Ort mit dem Sales-Team und der GF zu arbeiten</strong>. Gesucht werden Interessenten aus der <strong>Schwarzwaldregion im Dreieck Freiburg-Konstanz-Tübingen</strong> oder mit entsprechender Umzugsbereitschaft.</li>\n</ul>\n<p>Entscheidend ist: Du hast Lust auf Aufbau, Skalierung und Performance. Du möchtest nicht nur ein Team »betreuen«, sondern einen Vertrieb aktiv formen und auch persönlich von deiner Leistung sowie der Leistung des Teams profitieren.</p>\n<h2>Benefits</h2>\n<p><strong>Was dich erwartet ...</strong></p>\n<ul>\n<li>Du bekommst eine Rolle mit echter Gestaltungsfreiheit, direktem Zugang zur Geschäftsführung und viel Raum, um Strukturen, Prozesse und Teamaufbau maßgeblich zu prägen.</li>\n<li>Das Unternehmen bringt eine starke Marke, ein großes Kundenpotenzial, moderne Systeme und eine hohe Nachfrage in einem stabilen Marktumfeld mit. Gleichzeitig ist der Vertrieb noch nicht fertig gebaut → genau das ist die Chance.</li>\n<li>Die Vergütung besteht aus einem OTE zwischen €120k - €150k p.a. (nach oben offen, inkl. variabler Beteiligung an der Teamleistung) bei einem jeweiligen Fixum von 50%.</li>\n<li>Die variable Vergütung ist bewusst sehr leistungsorientiert und nach oben nicht gedeckelt. Gesucht wird jemand, der:die genau darin eine Chance sieht: Viel Verantwortung, viel Hebel, viel Upside.</li>\n</ul>\n<p><strong>Für wen diese Rolle ideal ist ...</strong></p>\n<ul>\n<li>Diese Position passt zu dir, wenn du Vertrieb als System verstehst aber trotzdem nah genug am Kunden bist, um selbst Abschlüsse zu machen.</li>\n<li>Wenn du gern mit jungen Teams arbeitest, Standards setzt, Prozesse baust, KPIs ernst nimmst und Menschen zu besserer Performance entwickelst.</li>\n<li>Wenn du nicht auf perfekte Strukturen wartest, sondern sie selbst schaffst.</li>\n<li>Und wenn dich eine Rolle reizt, in der du aus einer großen Lead-Basis, einem vorhandenen Team und einer starken Marktposition ein skalierbares Sales-Setup aufbauen kannst.</li>\n</ul>\n<p><strong>Interesse?</strong></p>\n<p>Dann freuen wir uns auf deinen Lebenslauf und ein paar konkrete Einblicke in das, was du bisher aufgebaut hast (gerne formlos per E-Mail / Nachricht):</p>\n<ul>\n<li>Welche Vertriebsteams hast du geführt oder skaliert?</li>\n<li>Welche Outbound-Strukturen hast du entwickelt?</li>\n<li>Welche KPIs, Umsätze oder Teamgrößen hast du verantwortet?</li>\n<li>Und warum ist genau diese Aufbaurolle der richtige nächste Schritt für dich?</li>\n</ul>\n<p>--</p>\n<p>Du kannst einen professionellen Prozess und zeitnahe Reaktionen von uns erwarten. Auch unterstützen wir dich dabei, dich optimal zu präsentieren und begleiten dich mit Rat &#x26; Tat im Prozess inkl. der Vertragsverhandlungen.</p>\n<p>Wir freuen uns schon sehr über deine Kontaktaufnahme!</p>\n<p>--</p>\n<p>* Diese Stelle steht allen Menschen offen, unabhängig von Geschlecht, Alter und anderen Merkmalen: m/w/d +</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Für unseren Mandanten, ein wachstumsstarkes, inhabergeführtes Handelsunternehmen im Bereich <strong>Sachwerte &#x26; Finanzanlagen</strong>, suchen wir eine vertriebsstarke Führungspersönlichkeit, die nicht nur Teams verwaltet, sondern Vertriebssysteme baut.</p>\n<p>Diese Rolle ist nichts für Menschen, die gern fertige Strukturen übernehmen. Hier geht es darum, ein junges Sales-Team auf das nächste Level zu bringen, Inbound und Outbound sauber zu trennen, klare Prozesse zu schaffen, Gesprächsführung zu professionalisieren und aus einer sehr großen Lead-Basis planbar mehr Umsatz zu machen.</p>\n<p>Das Unternehmen verfügt über eine <strong>starke und bekannte Marke</strong>, eine <strong>große Kundenbasis</strong>, moderne <strong>digitale Marketingkanäle</strong> und ein <strong>enormes Lead-Potenzial</strong>. Was jetzt gebraucht wird: Jemand, der:die daraus ein skalierbares, datengetriebenes Sale