(332, NULL, 'api', NULL, 'Operations staff', 'Blue Dart', 'Guwahati,', 'https://remoteOK.com/remote-jobs/remote-operations-staff-blue-dart-1132949', 'Qualification: Minimum 12th pass preferably Graduate.<br><br>Experience:<br><br>3-4 years of experience from hub background.<br><br>Age:28 to 32 years<br><br>Knowledge:<br><br>Should know local geography.<br><br>Skills:<br><br><br><ul><li> High organizational commitment</li><li> Good team worker</li><li> Preferably knows basic Computers</li><li> Good communication in Local/Hindi/English language</li></ul><br/><br/>Please mention the word **PRODIGIOUSLY** and tag RMjQuMTIwLjExMS4xNDQ= when applying to show you read the job post completely (#RMjQuMTIwLjExMS4xNDQ=). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', 'Qualification: Minimum 12th pass preferably Graduate.<br><br>Experience:<br><br>3-4 years of experience from hub background.<br><br>Age:28 to 32 years<br><br>Knowledge:<br><br>Should know local geography.<br><br>Skills:<br><br><br><ul><li> High organizational commitment</li><li> Good team worker</li><li> Preferably knows basic Computers</li><li> Good communication in Local/Hindi/English language</li></ul><br/><br/>Please mention the word **PRODIGIOUSLY** and tag RMjQuMTIwLjExMS4xNDQ= when applying to show you read the job post completely (#RMjQuMTIwLjExMS4xNDQ=). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', 'new', NULL, '2026-06-07 15:16:33.300', '2026-06-07 15:16:33.300', '', '', 'Remote', 'Europe', '', 'RemoteOK', 'API', 'READY', '', '', '', 'api', 'https://remoteOK.com/remote-jobs/remote-operations-staff-blue-dart-1132949', '', '[]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(333, NULL, 'api', NULL, 'Chief Operating Officer', 'Rose, Klein &amp; Marias', 'Sacramento, Sacramento, California, United States', 'https://remoteOK.com/remote-jobs/remote-chief-operating-officer-rose-klein-amp-marias-1132941', '<strong>Description<br><br></strong>Term of Employment: Full-time, Exempt<br><br>Reports to: Executive Director<br><br>Location: Remote (U.S.-based)<br><br><strong>Who We Are<br><br></strong>The Animal Legal Defense Fundâs mission is to protect the lives and advance the interests of animals through the legal system. The Animal Legal Defense Fund accomplishes this mission by filing high-impact lawsuits to protect animals from harm, providing free legal assistance and training to prosecutors to assure that animal abusers are held accountable for their crimes, supporting tough animal protection legislation and fighting legislation harmful to animals, gathering data about and advocating for effective regulation of animal exploitative industries and providing resources and opportunities to law students and professionals to advance the emerging field of animal law.<br><br><strong>Role Description<br><br></strong>The Chief Operating Officer (âCOOâ) is a member of the ALDF Senior Leadership Team and implements and oversees operations necessary to advance ALDFâs mission. The COO primarily will be responsible for enhancing the internal operations and infrastructure necessary for ALDFâs continued success and growth, as well as for directly managing the Human Resources, Technology, and Operations teams. This role will be responsible for ensuring the efficient, effective functioning and administration of the organization, advancing organizational growth and effective internal communications, optimizing resource allocation, while maintaining and building an excellent culture. The COO will supervise and coach a team of leaders and professionals and provide strategic guidance and support to the Executive Director, Leadership Team, and all staff members who report into and are stakeholders of the Operations functions.<br><br><strong>How You Will Make a Difference<br><br></strong><ul><li>Oversee the Human Resources, Technology, and Operations teams, managing the Directors of each of these departments and working with them to set department strategy, vision, and culture, as well as hiring, training, supervising, mentoring, and developing team members. </li><li>Determine and formulate policies and provide overall direction for ALDF operational activities in partnership with your department Directors and team members. </li><li>Direct and implement business objectives to ensure optimal operations, maximize returns on investments, and increase inter-departmental collaboration and productivity. Identify opportunities to increase the effectiveness and efficiency of internal operations. </li><li>Collaborate with ALDFâs Chief Financial Officer regarding shared services between the Human Resources and Finance departments, such as Payroll. </li><li>Work with your team leaders, the Executive Director, and Senior Leadership Team to prepare reports for key stakeholders such as the Board of Directors. </li><li>Direct the financial and budget activities for your teams, maximize outcomes, and increase efficiency. Work with the Senior Leadership Team and Directors to execute the annual budget planning process for your teams and monitor progress throughout the year. </li><li>Confer with fellow leaders and staff members to discuss issues, coordinate activities, and resolve problems. </li><li>Work with other members of the Senior Leadership Team to assess organizational risk and implement measures to ensure compliance and mitigate risk. Ensure that ALDF is operating in a manner that reflects sound controls, high mission impact, and manageable workloads for staff. </li><li>In partnership with the Senior Leadership Team, drive a positive, productive, and inclusive work environment at ALDF. </li><li>Oversee the development and implementation of practices that support a healthy culture across the organization, including strong internal communications and supporting the HR Director and other leaders in executing strategies that continuously improve ALDFâs culture. </li><li>Cultivate a positive and collaborative working relationship with fellow Leadership members and Programs staff, and support the Human Resources, Technology and Operations Directors in building strong cross-functional internal relationships. </li><li>Serve as an engaged and active member of the Senior Leadership Team and participate in and contribute to ALDF initiatives and processes. </li><li>Advise the Executive Director and Board on questions of organizational sustainability and other matters. </li><li>Oversee the development and implementation of programs and projects relating to infrastructure, Human Resources, Technology, and Operations and take the lead on internal change management for such initiatives. </li><li>Oversee the implementation and compliance with relevant ALDF policies, including record retention, technology use, employment and labor, communications standards. </li><li>Maintain a working knowledge of significant developments and trends in the fields of animal law. </li><li>Performing other duties as assigned. <br><br></li></ul><em>Please note, this job description is not intended to be a comprehensive list of all duties and responsibilities of the position, which are subject to change in order to best advance ALDFâs strategic objectives and mission.<br><br></em><strong>Requirements<br><br></strong><strong>We are Looking for Candidates With: <br><br></strong><ul><li>Strong leadership experience in a non-profit setting, which can take many forms. Preference for 10+ years of progressively responsible experience in a leadership capacity in at least two relevant areas of responsibility (Administration/ Operations, Human Resources, Technology). Preference for non-profit leadership experience and experience within a legal or law firm setting. We understand that candidates may not have direct experience with all of these responsibilities, and direct experience with each of these responsibilities is not required. </li><li>5+ years in a formal people leadership role, with a track record of modeling inclusive leadership for high performance teams. </li><li>A bachelor\'s degree in Business Administration, Management, or related field, or equivalent experience. Preference for advanced study in comparable areas (e.g., MBA, MA, or JD). </li><li>An understanding of and demonstrated commitment to the mission of the Animal Legal Defense Fund. Additionally, a demonstrated understanding of how legal action advances the organizationâs mission. </li><li>Exceptional leadership skills and experience expressing a vision for the organization and inspiring alignment to that vision. </li><li>Excellent written and verbal communication skills, including communicating with a variety of internal and external stakeholders. Strong listening and relationship building skills. </li><li>Excellent problem solving, critical thinking, and decision-making abilities. </li><li>Empathetic interpersonal and conflict resolution skills, with the ability to work collaboratively with others in a team-oriented environment and with external partners. </li><li>The ability to implement vision, think strategically, creatively problem solve, and exercise good judgment and self-control. </li><li>A commitment to working with integrity. </li><li>Experience with basic software applications, including Outlook, Word, Excel, and internet browsers. Experience with Salesforce preferred. </li><li>The ability to travel periodically for staff meetings and retreats (estimated 1-3 trips annually). Additionally, the COO must be available for periodic travel to conferences, training, Board meetings, and donor meetings as required.<br><br></li></ul><strong>We Offer Competitive Compensation With Excellent Benefits, Including<br><br></strong><ul><li>Starting annual salary of $203,838 for most geographic locations. </li><li>For candidates located within 25 miles of Washington D.C., Cotati, CA, or Los Angeles, starting salary is $214,567 </li><li>For candidates located within 25 miles of New York City or San Francisco, starting salary is $225,295. </li><li>To ensure salary equity, we do not negotiate salary outside of the published starting rate. Rate is determined by role, using set geographical factors. </li><li>Comprehensive health care, dental, life and vision benefits (100% employer paid); Flexible Spending Account (FSA) and Dependent Care Account (DCA) are also available. </li><li>192 hours of PTO. </li><li>19 paid holidays. </li><li>1-month paid sabbatical after 5 years of continuous employment. </li><li>16 weeks of paid parental leave. </li><li>401k plan with a maximum 5% employer contribution match after one year of employment. </li><li>Alternative work schedules (at managerâs discretion). </li><li>One-time remote work allowance of $750. </li><li>Annual professional development reimbursement of up to $1,000. <br><br></li></ul>Maintaining a healthy work/life balance is a core value for the Animal Legal Defense Fund.<br><br><strong>Additional Information<br><br></strong>This is a U.S.-based position. In compliance with federal law, all persons hired will be required to verify identity and eligibility to work in the United States and to complete the required employment eligibility verification form upon hire.<br><br>ALDF is an equal opportunity employer and committed to providing an employment environment which is welcoming of persons from diverse backgrounds and free from unlawful discrimination and harassment, and in which all legal rights of our employees are recognized and protected. ALDF conducts all internal and external operations, programs, and employment-related decision making (including hiring decisions) without regard to actual or perceived race, ancestry, color, religion, national origin, citizenship, immigration status, sex or gender (including pregnancy, childbirth, breastfeeding, or related medical conditions), gender identity or expression, political affiliation, disability or medical condition (including physical, intellectual, or psychiatric), sexual orientation, marital status, military or veteran status, genetic information, age, or other protected category, and in compliance with all applicable federal, state, and local anti-discrimination and anti-harassment laws.<br><br>Consistent with the organizationâs mission, our events are free of animal products and byproducts.<br><br><em><strong>The application deadline for this position is July 1, 2026. Applications will be reviewed on a rolling basis, so we encourage applicants to apply early as we may make a decision before the deadline closes.</strong></em><br/><br/>Please mention the word **TANTALIZE** and tag RMjQuMTIwLjExMS4xNDQ= when applying to show you read the job post completely (#RMjQuMTIwLjExMS4xNDQ=). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', '<strong>Description<br><br></strong>Term of Employment: Full-time, Exempt<br><br>Reports to: Executive Director<br><br>Location: Remote (U.S.-based)<br><br><strong>Who We Are<br><br></strong>The Animal Legal Defense Fundâs mission is to protect the lives and advance the interests of animals through the legal system. The Animal Legal Defense Fund accomplishes this mission by filing high-impact lawsuits to protect animals from harm, providing free legal assistance and training to prosecutors to assure that animal abusers are held accountable for their crimes, supporting tough animal protection legislation and fighting legislation harmful to animals, gathering data about and advocating for effective regulation of animal exploitative industries and providing resources and opportunities to law students and professionals to advance the emerging field of animal law.<br><br><strong>Role Description<br><br></strong>The Chief Operating Officer (âCOOâ) is a member of the ALDF Senior Leadership Team and implements and oversees operations necessary to advance ALDFâs mission. The COO primarily will be responsible for enhancing the internal operations and infrastructure necessary for ALDFâs continued success and growth, as well as for directly managing the Human Resources, Technology, and Operations teams. This role will be responsible for ensuring the efficient, effective functioning and administration of the organization, advancing organizational growth and effective internal communications, optimizing resource allocation, while maintaining and building an excellent culture. The COO will supervise and coach a team of leaders and professionals and provide strategic guidance and support to the Executive Director, Leadership Team, and all staff members who report into and are stakeholders of the Operations functions.<br><br><strong>How You Will Make a Difference<br><br></strong><ul><li>Oversee the Human Resources, Technology, and Operations teams, managing the Directors of each of these departments and working with them to set department strategy, vision, and culture, as well as hiring, training, supervising, mentoring, and developing team members. </li><li>Determine and formulate policies and provide overall direction for ALDF operational activities in partnership with your department Directors and team members. </li><li>Direct and implement business objectives to ensure optimal operations, maximize returns on investments, and increase inter-departmental collaboration and productivity. Identify opportunities to increase the effectiveness and efficiency of internal operations. </li><li>Collaborate with ALDFâs Chief Financial Officer regarding shared services between the Human Resources and Finance departments, such as Payroll. </li><li>Work with your team leaders, the Executive Director, and Senior Leadership Team to prepare reports for key stakeholders such as the Board of Directors. </li><li>Direct the financial and budget activities for your teams, maximize outcomes, and increase efficiency. Work with the Senior Leadership Team and Directors to execute the annual budget planning process for your teams and monitor progress throughout the year. </li><li>Confer with fellow leaders and staff members to discuss issues, coordinate activities, and resolve problems. </li><li>Work with other members of the Senior Leadership Team to assess organizational risk and implement measures to ensure compliance and mitigate risk. Ensure that ALDF is operating in a manner that reflects sound controls, high mission impact, and manageable workloads for staff. </li><li>In partnership with the Senior Leadership Team, drive a positive, productive, and inclusive work environment at ALDF. </li><li>Oversee the development and implementation of practices that support a healthy culture across the organization, including strong internal communications and supporting the HR Director and other leaders in executing strategies that continuously improve ALDFâs culture. </li><li>Cultivate a positive and collaborative working relationship with fellow Leadership members and Programs staff, and support the Human Resources, Technology and Operations Directors in building strong cross-functional internal relationships. </li><li>Serve as an engaged and active member of the Senior Leadership Team and participate in and contribute to ALDF initiatives and processes. </li><li>Advise the Executive Director and Board on questions of organizational sustainability and other matters. </li><li>Oversee the development and implementation of programs and projects relating to infrastructure, Human Resources, Technology, and Operations and take the lead on internal change management for such initiatives. </li><li>Oversee the implementation and compliance with relevant ALDF policies, including record retention, technology use, employment and labor, communications standards. </li><li>Maintain a working knowledge of significant developments and trends in the fields of animal law. </li><li>Performing other duties as assigned. <br><br></li></ul><em>Please note, this job description is not intended to be a comprehensive list of all duties and responsibilities of the position, which are subject to change in order to best advance ALDFâs strategic objectives and mission.<br><br></em><strong>Requirements<br><br></strong><strong>We are Looking for Candidates With: <br><br></strong><ul><li>Strong leadership experience in a non-profit setting, which can take many forms. Preference for 10+ years of progressively responsible experience in a leadership capacity in at least two relevant areas of responsibility (Administration/ Operations, Human Resources, Technology). Preference for non-profit leadership experience and experience within a legal or law firm setting. We understand that candidates may not have direct experience with all of these responsibilities, and direct experience with each of these responsibilities is not required. </li><li>5+ years in a formal people leadership role, with a track record of modeling inclusive leadership for high performance teams. </li><li>A bachelor\'s degree in Business Administration, Management, or related field, or equivalent experience. Preference for advanced study in comparable areas (e.g., MBA, MA, or JD). </li><li>An understanding of and demonstrated commitment to the mission of the Animal Legal Defense Fund. Additionally, a demonstrated understanding of how legal action advances the organizationâs mission. </li><li>Exceptional leadership skills and experience expressing a vision for the organization and inspiring alignment to that vision. </li><li>Excellent written and verbal communication skills, including communicating with a variety of internal and external stakeholders. Strong listening and relationship building skills. </li><li>Excellent problem solving, critical thinking, and decision-making abilities. </li><li>Empathetic interpersonal and conflict resolution skills, with the ability to work collaboratively with others in a team-oriented environment and with external partners. </li><li>The ability to implement vision, think strategically, creatively problem solve, and exercise good judgment and self-control. </li><li>A commitment to working with integrity. </li><li>Experience with basic software applications, including Outlook, Word, Excel, and internet browsers. Experience with Salesforce preferred. </li><li>The ability to travel periodically for staff meetings and retreats (estimated 1-3 trips annually). Additionally, the COO must be available for periodic travel to conferences, training, Board meetings, and donor meetings as required.<br><br></li></ul><strong>We Offer Competitive Compensation With Excellent Benefits, Including<br><br></strong><ul><li>Starting annual salary of $203,838 for most geographic locations. </li><li>For candidates located within 25 miles of Washington D.C., Cotati, CA, or Los Angeles, starting salary is $214,567 </li><li>For candidates located within 25 miles of New York City or San Francisco, starting salary is $225,295. </li><li>To ensure salary equity, we do not negotiate salary outside of the published starting rate. Rate is determined by role, using set geographical factors. </li><li>Comprehensive health care, dental, life and vision benefits (100% employer paid); Flexible Spending Account (FSA) and Dependent Care Account (DCA) are also available. </li><li>192 hours of PTO. </li><li>19 paid holidays. </li><li>1-month paid sabbatical after 5 years of continuous employment. </li><li>16 weeks of paid parental leave. </li><li>401k plan with a maximum 5% employer contribution match after one year of employment. </li><li>Alternative work schedules (at managerâs discretion). </li><li>One-time remote work allowance of $750. </li><li>Annual professional development reimbursement of up to $1,000. <br><br></li></ul>Maintaining a healthy work/life balance is a core value for the Animal Legal Defense Fund.<br><br><strong>Additional Information<br><br></strong>This is a U.S.-based position. In compliance with federal law, all persons hired will be required to verify identity and eligibility to work in the United States and to complete the required employment eligibility verification form upon hire.<br><br>ALDF is an equal opportunity employer and committed to providing an employment environment which is welcoming of persons from diverse backgrounds and free from unlawful discrimination and harassment, and in which all legal rights of our employees are recognized and protected. ALDF conducts all internal and external operations, programs, and employment-related decision making (including hiring decisions) without regard to actual or perceived race, ancestry, color, religion, national origin, citizenship, immigration status, sex or gender (including pregnancy, childbirth, breastfeeding, or related medical conditions), gender identity or expression, political affiliation, disability or medical condition (including physical, intellectual, or psychiatric), sexual orientation, marital status, military or veteran status, genetic information, age, or other protected category, and in compliance with all applicable federal, state, and local anti-discrimination and anti-harassment laws.<br><br>Consistent with the organizationâs mission, our events are free of animal products and byproducts.<br><br><em><strong>The application deadline for this position is July 1, 2026. Applications will be reviewed on a rolling basis, so we encourage applicants to apply early as we may make a decision before the deadline closes.</strong></em><br/><br/>Please mention the word **TANTALIZE** and tag RMjQuMTIwLjExMS4xNDQ= when applying to show you read the job post completely (#RMjQuMTIwLjExMS4xNDQ=). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', 'new', NULL, '2026-06-07 15:16:38.040', '2026-06-07 15:16:38.040', '', '', 'Remote', 'Europe', '', 'RemoteOK', 'API', 'READY', '', '', '', 'api', 'https://remoteOK.com/remote-jobs/remote-chief-operating-officer-rose-klein-amp-marias-1132941', '', '[]', 'pending', '', NULL),
(334, NULL, 'api', NULL, 'Donât See a Perfect Role Apply Anyway', 'Reducto', 'San Francisco,', 'https://remoteOK.com/remote-jobs/remote-dont-see-a-perfect-role-apply-anyway-reducto-1132975', '<strong><strong>About Reducto<br><br></strong></strong>Reducto is the agentic document platform for leading AI teams who demand enterprise performance at scale. We provide a comprehensive toolkit for working with documents the way a human would, combining custom in-house and leading frontier models to power efficient and accurate document workflows.<br><br>Weâve grown rapidly, increasing revenue 8x year over year and partnering with hundreds of companies, from leading AI teams like Harvey, Vanta, and Scale, to enterprise customers across FAANG and top trading firms.<br><br>Reducto has raised over $100M from world-class investors including a16z, Benchmark, and First Round Capital.<br><br><strong>The Opportunity<br><br></strong>Let us know what you want to do! We hire for talent and ambition first.<br><br><strong>About Reducto<br><br></strong><em>Nearly 80% of enterprise data is in unstructured formats like PDFs<br><br></em>PDFs are the status quo for enterprise knowledge in nearly every industry. Insurance claims, financial statements, invoices, and health records are all stored in a structure thatâs simply impractical for use in digital workflows. This isnât an inconvenienceâitâs a critical bottleneck that leads to dozens of wasted hours every week.<br><br><em>Traditional approaches fail at reliably extracting information in complex PDFs<br><br></em>OCR and even more sophisticated ML approaches work for simple text documents but are unreliable for anything more complex. Text from different columns are jumbled together, figures are ignored, and tables are a nightmare to get right. Overcoming this usually requires a large engineering effort dedicated to building specialized pipelines for every document type you work with.<br><br><strong>Reducto</strong><strong> breaks document layouts into subsections and then contextually parses each depending on the type of content.<br><br></strong>This Is Made Possible By a Combination Of Vision Models, LLMs, And a Suite Of Heuristics We Built Over Time. Put Simply, We Can Help You:<br><br><ul><li>Accurately extract text and tables even with nonstandard layouts</li><li>Automatically convert graphs to tabular data and summarize images in documents</li><li>Extract important fields from complex forms with simple, natural language instructions</li><li>Build powerful retrieval pipelines using Reductoâs document metadata</li><li>Intelligently chunk information using the documentâs layout data<br><br></li></ul>Benefits at Reducto<br><br><em>At Reducto, weâre invested in the well-being and growth of our team. Hereâs what we currently offer:<br><br></em><ul><li>Unlimited PTO: We believe great work requires recharging.</li><li>Lunch: Receive a free lunch to eat with your teammates daily at the office</li><li>Reimbursed Transportation: Provide us with your receipts and weâll take care of the costs</li><li>Insurance: Generous health insurance covering medical, dental, and vision.</li><li>Health and Wellness Budget: We provide up to $150/mo reimbursement for health and wellness spending, such as gym memberships, fitness classes, or similar.</li><li>Parental Leave: Work with us to build a leave schedule that works for you and your family<br><br></li></ul>Reducto is an Equal Opportunity Employer committed to diversity and inclusion in the workplace. All qualified applicants will receive consideration for employment without regard to sex, race, color, age, national origin, religion, physical and mental disability, genetic information, marital status, sexual orientation, gender identity/assignment, citizenship, pregnancy or maternity, protected veteran status, or any other status prohibited by applicable national, federal, state or local law.<br/><br/>Please mention the word **GLOWING** and tag RMjQ