INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(441, NULL, 'api', NULL, 'Hoteldirektor (m/w/d)', 'InterSPA Gruppe', 'Thurmansbang', 'https://www.arbeitnow.com/jobs/companies/interspa-gruppe/hoteldirektor-thurmansbang-131179', '<p>Die interSPA‑Gruppe zählt zu den führenden Unternehmen im deutschen Freizeit- und Urlaubssektor. Wir betreiben bundesweit Freizeit- und Erlebnisbäder, Thermen, SPAs, Fitnessclubs, Indoorspielplätze sowie Hotels und Resorts. Über 2,5 Millionen Gäste besuchen jährlich unsere Anlagen.</p>\n<p>Zur Verstärkung unseres Managements suchen wir engagierte Persönlichkeiten, die unsere Standorte mit Leidenschaft und Professionalität führen.</p>\n<p>Wir suchen zum nächstmöglichen Zeitpunkt für unser <strong>Dreiburgensee Naturhotel &#x26; SPA</strong></p>\n<p>eine/n</p>\n<p><strong>Hoteldirektor</strong> (m/w/d)</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Gesamtverantwortung für die operative und wirtschaftliche Leitung des Hotels</li>\n<li>Führung, Motivation und Weiterentwicklung des gesamten Hotelteams</li>\n<li>Sicherstellung höchster Gästezufriedenheit sowie Weiterentwicklung der Service- und Qualitätsstandards</li>\n<li>Repräsentation des Hotels gegenüber Gästen, Partnern, Behörden und regionalen Institutionen</li>\n<li>Unterstützung bei Vermarktung, Vertrieb und strategischer Positionierung des Hotels</li>\n<li>Erstellung von Budget, Forecasts und regelmäßigen Reportings an die Geschäftsleitung</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Abgeschlossene Ausbildung in der Hotellerie sowie mehrjährige Führungserfahrung in der 4‑Sterne‑Hotellerie (mind. 20 Mitarbeitende)</li>\n<li>Ausgeprägte Gastgeberqualitäten, hohe Serviceorientierung und Qualitätsbewusstsein</li>\n<li>Freundliches, vorbildliches und verbindliches Auftreten sowie hohe Belastbarkeit und ein gepflegtes Erscheinungsbild</li>\n<li>Eigeninitiative, Organisationsstärke und strukturierte Arbeitsweise</li>\n<li>Fundierte Kenntnisse in Preisstrategien, relevanten Vertriebskanälen und Revenue‑Management‑Tools; sicherer Umgang mit MS Office und gängigen Hotel‑Systemen (z.  Protel, IDeaS, MEWS, TAC, OpenTable)</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Verantwortungsvolle Führungsposition in einer wachsenden Unternehmensgruppe</li>\n<li>Hoher Gestaltungsspielraum und eigenverantwortliches Arbeiten</li>\n<li>Attraktives Vergütungspaket inkl. betrieblicher Altersvorsorge</li>\n<li>Professionelle Unterstützung durch unser zentrales Management</li>\n<li>Zahlreiche Mitarbeiterangebote bei über 800 Partnerunternehmen</li>\n</ul>\n<p>Wir freuen uns auf Ihre Bewerbung per E-Mail, bitte mit Angabe des frühestmöglichen Eintrittstermins und Ihrer Gehaltsvorstellung.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Die interSPA‑Gruppe zählt zu den führenden Unternehmen im deutschen Freizeit- und Urlaubssektor. Wir betreiben bundesweit Freizeit- und Erlebnisbäder, Thermen, SPAs, Fitnessclubs, Indoorspielplätze sowie Hotels und Resorts. Über 2,5 Millionen Gäste besuchen jährlich unsere Anlagen.</p>\n<p>Zur Verstärkung unseres Managements suchen wir engagierte Persönlichkeiten, die unsere Standorte mit Leidenschaft und Professionalität führen.</p>\n<p>Wir suchen zum nächstmöglichen Zeitpunkt für unser <strong>Dreiburgensee Naturhotel &#x26; SPA</strong></p>\n<p>eine/n</p>\n<p><strong>Hoteldirektor</strong> (m/w/d)</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Gesamtverantwortung für die operative und wirtschaftliche Leitung des Hotels</li>\n<li>Führung, Motivation und Weiterentwicklung des gesamten Hotelteams</li>\n<li>Sicherstellung höchster Gästezufriedenheit sowie Weiterentwicklung der Service- und Qualitätsstandards</li>\n<li>Repräsentation des Hotels gegenüber Gästen, Partnern, Behörden und regionalen Institutionen</li>\n<li>Unterstützung bei Vermarktung, Vertrieb und strategischer Positionierung des Hotels</li>\n<li>Erstellung von Budget, Forecasts und regelmäßigen Reportings an die Geschäftsleitung</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Abgeschlossene Ausbildung in der Hotellerie sowie mehrjährige Führungserfahrung in der 4‑Sterne‑Hotellerie (mind. 20 Mitarbeitende)</li>\n<li>Ausgeprägte Gastgeberqualitäten, hohe Serviceorientierung und Qualitätsbewusstsein</li>\n<li>Freundliches, vorbildliches und verbindliches Auftreten sowie hohe Belastbarkeit und ein gepflegtes Erscheinungsbild</li>\n<li>Eigeninitiative, Organisationsstärke und strukturierte Arbeitsweise</li>\n<li>Fundierte Kenntnisse in Preisstrategien, relevanten Vertriebskanälen und Revenue‑Management‑Tools; sicherer Umgang mit MS Office und gängigen Hotel‑Systemen (z.  Protel, IDeaS, MEWS, TAC, OpenTable)</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Verantwortungsvolle Führungsposition in einer wachsenden Unternehmensgruppe</li>\n<li>Hoher Gestaltungsspielraum und eigenverantwortliches Arbeiten</li>\n<li>Attraktives Vergütungspaket inkl. betrieblicher Altersvorsorge</li>\n<li>Professionelle Unterstützung durch unser zentrales Management</li>\n<li>Zahlreiche Mitarbeiterangebote bei über 800 Partnerunternehmen</li>\n</ul>\n<p>Wir freuen uns auf Ihre Bewerbung per E-Mail, bitte mit Angabe des frühestmöglichen Eintrittstermins und Ihrer Gehaltsvorstellung.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-09 15:17:50.106', '2026-06-09 15:17:50.106', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/interspa-gruppe/hoteldirektor-thurmansbang-131179', '', '[]', 'pending', '', NULL),
