INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(555, NULL, 'api', NULL, 'Senior Data Engineer', 'Onapsis', 'Biederbach Baden-Wurttemberg, Baden-Württemberg, Germany', 'https://www.arbeitnow.com/jobs/companies/onapsis/senior-data-engineer-biederbach-baden-wurttemberg-205487', '<p>&nbsp;</p>\n<h3>About the job</h3>\n<p>The world\'s most critical--and at risk--business applications have been neglected for far too long. <strong>Onapsis </strong>eliminates this blind spot by providing cybersecurity solutions dedicated to business-critical applications. Whether running on premises, in the cloud, or in a hybrid environment, Onapsis helps nearly 30% of the Forbes Global 100 understand the threats and risks across their SAP and Oracle landscapes.</p>\n<p>We are seeking a <strong>Senior Data Engineer</strong>&nbsp;to join our mission-driven team. This role is ideal for experienced data engineers with a proven track record in architecting scalable data pipelines, leveraging cloud technologies, and contributing to high-impact cybersecurity solutions. You will be responsible for building high-performance ETL frameworks, optimizing data platforms, and contributing directly to the enhancement of our customers\' threat detection, response, and remediation capabilities.</p>\n<h3>What you will be doing, your legacy:&nbsp;</h3>\n<p>You will be working directly with company Principal Engineers evaluating, scoping, proposing, and building features to fulfill business solution requirements to protect our customers. You will play a direct role in laying the technical foundation for a new product offering. Additionally, you will be working with Engineering and DevOps to deliver high-quality products and services while also working closely with security and IT professionals to ensure safe and secure best practices are followed.&nbsp;</p>\n<p><strong>Responsibilities:</strong></p>\n<ul>\n<li><strong>Architect and Design Scalable Data Solutions:</strong> Design/develop/maintain Data lakehouse solutions (Iceberg/Delta Lake /Hudi) applying industry best practices and structuring / optimizing the data according to data access patterns.</li>\n<li><strong>Data Pipeline Development:</strong> Implement ETL/ELT pipelines using cloud technologies (Spark / pySpark / Glue, Kinesis Streams / Iceberg) to load the data into a Lakehouse for both efficient ML processing and UI reporting.</li>\n<li>Implement data models and data processing frameworks (Spark, Kafka, Snowflake) to ingest, transform, and load large datasets into Data Lakehouse techs (Apache Iceberg, Apache Delta Lake or Apache Hudi), ensuring high availability and reliability of data.</li>\n<li><strong>Advanced Data Integration:</strong> Develop solutions that integrate multiple data sources into Snowflake or similar data warehouses to enable real-time analytics and reporting across dashboards.</li>\n<li><strong>AI/ML Integration:</strong> Collaborate with cross-functional teams to co-develop AI-driven features identifying patterns and anomalies in client data using AI/ML technologies (python).</li>\n<li><strong>Compliance and Security:</strong> Ensure compliance with industry standards and secure best practices (SOX, SOC 1/2), by implementing data governance frameworks, monitoring data pipelines, and optimizing cloud database architectures to protect sensitive information.</li>\n<li><strong>Stakeholder Collaboration:</strong> Work closely with stakeholders, including analysts, engineers, and product managers, to understand their data needs, propose solutions, and drive data-driven decision-making by delivering actionable insights.</li>\n<li><strong>Data Infrastructure Monitoring:</strong> Continuously monitor, troubleshoot, and enhance data pipelines, leveraging CI/CD tools (Docker, Jenkins, GitHub Actions) and orchestrating workflows using Apache Airflow to maintain operational efficiency.</li>\n<li><strong>Leadership and Mentorship:</strong> Provide hands-on mentorship and technical guidance to junior engineers, including code reviews and architecture discussions.</li>\n<li><strong>Documentation and Governance:</strong> Establish comprehensive documentation for data architecture, governance, and processes to ensure scalability, compliance, and security.</li>\n</ul>\n<h3><strong>Qualifications:</strong></h3>\n<ul>\n<li><strong>5+ years of proven experience as a Data Engineer or in a similar role </strong>with a deep understanding of data architecture and cloud-based ETL/ELT frameworks.</li>\n<li>Strong experience with <strong>AWS </strong>(preferably) or Azure , particularly with Glue, EMR, S3, Lambda. Databricks, Snowflake, Synapse experience is a bonus.</li>\n<li>Proficiency in <strong>big data technologies</strong> such as Apache Spark, Kafka, Hadoop, and Databricks for distributed data processing.</li>\n<li>Proficiency with Python libraries for data processing and ML (e.g., Pandas, NumPy, Polars, Scikit-learn, PyTorch, TensorFlow).</li>\n<li>Hands-on experience in building real-time data processing and AI/ML-driven analytics solutions (SageMaker, Bedrock, NLP, Power BI).</li>\n<li>Ability to architect and manage data lakehouse solutions (Iceberg / Delta Lake / Hudi) or classic warehouse solutions (Redshift, Snowflake).</li>\n<li>Familiarity with compliance and audit requirements (SOX, SOC 1/2, GDPR) and implementing data governance and security frameworks.</li>\n<li>Strong problem-solving skills with a focus on data integrity, scalability, and performance optimization.</li>\n<li>Experience with CI/CD tools (Jenkins, GitHub Actions, Docker) and data orchestration platforms (Apache Airflow).</li>\n</ul>\n<p><strong>Preferred Qualifications:</strong></p>\n<ul>\n<li>Experience with advanced data architecture principles (medallion architecture, materialized views, task scheduling).</li>\n<li>Experience using BI tools (e.g., Power BI, Tableau) for real-time analytics and operational reporting</li>\n</ul>\n<h3><strong>What we offer:&nbsp;</strong></h3>\n<ul>\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">A role in shaping the future of protecting the most critical applications that run the world\'s business and a career that grows as the company grows.</span></li>\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">A unique culture of high achievement and teamwork.</span></li>\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Supportive and humble colleagues are the space\'s top problem solvers and innovators.</span></li>\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Financial security through competitive compensation and incentives.</span></li>\n</ul>\n<h4>The location for this role is Heidelberg.&nbsp;<strong>This is a hybrid role, so candidates must be commutable to Heidelberg.</strong></h4>\n<h3><strong>About Onapsis:</strong></h3>\n<p><span style=\"font-weight: 400;\">Onapsis protects the business applications that run the global economy. The Onapsis Platform delivers vulnerability management, change assurance, and continuous compliance for business applications from leading vendors such as SAP, Oracle, and others. The Onapsis Platform is powered by the Onapsis Research Labs, the team responsible for the discovery and mitigation of more than 1,000 zero-day vulnerabilities in business applications.</span></p>\n<p><span style=\"font-weight: 400;\">Onapsis is headquartered in Boston, MA, with egional offices in Heidelberg, Germany; Buenos Aires, Argentina; Texas, USA, and now in Bucharest, Romania;&nbsp;and proudly serves hundreds of the world\'s leading brands, including close to 30% of the Forbes Global 100, six of the top 10 automotive companies, five of the top 10 chemical companies, four of the top 10 technology companies, and three of the top 10 oil and gas companies.&nbsp;</span></p>\n<p><span style=\"font-weight: 400;\">For more information, connect with Onapsis on </span><a href=\"https://cts.businesswire.com/ct/CT?id=smartlink&amp;url=https%3A%2F%2Fwww.linkedin.com%2Fcompany%2Fonapsis%2F&amp;esheet=53364949&amp;newsitemid=20230321005293&amp;lan=en-US&amp;anchor=LinkedIn&amp;index=8&amp;md5=1ee4c78f4a23262e26a7215c01ecac54\"><span style=\"font-weight: 400;\">LinkedIn</span></a><span style=\"font-weight: 400;\"> or visit </span><a href=\"https://cts.businesswire.com/ct/CT?id=smartlink&amp;url=https%3A%2F%2Fwww.onapsis.com%2F&amp;esheet=53364949&amp;newsitemid=20230321005293&amp;lan=en-US&amp;anchor=https%3A%2F%2Fwww.onapsis.com&amp;index=9&amp;md5=7be2a3923202e5a5e7391c73aeb37f49\"><span style=\"font-weight: 400;\">https://www.onapsis.com</span></a><span style=\"font-weight: 400;\">.</span></p>\n<h2><span style=\"font-weight: 400; font-size: 14px;\">#LI-AC1</span></h2>\n<p><span style=\"font-weight: 400; font-size: 14px;\">#LI-Hybrid</span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p><p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>&nbsp;</p>\n<h3>About the job</h3>\n<p>The world\'s most critical--and at risk--business applications have been neglected for far too long. <strong>Onapsis </strong>eliminates this blind spot by providing cybersecurity solutions dedicated to business-critical applications. Whether running on premises, in the cloud, or in a hybrid environment, Onapsis helps nearly 30% of the Forbes Global 100 understand the threats and risks across their SAP and Oracle landscapes.</p>\n<p>We are seeking a <strong>Senior Data Engineer</strong>&nbsp;to join our mission-driven team. This role is ideal for experienced data engineers with a proven track record in architecting scalable data pipelines, leveraging cloud technologies, and contributing to high-impact cybersecurity solutions. You will be responsible for building high-performance ETL frameworks, optimizing data platforms, and contributing directly to the enhancement of our customers\' threat detection, response, and remediation capabilities.</p>\n<h3>What you will be doing, your legacy:&nbsp;</h3>\n<p>You will be working directly with company Principal Engineers evaluating, scoping, proposing, and building features to fulfill business solution requirements to protect our customers. You will play a direct role in laying the technical foundation for a new product offering. Additionally, you will be working with Engineering and DevOps to deliver high-quality products and services while also working closely with security and IT professionals to ensure safe and secure best practices are followed.&nbsp;</p>\n<p><strong>Responsibilities:</strong></p>\n<ul>\n<li><strong>Architect and Design Scalable Data Solutions:</strong> Design/develop/maintain Data lakehouse solutions (Iceberg/Delta Lake /Hudi) applying industry best practices and structuring / optimizing the data according to data access patterns.</li>\n<li><strong>Data Pipeline Development:</strong> Implement ETL/ELT pipelines using cloud technologies (Spark / pySpark / Glue, Kinesis Streams / Iceberg) to load the data into a Lakehouse for both efficient ML processing and UI reporting.</li>\n<li>Implement data models and data processing frameworks (Spark, Kafka, Snowflake) to ingest, transform, and load large datasets into Data Lakehouse techs (Apache Iceberg, Apache Delta Lake or Apache Hudi), ensuring high availability and reliability of data.</li>\n<li><strong>Advanced Data Integration:</strong> Develop solutions that integrate multiple data sources into Snowflake or similar data warehouses to enable real-time analytics and reporting across dashboards.</li>\n<li><strong>AI/ML Integration:</strong> Collaborate with cross-functional teams to co-develop AI-driven features identifying patterns and anomalies in client data using AI/ML technologies (python).</li>\n<li><strong>Compliance and Security:</strong> Ensure compliance with industry standards and secure best practices (SOX, SOC 1/2), by implementing data governance frameworks, monitoring data pipelines, and optimizing cloud database architectures to protect sensitive information.</li>\n<li><strong>Stakeholder Collaboration:</strong> Work closely with stakeholders, including analysts, engineers, and product managers, to understand their data needs, propose solutions, and drive data-driven decision-making by delivering actionable insights.</li>\n<li><strong>Data Infrastructure Monitoring:</strong> Continuously monitor, troubleshoot, and enhance data pipelines, leveraging CI/CD tools (Docker, Jenkins, GitHub Actions) and orchestrating workflows using Apache Airflow to maintain operational efficiency.</li>\n<li><strong>Leadership and Mentorship:</strong> Provide hands-on mentorship and technical guidance to junior engineers, including code reviews and architecture discussions.</li>\n<li><strong>Documentation and Governance:</strong> Establish comprehensive documentation for data architecture, governance, and processes to ensure scalability, compliance, and security.</li>\n</ul>\n<h3><strong>Qualifications:</strong></h3>\n<ul>\n<li><strong>5+ years of proven experience as a Data Engineer or in a similar role </strong>with a deep understanding of data architecture and cloud-based ETL/ELT frameworks.</li>\n<li>Strong experience with <strong>AWS </strong>(preferably) or Azure , particularly with Glue, EMR, S3, Lambda. Databricks, Snowflake, Synapse experience is a bonus.</li>\n<li>Proficiency in <strong>big data technologies</strong> such as Apache Spark, Kafka, Hadoop, and Databricks for distributed data processing.</li>\n<li>Proficiency with Python libraries for data processing and ML (e.g., Pandas, NumPy, Polars, Scikit-learn, PyTorch, TensorFlow).</li>\n<li>Hands-on experience in building real-time data processing and AI/ML-driven analytics solutions (SageMaker, Bedrock, NLP, Power BI).</li>\n<li>Ability to architect and manage data lakehouse solutions (Iceberg / Delta Lake / Hudi) or classic warehouse solutions (Redshift, Snowflake).</li>\n<li>Familiarity with compliance and audit requirements (SOX, SOC 1/2, GDPR) and implementing data governance and security frameworks.</li>\n<li>Strong problem-solving skills with a focus on data integrity, scalability, and performance optimization.</li>\n<li>Experience with CI/CD tools (Jenkins, GitHub Actions, Docker) and data orchestration platforms (Apache Airflow).</li>\n</ul>\n<p><strong>Preferred Qualifications:</strong></p>\n<ul>\n<li>Experience with advanced data architecture principles (medallion architecture, materialized views, task scheduling).</li>\n<li>Experience using BI tools (e.g., Power BI, Tableau) for real-time analytics and operational reporting</li>\n</ul>\n<h3><strong>What we offer:&nbsp;</strong></h3>\n<ul>\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">A role in shaping the future of protecting the most critical applications that run the world\'s business and a career that grows as the company grows.</span></li>\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">A unique culture of high achievement and teamwork.</span></li>\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Supportive and humble colleagues are the space\'s top problem solvers and innovators.</span></li>\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Financial security through competitive compensation and incentives.</span></li>\n</ul>\n<h4>The location for this role is Heidelberg.&nbsp;<strong>This is a hybrid role, so candidates must be commutable to Heidelberg.</strong></h4>\n<h3><strong>About Onapsis:</strong></h3>\n<p><span style=\"font-weight: 400;\">Onapsis protects the business applications that run the global economy. The Onapsis Platform delivers vulnerability management, change assurance, and continuous compliance for business applications from leading vendors such as SAP, Oracle, and others. The Onapsis Platform is powered by the Onapsis Research Labs, the team responsible for the discovery and mitigation of more than 1,000 zero-day vulnerabilities in business applications.</span></p>\n<p><span style=\"font-weight: 400;\">Onapsis is headquartered in Boston, MA, with egional offices in Heidelberg, Germany; Buenos Aires, Argentina; Texas, USA, and now in Bucharest, Romania;&nbsp;and proudly serves hundreds of the world\'s leading brands, including close to 30% of the Forbes Global 100, six of the top 10 automotive companies, five of the top 10 chemical companies, four of the top 10 technology companies, and three of the top 10 oil and gas companies.&nbsp;</span></p>\n<p><span style=\"font-weight: 400;\">For more information, connect with Onapsis on </span><a href=\"https://cts.businesswire.com/ct/CT?id=smartlink&amp;url=https%3A%2F%2Fwww.linkedin.com%2Fcompany%2Fonapsis%2F&amp;esheet=53364949&amp;newsitemid=20230321005293&amp;lan=en-US&amp;anchor=LinkedIn&amp;index=8&amp;md5=1ee4c78f4a23262e26a7215c01ecac54\"><span style=\"font-weight: 400;\">LinkedIn</span></a><span style=\"font-weight: 400;\"> or visit </span><a href=\"https://cts.businesswire.com/ct/CT?id=smartlink&amp;url=https%3A%2F%2Fwww.onapsis.com%2F&amp;esheet=53364949&amp;newsitemid=20230321005293&amp;lan=en-US&amp;anchor=https%3A%2F%2Fwww.onapsis.com&amp;index=9&amp;md5=7be2a3923202e5a5e7391c73aeb37f49\"><span style=\"font-weight: 400;\">https://www.onapsis.com</span></a><span style=\"font-weight: 400;\">.</span></p>\n<h2><span style=\"font-weight: 400; font-size: 14px;\">#LI-AC1</span></h2>\n<p><span style=\"font-weight: 400; font-size: 14px;\">#LI-Hybrid</span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p><p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-11 03:15:56.463', '2026-06-11 03:15:56.463', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/onapsis/senior-data-engineer-biederbach-baden-wurttemberg-205487', '', '[]', 'pending', '', NULL),
(556, NULL, 'api', NULL, 'Chief Of Staff', 'Voltvera', 'Cologne', 'https://www.arbeitnow.com/jobs/companies/voltvera/chief-of-staff-cologne-130596', '<p>Wir sind Voltvera, ein junges, schnell wachsendes Energy-Tech-Startup aus dem Herzen von Köln. Unsere Mission: Industrieunternehmen ihre Energiekosten massiv senken, um den Industriestandort Deutschland zu stärken und gleichzeitig die Energiewende messbar beschleunigen.</p>\n<p>Dafür bauen wir intelligent gesteuerte Batteriespeicherlösungen für Industrie-Standorte. Wir optimieren damit Lastspitzen (Peak Shaving), PV-Eigenverbrauch, Strombezug und weitere energiewirtschaftliche Use Cases.</p>\n<p>Dabei profitieren wir von einem Marktumfeld, das sich gerade fundamental dreht: Die Volatilität der Preise und der Zwang zur Flexibilisierung machen unsere Lösung vom „Nice-to-have“ zum kritischen Infrastruktur-Investment. Wir skalieren genau in dem Moment, in dem der Markt für industrielle Speicher massiv anzieht.</p>\n<p>Als ehemalige Strategieberater und Ingenieure verbinden wir unternehmerische Execution mit strategischer Exzellenz und technischer Tiefe. Wir wollen, dass Deutschland in diesem Feld Vorreiter ist, und Voltvera ein relevanter Player im europäischen Energiemarkt wird. Wir sind überzeugt: Die nächsten Jahre entscheiden darüber, wer das neue Energie-Ökosystem prägt.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Strategische und operative Unterstützung der Geschäftsführung bei der Weiterentwicklung von Voltvera, einschließlich Marktanalysen, Business-Cases, Go-to-Market, Entscheidungsvorlagen und Sonderprojekten</li>\n<li>Analyse, Strukturierung und Aufbereitung wirtschaftlicher sowie technischer Fragestellungen rund um Batteriespeicherprojekte (z. B. Wirtschaftlichkeitsmodelle, Standortbewertungen, Angebots- und Projektkalkulationen)</li>\n<li>Schnittstellenfunktion zwischen Business, Technik und externen Partnern, inkl. Koordination von Projektpartnern, Vorbereitung von Kundenterminen sowie eigenständiger Übernahme operativer Verantwortung</li>\n<li>Ziel: Langfristige Entwicklung zur Gesamtverantwortung eines eigenen Teilbereichs inkl. Führung eines Teams</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Einschlägige Erfahrungen in Consulting, M&#x26;A oder Startups</li>\n<li>Analytisches Denken &#x26; Kommunikationsstärke</li>\n<li>Deutsch auf Muttersprach-Niveau</li>\n<li>Drive, Ownership und Lust auf Verantwortung</li>\n<li>Strukturierte, eigenständige Arbeitsweise</li>\n<li>Begeisterung für Energiewende, Tech &#x26; Wirtschaft</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Total Compensation realistisch: 50–80k € (Fix + Variable, abhängig von Erfahrung)</li>\n<li>Extrem steile Lernkurve direkt mit den Gründern (Strategie + Execution)</li>\n<li>Startup-Spirit: dynamisch, hands-on, unbürokratisch, junges Team, starker Zusammenhalt, schnelle Entscheidungen</li>\n<li>Office im Herzen von Köln</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Wir sind Voltvera, ein junges, schnell wachsendes Energy-Tech-Startup aus dem Herzen von Köln. Unsere Mission: Industrieunternehmen ihre Energiekosten massiv senken, um den Industriestandort Deutschland zu stärken und gleichzeitig die Energiewende messbar beschleunigen.</p>\n<p>Dafür bauen wir intelligent gesteuerte Batteriespeicherlösungen für Industrie-Standorte. Wir optimieren damit Lastspitzen (Peak Shaving), PV-Eigenverbrauch, Strombezug und weitere energiewirtschaftliche Use Cases.</p>\n<p>Dabei profitieren wir von einem Marktumfeld, das sich gerade fundamental dreht: Die Volatilität der Preise und der Zwang zur Flexibilisierung machen unsere Lösung vom „Nice-to-have“ zum kritischen Infrastruktur-Investment. Wir skalieren genau in dem Moment, in dem der Markt für industrielle Speicher massiv anzieht.</p>\n<p>Als ehemalige Strategieberater und Ingenieure verbinden wir unternehmerische Execution mit strategischer Exzellenz und technischer Tiefe. Wir wollen, dass Deutschland in diesem Feld Vorreiter ist, und Voltvera ein relevanter Player im europäischen Energiemarkt wird. Wir sind überzeugt: Die nächsten Jahre entscheiden darüber, wer das neue Energie-Ökosystem prägt.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Strategische und operative Unterstützung der Geschäftsführung bei der Weiterentwicklung von Voltvera, einschließlich Marktanalysen, Business-Cases, Go-to-Market, Entscheidungsvorlagen und Sonderprojekten</li>\n<li>Analyse, Strukturierung und Aufbereitung wirtschaftlicher sowie technischer Fragestellungen rund um Batteriespeicherprojekte (z. B. Wirtschaftlichkeitsmodelle, Standortbewertungen, Angebots- und Projektkalkulationen)</li>\n<li>Schnittstellenfunktion zwischen Business, Technik und externen Partnern, inkl. Koordination von Projektpartnern, Vorbereitung von Kundenterminen sowie eigenständiger Übernahme operativer Verantwortung</li>\n<li>Ziel: Langfristige Entwicklung zur Gesamtverantwortung eines eigenen Teilbereichs inkl. Führung eines Teams</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Einschlägige Erfahrungen in Consulting, M&#x26;A oder Startups</li>\n<li>Analytisches Denken &#x26; Kommunikationsstärke</li>\n<li>Deutsch auf Muttersprach-Niveau</li>\n<li>Drive, Ownership und Lust auf Verantwortung</li>\n<li>Strukturierte, eigenständige Arbeitsweise</li>\n<li>Begeisterung für Energiewende, Tech &#x26; Wirtschaft</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Total Compensation realistisch: 50–80k € (Fix + Variable, abhängig von Erfahrung)</li>\n<li>Extrem steile Lernkurve direkt mit den Gründern (Strategie + Execution)</li>\n<li>Startup-Spirit: dynamisch, hands-on, unbürokratisch, junges Team, starker Zusammenhalt, schnelle Entscheidungen</li>\n<li>Office im Herzen von Köln</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-11 03:16:06.256', '2026-06-11 03:16:06.256', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/voltvera/chief-of-staff-cologne-130596', '', '[]', 'pending', '', NULL),
(557, NULL, 'api', NULL, 'Life Cycle Product Manager (m/w/d)', 'Kopani Consulting GmbH', 'Stuttgart', 'https://www.arbeitnow.com/jobs/companies/kopani-consulting-gmbh/life-cycle-product-manager-stuttgart-401913', '<p>Unser Kunde ist ein international etablierter Key Player in der Medizintechnik, der hochpräzise Systeme für Anwendungen im regulierten Healthcare-Umfeld entwickelt und produziert. Zur Verstärkung des Teams suchen wir eine erfahrene Persönlichkeit für das Life-Cycle-Management und die technische Betreuung sowie Weiterentwicklung bestehender Produkte für den Standort im Raum Stuttgart (hybrid).</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Betreuung eines strategischen Key Accounts im Bereich serienproduktbezogener Themen</li>\n<li>Koordination und Bearbeitung von Kundenanfragen inkl. Aufwand-, Kosten- und Zeitabschätzung in Abstimmung mit Fachbereichen</li>\n<li>Steuerung von CAPAs, Reklamationen, Abweichungen sowie LCM- und Änderungsprojekten in enger Zusammenarbeit mit QM und Entwicklung</li>\n<li>Eigenständige Leitung von Projekten wie Alterungsstudien, Materialänderungen oder Lebensdauerverlängerungen inklusive Abstimmung mit Laboren und Fachbereichen</li>\n<li>Schnittstellenmanagement zwischen Key Account, internen Fachabteilungen und Lieferanten sowie Sicherstellung der Umsetzung</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Technisches oder naturwissenschaftliches Studium, z. B. Medizintechnik, Wirtschaftsingenieurwesen, technisches Produktdesign oder Biotechnologie</li>\n<li>+2 Jahre Berufserfahrung in der Medizintechnik oder der Pharmaindustrie</li>\n<li>Erfahrung im technischen Projekt- oder Kundenmanagement, idealerweise im LCM-Umfeld</li>\n<li>Spritzguss- oder mechaniknahe Produktkenntnisse von Vorteil</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Hybrides Arbeitsmodell mit flexiblen Präsenztagen vor Ort</li>\n<li>Verantwortungsvolle Rolle in einem dynamischen Mittelständler mit kurzen Entscheidungswegen und hoher Eigenverantwortung</li>\n<li>Hohe Sichtbarkeit der Position mit direktem Impact auf führende internationale Key Accounts der Healthcare-Branche</li>\n<li>Internationale Projekte im regulierten Medizintechnik-Umfeld</li>\n<li>Attraktives Vergütungspaket inklusive zusätzlicher Mitarbeiterbenefits</li>\n<li>Open Door Policy, Duz-Kultur sowie viele Corporate Benefits</li>\n</ul>\n<p>Kopani Consulting ist eine Personalberatung mit über zehn Jahren Erfahrung in der Rekrutierung und Beratung von Spezialisten und Führungskräften aus der Pharmaindustrie und Medizintechnikbranche. Aufgrund dieser Erfahrung können wir Fachexperten und Kunden individuell und diskret unterstützen. Schicken Sie uns bitte Ihre aussagekräftigen Bewerbungsunterlagen inkl. Gehaltswunsch und frühestmöglichen Starttermin.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Unser Kunde ist ein international etablierter Key Player in der Medizintechnik, der hochpräzise Systeme für Anwendungen im regulierten Healthcare-Umfeld entwickelt und produziert. Zur Verstärkung des Teams suchen wir eine erfahrene Persönlichkeit für das Life-Cycle-Management und die technische Betreuung sowie Weiterentwicklung bestehender Produkte für den Standort im Raum Stuttgart (hybrid).</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Betreuung eines strategischen Key Accounts im Bereich serienproduktbezogener Themen</li>\n<li>Koordination und Bearbeitung von Kundenanfragen inkl. Aufwand-, Kosten- und Zeitabschätzung in Abstimmung mit Fachbereichen</li>\n<li>Steuerung von CAPAs, Reklamationen, Abweichungen sowie LCM- und Änderungsprojekten in enger Zusammenarbeit mit QM und Entwicklung</li>\n<li>Eigenständige Leitung von Projekten wie Alterungsstudien, Materialänderungen oder Lebensdauerverlängerungen inklusive Abstimmung mit Laboren und Fachbereichen</li>\n<li>Schnittstellenmanagement zwischen Key Account, internen Fachabteilungen und Lieferanten sowie Sicherstellung der Umsetzung</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Technisches oder naturwissenschaftliches Studium, z. B. Medizintechnik, Wirtschaftsingenieurwesen, technisches Produktdesign oder Biotechnologie</li>\n<li>+2 Jahre Berufserfahrung in der Medizintechnik oder der Pharmaindustrie</li>\n<li>Erfahrung im technischen Projekt- oder Kundenmanagement, idealerweise im LCM-Umfeld</li>\n<li>Spritzguss- oder mechaniknahe Produktkenntnisse von Vorteil</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Hybrides Arbeitsmodell mit flexiblen Präsenztagen vor Ort</li>\n<li>Verantwortungsvolle Rolle in einem dynamischen Mittelständler mit kurzen Entscheidungswegen und hoher Eigenverantwortung</li>\n<li>Hohe Sichtbarkeit der Position mit direktem Impact auf führende internationale Key Accounts der Healthcare-Branche</li>\n<li>Internationale Projekte im regulierten Medizintechnik-Umfeld</li>\n<li>Attraktives Vergütungspaket inklusive zusätzlicher Mitarbeiterbenefits</li>\n<li>Open Door Policy, Duz-Kultur sowie viele Corporate Benefits</li>\n</ul>\n<p>Kopani Consulting ist eine Personalberatung mit über zehn Jahren Erfahrung in der Rekrutierung und Beratung von Spezialisten und Führungskräften aus der Pharmaindustrie und Medizintechnikbranche. Aufgrund dieser Erfahrung können wir Fachexperten und Kunden individuell und diskret unterstützen. Schicken Sie uns bitte Ihre aussagekräftigen Bewerbungsunterlagen inkl. Gehaltswunsch und frühestmöglichen Starttermin.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-11 03:16:16.359', '2026-06-11 03:16:16.359', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/kopani-consulting-gmbh/life-cycle-product-manager-stuttgart-401913', '', '[]', 'pending', '', NULL),
(558, NULL, 'api', NULL, 'Junior Online Marketing Manager', 'Cyrus Digital GmbH', 'Munich', 'https://www.arbeitnow.com/jobs/companies/cyrus-digital-gmbh/junior-online-marketing-manager-munich-311721', '<p><strong>Junior Performance Marketing Manager (m/w/d) – München</strong></p>\n<p>Du hast erste Berufserfahrung im Online Marketing gesammelt und möchtest dich im Performance Marketing weiterentwickeln? Dann bist du bei uns richtig.</p>\n<p>Cyrus Digital ist eine der führenden Boutique-Agenturen für Performance Marketing im E-Commerce. Wir betreuen renommierte D2C-Brands – darunter Luxusbetten24, Pammys, Freiluftkind und viele mehr.</p>\n<p>Im Herzen Schwabings bilden wir dich von Grund auf aus: Rund ein Jahr Erfahrung in einem beliebigen Bereich des Online Marketings genügt – den Rest bringen wir dir bei, strukturiert und unter direkter Anleitung erfahrener Kollegen.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Mitarbeit an Kampagnenaufbau und laufender Optimierung.</li>\n<li>Schrittweise Übernahme eigener Account-Verantwortung für echte Brands – bis hin zur vollständig eigenständigen Betreuung.</li>\n<li>Strategische Weiterentwicklung deiner Kunden – vom Umsetzer zum Sparringspartner auf Augenhöhe.</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Etwa ein Jahr Berufserfahrung im Online Marketing – die Disziplin ist zweitrangig.</li>\n<li>Sorgfältige, eigeninitiative Arbeitsweise und Freude an der Arbeit mit Zahlen.</li>\n<li>Wohnsitz in München oder Umzugsbereitschaft, sehr gute Deutschkenntnisse.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Eine fundierte Ausbildung zum Performance Marketer – mit Kompetenzen, die am Markt überdurchschnittlich vergütet werden.</li>\n<li>Einen klaren Entwicklungspfad vom Junior zur eigenständigen Account-Verantwortung. Als ausgebildeter Senior sind über unser Provisionsmodell bis zu 100.000 € pro Jahr realistisch.</li>\n<li>Internes Training mit erfahrenen Branchenexperten, zweimal wöchentlich.</li>\n<li>Ein Büro im beliebten Schwabing mit moderner Apple-Ausstattung.</li>\n<li>Ein ambitioniertes, kollegiales Team mit hohem Anspruch.</li>\n</ul>\n<p><strong>Der Bewerbungsprozess</strong></p>\n<ul>\n<li>Telefonisches Kennenlernen</li>\n<li>Fachliches Interview</li>\n<li>Abschlussgespräch</li>\n</ul>\n<p><strong>Hinweis zur Vergütung:</strong> Die angegebene Gehaltsspanne orientiert sich an aktuellen Marktdaten und an dem, was vergleichbare Kollegen derzeit bei uns in der Rolle verdienen. Wo genau du innerhalb der Spanne liegst, entscheidet sich anhand deiner Performance im Bewerbungsprozess.</p>\n<p>Wir freuen uns auf deine Bewerbung.</p>\n<p><strong>Interessiert?</strong></p>\n<p>Bewirb dich jetzt und werde Teil unseres Teams!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Junior Performance Marketing Manager (m/w/d) – München</strong></p>\n<p>Du hast erste Berufserfahrung im Online Marketing gesammelt und möchtest dich im Performance Marketing weiterentwickeln? Dann bist du bei uns richtig.</p>\n<p>Cyrus Digital ist eine der führenden Boutique-Agenturen für Performance Marketing im E-Commerce. Wir betreuen renommierte D2C-Brands – darunter Luxusbetten24, Pammys, Freiluftkind und viele mehr.</p>\n<p>Im Herzen Schwabings bilden wir dich von Grund auf aus: Rund ein Jahr Erfahrung in einem beliebigen Bereich des Online Marketings genügt – den Rest bringen wir dir bei, strukturiert und unter direkter Anleitung erfahrener Kollegen.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Mitarbeit an Kampagnenaufbau und laufender Optimierung.</li>\n<li>Schrittweise Übernahme eigener Account-Verantwortung für echte Brands – bis hin zur vollständig eigenständigen Betreuung.</li>\n<li>Strategische Weiterentwicklung deiner Kunden – vom Umsetzer zum Sparringspartner auf Augenhöhe.</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Etwa ein Jahr Berufserfahrung im Online Marketing – die Disziplin ist zweitrangig.</li>\n<li>Sorgfältige, eigeninitiative Arbeitsweise und Freude an der Arbeit mit Zahlen.</li>\n<li>Wohnsitz in München oder Umzugsbereitschaft, sehr gute Deutschkenntnisse.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Eine fundierte Ausbildung zum Performance Marketer – mit Kompetenzen, die am Markt überdurchschnittlich vergütet werden.</li>\n<li>Einen klaren Entwicklungspfad vom Junior zur eigenständigen Account-Verantwortung. Als ausgebildeter Senior sind über unser Provisionsmodell bis zu 100.000 € pro Jahr realistisch.</li>\n<li>Internes Training mit erfahrenen Branchenexperten, zweimal wöchentlich.</li>\n<li>Ein Büro im beliebten Schwabing mit moderner Apple-Ausstattung.</li>\n<li>Ein ambitioniertes, kollegiales Team mit hohem Anspruch.</li>\n</ul>\n<p><strong>Der Bewerbungsprozess</strong></p>\n<ul>\n<li>Telefonisches Kennenlernen</li>\n<li>Fachliches Interview</li>\n<li>Abschlussgespräch</li>\n</ul>\n<p><strong>Hinweis zur Vergütung:</strong> Die angegebene Gehaltsspanne orientiert sich an aktuellen Marktdaten und an dem, was vergleichbare Kollegen derzeit bei uns in der Rolle verdienen. Wo genau du innerhalb der Spanne liegst, entscheidet sich anhand deiner Performance im Bewerbungsprozess.</p>\n<p>Wir freuen uns auf deine Bewerbung.</p>\n<p><strong>Interessiert?</strong></p>\n<p>Bewirb dich jetzt und werde Teil unseres Teams!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-11 03:16:26.695', '2026-06-11 03:16:26.695', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/cyrus-digital-gmbh/junior-online-marketing-manager-munich-311721', '', '[]', 'pending', '', NULL),
(559, NULL, 'api', NULL, 'Werkstudent:in Customer Support (Niederländisch)', 'Speekly', 'Köln', 'https://www.arbeitnow.com/jobs/companies/speekly/werkstudentin-customer-support-niederlandisch-koln-98340', '<p><strong><span style=\"color: #000000\">Über Speekly:</span></strong></p><p><span style=\"color: #000000\">Speekly ist der größte Marktplatz für Creator Content in Europa. Wir arbeiten mit 100.000+ Creators sowie 12.000+ Brands zusammen und bauen das Operating System für Social Content. Wir sind ein schnell wachsendes Start-up mit über 6 Millionen Euro in VC-Funding. Wir sitzen in Köln und sind im DACH-Markt, den Niederlanden, Italien und UK erfolgreich.</span></p><p style=\";\"></p><p><strong><span style=\"color: #000000\">Unser Ziel</span></strong><span style=\"color: #000000\">: Der führende online Marktplatz für Creator-Content in Europa sein und unsere Kunden ermöglichen, Content einfach, schnell und skalierbar zu sourcen. Dabei sollen unsere Kunden den besten Service erhalten. </span></p><p style=\";\"></p><p><strong><span style=\"color: #000000\">Da kommst du ins Spiel 🫵</span></strong></p><br /><br /><p><strong><span style=\"color: #000000\">Was wir suchen:</span></strong></p><p><span style=\"color: #000000\">Keine klassische Werkstudent:in. Sondern jemanden, der:</span></p><ul><li><p><span style=\"color: #000000\">Ownership für die Zufriedenheit unserer internationalen Kunden übernimmt</span></p></li><li><p><span style=\"color: #000000\">Lust hat, unsere Software in der Tiefe kennen zu lernen und mit zu verbessern</span></p></li><li><p><span style=\"color: #000000\">ein gutes Gefühl für Social Media, Trends &amp; Content hat</span></p></li><li><p><span style=\"color: #000000\">Fließend Niederländisch und Deutsch spricht</span></p><p style=\";\"></p></li></ul><p><strong><span style=\"color: #000000\">Was du bei uns machst:</span></strong></p><p><span style=\"color: #000000\">Du bist die erste Anlaufstelle für unsere niederländischen Kunden:</span></p><ul><li><p><span style=\"color: #000000\">Du beantwortest alle Fragen rund um unsere Plattform und Services</span></p></li><li><p><span style=\"color: #000000\">Du unterstützt unsere Kunden und Content Creators bei Schwierigkeiten und sorgst dafür, dass Kollaborationen erfolgreich verlaufen und die Vorgaben unserer Plattorm eingehalten werden</span></p></li><li><p><span style=\"color: #000000\">Du vermittelst proaktiv zwischen Brands und Creators, wenn die Zusammenarbeit mal nicht reibungslos klappt</span></p></li><li><p><span style=\"color: #000000\">Du lernst Up- und Cross-Selling-Potenziale zu erkennen und diese Kunden weiterzuentwickeln </span></p></li><li><p><span style=\"color: #000000\">Du sammelst Feedback aus dem niederländischen Markt und bringst es direkt ins Team zurück</span></p></li></ul><p style=\";\"></p><p><span style=\"color: #000000\">👉 Dein Ziel: unsere niederländischen Kunden rund-um zufrieden zu machen</span></p><p style=\";\"></p><p><strong><span style=\"color: #000000\">Das solltest du mitbringen:</span></strong></p><ul><li><p><span style=\"color: #000000\">Fließendes Niederländisch und Deutsch</span></p></li><li><p><span style=\"color: #000000\">Du bist proaktiv, eigenständig und hast Lust, viel zu lernen und Verantwortung zu übernehmen</span></p></li><li><p><span style=\"color: #000000\">Du kannst Konflikte mit Empathie und Verständnis lösen, so dass alle Parteien am Ende profitieren</span></p></li><li><p><span style=\"color: #000000\">Du arbeitest strukturiert, zuverlässig und treibst Dinge selbst voran</span></p></li><li><p><span style=\"color: #000000\">Du bist täglich auf TikTok &amp; Instagram unterwegs und verstehst, was funktioniert</span></p></li></ul><p><strong><span style=\"color: #000000\"><br />Was du bekommst:</span></strong></p><ul><li><p><strong><span style=\"color: #000000\">Echte Verantwortung: </span></strong><span style=\"color: #000000\">Du übernimmst den ersten Kontaktpunkt unserer Kunden und wie sie Speekly hier wahrnehmen</span><strong><span style=\"color: #000000\">.</span></strong></p></li><li><p><strong><span style=\"color: #000000\">Starke persönliche Entwicklung: </span></strong><span style=\"color: #000000\">Du wirst aktiv gecoacht und bekommst regelmäßig Feedback. Unsere Team Leads werden daran gemessen, wie gut sich ihr Team entwickelt – deine Entwicklung hat also klare Priorität.</span></p></li><li><p><strong><span style=\"color: #000000\">Schnelle Lernkurve: </span></strong><span style=\"color: #000000\">Du bekommst Einblicke darin, wie man als Startup ein Business skaliert. Perfekt, wenn du später selbst gründen oder in einem Startup Verantwortung übernehmen willst</span></p></li><li><p><strong><span style=\"color: #000000\">Arbeiten an einem Software-Produkt: </span></strong><span style=\"color: #000000\">Du arbeitest eng mit unserem Tech-Team zusammen, um die Bedürfnisse unserer Kunden in unserer Software zu realisieren. </span></p></li><li><p><strong><span style=\"color: #000000\">Setup, das funktioniert: </span></strong><span style=\"color: #000000\">Büro in Köln, flexible Arbeitszeiten, hybrides Arbeiten (bis zu 2 Tage Home Office), Hardware deiner Wahl, Urban Sports Club</span></p></li></ul><p><br /></p><p style=\";\"></p><p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p><strong><span style=\"color: #000000\">Über Speekly:</span></strong></p><p><span style=\"color: #000000\">Speekly ist der größte Marktplatz für Creator Content in Europa. Wir arbeiten mit 100.000+ Creators sowie 12.000+ Brands zusammen und bauen das Operating System für Social Content. Wir sind ein schnell wachsendes Start-up mit über 6 Millionen Euro in VC-Funding. Wir sitzen in Köln und sind im DACH-Markt, den Niederlanden, Italien und UK erfolgreich.</span></p><p style=\";\"></p><p><strong><span style=\"color: #000000\">Unser Ziel</span></strong><span style=\"color: #000000\">: Der führende online Marktplatz für Creator-Content in Europa sein und unsere Kunden ermöglichen, Content einfach, schnell und skalierbar zu sourcen. Dabei sollen unsere Kunden den besten Service erhalten. </span></p><p style=\";\"></p><p><strong><span style=\"color: #000000\">Da kommst du ins Spiel 🫵</span></strong></p><br /><br /><p><strong><span style=\"color: #000000\">Was wir suchen:</span></strong></p><p><span style=\"color: #000000\">Keine klassische Werkstudent:in. Sondern jemanden, der:</span></p><ul><li><p><span style=\"color: #000000\">Ownership für die Zufriedenheit unserer internationalen Kunden übernimmt</span></p></li><li><p><span style=\"color: #000000\">Lust hat, unsere Software in der Tiefe kennen zu lernen und mit zu verbessern</span></p></li><li><p><span style=\"color: #000000\">ein gutes Gefühl für Social Media, Trends &amp; Content hat</span></p></li><li><p><span style=\"color: #000000\">Fließend Niederländisch und Deutsch spricht</span></p><p style=\";\"></p></li></ul><p><strong><span style=\"color: #000000\">Was du bei uns machst:</span></strong></p><p><span style=\"color: #000000\">Du bist die erste Anlaufstelle für unsere niederländischen Kunden:</span></p><ul><li><p><span style=\"color: #000000\">Du beantwortest alle Fragen rund um unsere Plattform und Services</span></p></li><li><p><span style=\"color: #000000\">Du unterstützt unsere Kunden und Content Creators bei Schwierigkeiten und sorgst dafür, dass Kollaborationen erfolgreich verlaufen und die Vorgaben unserer Plattorm eingehalten werden</span></p></li><li><p><span style=\"color: #000000\">Du vermittelst proaktiv zwischen Brands und Creators, wenn die Zusammenarbeit mal nicht reibungslos klappt</span></p></li><li><p><span style=\"color: #000000\">Du lernst Up- und Cross-Selling-Potenziale zu erkennen und diese Kunden weiterzuentwickeln </span></p></li><li><p><span style=\"color: #000000\">Du sammelst Feedback aus dem niederländischen Markt und bringst es direkt ins Team zurück</span></p></li></ul><p style=\";\"></p><p><span style=\"color: #000000\">👉 Dein Ziel: unsere niederländischen Kunden rund-um zufrieden zu machen</span></p><p style=\";\"></p><p><strong><span style=\"color: #000000\">Das solltest du mitbringen:</span></strong></p><ul><li><p><span style=\"color: #000000\">Fließendes Niederländisch und Deutsch</span></p></li><li><p><span style=\"color: #000000\">Du bist proaktiv, eigenständig und hast Lust, viel zu lernen und Verantwortung zu übernehmen</span></p></li><li><p><span style=\"color: #000000\">Du kannst Konflikte mit Empathie und Verständnis lösen, so dass alle Parteien am Ende profitieren</span></p></li><li><p><span style=\"color: #000000\">Du arbeitest strukturiert, zuverlässig und treibst Dinge selbst voran</span></p></li><li><p><span style=\"color: #000000\">Du bist täglich auf TikTok &amp; Instagram unterwegs und verstehst, was funktioniert</span></p></li></ul><p><strong><span style=\"color: #000000\"><br />Was du bekommst:</span></strong></p><ul><li><p><strong><span style=\"color: #000000\">Echte Verantwortung: </span></strong><span style=\"color: #000000\">Du übernimmst den ersten Kontaktpunkt unserer Kunden und wie sie Speekly hier wahrnehmen</span><strong><span style=\"color: #000000\">.</span></strong></p></li><li><p><strong><span style=\"color: #000000\">Starke persönliche Entwicklung: </span></strong><span style=\"color: #000000\">Du wirst aktiv gecoacht und bekommst regelmäßig Feedback. Unsere Team Leads werden daran gemessen, wie gut sich ihr Team entwickelt – deine Entwicklung hat also klare Priorität.</span></p></li><li><p><strong><span style=\"color: #000000\">Schnelle Lernkurve: </span></strong><span style=\"color: #000000\">Du bekommst Einblicke darin, wie man als Startup ein Business skaliert. Perfekt, wenn du später selbst gründen oder in einem Startup Verantwortung übernehmen willst</span></p></li><li><p><strong><span style=\"color: #000000\">Arbeiten an einem Software-Produkt: </span></strong><span style=\"color: #000000\">Du arbeitest eng mit unserem Tech-Team zusammen, um die Bedürfnisse unserer Kunden in unserer Software zu realisieren. </span></p></li><li><p><strong><span style=\"color: #000000\">Setup, das funktioniert: </span></strong><span style=\"color: #000000\">Büro in Köln, flexible Arbeitszeiten, hybrides Arbeiten (bis zu 2 Tage Home Office), Hardware deiner Wahl, Urban Sports Club</span></p></li></ul><p><br /></p><p style=\";\"></p><p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-11 03:16:35.116', '2026-06-11 03:16:35.116', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/speekly/werkstudentin-customer-support-niederlandisch-koln-98340', '', '[]', 'pending', '', NULL);
