INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(668, NULL, 'api', NULL, 'Strategy & Operations Associate', 'yasp.ai GmbH', 'Munich', 'https://www.arbeitnow.com/jobs/companies/yaspai-gmbh/strategy-operations-associate-munich-4944', '<p>yasp is building the future of software development: a compiler that uses agentic AI for advanced optimization and code generation. We are a deep-tech company scaling fast, where priorities shift week over week and the work rarely comes pre-defined. We are looking for a Strategy &#x26; Operations Associate to keep the company moving as one system: turning leadership decisions into execution and making sure the right things advance, fast and with clarity.</p>\n<p>This is a hands-on, individual-contributor role. You will work directly with the CEO and the Director Finance &#x26; Operations. You will not manage a team. You own outcomes yourself, and you are expected to go beyond the brief rather than wait for one. If you want autonomy, ownership, and a front-row seat in a fast-scaling AI company, this is for you.</p>\n<h2>Tasks</h2>\n<ul>\n<li>Translate leadership decisions into clear actions, owners, and timelines</li>\n<li>Own the operating cadence: planning cycles, check-ins, and follow-ups</li>\n<li>Coordinate execution across business and technical teams</li>\n<li>Take ambiguous, cross-functional problems and drive them to a result end to end</li>\n<li>Identify bottlenecks, risks, and misalignment early and surface them clearly</li>\n<li>Reduce friction and keep priorities moving forward week over week</li>\n</ul>\n<h2>Requirements</h2>\n<ul>\n<li>Top-tier strategy consulting experience (e.g. MBB or a Big-4 strategy practice) combined with hands-on experience in a startup or VC. We want both, not one or the other.</li>\n<li>2-5 years of total experience</li>\n<li>Strong academic record; a Master\'s degree is a plus</li>\n<li>A self-directed operator who thrives on autonomy and high ownership: you move things forward without being told how</li>\n<li>Ambitious and hands-on, willing to go the extra mile</li>\n<li>Comfortable with ambiguity and incomplete information</li>\n<li>Clear communicator who follows through</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Competitive salary</li>\n<li>Opportunities for professional development and growth</li>\n<li>Flexible work hours</li>\n<li>Dynamic and collaborative work environment</li>\n<li>Cutting-edge software and hardware platforms</li>\n</ul>\n<p><strong>Why join us?</strong></p>\n<p><strong>Ownership &#x26; Autonomy</strong> We give you the space to lead, experiment, and make decisions; we don\'t micromanage.</p>\n<p><strong>Growth Culture</strong> You won\'t be static. We support your learning with coaching, resources, and exposure to new challenges.</p>\n<p><strong>Stable &#x26; Ethical</strong> We operate with transparency, accountability, and financial responsibility. No surprises, no hollow promises.</p>\n<p><strong>Belonging &#x26; Diversity</strong> We believe diversity of background, thought, and experience makes us stronger. We strive for an inclusive culture where everyone can thrive. At yasp, we\'re committed to creating an inclusive and diverse environment where everyone has an equal opportunity to thrive.</p>\n<p><strong>Long-Term Vision</strong> We plan and invest for the long run: in the business, in our people, and in our community.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>yasp is building the future of software development: a compiler that uses agentic AI for advanced optimization and code generation. We are a deep-tech company scaling fast, where priorities shift week over week and the work rarely comes pre-defined. We are looking for a Strategy &#x26; Operations Associate to keep the company moving as one system: turning leadership decisions into execution and making sure the right things advance, fast and with clarity.</p>\n<p>This is a hands-on, individual-contributor role. You will work directly with the CEO and the Director Finance &#x26; Operations. You will not manage a team. You own outcomes yourself, and you are expected to go beyond the brief rather than wait for one. If you want autonomy, ownership, and a front-row seat in a fast-scaling AI company, this is for you.</p>\n<h2>Tasks</h2>\n<ul>\n<li>Translate leadership decisions into clear actions, owners, and timelines</li>\n<li>Own the operating cadence: planning cycles, check-ins, and follow-ups</li>\n<li>Coordinate execution across business and technical teams</li>\n<li>Take ambiguous, cross-functional problems and drive them to a result end to end</li>\n<li>Identify bottlenecks, risks, and misalignment early and surface them clearly</li>\n<li>Reduce friction and keep priorities moving forward week over week</li>\n</ul>\n<h2>Requirements</h2>\n<ul>\n<li>Top-tier strategy consulting experience (e.g. MBB or a Big-4 strategy practice) combined with hands-on experience in a startup or VC. We want both, not one or the other.</li>\n<li>2-5 years of total experience</li>\n<li>Strong academic record; a Master\'s degree is a plus</li>\n<li>A self-directed operator who thrives on autonomy and high ownership: you move things forward without being told how</li>\n<li>Ambitious and hands-on, willing to go the extra mile</li>\n<li>Comfortable with ambiguity and incomplete information</li>\n<li>Clear communicator who follows through</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Competitive salary</li>\n<li>Opportunities for professional development and growth</li>\n<li>Flexible work hours</li>\n<li>Dynamic and collaborative work environment</li>\n<li>Cutting-edge software and hardware platforms</li>\n</ul>\n<p><strong>Why join us?</strong></p>\n<p><strong>Ownership &#x26; Autonomy</strong> We give you the space to lead, experiment, and make decisions; we don\'t micromanage.</p>\n<p><strong>Growth Culture</strong> You won\'t be static. We support your learning with coaching, resources, and exposure to new challenges.</p>\n<p><strong>Stable &#x26; Ethical</strong> We operate with transparency, accountability, and financial responsibility. No surprises, no hollow promises.</p>\n<p><strong>Belonging &#x26; Diversity</strong> We believe diversity of background, thought, and experience makes us stronger. We strive for an inclusive culture where everyone can thrive. At yasp, we\'re committed to creating an inclusive and diverse environment where everyone has an equal opportunity to thrive.</p>\n<p><strong>Long-Term Vision</strong> We plan and invest for the long run: in the business, in our people, and in our community.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-12 03:17:50.812', '2026-06-12 03:17:50.812', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/yaspai-gmbh/strategy-operations-associate-munich-4944', '', '[]', 'pending', '', NULL),
(669, NULL, 'api', NULL, 'Senior Java- und TypeScript-Entwickler (m/w/d) (Ref.Nr.: 47006)', 'Wavestone Germany AG', 'Frankfurt am Main', 'https://www.arbeitnow.com/jobs/companies/wavestone-germany-ag/senior-java-und-typescript-entwickler-refnr-47006-frankfurt-am-main-101120', '<p>Wir suchen einen erfahrenen Softwareentwickler für ein anspruchsvolles Projekt im Bereich der Disposition im Eisenbahnbetrieb sowie der Weiterentwicklung des ART Kern DFI.</p>\n<p><strong>Key Facts</strong><br>\nStart: 01.07.2026<br>\nDauer: Nicht bekannt<br>\nAuslastung: 0 %<br>\nEinsatzart:<br>\nEinsatzort: Frankfurt am Main<br>\nEinsatzland: Deutschland</p>\n<p><strong>Ihre Aufgaben</strong><br>\n•Softwareentwicklung für den ART Kern DFI<br>\n•Mitarbeit und Entwicklung im Projekt Solution Disposition Eisenbahnbetrieb</p>\n<p><strong>Muss-Anforderungen</strong><br>\n•Mindestens 5 Jahre praktische Erfahrung in der Softwareentwicklung mit Java und TypeScript, im Lebenslauf nachvollziehbar<br>\n•Mindestens 3 Jahre Berufserfahrung mit React, wovon mindestens zwei Jahre innerhalb der letzten drei Jahre liegen müssen<br>\n•Mindestens 3 Jahre Berufserfahrung mit Spring Boot, wovon mindestens zwei Jahre innerhalb der letzten drei Jahre liegen müssen<br>\n•Hervorragende Deutschkenntnisse auf dem Niveau C2<br>\n•Einstufung als Senior Developer mit dem Profil Common<br>\n•Bereitschaft zur Erbringung von Leistungen vor Ort in Frankfurt am Main im Umfang von 4 Personentagen</p>\n<p><strong>Kann-Anforderungen</strong><br>\n-<br>\n<strong>Weitere Informationen</strong><br>\nDer Einsatzort ist Frankfurt am Main (Onshore Deutschland). Der Einsatzzeitraum ist vom 01.07.2026 bis 31.12.2026 mit einem Gesamtumfang von 102 Personentagen, wovon 4 Tage vor Ort geplant sind.</p>\n<p><strong>Let’s power the future together</strong><br>\nVom Business Case bis hin zur Umsetzung: Als führendes Beratungsunternehmen für strategische Transformationen sind wir vertrauenswürdiger Partner für unsere Kunden - und für unsere Mitarbeitenden. Verantwortungsvoll, leistungsstark und immer mit dem Menschen im Fokus. #WeAreWavestone<br>\nMit unserem 360°-Portfolio an Beratungsleistungen verbinden wir erstklassige Branchenexpertise mit einem breiten Spektrum an branchenübergreifenden Kompetenzen, arbeiten interdisziplinär und denken über den Tellerrand hinaus. Unseren Partnerunternehmen und Freelancern:Freelancerinnen können wir so umfassende Perspektiven innerhalb unserer eigenen Projekte bieten und unterstützen als langjähriger Rahmenvertragspartner bei der Besetzung von Projektvakanzen – zeitnah und direkt.</p>\n<p>Wir freuen uns auf Ihre Kontaktaufnahme!</p>\n<p><strong>Ihr direkter Ansprechpartner bei Wavestone</strong><br>\nEmira Bucan<br>\nTelefon: -<br>\nE-Mail: <a ----------\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Wir suchen einen erfahrenen Softwareentwickler für ein anspruchsvolles Projekt im Bereich der Disposition im Eisenbahnbetrieb sowie der Weiterentwicklung des ART Kern DFI.</p>\n<p><strong>Key Facts</strong><br>\nStart: 01.07.2026<br>\nDauer: Nicht bekannt<br>\nAuslastung: 0 %<br>\nEinsatzart:<br>\nEinsatzort: Frankfurt am Main<br>\nEinsatzland: Deutschland</p>\n<p><strong>Ihre Aufgaben</strong><br>\n•Softwareentwicklung für den ART Kern DFI<br>\n•Mitarbeit und Entwicklung im Projekt Solution Disposition Eisenbahnbetrieb</p>\n<p><strong>Muss-Anforderungen</strong><br>\n•Mindestens 5 Jahre praktische Erfahrung in der Softwareentwicklung mit Java und TypeScript, im Lebenslauf nachvollziehbar<br>\n•Mindestens 3 Jahre Berufserfahrung mit React, wovon mindestens zwei Jahre innerhalb der letzten drei Jahre liegen müssen<br>\n•Mindestens 3 Jahre Berufserfahrung mit Spring Boot, wovon mindestens zwei Jahre innerhalb der letzten drei Jahre liegen müssen<br>\n•Hervorragende Deutschkenntnisse auf dem Niveau C2<br>\n•Einstufung als Senior Developer mit dem Profil Common<br>\n•Bereitschaft zur E