e-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ; font-weight: bolder;\">Equal Opportunity</span></p><p style=\"border-color: rgb(229, 231, 235); --tw-shadow: 0 0 #0000; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ;  cursor: text; padding: 0px; counter-reset: list-1 0 list-2 0 list-3 0 list-4 0 list-5 0 list-6 0 list-7 0 list-8 0 list-9 0; color: rgb(65, 69, 71); letter-spacing: -0.25px; white-space: pre-wrap;\"></p><p style=\"box-sizing: border-box; border: 0px solid rgb(229, 231, 235); --tw-shadow: 0 0 #0000; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ; margin: 0px;  cursor: text; padding: 0px; counter-reset: list-1 0 list-2 0 list-3 0 list-4 0 list-5 0 list-6 0 list-7 0 list-8 0 list-9 0;\">All qualified applicants will receive consideration for a contractual relationship without regard to race, color, religion, sex, sexual orientation, gender identity, national origin, disability, or protected veteran status. At TELUS Digital AI, we are proud to offer equal opportunities and are committed to creating a diverse and inclusive community. All aspects of selection are based on applicants’ qualifications, merits, competence, and performance without regard to any characteristic related to diversity.</p>\n<img src=\"https://remotive.com/job/track/2090988/blank.gif?source=public_api\" alt=\"\"/>', 'new', NULL, '2026-06-13 13:44:42.848', '2026-06-13 13:44:42.848', '', 'part_time', 'Remote', 'United States', '', 'Remotive', 'API', 'READY', 'Web%20Developer', '', '', 'api', 'https://remotive.com/remote-jobs/all-others/quality-assurance-rater-german-germany-2090988', 'https://remotive.com/remote-jobs/all-others/quality-assurance-rater-german-germany-2090988', '[{\"url\":\"https://remotive.com/remote-jobs/all-others/quality-assurance-rater-german-germany-2090988\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(811, NULL, 'api', NULL, 'Senior Data Scientist', 'Lemon.io', 'Americas, Europe, Asia, Oceania', 'https://remotive.com/remote-jobs/data/senior-data-scientist-2090982', '<p>Are you a talented Senior Data Scientist looking for a remote job that lets you show your skills and get decent compensation? Look no further than <a href=\"https://lemon.io/for-developers/?utm_source=remotive&amp;utm_medium=job_ad&amp;utm_campaign=supply_en_data_scientist _jun_2026_job_ad\" rel=\"nofollow\" target=\"_self\">Lemon.io</a> — the marketplace that connects you with hand-picked startups in the US and Europe.</p>\n<p><strong> </strong></p>\n<p><strong>What we offer:</strong></p>\n<ul style=\"\">\n<li style=\"\">The rate depends on your skills and experience. We\'ve already paid out over $11M to our engineers.</li>\n<li style=\"\">No more hunting for clients or negotiating rates — let us handle the business side of things so you can focus on what you do best.</li>\n<li style=\"\">Choose a schedule that works best for you. It’s possible to communicate async or minimally overlap within team working hours.</li>\n<li style=\"\">We respect your seniority so you can expect no micromanagement or screen trackers.</li>\n<li style=\"\">Communicate directly with the clients. Most of them have technical backgrounds. Sounds good, yeah?</li>\n<li style=\"\">Most of our projects involve working in a fast-paced startup environment. We hope you like it as much as we do.</li>\n</ul>\n<p><strong> </strong></p>\n<p><strong>Requirements:</strong></p>\n<ul style=\"\">\n<li style=\"\">\n<p>4+ years of commercial experience as a Data Scientist</p>\n</li>\n<li style=\"\">\n<p>3+ years of experience with NumPy/Pandas</p>\n</li>\n<li style=\"\">\n<p>3+ years of experience with Python</p>\n</li>\n<li style=\"\">\n<p>Experience with AWS, GCP, or Azure is required</p>\n</li>\n<li style=\"\">\n<p>Strong technical skills: as a Senior Data Scientist, you are expected to be able to create projects from scratch and have a deep understanding of application architecture.</p>\n</li>\n<li style=\"\">\n<p>Clear and effective communication in English — advanced ability to discuss business tasks, justify decisions, and communicate issues. Good self-presentation is also essential for upcoming client calls.</p>\n</li>\n<li style=\"\">\n<p>Strong self-organizational skills — ability to work full-time remotely with no supervision.</p>\n</li>\n<li style=\"\">\n<p>Reliability — we want to trust you and expect that you won’t let us and the client down.</p>\n</li>\n<li style=\"\">\n<p>Adaptability and Flexibility — the ability to onboard the project promptly after accepting it and start delivering results quickly.</p>\n</li>\n</ul>\n<p><strong> </strong></p>\n<p><strong>NOT YOUR TECH STACK?</strong></p>\n<p>We have multiple projects available for Senior Developers. If you have 4+ years of commercial software development experience and are proficient in any of the following areas: AI Engineering, PHP &amp; Angular, React &amp; Java, Data Science, Blockchain (Web3/Solidity/Solana), React &amp; Python, React &amp; Node, React &amp; Golang, Data Analysis, React &amp; PHP, Symfony, PHP &amp; Vue, Vue &amp; Node.js, DevOps, Android &amp; iOS, Angular &amp; Node.js, Python &amp; Vue, MLOps, Rust, Golang, Shopify &amp; JavaScript, Unreal Engine &amp; C++, Python &amp; LLM, Unity, Vue &amp; Nuxt, Java &amp; Spring, ML Engineering, or Python &amp; Flask — we’d be happy to connect and match you with a suitable project.</p>\n<p> </p>\n<p>We do not provide visa assistance, and our cooperation model does not include the benefits typically offered with direct hire.</p>\n<p><!-- notionvc: 190240b5-e124-47d0-97d4-91a6bae76a90 --></p>\n<p> </p>\n<p>We work with developers from 75+ countries across Europe, Latin America, North America (the U.S. and Canada), selected countries in Asia (Japan, Singapore, South Korea, the Philippines, Indonesia, Malaysia, Vietnam, Thailand, and Israel), Oceania (Australia, New Zealand, and Papua New Guinea), and Africa (including Morocco and South Africa).</p>\n<img src=\"https://remotive.com/job/track/2090982/blank.gif?source=public_api\" alt=\"\"/>', '<p>Are you a talented Senior Data Scientist looking for a remote job that lets you show your skills and get decent compensation? Look no further than <a href=\"https://lemon.io/for-developers/?utm_source=remotive&amp;utm_medium=job_ad&amp;utm_campaign=supply_en_data_scientist _jun_2026_job_ad\" rel=\"nofollow\" target=\"_self\">Lemon.io</a> — the marketplace that connects you with hand-picked startups in the US and Europe.</p>\n<p><strong> </strong></p>\n<p><strong>What we offer:</strong></p>\n<ul style=\"\">\n<li style=\"\">The rate depends on your skills and experience. We\'ve already paid out over $11M to our engineers.</li>\n<li style=\"\">No more hunting for clients or negotiating rates — let us handle the business side of things so you can focus on what you do best.</li>\n<li style=\"\">Choose a schedule that works best for you. It’s possible to communicate async or minimally overlap within team working hours.</li>\n<li style=\"\">We respect your seniority so you can expect no micromanagement or screen trackers.</li>\n<li style=\"\">Communicate directly with the clients. Most of them have technical backgrounds. Sounds good, yeah?</li>\n<li style=\"\">Most of our projects involve working in a fast-paced startup environment. We hope you like it as much as we do.</li>\n</ul>\n<p><strong> </strong></p>\n<p><strong>Requirements:</strong></p>\n<ul style=\"\">\n<li style=\"\">\n<p>4+ years of commercial experience as a Data Scientist</p>\n</li>\n<li style=\"\">\n<p>3+ years of experience with NumPy/Pandas</p>\n</li>\n<li style=\"\">\n<p>3+ years of experience with Python</p>\n</li>\n<li style=\"\">\n<p>Experience with AWS, GCP, or Azure is required</p>\n</li>\n<li style=\"\">\n<p>Strong technical skills: as a Senior Data Scientist, you are expected to be able to create projects from scratch and have a deep understanding of application architecture.</p>\n</li>\n<li style=\"\">\n<p>Clear and effective communication in English — advanced ability to discuss business tasks, justify decisions, and communicate issues. Good self-presentation is also essential for upcoming client calls.</p>\n</li>\n<li style=\"\">\n<p>Strong self-organizational skills — ability to work full-time remotely with no supervision.</p>\n</li>\n<li style=\"\">\n<p>Reliability — we want to trust you and expect that you won’t let us and the client down.</p>\n</li>\n<li style=\"\">\n<p>Adaptability and Flexibility — the ability to onboard the project promptly after accepting it and start delivering results quickly.</p>\n</li>\n</ul>\n<p><strong> </strong></p>\n<p><strong>NOT YOUR TECH STACK?</strong></p>\n<p>We have multiple projects available for Senior Developers. If you have 4+ years of commercial software development experience and are proficient in any of the following areas: AI Engineering, PHP &amp; Angular, React &amp; Java, Data Science, Blockchain (Web3/Solidity/Solana), React &amp; Python, React &amp; Node, React &amp; Golang, Data Analysis, React &amp; PHP, Symfony, PHP &amp; Vue, Vue &amp; Node.js, DevOps, Android &amp; iOS, Angular &amp; Node.js, Python &amp; Vue, MLOps, Rust, Golang, Shopify &amp; JavaScript, Unreal Engine &amp; C++, Python &amp; LLM, Unity, Vue &amp; Nuxt, Java &amp; Spring, ML Engineering, or Python &amp; Flask — we’d be happy to connect and match you with a suitable project.</p>\n<p> </p>\n<p>We do not provide visa assistance, and our cooperation model does not include the benefits typically offered with direct hire.</p>\n<p><!-- notionvc: 190240b5-e124-47d0-97d4-91a6bae76a90 --></p>\n<p> </p>\n<p>We work with developers from 75+ countries across Europe, Latin America, North America (the U.S. and Canada), selected countries in Asia (Japan, Singapore, South Korea, the Philippines, Indonesia, Malaysia, Vietnam, Thailand, and Israel), Oceania (Australia, New Zealand, and Papua New Guinea), and Africa (including Morocco and South Africa).</p>\n<img src=\"https://remotive.com/job/track/2090982/blank.gif?source=public_api\" alt=\"\"/>', 'new', NULL, '2026-06-13 13:44:52.540', '2026-06-13 13:44:52.540', '', 'full_time', 'Remote', 'United States', '', 'Remotive', 'API', 'READY', 'Web%20Developer', '', '', 'api', 'https://remotive.com/remote-jobs/data/senior-data-scientist-2090982', 'https://remotive.com/remote-jobs/data/senior-data-scientist-2090982', '[{\"url\":\"https://remotive.com/remote-jobs/data/senior-data-scientist-2090982\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(812, NULL, 'api', NULL, 'Maintenance Contract & Billing Specialist EDL GmbH', 'Edl', 'Bochum', 'https://www.arbeitnow.com/jobs/companies/edl/maintenance-contract-billing-specialist-edl-gmbh-bochum-428837', '<p>Maintenance Contract &#x26; Billing Administrator (m/w/d)</p>\n<p><strong>About our company</strong></p>\n<p>EDL is a leading European provider of software solutions for Radiology Information Systems (RIS), Picture Archiving and Communication Systems (PACS), teleradiology, nuclear medicine, and AI-powered imaging solutions. With 180 employees and revenue of €30 million in 2025, EDL is the market leader in France and Switzerland and continues to expand across Belgium, Austria, and Germany.</p>\n<p>Our presence in Germany has grown significantly in recent years through targeted expansion and the integration of Penta Services. We are now accelerating our development in this market through a major acquisition currently underway, which will further strengthen our position and support our long-term growth ambitions in the region.</p>\n<p>About the Role</p>\n<p>We are looking for a Maintenance Contract &#x26; Billing Specialist (m/w/d) to manage the full lifecycle of maintenance and software support contracts while ensuring accurate and timely invoicing. This role serves as a key interface between customers, Sales, Service, Finance, and Legal teams, ensuring contractual compliance and efficient billing processes.</p>\n<p>Key Responsibilities</p>\n<ul>\n<li>Manage maintenance, support, and software service contracts throughout their lifecycle (creation, renewal, amendment, termination, and archiving)</li>\n<li>Monitor contract renewals, pricing updates, and inflation indexation where applicable</li>\n<li>Maintain and update contract and customer data in internal systems</li>\n<li>Prepare, review, and issue maintenance invoices in accordance with contractual terms</li>\n<li>Ensure billing accuracy and compliance with signed agreements</li>\n<li>Track payments and support collection activities for overdue invoices</li>\n<li>Manage purchase orders and administrative validation processes</li>\n<li>Act as the primary contact for customer inquiries related to contracts and billing</li>\n<li>Collaborate closely with Sales, Service, Finance, and Legal teams</li>\n<li>Prepare regular reports and maintain contract and billing dashboards</li>\n<li>Contribute to process improvements and ensure compliance with internal procedures</li>\n</ul>\n<p>Qualifications &#x26; Experience</p>\n<ul>\n<li>2–4 years of experience in contract administration, billing, order management, or a similar role</li>\n<li>Good understanding of maintenance, service, and software support contracts</li>\n<li>Basic knowledge of contract law and software licensing agreements</li>\n<li>Experience reviewing contractual terms and supporting contract renewals and pricing adjustments</li>\n<li>Strong organizational skills and attention to detail</li>\n<li>Proficiency with ERP systems (SAP preferred) and Microsoft Office, especially Excel</li>\n<li>Customer-focused with excellent communication skills</li>\n<li>Fluent German and good English language skills</li>\n</ul>\n<p>What We Offer</p>\n<ul>\n<li>An international and collaborative work environment</li>\n<li>A varied role combining contract management, customer interaction, and billing responsibilities</li>\n<li>Opportunities for professional growth and development</li>\n<li>Competitive salary and benefits package</li>\n</ul>\n<p><strong>Location:</strong> Bochum or Mannheim, Germany</p>\n<p><strong>Employment Type:</strong> Full-time</p>\n<p>Servicevertrags- und Fakturierungsspezialist (m/w/d)</p>\n<h2>Über uns</h2>\n<p>EDL ist ein führender europäischer Anbieter von Softwarelösungen für Radiologie-Informationssysteme (RIS), Picture Archiving and Communication Systems (PACS), Teleradiologie, Nuklearmedizin sowie KI-gestützte Bildgebungslösungen. Mit 180 Mitarbeitenden und einem Umsatz von 30 Mio. Euro im Jahr 2025 ist EDL Marktführer in Frankreich und der Schweiz und baut seine Präsenz in Belgien, Österreich und Deutschland kontinuierlich aus.</p>\n<p>Unsere Aktivitäten in Deutschland haben sich in den vergangenen Jahren durch gezielte Expansion und die Integration von Penta Services deutlich verstärkt. Mit einer derzeit laufenden bedeutenden Akquisition beschleunigen wir nun unser Wachstum auf dem deutschen Markt weiter und stärken nachhaltig unsere Position sowie unsere langfristigen Entwicklungsziele in der Region.</p>\n<h2>Ihre Aufgaben</h2>\n<p>Zur Verstärkung unseres Teams suchen wir einen Servicevertrags- und Fakturierungsspezialisten (m/w/d), der die Verwaltung unserer Wartungs-, Support- und Software-Serviceverträge über den gesamten Vertragslebenszyklus hinweg übernimmt und eine korrekte sowie termingerechte Fakturierung sicherstellt.</p>\n<p>In dieser Funktion arbeiten Sie eng mit unseren Kunden sowie den Bereichen Vertrieb, Service, Finanzen und Recht zusammen und leisten einen wichtigen Beitrag zur Einhaltung vertraglicher Vereinbarungen und zur Optimierung unserer Abrechnungsprozesse.</p>\n<p>Ihre Hauptaufgaben</p>\n<ul>\n<li>Verwaltung von Wartungs-, Support- und Software-Serviceverträgen über den gesamten Vertragslebenszyklus hinweg (Anlage, Verlängerung, Anpassung, Kündigung und Archivierung)</li>\n<li>Überwachung von Vertragsverlängerungen, Preisanpassungen und vertraglich vereinbarten Inflationsindexierungen</li>\n<li>Pflege und Aktualisierung von Vertrags- und Kundendaten in den internen Systemen</li>\n<li>Erstellung, Prüfung und Versand von Wartungsrechnungen gemäß den vertraglichen Vereinbarungen</li>\n<li>Sicherstellung der korrekten Fakturierung und Einhaltung der vertraglichen Bedingungen</li>\n<li>Überwachung von Zahlungseingängen sowie Unterstützung bei Mahn- und Inkassoprozessen</li>\n<li>Verwaltung von Bestellungen (Purchase Orders) und Durchführung administrativer Freigabeprozesse</li>\n<li>Ansprechpartner für Kundenanfragen zu Verträgen und Rechnungen</li>\n<li>Enge Zusammenarbeit mit den Bereichen Vertrieb, Service, Finanzen und Recht</li>\n<li>Erstellung regelmäßiger Reports sowie Pflege von Vertrags- und Fakturierungsübersichten</li>\n<li>Mitwirkung bei der Optimierung interner Prozesse und Sicherstellung der Einhaltung von Richtlinien und Verfahren</li>\n</ul>\n<h2>Ihr Profil</h2>\n<ul>\n<li>2 bis 4 Jahre Berufserfahrung im Vertragsmanagement, in der Fakturierung, Auftragsabwicklung oder einer vergleichbaren Funktion</li>\n<li>Gutes Verständnis von Wartungs-, Service- und Software-Supportverträgen</li>\n<li>Grundkenntnisse im Vertragsrecht sowie Verständnis von Softwarelizenz-, Wartungs- und Serviceverträgen</li>\n<li>Erfahrung in der Prüfung von Vertragsklauseln sowie der Unterstützung von Vertragsverlängerungen und Preisanpassungen</li>\n<li>Ausgeprägte Organisationsfähigkeit und hohe Detailgenauigkeit</li>\n<li>Sicherer Umgang mit ERP-Systemen (idealerweise SAP) sowie Microsoft Office, insbesondere Excel</li>\n<li>Kundenorientierte Arbeitsweise und sehr gute Kommunikationsfähigkeiten</li>\n<li>Fließende Deutschkenntnisse sowie gute Englischkenntnisse in Wort und Schrift</li>\n</ul>\n<h2>Wir bieten</h2>\n<ul>\n<li>Ein internationales und kollegiales Arbeitsumfeld</li>\n<li>Eine abwechslungsreiche Tätigkeit mit Verantwortung in den Bereichen Vertragsmanagement, Kundenbetreuung und Fakturierung</li>\n<li>Individuelle Entwicklungs- und Weiterbildungsmöglichkeiten</li>\n<li>Attraktive Vergütung und Sozialleistungen</li>\n</ul>\n<p><strong>Standort:</strong> Bochum oder Mannheim, Deutschland</p>\n<p><strong>Vertragsart:</strong> Vollzeit</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Maintenance Contract &#x26; Billing Administrator (m/w/d)</p>\n<p><strong>About our company</strong></p>\n<p>EDL is a leading European provider of software solutions for Radiology Information Systems (RIS), Picture Archiving and Communication Systems (PACS), teleradiology, nuclear medicine, and AI-powered imaging solutions. With 180 employees and revenue of €30 million in 2025, EDL is the market leader in France and Switzerland and continues to expand across Belgium, Austria, and Germany.</p>\n<p>Our presence in Germany has grown significantly in recent years through targeted expansion and the integration of Penta Services. We are now accelerating our development in this market through a major acquisition currently underway, which will further strengthen our position and support our long-term growth ambitions in the region.</p>\n<p>About the Role</p>\n<p>We are looking for a Maintenance Contract &#x26; Billing Specialist (m/w/d) to manage the full lifecycle of maintenance and software support contracts while ensuring accurate and timely invoicing. This role serves as a key interface between customers, Sales, Service, Finance, and Legal teams, ensuring contractual compliance and efficient billing processes.</p>\n<p>Key Responsibilities</p>\n<ul>\n<li>Manage maintenance, support, and software service contracts throughout their lifecycle (creation, renewal, amendment, termination, and archiving)</li>\n<li>Monitor contract renewals, pricing updates, and inflation indexation where applicable</li>\n<li>Maintain and update contract and customer data in internal systems</li>\n<li>Prepare, review, and issue maintenance invoices in accordance with contractual terms</li>\n<li>Ensure billing accuracy and compliance with signed agreements</li>\n<li>Track payments and support collection activities for overdue invoices</li>\n<li>Manage purchase orders and administrative validation processes</li>\n<li>Act as the primary contact for customer inquiries related to contracts and billing</li>\n<li>Collaborate closely with Sales, Service, Finance, and Legal teams</li>\n<li>Prepare regular reports and maintain contract and billing dashboards</li>\n<li>Contribute to process improvements and ensure compliance with internal procedures</li>\n</ul>\n<p>Qualifications &#x26; Experience</p>\n<ul>\n<li>2–4 years of experience in contract administration, billing, order management, or a similar role</li>\n<li>Good understanding of maintenance, service, and software support contracts</li>\n<li>Basic knowledge of contract law and software licensing agreements</li>\n<li>Experience reviewing contractual terms and supporting contract renewals and pricing adjustments</li>\n<li>Strong organizational skills and attention to detail</li>\n<li>Proficiency with ERP systems (SAP preferred) and Microsoft Office, especially Excel</li>\n<li>Customer-focused with excellent communication skills</li>\n<li>Fluent German and good English language skills</li>\n</ul>\n<p>What We Offer</p>\n<ul>\n<li>An international and collaborative work environment</li>\n<li>A varied role combining contract management, customer interaction, and billing responsibilities</li>\n<li>Opportunities for professional growth and development</li>\n<li>Competitive salary and benefits package</li>\n</ul>\n<p><strong>Location:</strong> Bochum or Mannheim, Germany</p>\n<p><strong>Employment Type:</strong> Full-time</p>\n<p>Servicevertrags- und Fakturierungsspezialist (m/w/d)</p>\n<h2>Über uns</h2>\n<p>EDL ist ein führender europäischer Anbieter von Softwarelösungen für Radiologie-Informationssysteme (RIS), Picture Archiving and Communication Systems (PACS), Teleradiologie, Nuklearmedizin sowie KI-gestützte Bildgebungslösungen. Mit 180 Mitarbeitenden und einem Umsatz von 30 Mio. Euro im Jahr 2025 ist EDL Marktführer in Frankreich und der Schweiz und baut seine Präsenz in Belgien, Österreich und Deutschland kontinuierlich aus.</p>\n<p>Unsere Aktivitäten in Deutschland haben sich in den vergangenen Jahren durch gezielte Expansion und die Integration von Penta Services deutlich verstärkt. Mit einer derzeit laufenden bedeutenden Akquisition beschleunigen wir nun unser Wachstum auf dem deutschen Markt weiter und stärken nachhaltig unsere Position sowie unsere langfristigen Entwicklungsziele in der Region.</p>\n<h2>Ihre Aufgaben</h2>\n<p>Zur Verstärkung unseres Teams suchen wir einen Servicevertrags- und Fakturierungsspezialisten (m/w/d), der die Verwaltung unserer Wartungs-, Support- und Software-Serviceverträge über den gesamten Vertragslebenszyklus hinweg übernimmt und eine korrekte sowie termingerechte Fakturierung sicherstellt.</p>\n<p>In dieser Funktion arbeiten Sie eng mit unseren Kunden sowie den Bereichen Vertrieb, Service, Finanzen und Recht zusammen und leisten einen wichtigen Beitrag zur Einhaltung vertraglicher Vereinbarungen und zur Optimierung unserer Abrechnungsprozesse.</p>\n<p>Ihre Hauptaufgaben</p>\n<ul>\n<li>Verwaltung von Wartungs-, Support- und Software-Serviceverträgen über den gesamten Vertragslebenszyklus hinweg (Anlage, Verlängerung, Anpassung, Kündigung und Archivierung)</li>\n<li>Überwachung von Vertragsverlängerungen, Preisanpassungen und vertraglich vereinbarten Inflationsindexierungen</li>\n<li>Pflege und Aktualisierung von Vertrags- und Kundendaten in den internen Systemen</li>\n<li>Erstellung, Prüfung und Versand von Wartungsrechnungen gemäß den vertraglichen Vereinbarungen</li>\n<li>Sicherstellung der korrekten Fakturierung und Einhaltung der vertraglichen Bedingungen</li>\n<li>Überwachung von Zahlungseingängen sowie Unterstützung bei Mahn- und Inkassoprozessen</li>\n<li>Verwaltung von Bestellungen (Purchase Orders) und Durchführung administrativer Freigabeprozesse</li>\n<li>Ansprechpartner für Kundenanfragen zu Verträgen und Rechnungen</li>\n<li>Enge Zusammenarbeit mit den Bereichen Vertrieb, Service, Finanzen und Recht</li>\n<li>Erstellung regelmäßiger Reports sowie Pflege von Vertrags- und Fakturierungsübersichten</li>\n<li>Mitwirkung bei der Optimierung interner Prozesse und Sicherstellung der Einhaltung von Richtlinien und Verfahren</li>\n</ul>\n<h2>Ihr Profil</h2>\n<ul>\n<li>2 bis 4 Jahre Berufserfahrung im Vertragsmanagement, in der Fakturierung, Auftragsabwicklung oder einer vergleichbaren Funktion</li>\n<li>Gutes Verständnis von Wartungs-, Service- und Software-Supportverträgen</li>\n<li>Grundkenntnisse im Vertragsrecht sowie Verständnis von Softwarelizenz-, Wartungs- und Serviceverträgen</li>\n<li>Erfahrung in der Prüfung von Vertragsklauseln sowie der Unterstützung von Vertragsverlängerungen und Preisanpassungen</li>\n<li>Ausgeprägte Organisationsfähigkeit und hohe Detailgenauigkeit</li>\n<li>Sicherer Umgang mit ERP-Systemen (idealerweise SAP) sowie Microsoft Office, insbesondere Excel</li>\n<li>Kundenorientierte Arbeitsweise und sehr gute Kommunikationsfähigkeiten</li>\n<li>Fließende Deutschkenntnisse sowie gute Englischkenntnisse in Wort und Schrift</li>\n</ul>\n<h2>Wir bieten</h2>\n<ul>\n<li>Ein internationales und kollegiales Arbeitsumfeld</li>\n<li>Eine abwechslungsreiche Tätigkeit mit Verantwortung in den Bereichen Vertragsmanagement, Kundenbetreuung und Fakturierung</li>\n<li>Individuelle Entwicklungs- und Weiterbildungsmöglichkeiten</li>\n<li>Attraktive Vergütung und Sozialleistungen</li>\n</ul>\n<p><strong>Standort:</strong> Bochum oder Mannheim, Deutschland</p>\n<p><strong>Vertragsart:</strong> Vollzeit</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-14 01:39:55.617', '2026-06-14 01:39:55.617', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/edl/maintenance-contract-billing-specialist-edl-gmbh-bochum-428837', 'https://www.arbeitnow.com/jobs/companies/edl/maintenance-contract-billing-specialist-edl-gmbh-bochum-428837', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/edl/maintenance-contract-billing-specialist-edl-gmbh-bochum-428837\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(813, NULL, 'api', NULL, 'Fachinformatiker Systemintegration / Systemadministrator (m/w/d)', 'IT Fabrik Systemhaus GmbH u. Co.KG', 'Hamburg', 'https://www.arbeitnow.com/jobs/companies/it-fabrik-systemhaus-gmbh-u-cokg/fachinformatiker-systemintegration-systemadministrator-hamburg-155942', '<p>Wir sind ein erfolgreiches IT Systemhaus und suchen motivierte Fachinformatiker (m/w/d), die uns mit ihrem Fachwissen und ihrer Leidenschaft für Technologien unterstützen. Als Teil unseres dynamischen Teams werdet ihr die Möglichkeit haben, an spannenden Projekten mitzuwirken und innovative Lösungen für unsere Kunden zu entwickeln. Wenn ihr mit uns die Zukunft der IT gestaltet möchtet, dann freuen wir uns auf eure Bewerbung.</p>\n<p><strong>Für die Betreuung unserer Kunden im Großraum Hamburg suchen wir einen Kollegen aus der Region Hamburg. Die Position ist remote ausgelegt, setzt jedoch die Bereitschaft voraus, bei Bedarf unsere Kunden vor Ort in Hamburg zu besuchen.</strong></p>\n<p>Die Aufgaben</p>\n<ul>\n<li>Konzeptionierung, Umsetzung und Betreuung von Microsoft 365 / Office 365 Strukturen</li>\n<li>Konfiguration und Administration von Windows Servern (2012/2016/2019)</li>\n<li>Konzeption, Umsetzung und Betreuung von virtuellen Systemen (HyperV, Vmware)</li>\n<li>Aufbau und Betreuung von Kundennetzen</li>\n<li>eigenverantwortliche Betreuung und Durchführung von IT-Projekten</li>\n<li>Kundensupport und Kundenbetreuung</li>\n<li>Hard- und Softwareinstallationen</li>\n</ul>\n<p>Systemanforderungen an dich</p>\n<ul>\n<li>sehr gute Kenntnisse in der Administration von Windows Servern/Clients</li>\n<li>gute Kenntnisse im Bereich Netzwerktechnik, Firewalls, Routing, VPN und WLAN</li>\n<li>sehr gute Hardwarekenntnisse</li>\n<li>fundierte Kenntnisse im Bereich Virtualisierung</li>\n<li>Kenntnisse im TK-Bereich von Vorteil</li>\n<li>analytische Denk- und Arbeitsweise sowie Kommunikationsstärke und Flexibilität</li>\n<li>Berufserfahrung ist von Vorteil</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Wir sind ein erfolgreiches IT Systemhaus und suchen motivierte Fachinformatiker (m/w/d), die uns mit ihrem Fachwissen und ihrer Leidenschaft für Technologien unterstützen. Als Teil unseres dynamischen Teams werdet ihr die Möglichkeit haben, an spannenden Projekten mitzuwirken und innovative Lösungen für unsere Kunden zu entwickeln. Wenn ihr mit uns die Zukunft der IT gestaltet möchtet, dann freuen wir uns auf eure Bewerbung.</p>\n<p><strong>Für die Betreuung unserer Kunden im Großraum Hamburg suchen wir einen Kollegen aus der Region Hamburg. Die Position ist remote ausgelegt, setzt jedoch die Bereitschaft voraus, bei Bedarf unsere Kunden vor Ort in Hamburg zu besuchen.</strong></p>\n<p>Die Aufgaben</p>\n<ul>\n<li>Konzeptionierung, Umsetzung und Betreuung von Microsoft 365 / Office 365 Strukturen</li>\n<li>Konfiguration und Administration von Windows Servern (2012/2016/2019)</li>\n<li>Konzeption, Umsetzung und Betreuung von virtuellen Systemen (HyperV, Vmware)</li>\n<li>Aufbau und Betreuung von Kundennetzen</li>\n<li>eigenverantwortliche Betreuung und Durchführung von IT-Projekten</li>\n<li>Kundensupport und Kundenbetreuung</li>\n<li>Hard- und Softwareinstallationen</li>\n</ul>\n<p>Systemanforderungen an dich</p>\n<ul>\n<li>sehr gute Kenntnisse in der Administration von Windows Servern/Clients</li>\n<li>gute Kenntnisse im Bereich Netzwerktechnik, Firewalls, Routing, VPN und WLAN</li>\n<li>sehr gute Hardwarekenntnisse</li>\n<li>fundierte Kenntnisse im Bereich Virtualisierung</li>\n<li>Kenntnisse im TK-Bereich von Vorteil</li>\n<li>analytische Denk- und Arbeitsweise sowie Kommunikationsstärke und Flexibilität</li>\n<li>Berufserfahrung ist von Vorteil</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-14 01:40:02.390', '2026-06-14 01:40:02.390', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/it-fabrik-systemhaus-gmbh-u-cokg/fachinformatiker-systemintegration-systemadministrator-hamburg-155942', 'https://www.arbeitnow.com/jobs/companies/it-fabrik-systemhaus-gmbh-u-cokg/fachinformatiker-systemintegration-systemadministrator-hamburg-155942', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/it-fabrik-systemhaus-gmbh-u-cokg/fachinformatiker-systemintegration-systemadministrator-hamburg-155942\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(814, NULL, 'api', NULL, 'Partner Success Specialist Central European Market (Based in Germany)', 'Playtomic', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/playtomic/partner-success-specialist-central-european-market-based-in-germany-berlin-323416', '<p><strong>Your mission</strong></p>\n<p>We are looking for a Partner Success Specialist to work with our sports clubs in the <strong>Central European region</strong>, with a primary focus on <strong>Germany</strong> (Germany based role).<br>\nAs a Partner Success Specialist, you’ll play a key role in building and maintaining strong relationships between sports clubs and Playtomic. If you are someone who has a tremendous amount of energy, curiosity and is persuasive… this is the role for you!</p>\n<p><strong>What you’ll be doing</strong></p>\n<ul>\n<li>Build long-term relationships with our top partner clubs through proactive and regular communication, supporting their needs and driving engagement with our platform, including weekly and monthly business reviews and face-to-face meetings.</li>\n<li>Willingness to travel up to 15% and visit partner clubs for face-to-face meetings across Germany</li>\n<li>Improve operational performance of our partner clubs making sure we always deliver the best service to our clubs and players while increasing Playtomic’s revenue</li>\n<li>Onboard new partner clubs to our platform by providing them with all the information and tools they need to start working</li>\n<li>Conduct demo calls with new prospects</li>\n<li>Reduce partner churn by maintaining a very close relationship and being their preferred partner</li>\n<li>Identify and analyze the needs of churned and inactive partners in order to build an action plan for reactivation</li>\n</ul>\n<p><strong>Who you’ll be playing with</strong></p>\n<p>You\'ll be working closely with and reporting to the Regional Director. You\'ll be part of a wider team of Partner Strategic Consultants, each managing their own region.</p>\n<p><strong>Our Ideal \"Player\"</strong></p>\n<ul>\n<li>2-4 years of work experience in Key Account Management, Sales or Customer Success roles</li>\n<li>Preferred: Experience in the padel industry</li>\n<li>Data driven personality</li>\n<li>German native or fluent proficiency / Professional fluency in English (business level)</li>\n<li>Knowledge of padel industry</li>\n<li>Expertise in Excel/Google Sheets is a must</li>\n<li>Strong negotiation, communication, and interpersonal skills</li>\n<li>Problem solver, highly organized and detail oriented</li>\n<li>Comfortable working in a fast-paced, high-growth and high-performance organization</li>\n</ul>\n<p><strong>Extra points</strong></p>\n<ul>\n<li>Experience in the padel industry</li>\n<li>Experience with Hubspot is a plus</li>\n<li>Racket-sports lover!</li>\n</ul>\n<p><strong>What’s in it for you</strong></p>\n<ul>\n<li>Salary: Depending on experience, to be discussed in the meeting with People Team</li>\n<li>Budget for personal training</li>\n<li>Holidays according to the country based + day off on your birthday + 2 days off for Wellness days in August.</li>\n<li>1 additional day off per year worked.</li>\n<li>Perks related to the brand and our sponsorship agreements</li>\n<li>Summer work schedule (July-August 7h/day Monday to Friday)</li>\n<li>Languages Classes</li>\n</ul>\n<p><strong>Our hiring process</strong></p>\n<p>Last, and for you to start warming up, we want to show you whatour process looks like:</p>\n<ul>\n<li><strong>Technical Interview</strong> with the Hiring Manager Manager</li>\n<li><strong>People Interview</strong> - cultural fit + conditions of the offer</li>\n<li><strong>Final Interview with VP New Markets</strong></li>\n</ul>\n<p><strong>About PLAYTOMIC</strong> We\'re the world\'s largest racket sports app, facilitating court bookings, player connections, and community engagement. With trust from investors globally, we\'re leading the charge in sports digitalization, with a diverse team spanning the globe.</p>\n<p>Take a look to our candidate playbook!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Your mission</strong></p>\n<p>We are looking for a Partner Success Specialist to work with our sports clubs in the <strong>Central European region</strong>, with a primary focus on <strong>Germany</strong> (Germany based role).<br>\nAs a Partner Success Specialist, you’ll play a key role in building and maintaining strong relationships between sports clubs and Playtomic. If you are someone who has a tremendous amount of energy, curiosity and is persuasive… this is the role for you!</p>\n<p><strong>What you’ll be doing</strong></p>\n<ul>\n<li>Build long-term relationships with our top partner clubs through proactive and regular communication, supporting their needs and driving engagement with our platform, including weekly and monthly business reviews and face-to-face meetings.</li>\n<li>Willingness to travel up to 15% and visit partner clubs for face-to-face meetings across Germany</li>\n<li>Improve operational performance of our partner clubs making sure we always deliver the best service to our clubs and players while increasing Playtomic’s revenue</li>\n<li>Onboard new partner clubs to our platform by providing them with all the information and tools they need to start working</li>\n<li>Conduct demo calls with new prospects</li>\n<li>Reduce partner churn by maintaining a very close relationship and being their preferred partner</li>\n<li>Identify and analyze the needs of churned and inactive partners in order to build an action plan for reactivation</li>\n</ul>\n<p><strong>Who you’ll be playing with</strong></p>\n<p>You\'ll be working closely with and reporting to the Regional Director. You\'ll be part of a wider team of Partner Strategic Consultants, each managing their own region.</p>\n<p><strong>Our Ideal \"Player\"</strong></p>\n<ul>\n<li>2-4 years of work experience in Key Account Management, Sales or Customer Success roles</li>\n<li>Preferred: Experience in the padel industry</li>\n<li>Data driven personality</li>\n<li>German native or fluent proficiency / Professional fluency in English (business level)</li>\n<li>Knowledge of padel industry</li>\n<li>Expertise in Excel/Google Sheets is a must</li>\n<li>Strong negotiation, communication, and interpersonal skills</li>\n<li>Problem solver, highly organized and detail oriented</li>\n<li>Comfortable working in a fast-paced, high-growth and high-performance organization</li>\n</ul>\n<p><strong>Extra points</strong></p>\n<ul>\n<li>Experience in the padel industry</li>\n<li>Experience with Hubspot is a plus</li>\n<li>Racket-sports lover!</li>\n</ul>\n<p><strong>What’s in it for you</strong></p>\n<ul>\n<li>Salary: Depending on experience, to be discussed in the meeting with People Team</li>\n<li>Budget for personal training</li>\n<li>Holidays according to the country based + day off on your birthday + 2 days off for Wellness days in August.</li>\n<li>1 additional day off per year worked.</li>\n<li>Perks related to the brand and our sponsorship agreements</li>\n<li>Summer work schedule (July-August 7h/day Monday to Friday)</li>\n<li>Languages Classes</li>\n</ul>\n<p><strong>Our hiring process</strong></p>\n<p>Last, and for you to start warming up, we want to show you whatour process looks like:</p>\n<ul>\n<li><strong>Technical Interview</strong> with the Hiring Manager Manager</li>\n<li><strong>People Interview</strong> - cultural fit + conditions of the offer</li>\n<li><strong>Final Interview with VP New Markets</strong></li>\n</ul>\n<p><strong>About PLAYTOMIC</strong> We\'re the world\'s largest racket sports app, facilitating court bookings, player connections, and community engagement. With trust from investors globally, we\'re leading the charge in sports digitalization, with a diverse team spanning the globe.</p>\n<p>Take a look to our candidate playbook!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-14 01:40:09.329', '2026-06-14 01:40:09.329', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/playtomic/partner-success-specialist-central-european-market-based-in-germany-berlin-323416', 'https://www.arbeitnow.com/jobs/companies/playtomic/partner-success-specialist-central-european-market-based-in-germany-berlin-323416', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/playtomic/partner-success-specialist-central-european-market-based-in-germany-berlin-323416\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(815, NULL, 'api', NULL, 'Projektleiter im Bereich Kabelleitungsbau', 'ONT Oberhausener Nachrichtentechnik GmbH', 'Oberhausen', 'https://www.arbeitnow.com/jobs/companies/ont-oberhausener-nachrichtentechnik-gmbh/projektleiter-im-bereich-kabelleitungsbau-oberhausen-217422', '<p>Die ONT Oberhausener Nachrichtentechnik GmbH ist ein bundesweit agierendes Unternehmen für Kommunikationstechnik und Systemintegration. Als Team greifen wir auf eine jahrelange Erfahrung im Telekommunikationsbereich zurück. Zu unseren Kunden gehören Telekommunikationsanbieter, Energieversorger, Industriebetriebe sowie Verkehrs- und Bahnunternehmen. Als dynamisches Unternehmen bieten wir eine offene Unternehmensstruktur mit flachen Hierarchien.\nWir verstehen die Zufriedenheit und Qualifikation unserer Mitarbeiter als Basis unseres Erfolgs.</p>\n<h2>Aufgaben</h2>\n<p>•Sie arbeiten bei internem und externen Genehmigungs- und Planungsaufgaben mit und sind verantwortlich für Projektsteuerung, Bauablauf- u. Ressourcenplanung\n•Als projektbezogener Ansprechpartner kommunizieren Sie mit unseren Auftraggebern und Bauherren\n•Sie stellen die termin- und qualitätsgerechte Abwicklung von Tiefbauvorhaben sicher\n•Außerdem gehören die Überwachung und Koordination von Nachunternehmern bei der Rohr- u. Kabelverlegung zu Ihren Aufgaben\n•Sie bereiten die Projektdokumentationen für den Innendienst vor sowie die\n•Abrechnung und das Nachtragsmanagement</p>\n<h2>Qualifikation</h2>\n<p>•Sie haben ein abgeschlossenes Studium im technischen Umfeld oder die Meisterschule abgeschlossen\n•Idealerweise verfügen Sie über mehrjährige Berufserfahrung in der Abwicklung von Tief- und Leitungsbauprojekten sowie Kenntnisse im Bereich HDD-Spülbohrverfahren\n•Sie bringen ein hohes Maß an Initiative und Lernbereitschaft mit und arbeiten eigenständig und verantwortungsbewusst\n•Sie sind in der Lage betriebsorientiert zu Denken und Handeln\n•Der Einsatz auf der Baustelle im Bundesgebiet (tageweise, überwiegend NRW) ist für Sie kein Hindernis\n•Sie verfügen über einen Führerschein der Klasse B (Pkw)</p>\n<h2>Benefits</h2>\n<p>•Neben einem attraktiven Vergütungspaket erwartet Sie Fairness im Umgang, motivierte und erfahrene Mitarbeiter sowie ein kollegiales Führungsteam\n•Sie können sich auf langfristige Perspektive in einem schnell wachsenden Unternehmen freuen\n•Ein Dienstfahrzeug zur privaten Nutzung gehört ebenfalls dazu\n•Es stehen Ihnen individuell zugeschnittene Weiterbildungsmöglichkeiten zur Verfügung\n•Und ganz wichtig: Unsere gesamte Leidenschaft unser Team zu verbessern und zusammen weiter zu wachsen</p>\n<p>Wir freuen freuen uns über Ihre Bewerbung !</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Die ONT Oberhausener Nachrichtentechnik GmbH ist ein bundesweit agierendes Unternehmen für Kommunikationstechnik und Systemintegration. Als Team greifen wir auf eine jahrelange Erfahrung im Telekommunikationsbereich zurück. Zu unseren Kunden gehören Telekommunikationsanbieter, Energieversorger, Industriebetriebe sowie Verkehrs- und Bahnunternehmen. Als dynamisches Unternehmen bieten wir eine offene Unternehmensstruktur mit flachen Hierarchien.\nWir verstehen die Zufriedenheit und Qualifikation unserer Mitarbeiter als Basis unseres Erfolgs.</p>\n<h2>Aufgaben</h2>\n<p>•Sie arbeiten bei internem und externen Genehmigungs- und Planungsaufgaben mit und sind verantwortlich für Projektsteuerung, Bauablauf- u. Ressourcenplanung\n•Als projektbezogener Ansprechpartner kommunizieren Sie mit unseren Auftraggebern und Bauherren\n•Sie stellen die termin- und qualitätsgerechte Abwicklung von Tiefbauvorhaben sicher\n•Außerdem gehören die Überwachung und Koordination von Nachunternehmern bei der Rohr- u. Kabelverlegung zu Ihren Aufgaben\n•Sie bereiten die Projektdokumentationen für den Innendienst vor sowie die\n•Abrechnung und das Nachtragsmanagement</p>\n<h2>Qualifikation</h2>\n<p>•Sie haben ein abgeschlossenes Studium im technischen Umfeld oder die Meisterschule abgeschlossen\n•Idealerweise verfügen Sie über mehrjährige Berufserfahrung in der Abwicklung von Tief- und Leitungsbauprojekten sowie Kenntnisse im Bereich HDD-Spülbohrverfahren\n•Sie bringen ein hohes Maß an Initiative und Lernbereitschaft mit und arbeiten eigenständig und verantwortungsbewusst\n•Sie sind in der Lage betriebsorientiert zu Denken und Handeln\n•Der Einsatz auf der Baustelle im Bundesgebiet (tageweise, überwiegend NRW) ist für Sie kein Hindernis\n•Sie verfügen über einen Führerschein der Klasse B (Pkw)</p>\n<h2>Benefits</h2>\n<p>•Neben einem attraktiven Vergütungspaket erwartet Sie Fairness im Umgang, motivierte und erfahrene Mitarbeiter sowie ein kollegiales Führungsteam\n•Sie können sich auf langfristige Perspektive in einem schnell wachsenden Unternehmen freuen\n•Ein Dienstfahrzeug zur privaten Nutzung gehört ebenfalls dazu\n•Es stehen Ihnen individuell zugeschnittene Weiterbildungsmöglichkeiten zur Verfügung\n•Und ganz wichtig: Unsere gesamte Leidenschaft unser Team zu verbessern und zusammen weiter zu wachsen</p>\n<p>Wir freuen freuen uns über Ihre Bewerbung !</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-14 01:40:16.805', '2026-06-14 01:40:16.805', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/ont-oberhausener-nachrichtentechnik-gmbh/projektleiter-im-bereich-kabelleitungsbau-oberhausen-217422', 'https://www.arbeitnow.com/jobs/companies/ont-oberhausener-nachrichtentechnik-gmbh/projektleiter-im-bereich-kabelleitungsbau-oberhausen-217422', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/ont-oberhausener-nachrichtentechnik-gmbh/projektleiter-im-bereich-kabelleitungsbau-oberhausen-217422\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
