INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(901, NULL, 'api', NULL, 'Controller (m/w/d)', 'ANGEHEUERT GmbH Personalberatung', 'Föhren', 'https://www.arbeitnow.com/jobs/companies/angeheuert-gmbh-personalberatung/controller-fohren-300477', '<p>Unser Kunde aus der Branche der erneuerbaren Energien verfolgt das Ziel, nachhaltige Energieversorgung für Privatkunden, Unternehmen und Industrie zugänglich zu machen. Das Unternehmen gehört zu den etablierten Anbietern seiner Branche. Kaufmännische Entscheidungen spielen dabei eine wichtige Rolle für die weitere Entwicklung. Als Controller unterstützt du die wirtschaftliche Steuerung des Unternehmens. So verbindest du analytische Arbeit mit einem klaren Zukunftsbezug.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li><strong>Reporting:</strong> Erstellung von Monats, Quartals und Jahresreportings für die Unternehmensgruppe.</li>\n<li><strong>Abweichungsanalysen:</strong> Durchführung von Soll Ist Vergleichen und Analyse wirtschaftlicher Entwicklungen.</li>\n<li><strong>Handlungsempfehlungen:</strong> Ableitung fundierter Empfehlungen für Managemententscheidungen.</li>\n<li><strong>Budgetplanung:</strong> Mitarbeit bei Budgetierungs und Forecastprozessen.</li>\n<li><strong>Berichtswesen:</strong> Weiterentwicklung bestehender Reportingstrukturen.</li>\n<li><strong>Prozessoptimierung:</strong> Optimierung und Ausbau der Controllingprozesse.</li>\n<li><strong>BI Tools:</strong> Unterstützung beim Aufbau und der Weiterentwicklung moderner BI Lösungen.</li>\n<li><strong>Reporting Systeme:</strong> Pflege von Reporting Systemen und Sicherstellung einer hohen Datenqualität.</li>\n<li><strong>Business Partnering:</strong> Übernahme der Rolle als betriebswirtschaftlicher Sparringspartner für Fachabteilungen.</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li><strong>Studium:</strong> Erfolgreich abgeschlossenes Studium der Betriebswirtschaftslehre mit Schwerpunkt Finanzen und Controlling oder eine vergleichbare Qualifikation.</li>\n<li><strong>Berufserfahrung:</strong> Als <strong>Controller</strong> bringst du mindestens vier bis sechs Jahre Berufserfahrung im Controlling mit.</li>\n<li><strong>MS Excel:</strong> Sehr gute Kenntnisse in MS Excel.</li>\n<li><strong>SAP Business One:</strong> Praktische Erfahrung im Umgang mit SAP Business One.</li>\n<li><strong>BI Tools:</strong> Sicherer Umgang mit gängigen BI Tools.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li><strong>Unbefristete Festanstellung:</strong> Langfristige Perspektive in einem wachsenden Unternehmen.</li>\n<li><strong>Homeoffice Möglichkeit:</strong> Flexible Kombination aus Büro und mobilem Arbeiten.</li>\n<li><strong>Flexible Arbeitszeiten:</strong> Mehr Freiraum für Beruf und Privatleben.</li>\n<li><strong>30 Tage Urlaub:</strong> Zeit für Erholung und persönliche Projekte.</li>\n<li><strong>Weiterbildung:</strong> Umfangreiche Entwicklungsmöglichkeiten über die interne Akademie.</li>\n<li><strong>Betriebliche Zusatzkrankenversicherung:</strong> 70 % Zahnersatz sowie 300 € Gesundheitsbudget pro Jahr.</li>\n<li><strong>Jobrad:</strong> Nachhaltige Mobilität mit attraktiven Konditionen.</li>\n<li><strong>Firmenfitness:</strong> Unterstützung deiner gesundheitlichen Ziele.</li>\n<li><strong>Mitarbeiterberatung:</strong> Externe Unterstützung bei beruflichen und privaten Themen.</li>\n<li><strong>Corporate Benefits:</strong> Zugang zu attraktiven Angeboten bei zahlreichen Partnerunternehmen.</li>\n</ul>\n<p><strong>So geht es weiter</strong></p>\n<p>Du möchtest mit deiner analytischen Arbeit einen Beitrag zu einer nachhaltigen Zukunft leisten und dabei Verantwortung übernehmen? Hier erwarten dich spannende Aufgaben, kurze Entscheidungswege und echte Gestaltungsmöglichkeiten. Dann bewirb dich jetzt als Controller.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Unser Kunde aus der Branche der erneuerbaren Energien verfolgt das Ziel, nachhaltige Energieversorgung für Privatkunden, Unternehmen und Industrie zugänglich zu machen. Das Unternehmen gehört zu den etablierten Anbietern seiner Branche. Kaufmännische Entscheidungen spielen dabei eine wichtige Rolle für die weitere Entwicklung. Als Controller unterstützt du die wirtschaftliche Steuerung des Unternehmens. So verbindest du analytische Arbeit mit einem klaren Zukunftsbezug.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li><strong>Reporting:</strong> Erstellung von Monats, Quartals und Jahresreportings für die Unternehmensgruppe.</li>\n<li><strong>Abweichungsanalysen:</strong> Durchführung von Soll Ist Vergleichen und Analyse wirtschaftlicher Entwicklungen.</li>\n<li><strong>Handlungsempfehlungen:</strong> Ableitung fundierter Empfehlungen für Managemententscheidungen.</li>\n<li><strong>Budgetplanung:</strong> Mitarbeit bei Budgetierungs und Forecastprozessen.</li>\n<li><strong>Berichtswesen:</strong> Weiterentwicklung bestehender Reportingstrukturen.</li>\n<li><strong>Prozessoptimierung:</strong> Optimierung und Ausbau der Controllingprozesse.</li>\n<li><strong>BI Tools:</strong> Unterstützung beim Aufbau und der Weiterentwicklung moderner BI Lösungen.</li>\n<li><strong>Reporting Systeme:</strong> Pflege von Reporting Systemen und Sicherstellung einer hohen Datenqualität.</li>\n<li><strong>Business Partnering:</strong> Übernahme der Rolle als betriebswirtschaftlicher Sparringspartner für Fachabteilungen.</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li><strong>Studium:</strong> Erfolgreich abgeschlossenes Studium der Betriebswirtschaftslehre mit Schwerpunkt Finanzen und Controlling oder eine vergleichbare Qualifikation.</li>\n<li><strong>Berufserfahrung:</strong> Als <strong>Controller</strong> bringst du mindestens vier bis sechs Jahre Berufserfahrung im Controlling mit.</li>\n<li><strong>MS Excel:</strong> Sehr gute Kenntnisse in MS Excel.</li>\n<li><strong>SAP Business One:</strong> Praktische Erfahrung im Umgang mit SAP Business One.</li>\n<li><strong>BI Tools:</strong> Sicherer Umgang mit gängigen BI Tools.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li><strong>Unbefristete Festanstellung:</strong> Langfristige Perspektive in einem wachsenden Unternehmen.</li>\n<li><strong>Homeoffice Möglichkeit:</strong> Flexible Kombination aus Büro und mobilem Arbeiten.</li>\n<li><strong>Flexible Arbeitszeiten:</strong> Mehr Freiraum für Beruf und Privatleben.</li>\n<li><strong>30 Tage Urlaub:</strong> Zeit für Erholung und persönliche Projekte.</li>\n<li><strong>Weiterbildung:</strong> Umfangreiche Entwicklungsmöglichkeiten über die interne Akademie.</li>\n<li><strong>Betriebliche Zusatzkrankenversicherung:</strong> 70 % Zahnersatz sowie 300 € Gesundheitsbudget pro Jahr.</li>\n<li><strong>Jobrad:</strong> Nachhaltige Mobilität mit attraktiven Konditionen.</li>\n<li><strong>Firmenfitness:</strong> Unterstützung deiner gesundheitlichen Ziele.</li>\n<li><strong>Mitarbeiterberatung:</strong> Externe Unterstützung bei beruflichen und privaten Themen.</li>\n<li><strong>Corporate Benefits:</strong> Zugang zu attraktiven Angeboten bei zahlreichen Partnerunternehmen.</li>\n</ul>\n<p><strong>So geht es weiter</strong></p>\n<p>Du möchtest mit deiner analytischen Arbeit einen Beitrag zu einer nachhaltigen Zukunft leisten und dabei Verantwortung übernehmen? Hier erwarten dich spannende Aufgaben, kurze Entscheidungswege und echte Gestaltungsmöglichkeiten. Dann bewirb dich jetzt als Controller.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-15 13:41:49.628', '2026-06-15 13:41:49.628', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/angeheuert-gmbh-personalberatung/controller-fohren-300477', 'https://www.arbeitnow.com/jobs/companies/angeheuert-gmbh-personalberatung/controller-fohren-300477', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/angeheuert-gmbh-personalberatung/controller-fohren-300477\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(902, NULL, 'api', NULL, 'Projektleiter SHK/TGA (m/w/d)', 'Maier Heiztechnik GmbH', 'Köngen', 'https://www.arbeitnow.com/jobs/companies/maier-heiztechnik-gmbh/projektleiter-shk-tga-kongen-454669', '<h2>Ihre Aufgaben</h2>\n<ul>\n<li>Selbstständige Planung, Abwicklung und Koordination von Projekten</li>\n<li>Erstellung von Angeboten, Nachträgen und regelmäßiger Ausmaß</li>\n<li>Fachliche Führung und Koordination der Monteure, Obermonteure und Subunternehmer auf der Baustelle</li>\n<li>Dokumentation und Baustellenüberwachung bis zur erfolgreichen Abnahme</li>\n<li>Vorbereitung und Unterstützung der Inbetriebnahme und Abnahme dieser Anlagen</li>\n</ul>\n<h2>Ihr Profil</h2>\n<ul>\n<li>Abschluss als Techniker oder Meister mit mehrjähriger Berufserfahrung in der Projektleitung im Anlagenbau mit Schwerpunkt Heizung, Kälte und Klima</li>\n<li>Selbstständige und eigenverantwortliche Arbeitsweise</li>\n<li>Teamfähigkeit und Belastbarkeit auch in hektischen Situationen</li>\n<li>Lesen und verstehen von Montageplänen</li>\n<li>Kenntnisse für die Aufmaßerstellung und der VOB</li>\n<li>Gute Deutschkenntnisse in Wort</li>\n</ul>\n<h2>Warum wir?</h2>\n<ul>\n<li>Abwechslungsreicher und zukunftssicherer Arbeitsplatz in Festanstellung</li>\n<li>Hohe Bezahlung mit Top Konditionen und Sonderzahlungen</li>\n<li>Viel Gestaltungsspielraum und Platz für eigene Ideen</li>\n<li>Ambitioniertes Team mit Leidenschaft und Spaß an der Arbeit</li>\n<li>Spannende Projekte in der Region</li>\n<li>Modernes Dienstfahrzeug und hochwertiges Werkzeug</li>\n<li>Aktuelles Firmenhandy und Tablet, gelebte Digitalisierung</li>\n<li>Gemeinsame Aktivitäten auch nach der Arbeit</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>Ihre Aufgaben</h2>\n<ul>\n<li>Selbstständige Planung, Abwicklung und Koordination von Projekten</li>\n<li>Erstellung von Angeboten, Nachträgen und regelmäßiger Ausmaß</li>\n<li>Fachliche Führung und Koordination der Monteure, Obermonteure und Subunternehmer auf der Baustelle</li>\n<li>Dokumentation und Baustellenüberwachung bis zur erfolgreichen Abnahme</li>\n<li>Vorbereitung und Unterstützung der Inbetriebnahme und Abnahme dieser Anlagen</li>\n</ul>\n<h2>Ihr Profil</h2>\n<ul>\n<li>Abschluss als Techniker oder Meister mit mehrjähriger Berufserfahrung in der Projektleitung im Anlagenbau mit Schwerpunkt Heizung, Kälte und Klima</li>\n<li>Selbstständige und eigenverantwortliche Arbeitsweise</li>\n<li>Teamfähigkeit und Belastbarkeit auch in hektischen Situationen</li>\n<li>Lesen und verstehen von Montageplänen</li>\n<li>Kenntnisse für die Aufmaßerstellung und der VOB</li>\n<li>Gute Deutschkenntnisse in Wort</li>\n</ul>\n<h2>Warum wir?</h2>\n<ul>\n<li>Abwechslungsreicher und zukunftssicherer Arbeitsplatz in Festanstellung</li>\n<li>Hohe Bezahlung mit Top Konditionen und Sonderzahlungen</li>\n<li>Viel Gestaltungsspielraum und Platz für eigene Ideen</li>\n<li>Ambitioniertes Team mit Leidenschaft und Spaß an der Arbeit</li>\n<li>Spannende Projekte in der Region</li>\n<li>Modernes Dienstfahrzeug und hochwertiges Werkzeug</li>\n<li>Aktuelles Firmenhandy und Tablet, gelebte Digitalisierung</li>\n<li>Gemeinsame Aktivitäten auch nach der Arbeit</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-15 13:41:58.343', '2026-06-15 13:41:58.343', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/maier-heiztechnik-gmbh/projektleiter-shk-tga-kongen-454669', 'https://www.arbeitnow.com/jobs/companies/maier-heiztechnik-gmbh/projektleiter-shk-tga-kongen-454669', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/maier-heiztechnik-gmbh/projektleiter-shk-tga-kongen-454669\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(903, NULL, 'api', NULL, 'IT Engineer für digitale Lösungen und technische Systeme (m/w/d)', 'CaraConsult GmbH', 'Bad Homburg', 'https://www.arbeitnow.com/jobs/companies/caraconsult-gmbh/it-engineer-fur-digitale-losungen-und-technische-systeme-bad-homburg-72835', '<p>Gestalte IT, Daten und digitale Lösungen mit echtem Praxisbezug</p>\n<p>Du hast bereits Erfahrung im IT-Umfeld gesammelt und möchtest technische Themen nicht nur verwalten, sondern aktiv weiterentwickeln? Du arbeitest gerne an unterschiedlichen Aufgaben, verstehst technische Zusammenhänge und möchtest Lösungen bauen, verbessern und im laufenden Betrieb begleiten? Dann könnte diese Rolle gut zu dir passen.</p>\n<p>CaraConsult ist eine spezialisierte Beratungsgesellschaft für die Caravaning-Branche. Unsere Kunden sind vor allem mittelständische Unternehmen rund um Wohnmobile, Wohnwagen und Freizeitfahrzeuge. Wir unterstützen sie dabei, Prozesse zu verbessern, Daten besser zu nutzen, Digitalisierungsvorhaben umzusetzen und wirtschaftlich fundierte Entscheidungen zu treffen.</p>\n<p>Unsere IT ist eng mit diesen Themen verbunden. Wir betreiben nicht nur interne Systeme, sondern entwickeln auch eigene Anwendungen, Datenlösungen, Automatisierungen, Schnittstellen und Reportinglösungen. Ein wichtiger Teil unserer Arbeit besteht darin, technische Anforderungen aus dem Alltag zu verstehen und daraus pragmatische, stabile und nutzbare Lösungen zu machen.</p>\n<p>Für diese Rolle suchen wir keine Person, die jedes einzelne Thema bereits perfekt beherrscht. Wichtig ist uns ein solides technisches Fundament, Lernbereitschaft, Verantwortungsbewusstsein und die Fähigkeit, sich in gewachsene Systeme und neue Fragestellungen einzuarbeiten.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Du arbeitest an IT- und Digitalisierungsthemen im laufenden Betrieb und in Projekten. Dazu gehören die Betreuung und Weiterentwicklung unserer Microsoft-365-Umgebung, die Mitarbeit an internen Systemen, Daten- und Reportinglösungen, Automatisierungen, Schnittstellen sowie technischen Kundenprojekten.</li>\n<li>Du analysierst Anforderungen, ordnest technische Möglichkeiten ein und setzt Verbesserungen pragmatisch um. Dabei geht es nicht nur darum, dass etwas kurzfristig funktioniert, sondern auch darum, dass Lösungen nachvollziehbar, wartbar und langfristig stabil bleiben.</li>\n<li>Je nach Erfahrung und persönlichem Schwerpunkt kannst du dich stärker in IT-Betrieb, Softwareentwicklung, Datenverarbeitung, Automatisierung, Infrastruktur oder technische Kundenlösungen einbringen. Wichtig ist, dass du technische Themen ganzheitlich betrachten möchtest und verstehst, dass Entwicklung, Betrieb, Dokumentation und kontinuierliche Verbesserung eng zusammenhängen.</li>\n<li>Du hilfst außerdem dabei, bestehende Lösungen transparenter zu machen, Wissen besser zu dokumentieren und technische Strukturen Schritt für Schritt weiterzuentwickeln.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Wichtig ist uns nicht, dass du jede einzelne Technologie aus dem Stand beherrschst. Entscheidend ist, dass du ein gutes technisches Gesamtverständnis mitbringst und dich sicher in unterschiedlichen IT-Fragestellungen bewegst.</p>\n<p>Besonders relevant sind für uns:</p>\n<ul>\n<li>mehrjährige Erfahrung im IT-Umfeld, zum Beispiel in Administration, Systembetreuung, technischer Projektarbeit, Digitalisierung, Softwareentwicklung, Datenverarbeitung oder einer vergleichbaren Rolle</li>\n<li>praktische Erfahrung mit mindestens einer Programmiersprache oder Skriptsprache, zum Beispiel Python, PHP, JavaScript, TypeScript oder einer vergleichbaren Sprache</li>\n<li>gutes Verständnis für Microsoft 365, insbesondere Benutzer, Gruppen, Berechtigungen, SharePoint, Teams und grundlegende Administrations- oder Supportprozesse</li>\n<li>Erfahrung oder gutes Grundverständnis im Umgang mit Daten, Datenbanken, SQL, Reporting und Power BI</li>\n<li>Bereitschaft, dich in bestehende Anwendungen, Automatisierungen, Schnittstellen und technische Prozesse einzuarbeiten</li>\n<li>Grundverständnis für produktive Systeme, Hosting, Deployment, Serverbetrieb oder Cloud-Plattformen</li>\n<li>Fähigkeit, technische Anforderungen zu analysieren, Prioritäten zu erkennen und pragmatische Lösungen umzusetzen</li>\n<li>strukturierte Arbeitsweise, Verantwortungsbewusstsein und Bereitschaft, Wissen nachvollziehbar zu dokumentieren</li>\n<li>Interesse daran, fachliche Anforderungen und Kundenprozesse zu verstehen</li>\n</ul>\n<p>Power BI ist für uns besonders relevant, weil wir es aktuell intensiv für Daten-, Reporting- und Kundenlösungen einsetzen. Du musst nicht jedes Detail perfekt beherrschen, solltest aber entweder bereits praktische Erfahrung damit mitbringen oder sehr bereit sein, dich schnell und intensiv in diesen Bereich einzuarbeiten.</p>\n<h2>Benefits</h2>\n<ul>\n<li>Bei uns arbeitest du in einem <strong>modernen Umfeld</strong> mit echten Einblicken in Unternehmen, reale Prozesse und konkrete technische Anforderungen. Dich erwartet eine <strong>verantwortungsvolle Rolle mit Gestaltungsspielraum</strong>, kurzen Entscheidungswegen und direkter Zusammenarbeit.</li>\n<li>Unser Büro liegt <strong>zentral in Bad Homburg</strong>, direkt gegenüber vom Kurpark, in einem schönen Altbau mit modernen Arbeitsplätzen und guter Verkehrsanbindung. Wir legen Wert auf ein gutes Miteinander und nutzen gemeinsame Tage im Büro bewusst für Austausch, Teamarbeit und persönliche Abstimmung.</li>\n<li>Du erhältst <strong>flexible Arbeitszeiten</strong>, mobiles Arbeiten, eine Ausstattung für dein <strong>Homeoffice</strong>, regelmäßige Teamevents, gemeinsame Workshops, kostenfreie Getränke im Büro und Möglichkeiten zur fachlichen Weiterentwicklung.</li>\n<li>Nach der Einarbeitungszeit ist eine überwiegend remote mögliche Tätigkeit realistisch. Gleichzeitig wirst du bei uns nicht allein gelassen: Wir arbeiten dich strukturiert ein, geben dir Einblick in unsere Systeme und unterstützen dich dabei, Schritt für Schritt Verantwortung zu übernehmen.</li>\n</ul>\n<p>Diese Rolle passt besonders gut zu Menschen, die technische Breite mögen und nicht nur ein sehr enges Aufgabengebiet bearbeiten möchten. Bei uns gibt es gewachsene Systeme, konkrete Kundenanforderungen und viele Themen, die pragmatisch weiterentwickelt werden müssen. Das erfordert technisches Verständnis, Eigeninitiative und die Bereitschaft, Verantwortung für Lösungen zu übernehmen.</p>\n<p>Hilfreich ist außerdem, wenn du gerne zwischen unterschiedlichen Themen wechselst, dich nicht von unklaren Anforderungen abschrecken lässt und bestehende Strukturen lieber verbesserst, statt dich über sie zu ärgern. Wir suchen jemanden, der sauber arbeitet, aber nicht nur theoretische Ideallösungen verfolgt. Am Ende sollen Lösungen funktionieren, verständlich bleiben und für unser Team oder unsere Kunden echten Nutzen schaffen.</p>\n<p>Branchenwissen im Caravaning-Handel brauchst du nicht mitzubringen. Wichtig ist aber, dass du verstehen möchtest, wie unsere Kunden arbeiten und welche technischen Lösungen ihnen im Alltag wirklich helfen.</p>\n<p><strong>Klingt interessant?</strong></p>\n<p>Dann freuen wir uns darauf, dich kennenzulernen.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Gestalte IT, Daten und digitale Lösungen mit echtem Praxisbezug</p>\n<p>Du hast bereits Erfahrung im IT-Umfeld gesammelt und möchtest technische Themen nicht nur verwalten, sondern aktiv weiterentwickeln? Du arbeitest gerne an unterschiedlichen Aufgaben, verstehst technische Zusammenhänge und möchtest Lösungen bauen, verbessern und im laufenden Betrieb begleiten? Dann könnte diese Rolle gut zu dir passen.</p>\n<p>CaraConsult ist eine spezialisierte Beratungsgesellschaft für die Caravaning-Branche. Unsere Kunden sind vor allem mittelständische Unternehmen rund um Wohnmobile, Wohnwagen und Freizeitfahrzeuge. Wir unterstützen sie dabei, Prozesse zu verbessern, Daten besser zu nutzen, Digitalisierungsvorhaben umzusetzen und wirtschaftlich fundierte Entscheidungen zu treffen.</p>\n<p>Unsere IT ist eng mit diesen Themen verbunden. Wir betreiben nicht nur interne Systeme, sondern entwickeln auch eigene Anwendungen, Datenlösungen, Automatisierungen, Schnittstellen und Reportinglösungen. Ein wichtiger Teil unserer Arbeit besteht darin, technische Anforderungen aus dem Alltag zu verstehen und daraus pragmatische, stabile und nutzbare Lösungen zu machen.</p>\n<p>Für diese Rolle suchen wir keine Person, die jedes einzelne Thema bereits perfekt beherrscht. Wichtig ist uns ein solides technisches Fundament, Lernbereitschaft, Verantwortungsbewusstsein und die Fähigkeit, sich in gewachsene Systeme und neue Fragestellungen einzuarbeiten.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Du arbeitest an IT- und Digitalisierungsthemen im laufenden Betrieb und in Projekten. Dazu gehören die Betreuung und Weiterentwicklung unserer Microsoft-365-Umgebung, die Mitarbeit an internen Systemen, Daten- und Reportinglösungen, Automatisierungen, Schnittstellen sowie technischen Kundenprojekten.</li>\n<li>Du analysierst Anforderungen, ordnest technische Möglichkeiten ein und setzt Verbesserungen pragmatisch um. Dabei geht es nicht nur darum, dass etwas kurzfristig funktioniert, sondern auch darum, dass Lösungen nachvollziehbar, wartbar und langfristig stabil bleiben.</li>\n<li>Je nach Erfahrung und persönlichem Schwerpunkt kannst du dich stärker in IT-Betrieb, Softwareentwicklung, Datenverarbeitung, Automatisierung, Infrastruktur oder technische Kundenlösungen einbringen. Wichtig ist, dass du technische Themen ganzheitlich betrachten möchtest und verstehst, dass Entwicklung, Betrieb, Dokumentation und kontinuierliche Verbesserung eng zusammenhängen.</li>\n<li>Du hilfst außerdem dabei, bestehende Lösungen transparenter zu machen, Wissen besser zu dokumentieren und technische Strukturen Schritt für Schritt weiterzuentwickeln.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Wichtig ist uns nicht, dass du jede einzelne Technologie aus dem Stand beherrschst. Entscheidend ist, dass du ein gutes technisches Gesamtverständnis mitbringst und dich sicher in unterschiedlichen IT-Fragestellungen bewegst.</p>\n<p>Besonders relevant sind für uns:</p>\n<ul>\n<li>mehrjährige Erfahrung im IT-Umfeld, zum Beispiel in Administration, Systembetreuung, technischer Projektarbeit, Digitalisierung, Softwareentwicklung, Datenverarbeitung oder einer vergleichbaren Rolle</li>\n<li>praktische Erfahrung mit mindestens einer Programmiersprache oder Skriptsprache, zum Beispiel Python, PHP, JavaScript, TypeScript oder einer vergleichbaren Sprache</li>\n<li>gutes Verständnis für Microsoft 365, insbesondere Benutzer, Gruppen, Berechtigungen, SharePoint, Teams und grundlegende Administrations- oder Supportprozesse</li>\n<li>Erfahrung oder gutes Grundverständnis im Umgang mit Daten, Datenbanken, SQL, Reporting und Power BI</li>\n<li>Bereitschaft, dich in bestehende Anwendungen, Automatisierungen, Schnittstellen und technische Prozesse einzuarbeiten</li>\n<li>Grundverständnis für produktive Systeme, Hosting, Deployment, Serverbetrieb oder Cloud-Plattformen</li>\n<li>Fähigkeit, technische Anforderungen zu analysieren, Prioritäten zu erkennen und pragmatische Lösungen umzusetzen</li>\n<li>strukturierte Arbeitsweise, Verantwortungsbewusstsein und Bereitschaft, Wissen nachvollziehbar zu dokumentieren</li>\n<li>Interesse daran, fachliche Anforderungen und Kundenprozesse zu verstehen</li>\n</ul>\n<p>Power BI ist für uns besonders relevant, weil wir es aktuell intensiv für Daten-, Reporting- und Kundenlösungen einsetzen. Du musst nicht jedes Detail perfekt beherrschen, solltest aber entweder bereits praktische Erfahrung damit mitbringen oder sehr bereit sein, dich schnell und intensiv in diesen Bereich einzuarbeiten.</p>\n<h2>Benefits</h2>\n<ul>\n<li>Bei uns arbeitest du in einem <strong>modernen Umfeld</strong> mit echten Einblicken in Unternehmen, reale Prozesse und konkrete technische Anforderungen. Dich erwartet eine <strong>verantwortungsvolle Rolle mit Gestaltungsspielraum</strong>, kurzen Entscheidungswegen und direkter Zusammenarbeit.</li>\n<li>Unser Büro liegt <strong>zentral in Bad Homburg</strong>, direkt gegenüber vom Kurpark, in einem schönen Altbau mit modernen Arbeitsplätzen und guter Verkehrsanbindung. Wir legen Wert auf ein gutes Miteinander und nutzen gemeinsame Tage im Büro bewusst für Austausch, Teamarbeit und persönliche Abstimmung.</li>\n<li>Du erhältst <strong>flexible Arbeitszeiten</strong>, mobiles Arbeiten, eine Ausstattung für dein <strong>Homeoffice</strong>, regelmäßige Teamevents, gemeinsame Workshops, kostenfreie Getränke im Büro und Möglichkeiten zur fachlichen Weiterentwicklung.</li>\n<li>Nach der Einarbeitungszeit ist eine überwiegend remote mögliche Tätigkeit realistisch. Gleichzeitig wirst du bei uns nicht allein gelassen: Wir arbeiten dich strukturiert ein, geben dir Einblick in unsere Systeme und unterstützen dich dabei, Schritt für Schritt Verantwortung zu übernehmen.</li>\n</ul>\n<p>Diese Rolle passt besonders gut zu Menschen, die technische Breite mögen und nicht nur ein sehr enges Aufgabengebiet bearbeiten möchten. Bei uns gibt es gewachsene Systeme, konkrete Kundenanforderungen und viele Themen, die pragmatisch weiterentwickelt werden müssen. Das erfordert technisches Verständnis, Eigeninitiative und die Bereitschaft, Verantwortung für Lösungen zu übernehmen.</p>\n<p>Hilfreich ist außerdem, wenn du gerne zwischen unterschiedlichen Themen wechselst, dich nicht von unklaren Anforderungen abschrecken lässt und bestehende Strukturen lieber verbesserst, statt dich über sie zu ärgern. Wir suchen jemanden, der sauber arbeitet, aber nicht nur theoretische Ideallösungen verfolgt. Am Ende sollen Lösungen funktionieren, verständlich bleiben und für unser Team oder unsere Kunden echten Nutzen schaffen.</p>\n<p>Branchenwissen im Caravaning-Handel brauchst du nicht mitzubringen. Wichtig ist aber, dass du verstehen möchtest, wie unsere Kunden arbeiten und welche technischen Lösungen ihnen im Alltag wirklich helfen.</p>\n<p><strong>Klingt interessant?</strong></p>\n<p>Dann freuen wir uns darauf, dich kennenzulernen.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-15 13:42:07.187', '2026-06-15 13:42:07.187', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/caraconsult-gmbh/it-engineer-fur-digitale-losungen-und-technische-systeme-bad-homburg-72835', 'https://www.arbeitnow.com/jobs/companies/caraconsult-gmbh/it-engineer-fur-digitale-losungen-und-technische-systeme-bad-homburg-72835', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/caraconsult-gmbh/it-engineer-fur-digitale-losungen-und-technische-systeme-bad-homburg-72835\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(904, NULL, 'api', NULL, 'Werkstudent:in Founder\'s Associate (m/w/d) - Internal Projects & Strategy', 'VT Netzwelt GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/vt-netzwelt-gmbh/werkstudentin-founders-associate-internal-projects-strategy-berlin-303565', '<p><strong>Standort: Berlin (Hybrid möglich) | Start: ab sofort | Vergütung: überdurchschnittliche 22–25 €/Stunde (je nach Profil)</strong></p>\n<p><strong>Du willst wissen, wie ein digitales Unternehmen wirklich von innen funktioniert?</strong></p>\n<p>Wir sind VT Netzwelt – eine Techagentur mit Fokus auf digitale Produktentwicklung, Startup-Building und skalierbare Plattformen. Unsere 150 weltweit agierenden Mitarbeiter:innen arbeiten an ambitionierten Kundenprojekten genauso wie an eigenen digitalen Ventures. Was uns ausmacht: Technische Exzellenz, strategisches Denken und echte Umsetzungspower.Als Werkstudent:in im Bereich interne Projekte &#x26; Operations wirst du Teil unseres Innovationsteams – und arbeitest direkt mit unserem CEO an unternehmensinternen Projekten mit echter Wirkung.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li><strong>Interne Projekte umsetzen:</strong> Du begleitest interne strategische Initiativen von der ersten Idee bis zur Umsetzung. Du arbeitest dabei eng mit der Geschäftsführung sowie internen Teams zusammen und stellst sicher, dass wir unsere internen Ziele effizient erreichen – z. B. durch Prozessverbesserung, Tool-Einführung oder Strukturaufbau.</li>\n<li><strong>Eigene Teilprojekte verantworten:</strong> Du übernimmst kleinere (Teil-)Projekte eigenständig – etwa zur Optimierung von Prozessen, Automatisierungen oder internen Reportings. Du kannst interne Themen maßgeblich mitgestalten und Verantwortung übernehmen.</li>\n<li><strong>AI-gestützte Prozessoptimierung:</strong> Ein Schwerpunkt liegt darin, künstliche Intelligenz gezielt einzusetzen, um interne Abläufe und Prozesse effizienter zu gestalten. Du identifizierst Potenziale, testest AI-Tools und unterstützt deren Implementierung in unserem Unternehmen.</li>\n<li><strong>Proaktive Verbesserungen &#x26; AI/Tool-Scouting:</strong> Du unterstützt bei der Ideation, identifizierst Optimierungspotenziale und bringst eigenständig Vorschläge ein, die einen echten Unterschied machen. Du verfolgst auch neueste KI-Tools und Technologien, testest sie und hilfst bei deren Einführung – mit Fokus auf unseren internen Einsatz.</li>\n<li><strong>Schnelles Prototyping &#x26; R&#x26;D:</strong> Gemeinsam entwickeln wir interne Prototypen, evaluieren Tools und Konzepte und validieren neue Ideen – immer mit Blick auf die Weiterentwicklung unseres Unternehmens.</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Laufendes Studium in Wirtschaftsinformatik, Wirtschaftswissenschaften oder einem vergleichbaren Bereich – du hast ein Growth Mindset und bringst „Entrepreneurial Spirit“ mit.</li>\n<li>Ausgeprägte Problemlösungskompetenz: Du bist ein:e Troubleshooter:in, denkst analytisch und findest auch in komplexen Situationen pragmatische Lösungen.</li>\n<li>Hunger auf Neues &#x26; Kreativität: Du hast Spaß daran, originelle Ideen zu entwickeln und diese eigenverantwortlich in konkrete Ergebnisse umzusetzen.</li>\n<li>Technisches Interesse und Grundkenntnisse (z. B. Coding) sind ein Plus, aber kein Muss – wichtiger sind Lernbereitschaft und ein grundlegendes Verständnis für digitale Tools und Prozesse.</li>\n<li>Sehr gute Deutsch- und Englischkenntnisse – du kommunizierst souverän in beiden Sprachen.</li>\n<li>Eigeninitiative &#x26; Verantwortungsgefühl: Du gehst souverän mit Unsicherheiten um und behältst deine Projekte selbstständig im Blick.</li>\n<li>Vorausschauendes Denken: Du hinterfragst Prozesse, suchst aktiv nach Verbesserungsmöglichkeiten und bringst neue Ideen ins Team.</li>\n<li>Du denkst nicht in Kundenprojekten, sondern in Unternehmensstrukturen – und willst verstehen, wie Organisationen von innen heraus funktionieren und wachsen.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Einblicke in interne Strategie &#x26; Organisationsentwicklung: Du arbeitest direkt mit dem CEO und bekommst Zugang zu Themen, die sonst oft hinter verschlossenen Türen stattfinden.</li>\n<li>Eigene Projekte mit Verantwortung: Du kannst echte Verantwortung übernehmen und interne Projekte sichtbar vorantreiben.</li>\n<li>Aktive Förderung &#x26; Lernkurve: Mentoring, ehrliches Feedback und persönliche Entwicklung sind fester Bestandteil unserer Unternehmenskultur.</li>\n<li>Flache Hierarchien &#x26; Vertrauen: Bei uns wird Eigenverantwortung gelebt – mit offener Kommunikation auf Augenhöhe und einem Team, das gemeinsam für Qualität brennt.</li>\n<li>Flexibles Setup: Hybrides Arbeiten, flexible Arbeitszeiten und ein moderner Arbeitsplatz in Berlin sorgen für eine gesunde Balance.Attraktive Vergütung: Für starke Leistungen bieten wir eine überdurchschnittliche Bezahlung.</li>\n</ul>\n<p>Klingt nach dir?<br>\nDann freuen wir uns auf deine Bewerbung!</p>\n<p><strong>Wir freuen uns darauf, gemeinsam mit dir unser Unternehmen von innen heraus weiterzuentwickeln – und dich kennenzulernen!</strong></p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Standort: Berlin (Hybrid möglich) | Start: ab sofort | Vergütung: überdurchschnittliche 22–25 €/Stunde (je nach Profil)</strong></p>\n<p><strong>Du willst wissen, wie ein digitales Unternehmen wirklich von innen funktioniert?</strong></p>\n<p>Wir sind VT Netzwelt – eine Techagentur mit Fokus auf digitale Produktentwicklung, Startup-Building und skalierbare Plattformen. Unsere 150 weltweit agierenden Mitarbeiter:innen arbeiten an ambitionierten Kundenprojekten genauso wie an eigenen digitalen Ventures. Was uns ausmacht: Technische Exzellenz, strategisches Denken und echte Umsetzungspower.Als Werkstudent:in im Bereich interne Projekte &#x26; Operations wirst du Teil unseres Innovationsteams – und arbeitest direkt mit unserem CEO an unternehmensinternen Projekten mit echter Wirkung.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li><strong>Interne Projekte umsetzen:</strong> Du begleitest interne strategische Initiativen von der ersten Idee bis zur Umsetzung. Du arbeitest dabei eng mit der Geschäftsführung sowie internen Teams zusammen und stellst sicher, dass wir unsere internen Ziele effizient erreichen – z. B. durch Prozessverbesserung, Tool-Einführung oder Strukturaufbau.</li>\n<li><strong>Eigene Teilprojekte verantworten:</strong> Du übernimmst kleinere (Teil-)Projekte eigenständig – etwa zur Optimierung von Prozessen, Automatisierungen oder internen Reportings. Du kannst interne Themen maßgeblich mitgestalten und Verantwortung übernehmen.</li>\n<li><strong>AI-gestützte Prozessoptimierung:</strong> Ein Schwerpunkt liegt darin, künstliche Intelligenz gezielt einzusetzen, um interne Abläufe und Prozesse effizienter zu gestalten. Du identifizierst Potenziale, testest AI-Tools und unterstützt deren Implementierung in unserem Unternehmen.</li>\n<li><strong>Proaktive Verbesserungen &#x26; AI/Tool-Scouting:</strong> Du unterstützt bei der Ideation, identifizierst Optimierungspotenziale und bringst eigenständig Vorschläge ein, die einen echten Unterschied machen. Du verfolgst auch neueste KI-Tools und Technologien, testest sie und hilfst bei deren Einführung – mit Fokus auf unseren internen Einsatz.</li>\n<li><strong>Schnelles Prototyping &#x26; R&#x26;D:</strong> Gemeinsam entwickeln wir interne Prototypen, evaluieren Tools und Konzepte und validieren neue Ideen – immer mit Blick auf die Weiterentwicklung unseres Unternehmens.</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Laufendes Studium in Wirtschaftsinformatik, Wirtschaftswissenschaften oder einem vergleichbaren Bereich – du hast ein Growth Mindset und bringst „Entrepreneurial Spirit“ mit.</li>\n<li>Ausgeprägte Problemlösungskompetenz: Du bist ein:e Troubleshooter:in, denkst analytisch und findest auch in komplexen Situationen pragmatische Lösungen.</li>\n<li>Hunger auf Neues &#x26; Kreativität: Du hast Spaß daran, originelle Ideen zu entwickeln und diese eigenverantwortlich in konkrete Ergebnisse umzusetzen.</li>\n<li>Technisches Interesse und Grundkenntnisse (z. B. Coding) sind ein Plus, aber kein Muss – wichtiger sind Lernbereitschaft und ein grundlegendes Verständnis für digitale Tools und Prozesse.</li>\n<li>Sehr gute Deutsch- und Englischkenntnisse – du kommunizierst souverän in beiden Sprachen.</li>\n<li>Eigeninitiative &#x26; Verantwortungsgefühl: Du gehst souverän mit Unsicherheiten um und behältst deine Projekte selbstständig im Blick.</li>\n<li>Vorausschauendes Denken: Du hinterfragst Prozesse, suchst aktiv nach Verbesserungsmöglichkeiten und bringst neue Ideen ins Team.</li>\n<li>Du denkst nicht in Kundenprojekten, sondern in Unternehmensstrukturen – und willst verstehen, wie Organisationen von innen heraus funktionieren und wachsen.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Einblicke in interne Strategie &#x26; Organisationsentwicklung: Du arbeitest direkt mit dem CEO und bekommst Zugang zu Themen, die sonst oft hinter verschlossenen Türen stattfinden.</li>\n<li>Eigene Projekte mit Verantwortung: Du kannst echte Verantwortung übernehmen und interne Projekte sichtbar vorantreiben.</li>\n<li>Aktive Förderung &#x26; Lernkurve: Mentoring, ehrliches Feedback und persönliche Entwicklung sind fester Bestandteil unserer Unternehmenskultur.</li>\n<li>Flache Hierarchien &#x26; Vertrauen: Bei uns wird Eigenverantwortung gelebt – mit offener Kommunikation auf Augenhöhe und einem Team, das gemeinsam für Qualität brennt.</li>\n<li>Flexibles Setup: Hybrides Arbeiten, flexible Arbeitszeiten und ein moderner Arbeitsplatz in Berlin sorgen für eine gesunde Balance.Attraktive Vergütung: Für starke Leistungen bieten wir eine überdurchschnittliche Bezahlung.</li>\n</ul>\n<p>Klingt nach dir?<br>\nDann freuen wir uns auf deine Bewerbung!</p>\n<p><strong>Wir freuen uns darauf, gemeinsam mit dir unser Unternehmen von innen heraus weiterzuentwickeln – und dich kennenzulernen!</strong></p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-15 13:42:16.718', '2026-06-15 13:42:16.718', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/vt-netzwelt-gmbh/werkstudentin-founders-associate-internal-projects-strategy-berlin-303565', 'https://www.arbeitnow.com/jobs/companies/vt-netzwelt-gmbh/werkstudentin-founders-associate-internal-projects-strategy-berlin-303565', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/vt-netzwelt-gmbh/werkstudentin-founders-associate-internal-projects-strategy-berlin-303565\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(905, NULL, 'api', NULL, 'Werkstudent Produktmanagement (w/m/d) Techagentur', 'VT Netzwelt GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/vt-netzwelt-gmbh/werkstudent-produktmanagement-techagentur-berlin-171540', '<p><strong>Standort: Berlin (Hybrid möglich) | Start: ab sofort</strong><br>\n<strong>Vergütung: überdurchschnittliche 22 - 25€/Stunde</strong></p>\n<p><strong>Du willst wissen, wie digitale Produkte</strong> <strong><em>wirklich</em></strong> <strong>gebaut werden?</strong></p>\n<p>Wir sind <strong>VT Netzwelt</strong> – eine Techagentur mit Fokus auf digitale Produktentwicklung, Startup-Building und skalierbare Plattformen. Wir arbeiten an ambitionierten Kundenprojekten genauso wie an eigenen digitalen Ventures. Was uns ausmacht: Technische Exzellenz, strategisches Denken und echte Umsetzungspower.</p>\n<p>Als Werkstudent:in im Produktmanagement wirst du Teil unseres internen Innovationsteams – und arbeitest mit uns an mehreren parallelen Projekten mit echter Wirkung.</p>\n<h2>Aufgaben</h2>\n<p><strong>Was du bei uns machst</strong></p>\n<ul>\n<li><strong>Innovationsprojekte umsetzen</strong></li>\n</ul>\n<p>Du begleitest digitale Lösungen von der ersten Idee bis zur Marktreife, arbeitest eng mit Kund:innen sowie Design-, Entwicklungs- und Management-Teams zusammen und stellst sicher, dass wir unsere Ziele effizient erreichen. Dabei bist du auch in der <strong>internationalen Zusammenarbeit</strong> mit unserem Team aktiv ingebunden.</p>\n<ul>\n<li><strong>Eigene Ventures &#x26; Teilprojekte verantworten</strong></li>\n</ul>\n<p>Du übernimmst nicht nur kleinere (Teil-)Projekte eigenständig, sondern arbeitest auch an eigenen Ventures mit großer Außenwirkung, die du maßgeblich beeinflussen kannst. In einer <strong>dynamischen Umgebung</strong> mit hohem Tempo hast du jederzeit die Möglichkeit, Ownership zu übernehmen.</p>\n<ul>\n<li><strong>Proaktive Verbesserungen &#x26; AI/Tech-Scouting</strong></li>\n</ul>\n<p>Du unterstützt bei der Ideation, identifizierst Optimierungspotenziale und bringst eigenständig Vorschläge ein, die einen echten Unterschied machen. <strong>Du verfolgst auch neueste KI-Tools und Technologien</strong>, testest sie und hilfst bei der Einführung in unsere Projekte und Prozesse.</p>\n<ul>\n<li><strong>Schnelles Prototyping &#x26; R&#x26;D</strong></li>\n</ul>\n<p>Gemeinsam setzen wir auf kurze Entwicklungszyklen, validieren Ideen früh und reagieren schnell auf Feedback. Du bist mittendrin, wenn wir Prototypen bauen und Konzepte auf ihre Machbarkeit prüfen.</p>\n<h2>Qualifikation</h2>\n<p><strong>Was du mitbringst</strong></p>\n<ul>\n<li><strong>Laufendes Studium</strong> in Wirtschaftswissenschaften, Informatik oder einem vergleichbaren Bereich – du hast ein Growth Mindset und bringst „Entrepreneurial<br>\nSpirit“ mit.</li>\n<li><strong>Ausgeprägte Problemlösungskompetenz</strong>: Du bist ein erstklassiger Troubleshooter, denkst analytisch und findest auch in komplexen Situationen Lösungen, statt nur Probleme zu sehen.</li>\n<li><strong>Hunger auf Neues &#x26; Kreativität</strong>: Du hast Spaß daran, originelle Ideen zu entwickeln und diese eigenverantwortlich in konkrete Ergebnisse umzusetzen – und gibst erst<br>\nRuhe, wenn das Ergebnis wirklich überzeugt.</li>\n<li><strong>Technisches Interesse und Grundkenntnisse</strong> (z. B. Coding) sind ein Plus, aber kein Muss – wichtiger sind Lernbereitschaft und ein grundlegendes Verständnis für agile Methoden.</li>\n<li><strong>Sehr gute Deutsch- und Englischkenntnisse</strong> – du kommunizierst souverän in beiden Sprachen.</li>\n<li><strong>Eigeninitiative &#x26; Verantwortungsgefühl</strong>: Du gehst souverän mit Unsicherheiten um und behältst deine Projekte selbstständig im Blick.</li>\n<li><strong>Vorausschauendes Denken</strong>: Du hinterfragst Prozesse, suchst aktiv nach Verbesserungsmöglichkeiten und bringst neue Ideen ins Team.</li>\n<li><strong>Kunden- und Unternehmensperspektive</strong>: Du verstehst die Bedürfnisse unserer Kund:innen ebenso wie unsere internen Ziele und schlägst wirkungsvolle Lösungen vor.</li>\n<li><strong>Hohes Tempo</strong>: Du fühlst dich wohl, wenn Projekte sich schnell drehen, und kannst mehrere Aufgaben gleichzeitig jonglieren.</li>\n<li><strong>Erste Erfahrungen</strong> im Bereich Produktmanagement, Startup-Umfeld oder Entwicklung sind ein Plus, aber ebenfalls kein Muss.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Was dich erwartet</strong></p>\n<ul>\n<li><strong>Vielfältige Kunden &#x26; Projekte:</strong> Vom Mittelstand bis zu internationalen Scale-ups und DAX-Konzernen – du arbeitest an echten Herausforderungen mit hohem Impact.</li>\n<li><strong>Eigene digitale Ventures:</strong> Wir geben dir die Chance, Produkte und Startups von Grund auf mitzugestalten und sichtbar zu machen.</li>\n<li><strong>Aktive Förderung &#x26; Strategische Lernkurve:</strong> Mentoring, ehrliches Feedback und persönliche Entwicklung sind fester Bestandteil unserer Unternehmenskultur. Neben dem operativen Tagesgeschäft bekommst du Einblicke in strategische Entscheidungen und lernst, wie man eine Techagentur und eigene Ventures aufbaut.</li>\n<li><strong>Flache Hierarchien &#x26; Vertrauen:</strong> Bei uns wird Eigenverantwortung gelebt – mit offener Kommunikation auf Augenhöhe und einem Team, das gemeinsam für Qualität brennt.</li>\n<li><strong>Flexibles Setup:</strong> Hybrides Arbeiten, flexible Arbeitszeiten und ein moderner Arbeitsplatz in Berlin sorgen für eine gesunde Balance.</li>\n<li><strong>Attraktive Vergütung:</strong> Für starke Leistungen bieten wir eine überdurchschnittliche Bezahlung..</li>\n</ul>\n<p>Wenn du es liebst, technische Herausforderungen in umsetzbare Lösungen zu verwandeln und unsere Kund:innen auf ihrer digitalen Reise aktiv voranzubringen, freuen wir uns auf deine Bewerbung.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Standort: Berlin (Hybrid möglich) | Start: ab sofort</strong><br>\n<strong>Vergütung: überdurchschnittliche 22 - 25€/Stunde</strong></p>\n<p><strong>Du willst wissen, wie digitale Produkte</strong> <strong><em>wirklich</em></strong> <strong>gebaut werden?</strong></p>\n<p>Wir sind <strong>VT Netzwelt</strong> – eine Techagentur mit Fokus auf digitale Produktentwicklung, Startup-Building und skalierbare Plattformen. Wir arbeiten an ambitionierten Kundenprojekten genauso wie an eigenen digitalen Ventures. Was uns ausmacht: Technische Exzellenz, strategisches Denken und echte Umsetzungspower.</p>\n<p>Als Werkstudent:in im Produktmanagement wirst du Teil unseres internen Innovationsteams – und arbeitest mit uns an mehreren parallelen Projekten mit echter Wirkung.</p>\n<h2>Aufgaben</h2>\n<p><strong>Was du bei uns machst</strong></p>\n<ul>\n<li><strong>Innovationsprojekte umsetzen</strong></li>\n</ul>\n<p>Du begleitest digitale Lösungen von der ersten Idee bis zur Marktreife, arbeitest eng mit Kund:innen sowie Design-, Entwicklungs- und Management-Teams zusammen und stellst sicher, dass wir unsere Ziele effizient erreichen. Dabei bist du auch in der <strong>internationalen Zusammenarbeit</strong> mit unserem Team aktiv ingebunden.</p>\n<ul>\n<li><strong>Eigene Ventures &#x26; Teilprojekte verantworten</strong></li>\n</ul>\n<p>Du übernimmst nicht nur kleinere (Teil-)Projekte eigenständig, sondern arbeitest auch an eigenen Ventures mit großer Außenwirkung, die du maßgeblich beeinflussen kannst. In einer <strong>dynamischen Umgebung</strong> mit hohem Tempo hast du jederzeit die Möglichkeit, Ownership zu übernehmen.</p>\n<ul>\n<li><strong>Proaktive Verbesserungen &#x26; AI/Tech-Scouting</strong></li>\n</ul>\n<p>Du unterstützt bei der Ideation, identifizierst Optimierungspotenziale und bringst eigenständig Vorschläge ein, die einen echten Unterschied machen. <strong>Du verfolgst auch neueste KI-Tools und Technologien</strong>, testest sie und hilfst bei der Einführung in unsere Projekte und Prozesse.</p>\n<ul>\n<li><strong>Schnelles Prototyping &#x26; R&#x26;D</strong></li>\n</ul>\n<p>Gemeinsam setzen wir auf kurze Entwicklungszyklen, validieren Ideen früh und reagieren schnell auf Feedback. Du bist mittendrin, wenn wir Prototypen bauen und Konzepte auf ihre Machbarkeit prüfen.</p>\n<h2>Qualifikation</h2>\n<p><strong>Was du mitbringst</strong></p>\n<ul>\n<li><strong>Laufendes Studium</strong> in Wirtschaftswissenschaften, Informatik oder einem vergleichbaren Bereich – du hast ein Growth Mindset und bringst „Entrepreneurial<br>\nSpirit“ mit.</li>\n<li><strong>Ausgeprägte Problemlösungskompetenz</strong>: Du bist ein erstklassiger Troubleshooter, denkst analytisch und findest auch in komplexen Situationen Lösungen, statt nur Probleme zu sehen.</li>\n<li><strong>Hunger auf Neues &#x26; Kreativität</strong>: Du hast Spaß daran, originelle Ideen zu entwickeln und diese eigenverantwortlich in konkrete Ergebnisse umzusetzen – und gibst erst<br>\nRuhe, wenn das Ergebnis wirklich überzeugt.</li>\n<li><strong>Technisches Interesse und Grundkenntnisse</strong> (z. B. Coding) sind ein Plus, aber kein Muss – wichtiger sind Lernbereitschaft und ein grundlegendes Verständnis für agile Methoden.</li>\n<li><strong>Sehr gute Deutsch- und Englischkenntnisse</strong> – du kommunizierst souverän in beiden Sprachen.</li>\n<li><strong>Eigeninitiative &#x26; Verantwortungsgefühl</strong>: Du gehst souverän mit Unsicherheiten um und behältst deine Projekte selbstständig im Blick.</li>\n<li><strong>Vorausschauendes Denken</strong>: Du hinterfragst Prozesse, suchst aktiv nach Verbesserungsmöglichkeiten und bringst neue Ideen ins Team.</li>\n<li><strong>Kunden- und Unternehmensperspektive</strong>: Du verstehst die Bedürfnisse unserer Kund:innen ebenso wie unsere internen Ziele und schlägst wirkungsvolle Lösungen vor.</li>\n<li><strong>Hohes Tempo</strong>: Du fühlst dich wohl, wenn Projekte sich schnell drehen, und kannst mehrere Aufgaben gleichzeitig jonglieren.</li>\n<li><strong>Erste E