(954, NULL, 'api', NULL, 'PDM Application Developer (m/w/x)', 'K-tronik GmbH', 'Munich', 'https://www.arbeitnow.com/jobs/companies/k-tronik-gmbh/pdm-application-developer-munich-468475', '<h2>Projektbeschreibung:</h2>\n<p>Technologie begeistert Sie? Uns auch! Zur Verstärkung unseres Expertenteams bei unserem Kunden aus der Defense &#x26; Security Branche suchen wir einen PDM Application Developer (m/w/x) in Festanstellung bei K-tronik. Wir freuen uns darauf, Sie persönlich kennen zu lernen - und gemeinsam mit Leidenschaft und Teamgeist an spannenden Projekten und zukunftsweisenden Technologien zu arbeiten.</p>\n<h2>Aufgaben:</h2>\n<ul>\n<li>Entwicklung eigener und Ergänzung bestehender Applikationen im Team- Konfiguration und Anpassung von Funktionen an bestehenden PLM / PDM Systemen - Betrieb und Wartung der PLM / PDM System Komponenten - Analyse der Anforderungen, Entwurf und Spezifikation, Implementierung und Test - Planung von Arbeitspaketen (Budget und Zeit) - Integration der Applikation in die R&#x26;S PDM und IT Landschaft - Erstellen der erforderlichen Dokumentation und Schulungsaufgaben - Anwenderberatung und Fehlerbehebung im Raumen des 2nd Level-Support, Schulung und Anwendertraining</li>\n</ul>\n<h2>Qualifikationen:</h2>\n<ul>\n<li>Gute Kenntnisse in Objektorientierten Programmiersprachen - Generelle Kenntnisse in der Softwareentwicklung - Ausgeprägte Kunden-/Serviceorientierung - Durchsetzungsvermögen - Eigenverantwortlicher Arbeitsstil - Engagierte, teamorientierte Arbeitsweise - Interkulturelle Kompetenz - Kommunikationsstärke - Sprachen: Deutsch &#x26; Englisch</li>\n</ul>\n<h2>Benefits:</h2>\n<ul>\n<li>Kollegiales und freundschaftliches Arbeitsklima</li>\n<li>Flexible Arbeitszeiten</li>\n<li>30 Urlaubstage und flexible Urlaubsplanung</li>\n<li>Regelmäßige Team-Events</li>\n<li>Auszeichnung als Kununu TOP Company</li>\n<li>Corporate Benefits (Mitarbeiterangebote)</li>\n<li>Kostenlose Getränke</li>\n<li>Individuelle Weiterbildungsmöglichkeiten</li>\n<li>360° Betreuung: Feedbackgespräche, Karriereplanung, Unterstützung bei Umzug, etc.</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>Projektbeschreibung:</h2>\n<p>Technologie begeistert Sie? Uns auch! Zur Verstärkung unseres Expertenteams bei unserem Kunden aus der Defense &#x26; Security Branche suchen wir einen PDM Application Developer (m/w/x) in Festanstellung bei K-tronik. Wir freuen uns darauf, Sie persönlich kennen zu lernen - und gemeinsam mit Leidenschaft und Teamgeist an spannenden Projekten und zukunftsweisenden Technologien zu arbeiten.</p>\n<h2>Aufgaben:</h2>\n<ul>\n<li>Entwicklung eigener und Ergänzung bestehender Applikationen im Team- Konfiguration und Anpassung von Funktionen an bestehenden PLM / PDM Systemen - Betrieb und Wartung der PLM / PDM System Komponenten - Analyse der Anforderungen, Entwurf und Spezifikation, Implementierung und Test - Planung von Arbeitspaketen (Budget und Zeit) - Integration der Applikation in die R&#x26;S PDM und IT Landschaft - Erstellen der erforderlichen Dokumentation und Schulungsaufgaben - Anwenderberatung und Fehlerbehebung im Raumen des 2nd Level-Support, Schulung und Anwendertraining</li>\n</ul>\n<h2>Qualifikationen:</h2>\n<ul>\n<li>Gute Kenntnisse in Objektorientierten Programmiersprachen - Generelle Kenntnisse in der Softwareentwicklung - Ausgeprägte Kunden-/Serviceorientierung - Durchsetzungsvermögen - Eigenverantwortlicher Arbeitsstil - Engagierte, teamorientierte Arbeitsweise - Interkulturelle Kompetenz - Kommunikationsstärke - Sprachen: Deutsch &#x26; Englisch</li>\n</ul>\n<h2>Benefits:</h2>\n<ul>\n<li>Kollegiales und freundschaftliches Arbeitsklima</li>\n<li>Flexible Arbeitszeiten</li>\n<li>30 Urlaubstage und flexible Urlaubsplanung</li>\n<li>Regelmäßige Team-Events</li>\n<li>Auszeichnung als Kununu TOP Company</li>\n<li>Corporate Benefits (Mitarbeiterangebote)</li>\n<li>Kostenlose Getränke</li>\n<li>Individuelle Weiterbildungsmöglichkeiten</li>\n<li>360° Betreuung: Feedbackgespräche, Karriereplanung, Unterstützung bei Umzug, etc.</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-16 13:42:05.230', '2026-06-16 13:42:05.230', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/k-tronik-gmbh/pdm-application-developer-munich-468475', 'https://www.arbeitnow.com/jobs/companies/k-tronik-gmbh/pdm-application-developer-munich-468475', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/k-tronik-gmbh/pdm-application-developer-munich-468475\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(955, NULL, 'api', NULL, 'Hardware Entwickler Digital (m/w/x)', 'K-tronik GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/k-tronik-gmbh/hardware-entwickler-digital-berlin-217700', '<h2>Projektbeschreibung:</h2>\n<p>Technologie begeistert Sie? Uns auch! Zur Verstärkung unseres Expertenteams bei unserem Kunden aus der Funk- und Kommunikationsbranche suchen wir einen Hardware Entwickler Digital (m/w/x) in Festanstellung bei K-tronik. Wir freuen uns darauf, Sie persönlich kennen zu lernen - und gemeinsam mit Leidenschaft und Teamgeist an spannenden Projekten und zukunftsweisenden Technologien zu arbeiten.</p>\n<h2>Aufgaben:</h2>\n<ul>\n<li>Du bist maßgeblich an Entwicklung und Integration innovativer Baugruppen für unsere hochleistungsfähigen, gerichteten Funkkommunikationssystemen beteiligt - Du konzipierst und entwickelst die digitalen Anteile unserer Funkgeräte, einschließlich der Auswahl und Integration von digitalen Komponenten und der Schnittstellen zur analogen HW- Du übernimmst die Schaltplanerstellung und Simulation und betreust das Layout der Schaltungen unter Einsatz moderner CAE-Tools - Du verifizierst und validierst die Schaltungsperformance durch Messungen und Tests - von der Charakterisierung einzelner Komponenten bis hin zur Systemintegration - Du arbeitest interdisziplinär mit Experten aus System Engineering, SW-Entwicklung sowie elektrischer und mechanischer Konstruktion sowie mit Kunden zusammen, um eine erfolgreiche Systemintegration sicherzustellen</li>\n</ul>\n<h2>Qualifikationen:</h2>\n<ul>\n<li>Abgeschlossenes Studium im Bereich der Elektrotechnik mit Schwerpunkt Kommunikations- / Nachrichtentechnik oder vergleichbare Aubsildung - Mehrjährige Berufserfahrung in der Entwicklung von digitaler Hardware- Praktische Erfahrungen in der Umsetzung komplexer HW-Designs mit FPGAs, SoCs, DDR Memory, High-Speed-Digital Schnittstellen und Power Supply in produzierbare Baugruppen - Erfahrung in Inbetriebnahme, Test und Verifikation von HW-Baugruppen unter Nutzung von Messtechnik wie Oszilloskop, Netzwerkanalysator und Signalgenerator - Erfahrungen in der FPGA-Entwicklung und gute Kenntnisse in VHDL von Vorteil - Erfahrung im Umgang mit Empfängern, HF-Frontends und Kommunikationssystemen von Vorteil - Sehr sorgfältige, strukturierte und verantwortungsbewusste Arbeitsweise - Hohe Teamfähigkeit, schnelle Auffassungsgabe sowie ausgeprägte Kommunikationsstärke - Sehr gute Deutschkenntnisse sowie gute Englischkenntnisse in Wort und Schrift</li>\n</ul>\n<h2>Benefits:</h2>\n<ul>\n<li>Kollegiales und freundschaftliches Arbeitsklima</li>\n<li>Flexible Arbeitszeiten</li>\n<li>30 Urlaubstage und flexible Urlaubsplanung</li>\n<li>Regelmäßige Team-Events</li>\n<li>Auszeichnung als Kununu TOP Company</li>\n<li>Corporate Benefits (Mitarbeiterangebote)</li>\n<li>Kostenlose Getränke</li>\n<li>Individuelle Weiterbildungsmöglichkeiten</li>\n<li>360° Betreuung: Feedbackgespräche, Karriereplanung, Unterstützung bei Umzug, etc.</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<h2>Projektbeschreibung:</h2>\n<p>Technologie begeistert Sie? Uns auch! Zur Verstärkung unseres Expertenteams bei unserem Kunden aus der Funk- und Kommunikationsbranche suchen wir einen Hardware Entwickler Digital (m/w/x) in Festanstellung bei K-tronik. Wir freuen uns darauf, Sie persönlich kennen zu lernen - und gemeinsam mit Leidenschaft und Teamgeist an spannenden Projekten und zukunftsweisenden Technologien zu arbeiten.</p>\n<h2>Aufgaben:</h2>\n<ul>\n<li>Du bist maßgeblich an Entwicklung und Integration innovativer Baugruppen für unsere hochleistungsfähigen, gerichteten Funkkommunikationssystemen beteiligt - Du konzipierst und entwickelst die digitalen Anteile unserer Funkgeräte, einschließlich der Auswahl und Integration von digitalen Komponenten und der Schnittstellen zur analogen HW- Du übernimmst die Schaltplanerstellung und Simulation und betreust das Layout der Schaltungen unter Einsatz moderner CAE-Tools - Du verifizierst und validierst die Schaltungsperformance durch Messungen und Tests - von der Charakterisierung einzelner Komponenten bis hin zur Systemintegration - Du arbeitest interdisziplinär mit Experten aus System Engineering, SW-Entwicklung sowie elektrischer und mechanischer Konstruktion sowie mit Kunden zusammen, um eine erfolgreiche Systemintegration sicherzustellen</li>\n</ul>\n<h2>Qualifikationen:</h2>\n<ul>\n<li>Abgeschlossenes Studium im Bereich der Elektrotechnik mit Schwerpunkt Kommunikations- / Nachrichtentechnik oder vergleichbare Aubsildung - Mehrjährige Berufserfahrung in der Entwicklung von digitaler Hardware- Praktische Erfahrungen in der Umsetzung komplexer HW-Designs mit FPGAs, SoCs, DDR Memory, High-Speed-Digital Schnittstellen und Power Supply in produzierbare Baugruppen - Erfahrung in Inbetriebnahme, Test und Verifikation von HW-Baugruppen unter Nutzung von Messtechnik wie Oszilloskop, Netzwerkanalysator und Signalgenerator - Erfahrungen in der FPGA-Entwicklung und gute Kenntnisse in VHDL von Vorteil - Erfahrung im Umgang mit Empfängern, HF-Frontends und Kommunikationssystemen von Vorteil - Sehr sorgfältige, strukturierte und verantwortungsbewusste Arbeitsweise - Hohe Teamfähigkeit, schnelle Auffassungsgabe sowie ausgeprägte Kommunikationsstärke - Sehr gute Deutschkenntnisse sowie gute Englischkenntnisse in Wort und Schrift</li>\n</ul>\n<h2>Benefits:</h2>\n<ul>\n<li>Kollegiales und freundschaftliches Arbeitsklima</li>\n<li>Flexible Arbeitszeiten</li>\n<li>30 Urlaubstage und flexible Urlaubsplanung</li>\n<li>Regelmäßige Team-Events</li>\n<li>Auszeichnung als Kununu TOP Company</li>\n<li>Corporate Benefits (Mitarbeiterangebote)</li>\n<li>Kostenlose Getränke</li>\n<li>Individuelle Weiterbildungsmöglichkeiten</li>\n<li>360° Betreuung: Feedbackgespräche, Karriereplanung, Unterstützung bei Umzug, etc.</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-16 13:42:12.790', '2026-06-16 13:42:12.790', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/k-tronik-gmbh/hardware-entwickler-digital-berlin-217700', 'https://www.arbeitnow.com/jobs/companies/k-tronik-gmbh/hardware-entwickler-digital-berlin-217700', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/k-tronik-gmbh/hardware-entwickler-digital-berlin-217700\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(956, NULL, 'api', NULL, 'Business Controller (m/w/d)', 'SafeDriver Group GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/safedriver-group-gmbh/business-controller-berlin-83263', '<p>Ennoo Rental, Teil der SafeDriver Group, skaliert ihre Flotten- und Vermietmodelle in der Mietwagenbranche. Zur Verstärkung des Finance-Teams suchen wir einen <strong>Business Controller (m/w/d)</strong> mit starkem analytischem Fokus.</p>\n<p>Du verantwortest ein belastbares Monats- und Quartalsreporting, steuerst zentrale KPIs und behältst Finanzierungslinien sowie Covenants im Blick. An der Schnittstelle zwischen Buchhaltung, Controlling und operativen Prozessen sorgst du für transparente Entscheidungsgrundlagen für Geschäftsführung und Management. Die Rolle ist hands-on: Du optimierst Strukturen, verbesserst Prozesse und arbeitest eng mit der Geschäftsführung und den zentralen Finance-Teams der Gruppe zusammen.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li><strong>Monitoring der Fremdfinanzierung:</strong> Steuerung von Finanzierungsstrukturen, Covenant- und KPI-Tracking, regelmäßiges Reporting an interne Stakeholder</li>\n<li><strong>Reporting &#x26; Steuerung:</strong> Aufbau und Verantwortung für Monats- und Quartalsreportings (Management-Reporting, Plan-Ist-Vergleiche, KPI-Systeme, offene Forderungen)</li>\n<li><strong>Budget- und Forecast-Monitoring:</strong> Analyse von Abweichungen, Ableitung von Maßnahmen, Unterstützung der operativen Steuerung</li>\n<li><strong>Portfolio-Monitoring:</strong> Analyse der wirtschaftlichen Entwicklung des Fahrzeugportfolios und Etablierung zentraler Steuerungskennzahlen</li>\n<li><strong>Prozessoptimierung:</strong> Weiterentwicklung der Schnittstellen zwischen Buchhaltung und Controlling (z. B. Monatsabschluss, Datenqualität, Workflows)</li>\n<li><strong>Stakeholder-Management:</strong> Enge Zusammenarbeit mit der Geschäftsführung von Ennoo Rental, dem Head of Controlling sowie dem CFO der SafeDriver Group</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>1–5 Jahre relevante Berufserfahrung im Finance-Umfeld (z. B. Controlling, Finance Operations, accounting-nahes Controlling, Audit oder transaktionsnahe Beratung)</li>\n<li>Sehr gutes Verständnis für betriebswirtschaftliche Zusammenhänge und Finance-Prozesse (Monatsabschluss, Reporting, Budgetierung, Wirtschaftsplanung)</li>\n<li>Strukturierte, eigenständige und lösungsorientierte Arbeitsweise mit ausgeprägter Hands-on-Mentalität</li>\n<li>Sicherer Umgang mit Excel und/oder Google Sheets; Erfahrung im Aufbau von Reporting- und KPI-Strukturen von Vorteil</li>\n<li>Klare, adressatengerechte Kommunikation gegenüber Management und internen Stakeholdern</li>\n<li>Keine disziplinarische Führungsverantwortung erforderlich – Ownership, Verlässlichkeit und Umsetzungsstärke werden jedoch vorausgesetzt</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Direkte Zusammenarbeit mit der Geschäftsführung und hohe Sichtbarkeit der eigenen Arbeit</li>\n<li>Aktive Mitgestaltung von Finance-Strukturen in einem skalierenden Geschäftsmodell</li>\n<li>Ein etabliertes, gruppenweites Finance-Team (ca. 10 Personen) als Sparringspartner</li>\n<li>Attraktives Vergütungspaket sowie Entwicklungsperspektiven innerhalb der Unternehmensgruppe</li>\n</ul>\n<p>Matthias freut sich auf deine vollständigen Bewerbungsunterlagen unter Angabe deiner Gehaltsvorstellung und deines frühestmöglichen Eintrittstermins.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Ennoo Rental, Teil der SafeDriver Group, skaliert ihre Flotten- und Vermietmodelle in der Mietwagenbranche. Zur Verstärkung des Finance-Teams suchen wir einen <strong>Business Controller (m/w/d)</strong> mit starkem analytischem Fokus.</p>\n<p>Du verantwortest ein belastbares Monats- und Quartalsreporting, steuerst zentrale KPIs und behältst Finanzierungslinien sowie Covenants im Blick. An der Schnittstelle zwischen Buchhaltung, Controlling und operativen Prozessen sorgst du für transparente Entscheidungsgrundlagen für Geschäftsführung und Management. Die Rolle ist hands-on: Du optimierst Strukturen, verbesserst Prozesse und arbeitest eng mit der Geschäftsführung und den zentralen Finance-Teams der Gruppe zusammen.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li><strong>Monitoring der Fremdfinanzierung:</strong> Steuerung von Finanzierungsstrukturen, Covenant- und KPI-Tracking, regelmäßiges Reporting an interne Stakeholder</li>\n<li><strong>Reporting &#x26; Steuerung:</strong> Aufbau und Verantwortung für Monats- und Quartalsreportings (Management-Reporting, Plan-Ist-Vergleiche, KPI-Systeme, offene Forderungen)</li>\n<li><strong>Budget- und Forecast-Monitoring:</strong> Analyse von Abweichungen, Ableitung von Maßnahmen, Unterstützung der operativen Steuerung</li>\n<li><strong>Portfolio-Monitoring:</strong> Analyse der wirtschaftlichen Entwicklung des Fahrzeugportfolios und Etablierung zentraler Steuerungskennzahlen</li>\n<li><strong>Prozessoptimierung:</strong> Weiterentwicklung der Schnittstellen zwischen Buchhaltung und Controlling (z. B. Monatsabschluss, Datenqualität, Workflows)</li>\n<li><strong>Stakeholder-Management:</strong> Enge Zusammenarbeit mit der Geschäftsführung von Ennoo Rental, dem Head of Controlling sowie dem CFO der SafeDriver Group</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>1–5 Jahre relevante Berufserfahrung im Finance-Umfeld (z. B. Controlling, Finance Operations, accounting-nahes Controlling, Audit oder transaktionsnahe Beratung)</li>\n<li>Sehr gutes Verständnis für betriebswirtschaftliche Zusammenhänge und Finance-Prozesse (Monatsabschluss, Reporting, Budgetierung, Wirtschaftsplanung)</li>\n<li>Strukturierte, eigenständige und lösungsorientierte Arbeitsweise mit ausgeprägter Hands-on-Mentalität</li>\n<li>Sicherer Umgang mit Excel und/oder Google Sheets; Erfahrung im Aufbau von Reporting- und KPI-Strukturen von Vorteil</li>\n<li>Klare, adressatengerechte Kommunikation gegenüber Management und internen Stakeholdern</li>\n<li>Keine disziplinarische Führungsverantwortung erforderlich – Ownership, Verlässlichkeit und Umsetzungsstärke werden jedoch vorausgesetzt</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Direkte Zusammenarbeit mit der Geschäftsführung und hohe Sichtbarkeit der eigenen Arbeit</li>\n<li>Aktive Mitgestaltung von Finance-Strukturen in einem skalierenden Geschäftsmodell</li>\n<li>Ein etabliertes, gruppenweites Finance-Team (ca. 10 Personen) als Sparringspartner</li>\n<li>Attraktives Vergütungspaket sowie Entwicklungsperspektiven innerhalb der Unternehmensgruppe</li>\n</ul>\n<p>Matthias freut sich auf deine vollständigen Bewerbungsunterlagen unter Angabe deiner Gehaltsvorstellung und deines frühestmöglichen Eintrittstermins.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-16 13:42:20.668', '2026-06-16 13:42:20.668', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/safedriver-group-gmbh/business-controller-berlin-83263', 'https://www.arbeitnow.com/jobs/companies/safedriver-group-gmbh/business-controller-berlin-83263', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/safedriver-group-gmbh/business-controller-berlin-83263\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
