INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1030, NULL, 'api', NULL, 'Content Creation (m/w/d) Minijob oder Teilzeit', 'CAPULET Jewelry', 'Munich', 'https://www.arbeitnow.com/jobs/companies/capulet-jewelry/content-creation-minijob-oder-teilzeit-munich-393883', '<p>📍 München | ⏳ Minijob | 15–25 Stunden pro Woche</p>\n<p>Du liebst Social Media, fühlst Dich vor der Kamera wohl und hast Lust, Teil einer schnell wachsenden Schmuckmarke zu werden?</p>\n<p>✨ CAPULET Jewelry steht für handgefertigten Schmuck aus München. Jedes Schmuckstück wird in Deutschland gefertigt – kein Massenprodukt, keine Fast Fashion.</p>\n<p>Für unser Team suchen wir eine kreative, authentische und kamerasichere Persönlichkeit, die zum Gesicht unserer Social-Media-Kanäle wird und unsere Marke gemeinsam mit unserem Goldschmiede Team täglich mit Leben füllt.</p>\n<p>Über CAPULET</p>\n<ul>\n<li>CAPULET ist eine unabhängige Luxus Schmuckmarke aus Deutschland. Mit Headquarter in München und weiteren Werkstätten in Pforzheim und Berlin.</li>\n</ul>\n<p>Seit über 15 Jahren stehen wir für hochwertigen handgefertigten Schmuck aus Gold und Silber – mit klarer Haltung und einem unverwechselbaren Stil.</p>\n<h2>Aufgaben</h2>\n<p><strong>💎 Deine Aufgaben</strong></p>\n<p>🎬 Du stehst regelmäßig vor der Kamera und präsentierst unsere Schmuckstücke</p>\n<p>📱 Du drehst eigenständig Content für Instagram, TikTok und weitere Plattformen</p>\n<p>💡 Du entwickelst gemeinsam mit unserem Marketing-Team neue Content-Ideen und Formate</p>\n<p>🚀 Du testest Trends, Hooks und Storytelling-Ansätze</p>\n<p>📸 Du unterstützt bei Shootings, Kampagnen und Content-Days mit dem Team</p>\n<p>🗓️ Bonus: Du entwickelst eigene Content-Pläne und kreative Ideen</p>\n<h2>Qualifikation</h2>\n<p><strong>✨ Das bringst Du mit</strong></p>\n<p>🎥 Du hast umfassende Kenntnisse im Drehen und Schneiden von Videos und fühlst Dich vor der Kamera wohl und wirkst natürlich, sympathisch und authentisch</p>\n<p>📲 Du interessierst Dich für Social Media und aktuelle Trends</p>\n<p>🇩🇪🇬🇧 Du sprichst fließend Deutsch und Englisch</p>\n<p>📍 Du wohnst in München oder Umgebung</p>\n<p>⚡ Du arbeitest zuverlässig, selbstständig und bringst Eigeninitiative mit</p>\n<h2>Benefits</h2>\n<p><strong>🤍 Das erwartet Dich</strong></p>\n<p>✨ kreative Freiheit</p>\n<p>💎 Einblicke in den Aufbau einer Premium-Schmuckmarke</p>\n<p>🎬 Kreative Projekte und abwechslungsreiche Shootings</p>\n<p>🏙️ Arbeitsplatz in München</p>\n<p>⏰ Flexible Arbeitszeiten</p>\n<p>🚀 Viel Raum für eigene Ideen und Verantwortung</p>\n<p><strong>📩 Bewerbung</strong></p>\n<p>Bitte sende uns keinen klassischen Lebenslauf.</p>\n<p>🎥 Schicke uns stattdessen einen Link zu einem kurzen Video (max. 60 Sekunden), in dem Du Dich vorstellst und uns zeigst, warum Du perfekt zu CAPULET passt. Das geht auch als DM bei Social Media von CAPULETjewelry.</p>\n<p>Verlinke gerne Deinen Account/ oder Accounts, die Du bereits aufgebaut hast.</p>\n<p>Wir freuen uns auf Dich und Deine aussagekräftige Bewerbung!!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>📍 München | ⏳ Minijob | 15–25 Stunden pro Woche</p>\n<p>Du liebst Social Media, fühlst Dich vor der Kamera wohl und hast Lust, Teil einer schnell wachsenden Schmuckmarke zu werden?</p>\n<p>✨ CAPULET Jewelry steht für handgefertigten Schmuck aus München. Jedes Schmuckstück wird in Deutschland gefertigt – kein Massenprodukt, keine Fast Fashion.</p>\n<p>Für unser Team suchen wir eine kreative, authentische und kamerasichere Persönlichkeit, die zum Gesicht unserer Social-Media-Kanäle wird und unsere Marke gemeinsam mit unserem Goldschmiede Team täglich mit Leben füllt.</p>\n<p>Über CAPULET</p>\n<ul>\n<li>CAPULET ist eine unabhängige Luxus Schmuckmarke aus Deutschland. Mit Headquarter in München und weiteren Werkstätten in Pforzheim und Berlin.</li>\n</ul>\n<p>Seit über 15 Jahren stehen wir für hochwertigen handgefertigten Schmuck aus Gold und Silber – mit klarer Haltung und einem unverwechselbaren Stil.</p>\n<h2>Aufgaben</h2>\n<p><strong>💎 Deine Aufgaben</strong></p>\n<p>🎬 Du stehst regelmäßig vor der Kamera und präsentierst unsere Schmuckstücke</p>\n<p>📱 Du drehst eigenständig Content für Instagram, TikTok und weitere Plattformen</p>\n<p>💡 Du entwickelst gemeinsam mit unserem Marketing-Team neue Content-Ideen und Formate</p>\n<p>🚀 Du testest Trends, Hooks und Storytelling-Ansätze</p>\n<p>📸 Du unterstützt bei Shootings, Kampagnen und Content-Days mit dem Team</p>\n<p>🗓️ Bonus: Du entwickelst eigene Content-Pläne und kreative Ideen</p>\n<h2>Qualifikation</h2>\n<p><strong>✨ Das bringst Du mit</strong></p>\n<p>🎥 Du hast umfassende Kenntnisse im Drehen und Schneiden von Videos und fühlst Dich vor der Kamera wohl und wirkst natürlich, sympathisch und authentisch</p>\n<p>📲 Du interessierst Dich für Social Media und aktuelle Trends</p>\n<p>🇩🇪🇬🇧 Du sprichst fließend Deutsch und Englisch</p>\n<p>📍 Du wohnst in München oder Umgebung</p>\n<p>⚡ Du arbeitest zuverlässig, selbstständig und bringst Eigeninitiative mit</p>\n<h2>Benefits</h2>\n<p><strong>🤍 Das erwartet Dich</strong></p>\n<p>✨ kreative Freiheit</p>\n<p>💎 Einblicke in den Aufbau einer Premium-Schmuckmarke</p>\n<p>🎬 Kreative Projekte und abwechslungsreiche Shootings</p>\n<p>🏙️ Arbeitsplatz in München</p>\n<p>⏰ Flexible Arbeitszeiten</p>\n<p>🚀 Viel Raum für eigene Ideen und Verantwortung</p>\n<p><strong>📩 Bewerbung</strong></p>\n<p>Bitte sende uns keinen klassischen Lebenslauf.</p>\n<p>🎥 Schicke uns stattdessen einen Link zu einem kurzen Video (max. 60 Sekunden), in dem Du Dich vorstellst und uns zeigst, warum Du perfekt zu CAPULET passt. Das geht auch als DM bei Social Media von CAPULETjewelry.</p>\n<p>Verlinke gerne Deinen Account/ oder Accounts, die Du bereits aufgebaut hast.</p>\n<p>Wir freuen uns auf Dich und Deine aussagekräftige Bewerbung!!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-17 13:41:11.882', '2026-06-17 13:41:11.882', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/capulet-jewelry/content-creation-minijob-oder-teilzeit-munich-393883', 'https://www.arbeitnow.com/jobs/companies/capulet-jewelry/content-creation-minijob-oder-teilzeit-munich-393883', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/capulet-jewelry/content-creation-minijob-oder-teilzeit-munich-393883\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1031, NULL, 'api', NULL, 'Head of Digital (m/w/d)', 'ju:niz Energy GmbH', 'Munich', 'https://www.arbeitnow.com/jobs/companies/juniz-energy-gmbh/head-of-digital-munich-353055', '<h2>Über uns</h2>\n<p><strong>Ohne Speicher keine Energiewende.</strong></p>\n<p>ju:niz Energy entwickelt und betreibt große Batteriespeicherprojekte und schafft damit die Grundlage für ein stabiles, nachhaltiges Energiesystem von morgen. Damit unsere Organisation gemeinsam mit unserem Wachstum skalieren kann, bauen wir unsere digitale Plattformlandschaft konsequent weiter aus.</p>\n<p>Du übernimmst die strategische Verantwortung für unsere digitale Plattformlandschaft und gestaltest aktiv den technologischen Ausbau eines stark wachsenden Energieunternehmens mit.<br>\nDabei verbindest du strategisches Denken mit operativer Umsetzung und entwickelst gemeinsam mit deinem Team ein skalierbares digitales Fundament für die nächsten Wachstumsphasen von ju:niz Energy.<br>\nVon Enterprise Architecture über Plattformstrategie bis hin zu Cyber Security und Governance bringst du unsere digitale Transformation auf das nächste Level – pragmatisch, modern und mit echtem Gestaltungsspielraum.</p>\n<h2>Deine Aufgaben</h2>\n<ul>\n<li>Du entwickelst unsere unternehmensweite Digital Strategy weiter und übersetzt diese in konkrete, skalierbare Lösungen.</li>\n<li>Gemeinsam mit deinem Team schaffst du ein leistungsfähiges „Digital Backbone“ für zukünftiges Wachstum.</li>\n<li>Du verantwortest die Weiterentwicklung unserer Enterprise- und Plattformarchitektur – von ERP über Data Platforms bis hin zu Cloud- und OT-Infrastrukturen.</li>\n<li>Digitale Transformationsprojekte steuerst du end-to-end und sorgst für eine nachhaltige Integration in unsere Unternehmensprozesse.</li>\n<li>Mit unterschiedlichen Stakeholdern aus Operations, Delivery, Finance und Management arbeitest du eng zusammen und bringst Anforderungen strukturiert in die Umsetzung.</li>\n<li>Du führst ein interdisziplinäres Digital-Team, schaffst Orientierung und entwickelst Strukturen sowie Kompetenzen kontinuierlich weiter.</li>\n<li>Gleichzeitig behältst du Budget, Prioritäten, Governance sowie regulatorische Anforderungen wie ISO 27001, KRITIS oder NIS2 im Blick.</li>\n<li>Neue Technologien, Automatisierungspotenziale und der sinnvolle Einsatz von AI gehören für dich selbstverständlich zu einer modernen Plattformstrategie dazu.</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>Du bringst mehrere Jahre Erfahrung in einer leitenden Rolle im Bereich Digital, IT, Plattformen oder Transformation mit.</li>\n<li>Komplexe digitale Landschaften, Enterprise-Strukturen und skalierbare Plattformmodelle sind dir vertraut.</li>\n<li>Idealerweise hast du bereits Transformationsprojekte in dynamischen Mittelstands- oder Scale-up-Umfeldern begleitet.</li>\n<li>Du kannst strategisch denken, gleichzeitig, aber auch pragmatisch Entscheidungen treffen und Dinge umsetzen.</li>\n<li>Führung bedeutet für dich nicht nur Steuerung, sondern vor allem Orientierung, Zusammenarbeit und Entwicklung von Teams.</li>\n<li>Technische Themen kannst du verständlich kommunizieren – sowohl mit Fachbereichen als auch auf Management-Ebene.</li>\n<li>Du arbeitest strukturiert, lösungsorientiert und behältst auch bei vielen parallelen Themen den Überblick.</li>\n<li>Gleichzeitig bringst du eine Hands-on-Mentalität, Eigeninitiative und Lust auf Gestaltung mit.</li>\n<li>Für die enge Zusammenarbeit mit Teams, Stakeholdern und Projekten bist du regelmäßig an unserem Standort in München sowie bei relevanten Projektterminen vor Ort präsent.</li>\n<li>Deutsch und Englisch beherrschst du sicher in der Zusammenarbeit mit unterschiedlichen Stakeholdern.</li>\n</ul>\n<h2>Warum wir?</h2>\n<ul>\n<li>Viel Gestaltungsspielraum und echte Verantwortung ab dem ersten Tag</li>\n<li>Direkten Einfluss auf die digitale Weiterentwicklung eines stark wachsenden Unternehmens</li>\n<li>Moderne Technologien, spannende Plattformprojekte und komplexe Transformationsvorhaben</li>\n<li>Zusammenarbeit auf Augenhöhe in einem ambitionierten und pragmatischen Umfeld</li>\n<li>Flexible Arbeitsmodelle sowie Mobile-Office-Möglichkeiten</li>\n<li>Unbefristete Festanstellung mit langfristiger Perspektive</li>\n<li>Benefits wie Givve Card, Fitness-Angebote und weitere Zusatzleistungen</li>\n<li>Ein Umfeld, das Innovation, Eigenverantwortung und nachhaltiges Wachstum verbindet</li>\n</ul>\n<h2>Kontakt</h2>\n<p><strong>Bewirb dich jetzt</strong> – auch wenn dein Lebenslauf nicht alle Punkte erfüllt. Uns zählen Motivation, Potenzial und dein Wille, die Energiewende voranzubringen.</p>\n<p>Wir freuen uns ausdrücklich über Bewerbungen von Menschen mit unterschiedlichen Hintergründen, Perspektiven und Erfahrungen. Gemeinsam schaffen wir ein Umfeld, in dem jeder sein volles Potenzial entfalten kann.</p>\n<p>Hinweis für Personalberatungen, Headhunter und andere Dienstleister: Wir besetzen diese Position eigenständig und bitten daher von einer unaufgeforderten Zusendung von Kandidatenprofilen oder Akquise Anfragen abzusehen.</p>\n<p>Dein Ansprechpartner<br>\nMoritz Erlbeck<br>\nPeople Growth &#x26; Hiring Lead</p>\n<p><strong>ju:niz Energy GmbH</strong><br>\nEinsteinring 43<br>\n85609 Aschheim</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>Über uns</h2>\n<p><strong>Ohne Speicher keine Energiewende.</strong></p>\n<p>ju:niz Energy entwickelt und betreibt große Batteriespeicherprojekte und schafft damit die Grundlage für ein stabiles, nachhaltiges Energiesystem von morgen. Damit unsere Organisation gemeinsam mit unserem Wachstum skalieren kann, bauen wir unsere digitale Plattformlandschaft konsequent weiter aus.</p>\n<p>Du übernimmst die strategische Verantwortung für unsere digitale Plattformlandschaft und gestaltest aktiv den technologischen Ausbau eines stark wachsenden Energieunternehmens mit.<br>\nDabei verbindest du strategisches Denken mit operativer Umsetzung und entwickelst gemeinsam mit deinem Team ein skalier