INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1065, NULL, 'api', NULL, 'Digital Workplace Manager (m/w/d)', 'TEQWERK GmbH', 'Brannenburg', 'https://www.arbeitnow.com/jobs/companies/teqwerk-gmbh/digital-workplace-manager-brannenburg-293524', '<p>Du gestaltest digitale Arbeitsumgebungen, die Menschen wirklich nutzen wollen.<br>\nNicht nur technisch sauber - sondern durchdacht, praxisnah und mit echtem Mehrwert.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Du konzipierst und implementierst digitale Arbeitsplatzlösungen - von Collaboration-Tools über Workflow-Automatisierung bis zu Cloud-Integrationen</li>\n<li>Du analysierst Kundenanforderungen und entwickelst Lösungen, die wirklich passen</li>\n<li>Du übersetzt komplexe technische Anforderungen in praxisnahe Lösungen – verständlich für IT und Business gleichermaßen</li>\n<li>Du hast Trends im Bereich Digital Workplace im Blick und bringst neue Technologien wie KI und Automatisierung aktiv ein</li>\n</ul>\n<p><strong>Wichtig:</strong> Du bist nicht nur Umsetzer - du denkst mit, gestaltest und übernimmst Verantwortung für deine Lösungen.</p>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erfahrung in der Architektur oder Implementierung digitaler Arbeitsplatzlösungen (z.B. Microsoft 365, SharePoint, Teams)</li>\n<li>Solides Verständnis für Cloud-Technologien und moderne Collaboration-Tools</li>\n<li>Fähigkeit, komplexe Projekte zu planen und dabei das große Ganze im Blick zu behalten</li>\n<li>Kommunikationsstärke - egal ob im Entwicklerteam oder beim KundenLust, digitale Transformation wirklich voranzubringen</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Hohe Gestaltungsfreiheit in einem wachsenden Unternehmen</li>\n<li>Direkter Einfluss auf die Weiterentwicklung von TEQWERK</li>\n<li>Enge Zusammenarbeit mit erfahrenen Cloud- und Data-Experten</li>\n<li>Spannende Projekte im Bereich Azure, Data &#x26; AI und Digital Workplace</li>\n<li>Attraktives Vergütungsmodell</li>\n<li>Flexible Arbeitsmodelle (remote / hybrid)</li>\n</ul>\n<p><strong>Warum TEQWERK?</strong></p>\n<p>Weil digitaler Workplace bei uns nicht bedeutet, SharePoint-Seiten zu bauen -<br>\nsondern Arbeitsumgebungen zu schaffen, die einen echten Unterschied machen.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Du gestaltest digitale Arbeitsumgebungen, die Menschen wirklich nutzen wollen.<br>\nNicht nur technisch sauber - sondern durchdacht, praxisnah und mit echtem Mehrwert.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Du konzipierst und implementierst digitale Arbeitsplatzlösungen - von Collaboration-Tools über Workflow-Automatisierung bis zu Cloud-Integrationen</li>\n<li>Du analysierst Kundenanforderungen und entwickelst Lösungen, die wirklich passen</li>\n<li>Du übersetzt komplexe technische Anforderungen in praxisnahe Lösungen – verständlich für IT und Business gleichermaßen</li>\n<li>Du hast Trends im Bereich Digital Workplace im Blick und bringst neue Technologien wie KI und Automatisierung aktiv ein</li>\n</ul>\n<p><strong>Wichtig:</strong> Du bist nicht nur Umsetzer - du denkst mit, gestaltest und übernimmst Verantwortung für deine Lösungen.</p>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erfahrung in der Architektur oder Implementierung digitaler Arbeitsplatzlösungen (z.B. Microsoft 365, SharePoint, Teams)</li>\n<li>Solides Verständnis für Cloud-Technologien und moderne Collaboration-Tools</li>\n<li>Fähigkeit, komplexe Projekte zu planen und dabei das große Ganze im Blick zu behalten</li>\n<li>Kommunikationsstärke - egal ob im Entwicklerteam oder beim KundenLust, digitale Transformation wirklich voranzubringen</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Hohe Gestaltungsfreiheit in einem wachsenden Unternehmen</li>\n<li>Direkter Einfluss auf die Weiterentwicklung von TEQWERK</li>\n<li>Enge Zusammenarbeit mit erfahrenen Cloud- und Data-Experten</li>\n<li>Spannende Projekte im Bereich Azure, Data &#x26; AI und Digital Workplace</li>\n<li>Attraktives Vergütungsmodell</li>\n<li>Flexible Arbeitsmodelle (remote / hybrid)</li>\n</ul>\n<p><strong>Warum TEQWERK?</strong></p>\n<p>Weil digitaler Workplace bei uns nicht bedeutet, SharePoint-Seiten zu bauen -<br>\nsondern Arbeitsumgebungen zu schaffen, die einen echten Unterschied machen.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-18 01:41:24.349', '2026-06-18 01:41:24.349', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/teqwerk-gmbh/digital-workplace-manager-brannenburg-293524', 'https://www.arbeitnow.com/jobs/companies/teqwerk-gmbh/digital-workplace-manager-brannenburg-293524', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/teqwerk-gmbh/digital-workplace-manager-brannenburg-293524\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1066, NULL, 'api', NULL, 'Windows Server Administrator / Messaging Engineer (m/w/d) - 1429', 'ITconfig/all GmbH', 'Wiesbaden', 'https://www.arbeitnow.com/jobs/companies/itconfigall-gmbh/windows-server-administrator-messaging-engineer-wiesbaden-53082', '<p>Für einen Kunden suchen wir einen erfahrenen <strong>Windows Server Administrator (m/w/d)</strong> mit Schwerpunkt auf dem Betrieb und der Administration von Microsoft-basierten Mailing- und Arbeitsplatzumgebungen.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Administration und Betrieb von Windows Server 2019 Umgebungen</li>\n<li>Betreuung und Optimierung von Microsoft Outlook und Exchange</li>\n<li>Administration von Windows 11 Clients und Microsoft Office Anwendungen</li>\n<li>Betreuung von Webservern (IIS, Tomcat) sowie Anbindung von Datenbanken (SQL, Oracle, DB2)</li>\n<li>Administration und Konfiguration von Office-Erweiterungen wie Think Cell oder EfficientElements</li>\n<li>Fehleranalyse, Incident-Bearbeitung und Unterstützung im operativen Betrieb</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Mehrjährige Erfahrung als Windows Server Administrator, Messaging Engineer oder in einer vergleichbaren Rolle</li>\n<li>Sehr gute Kenntnisse in Windows Server 2019 und Windows 11</li>\n<li>Fundierte Erfahrung mit Microsoft Exchange, Outlook und Microsoft Office</li>\n<li>Kenntnisse in der Administration von IIS, Tomcat sowie Datenbankanbindungen (SQL, Oracle, DB2)</li>\n<li>Erfahrung mit Office-Add-ons und ergänzender Standardsoftware</li>\n<li>Kenntnisse regulatorischer Anforderungen im Finanz- oder Bankenumfeld von Vorteil</li>\n<li>Sehr gute Deutschkenntnisse in Wort und Schrift</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Persönliche Zusatzleistungen, flexibel auf deine Bedürfnisse zugeschnitten – z. B. Jobticket, JobRad, Gympass oder andere Zusatzleistungen, die individuell vereinbart werden können</li>\n<li>Flexible Arbeitszeiten, Homeoffice und Workations nach Absprache</li>\n<li>Projekte in einem internationalen Umfeld</li