(1080, NULL, 'api', NULL, 'DevOps Engineer (Part-Time, Remote)', 'Louco Event Media GmbH', 'Offenbach', 'https://www.arbeitnow.com/jobs/companies/louco-event-media-gmbh/devops-engineer-part-time-remote-offenbach-176013', '<p>Louco is an AI-powered event discovery platform helping people discover events that truly match their interests and preferences.</p>\n<p>We are looking for a hands-on DevOps Engineer to support our infrastructure, deployments, security, and scalability as we prepare for our next growth phase.</p>\n<p>This is a remote freelance position (approximately 20–40 hours per month initially), with the potential to grow over time.</p>\n<h2>Tasks</h2>\n<p>What You Will Do</p>\n<ul>\n<li>Manage and optimize our cloud infrastructure</li>\n<li>Maintain development, staging, and production environments</li>\n<li>Build and improve CI/CD pipelines</li>\n<li>Support deployments and release processes</li>\n<li>Monitor uptime, performance, and security</li>\n<li>Implement backup and disaster recovery strategies</li>\n<li>Configure domains, SSL certificates, and networking</li>\n<li>Support developers with infrastructure-related topics</li>\n<li>Improve scalability, reliability, and system performance</li>\n</ul>\n<p>Environment</p>\n<ul>\n<li>Hetzner Cloud</li>\n<li>Linux</li>\n<li>Docker</li>\n<li>Supabase</li>\n<li>PostgreSQL</li>\n<li>GitHub</li>\n<li>GitHub Actions</li>\n<li>Cloudflare</li>\n</ul>\n<h2>Requirements</h2>\n<p><strong>Must Have</strong></p>\n<ul>\n<li>Strong Linux administration skills</li>\n<li>Experience with Hetzner Cloud or similar cloud environments</li>\n<li>Docker and container management</li>\n<li>CI/CD pipelines</li>\n<li>GitHub Actions</li>\n<li>PostgreSQL</li>\n<li>Monitoring and logging tools</li>\n<li>Security best practices</li>\n<li>DNS, SSL and networking knowledge</li>\n<li>Backup and disaster recovery concepts</li>\n</ul>\n<p><strong>Nice to Have</strong></p>\n<ul>\n<li>Supabase experience</li>\n<li>Nginx or Traefik</li>\n<li>Terraform</li>\n<li>Kubernetes</li>\n<li>Mobile app infrastructure experience</li>\n<li>Startup experience</li>\n</ul>\n<p><strong>What We Are Looking For</strong></p>\n<ul>\n<li>Startup mindset</li>\n<li>Hands-on and pragmatic approach</li>\n<li>Strong problem-solving skills</li>\n<li>Ability to work independently</li>\n<li>Good communication skills</li>\n<li>Comfortable working with remote teams</li>\n<li>Fluent English</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Remote</li>\n<li>Freelance</li>\n<li>Part-Time (20–40 hours/month initially)</li>\n<li>Flexible working hours</li>\n<li>Long-term collaboration preferred</li>\n</ul>\n<p>How to Apply</p>\n<p>Please send:</p>\n<ul>\n<li>CV or LinkedIn profile</li>\n<li>Hourly rate expectation</li>\n<li>Availability (hours per month)</li>\n<li>Short description of relevant DevOps projects</li>\n</ul>\n<p>We look forward to hearing from you.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Louco is an AI-powered event discovery platform helping people discover events that truly match their interests and preferences.</p>\n<p>We are looking for a hands-on DevOps Engineer to support our infrastructure, deployments, security, and scalability as we prepare for our next growth phase.</p>\n<p>This is a remote freelance position (approximately 20–40 hours per month initially), with the potential to grow over time.</p>\n<h2>Tasks</h2>\n<p>What You Will Do</p>\n<ul>\n<li>Manage and optimize our cloud infrastructure</li>\n<li>Maintain development, staging, and production environments</li>\n<li>Build and improve CI/CD pipelines</li>\n<li>Support deployments and release processes</li>\n<li>Monitor uptime, performance, and security</li>\n<li>Implement backup and disaster recovery strategies</li>\n<li>Configure domains, SSL certificates, and networking</li>\n<li>Support developers with infrastructure-related topics</li>\n<li>Improve scalability, reliability, and system performance</li>\n</ul>\n<p>Environment</p>\n<ul>\n<li>Hetzner Cloud</li>\n<li>Linux</li>\n<li>Docker</li>\n<li>Supabase</li>\n<li>PostgreSQL</li>\n<li>GitHub</li>\n<li>GitHub Actions</li>\n<li>Cloudflare</li>\n</ul>\n<h2>Requirements</h2>\n<p><strong>Must Have</strong></p>\n<ul>\n<li>Strong Linux administration skills</li>\n<li>Experience with Hetzner Cloud or similar cloud environments</li>\n<li>Docker and container management</li>\n<li>CI/CD pipelines</li>\n<li>GitHub Actions</li>\n<li>PostgreSQL</li>\n<li>Monitoring and logging tools</li>\n<li>Security best practices</li>\n<li>DNS, SSL and networking knowledge</li>\n<li>Backup and disaster recovery concepts</li>\n</ul>\n<p><strong>Nice to Have</strong></p>\n<ul>\n<li>Supabase experience</li>\n<li>Nginx or Traefik</li>\n<li>Terraform</li>\n<li>Kubernetes</li>\n<li>Mobile app infrastructure experience</li>\n<li>Startup experience</li>\n</ul>\n<p><strong>What We Are Looking For</strong></p>\n<ul>\n<li>Startup mindset</li>\n<li>Hands-on and pragmatic approach</li>\n<li>Strong problem-solving skills</li>\n<li>Ability to work independently</li>\n<li>Good communication skills</li>\n<li>Comfortable working with remote teams</li>\n<li>Fluent English</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Remote</li>\n<li>Freelance</li>\n<li>Part-Time (20–40 hours/month initially)</li>\n<li>Flexible working hours</li>\n<li>Long-term collaboration preferred</li>\n</ul>\n<p>How to Apply</p>\n<p>Please send:</p>\n<ul>\n<li>CV or LinkedIn profile</li>\n<li>Hourly rate expectation</li>\n<li>Availability (hours per month)</li>\n<li>Short description of relevant DevOps projects</li>\n</ul>\n<p>We look forward to hearing from you.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-18 01:43:46.029', '2026-06-18 01:43:46.029', '', '', 'Remote', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/louco-event-media-gmbh/devops-engineer-part-time-remote-offenbach-176013', 'https://www.arbeitnow.com/jobs/companies/louco-event-media-gmbh/devops-engineer-part-time-remote-offenbach-176013', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/louco-event-media-gmbh/devops-engineer-part-time-remote-offenbach-176013\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
