INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1124, NULL, 'api', NULL, 'Werkstudent (m/w/d) - E-Commerce, Produktmanagement & Softwareentwicklung', 'SpielundLern GmbH', 'Neumarkt in der Oberpfalz', 'https://www.arbeitnow.com/jobs/companies/spielundlern-gmbh/werkstudent-e-commerce-produktmanagement-softwareentwicklung-neumarkt-in-der-oberpfalz-383054', '<p><strong>Über uns</strong></p>\n<p>Spiel und Lern ist ein spezialisierter Online-Fachhandel mit über 20 Jahren Erfahrung im Bereich pädagogisches Spiel- und Fördermaterial für Kinder. Unser Sortiment richtet sich in erster Linie an B2B-Kunden aus dem Bildungs-, Förder- und Therapiebereich – darunter Kindertagesstätten, Grundschulen, Ergotherapie- und Logopädiepraxen sowie Kliniken und therapeutische Einrichtungen. Mit unserem Onlineshop bieten wir unseren Kunden ein umfangreiches Sortiment und erstklassigen Service. Um unsere digitale Plattform und unsere internen Prozesse weiterzuentwickeln, suchen wir Verstärkung für unser Team.</p>\n<h2>Aufgaben</h2>\n<p>Deine MissionAls Werkstudent (m/w/d) im Bereich E-Commerce und Softwareentwicklung bist du ein wichtiger Teil unseres Teams und agierst an der spannenden Schnittstelle zwischen Produktmanagement, E-Commerce und Softwareentwicklung. Deine Mission ist es, unsere digitale Plattform aktiv mitgestalten – von der ersten Idee zur Prozessoptimierung bis zur fertigen Lösung. Du analysierst die Bedürfnisse unserer B2B-Kunden, sammelst wertvolles Feedback und innovative Ideen für neue Features unseres Onlineshops, priorisierst diese gemeinsam mit der Geschäftsleitung und begleitest die Umsetzung.</p>\n<p><strong>Deine Aufgaben im Detail</strong></p>\n<ul>\n<li>Kundenkommunikation &#x26; Feedback-Management: Du gehst proaktiv in den Austausch mit unseren B2B-Kunden (Kitas, Schulen, Praxen), um deren Bedürfnisse, Herausforderungen und Ideen für neue Funktionen in unserem Onlineshop zu verstehen und zu dokumentieren.</li>\n<li>Anforderungsanalyse &#x26; Priorisierung: Du strukturierst das gesammelte Kundenfeedback, analysierst die Anforderungen und erarbeitest gemeinsam mit der Geschäftsleitung eine Priorisierung der umzusetzenden Themen zur Optimierung der Customer Journey.</li>\n<li>Schnittstellenfunktion (Produktmanagement): Du fungierst als Bindeglied zwischen den Kundenanforderungen, dem Produktmanagement und der Softwareentwicklung/IT und sorgst für einen reibungslosen Informationsfluss.</li>\n<li>Begleitung der E-Commerce-Entwicklung: Du unterstützt bei der Konzeption und Umsetzung neuer Features und Microservices für unseren Onlineshop und unsere internen Systeme – von der technischen Spezifikation über die Entwicklung (z.B. mit PHP, JavaScript/TypeScript oder Python) bis hin zur Bereitstellung.</li>\n<li>Feedbackschleifen &#x26; Iteration: Nach der Umsetzung neuer Funktionen im Shop holst du erneut Feedback bei den Kunden ein, um die entwickelten Lösungen kontinuierlich zu verbessern.</li>\n<li>Markt- &#x26; Wettbewerbsbeobachtung: Du behältst aktuelle Trends im Bereich E-Commerce, B2B-Shopsysteme und digitale Bildung im Blick und leitest daraus Impulse für unsere Weiterentwicklung ab.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Dein Profil</p>\n<p>Du studierst Wirtschaftsinformatik, Informatik, E-Commerce, BWL mit IT-Schwerpunkt oder einen vergleichbaren Studiengang. Du bringst IT-Affinität und Grundkenntnisse in der Webentwicklung mit; Kenntnisse in gängigen Webtechnologien wie PHP, JavaScript oder HTML/CSS sind von Vorteil. Interesse an oder erste Erfahrungen mit Onlineshopsystemen, E-Commerce-Prozessen oder Schnittstellenmanagement sind wünschenswert. Du hast Freude am Kundenkontakt, hörst aktiv zu und kannst technische Themen verständlich kommunizieren. Deine Arbeitsweise ist analytisch, strukturiert und eigenverantwortlich. Du bringst dich proaktiv mit eigenen Ideen ein und bist ein echter Teamplayer. Sehr gute Deutschkenntnisse sowie gute Englischkenntnisse runden dein Profil ab.</p>\n<h2>Benefits</h2>\n<p>Was wir dir bieten</p>\n<ul>\n<li>Praxiserfahrung mit echtem Impact: Du erhältst tiefe Einblicke in den B2B-E-Commerce und gestaltest die Weiterentwicklung unserer digitalen Plattform aktiv mit – deine Arbeit schafft messbaren Mehrwert für unsere Kunden im Bildungs- und Therapiebereich.</li>\n<li>Verantwortung von Anfang an: Du arbeitest direkt mit der Geschäftsleitung zusammen und übernimmst eigenständig Verantwortung für Themen, die das Unternehmen voranbringen.</li>\n<li>Flexibilität: Flexible Arbeitszeiten, die sich gut mit deinem Studium vereinbaren lassen, sowie die Möglichkeit, teilweise im Homeoffice zu arbeiten.</li>\n<li>Mentoring &#x26; Entwicklung: Ein erfahrenes Team, das dich betreut und deine fachliche sowie persönliche Weiterentwicklung aktiv fördert.</li>\n<li>Team &#x26; Kultur: Ein hochmotiviertes Team, flache Hierarchien und eine offene, wertschätzende Unternehmenskultur</li>\n</ul>\n<p>Interessiert?</p>\n<p>Dann freuen wir uns auf deine aussagekräftige Bewerbung :)</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Über uns</strong></p>\n<p>Spiel und Lern ist ein spezialisierter Online-Fachhandel mit über 20 Jahren Erfahrung im Bereich pädagogisches Spiel- und Fördermaterial für Kinder. Unser Sortiment richtet sich in erster Linie an B2B-Kunden aus dem Bildungs-, Förder- und Therapiebereich – darunter Kindertagesstätten, Grundschulen, Ergotherapie- und Logopädiepraxen sowie Kliniken und therapeutische Einrichtungen. Mit unserem Onlineshop bieten wir unseren Kunden ein umfangreiches Sortiment und erstklassigen Service. Um unsere digitale Plattform und unsere internen Prozesse weiterzuentwickeln, suchen wir Verstärkung für unser Team.</p>\n<h2>Aufgaben</h2>\n<p>Deine MissionAls Werkstudent (m/w/d) im Bereich E-Commerce und Softwareentwicklung bist du ein wichtiger Teil unseres Teams und agierst an der spannenden Schnittstelle zwischen Produktmanagement, E-Commerce und Softwareentwicklung. Deine Mission ist es, unsere digitale Plattform aktiv mitgestalten – von der ersten Idee zur Prozessoptimierung bis zur fertigen Lösung. Du analysierst die Bedürfnisse unserer B2B-Kunden, sammelst wertvolles Feedback und innovative Ideen für neue Features unseres Onlineshops, priorisierst diese gemeinsam mit der Geschäftsleitung und begleitest die Umsetzung.</p>\n<p><strong>Deine Aufgaben im Detail</strong></p>\n<ul>\n<li>Kundenkommunikation &#x26; Feedback-Management: Du gehst proaktiv in den Austausch mit unseren B2B-Kunden (Kitas, Schulen, Praxen), um deren Bedürfnisse, Herausforderungen und Ideen für neue Funktionen in unserem Onlineshop zu verstehen und zu dokumentieren.</li>\n<li>Anforderungsanalyse &#x26; Priorisierung: Du strukturierst das gesammelte Kundenfeedback, analysierst die Anforderungen und erarbeitest gemeinsam mit der Geschäftsleitung eine Priorisierung der umzusetzenden Themen zur Optimierung der Customer Journey.</li>\n<li>Schnittstellenfunktion (Produktmanagement): Du fungierst als Bindeglied zwischen den Kundenanforderungen, dem Produktmanagement und der Softwareentwicklung/IT und sorgst für einen reibungslosen Informationsfluss.</li>\n<li>Begleitung der E-Commerce-Entwicklung: Du unterstützt bei der Konzeption und Umsetzung neuer Features und Microservices für unseren Onlineshop und unsere internen Systeme – von der technischen Spezifikation über die Entwicklung (z.B. mit PHP, JavaScript/TypeScript oder Python) bis hin zur Bereitstellung.</li>\n<li>Feedbackschleifen &#x26; Iteration: Nach der Umsetzung neuer Funktionen im Shop holst du erneut Feedback bei den Kunden ein, um die entwickelten Lösungen kontinuierlich zu verbessern.</li>\n<li>Markt- &#x26; Wettbewerbsbeobachtung: Du behältst aktuelle Trends im Bereich E-Commerce, B2B-Shopsysteme und digitale Bildung im Blick und leitest daraus Impulse für unsere Weiterentwicklung ab.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Dein Profil</p>\n<p>Du studierst Wirtschaftsinformatik, Informatik, E-Commerce, BWL mit IT-Schwerpunkt oder einen vergleichbaren Studiengang. Du bringst IT-Affinität und Grundkenntnisse in der Webentwicklung mit; Kenntnisse in gängigen Webtechnologien wie PHP, JavaScript oder HTML/CSS sind von Vorteil. Interesse an oder erste Erfahrungen mit Onlineshopsystemen, E-Commerce-Prozessen oder Schnittstellenmanagement sind wünschenswert. Du hast Freude am Kundenkontakt, hörst aktiv zu und kannst technische Themen verständlich kommunizieren. Deine Arbeitsweise ist analytisch, strukturiert und eigenverantwortlich. Du bringst dich proaktiv mit eigenen Ideen ein und bist ein echter Teamplayer. Sehr gute Deutschkenntnisse sowie gute Englischkenntnisse runden dein Profil ab.</p>\n<h2>Benefits</h2>\n<p>Was wir dir bieten</p>\n<ul>\n<li>Praxiserfahrung mit echtem Impact: Du erhältst tiefe Einblicke in den B2B-E-Commerce und gestaltest die Weiterentwicklung unserer digitalen Plattform aktiv mit – deine Arbeit schafft messbaren Mehrwert für unsere Kunden im Bildungs- und Therapiebereich.</li>\n<li>Verantwortung von Anfang an: Du arbeitest direkt mit der Geschäftsleitung zusammen und übernimmst eigenständig Verantwortung für Themen, die das Unternehmen voranbringen.</li>\n<li>Flexibilität: Flexible Arbeitszeiten, die sich gut mit deinem Studium vereinbaren lassen, sowie die Möglichkeit, teilweise im Homeoffice zu arbeiten.</li>\n<li>Mentoring &#x26; Entwicklung: Ein erfahrenes Team, das dich betreut und deine fachliche sowie persönliche Weiterentwicklung aktiv fördert.</li>\n<li>Team &#x26; Kultur: Ein hochmotiviertes Team, flache Hierarchien und eine offene, wertschätzende Unternehmenskultur</li>\n</ul>\n<p>Interessiert?</p>\n<p>Dann freuen wir uns auf deine aussagekräftige Bewerbung :)</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-18 13:42:02.386', '2026-06-18 13:42:02.386', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/spielundlern-gmbh/werkstudent-e-commerce-produktmanagement-softwareentwicklung-neumarkt-in-der-oberpfalz-383054', 'https://www.arbeitnow.com/jobs/companies/spielundlern-gmbh/werkstudent-e-commerce-produktmanagement-softwareentwicklung-neumarkt-in-der-oberpfalz-383054', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/spielundlern-gmbh/werkstudent-e-commerce-produktmanagement-softwareentwicklung-neumarkt-in-der-oberpfalz-383054\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1125, NULL, 'api', NULL, 'Immobiliengutachter (m/w/d) in Voll- und Teilzeit', 'Volksbank Westmünsterland eG', 'Haltern am See', 'https://www.arbeitnow.com/jobs/companies/volksbank-westmunsterland-eg/immobiliengutachter-in-voll-und-teilzeit-haltern-am-see-183665', '<p>Mit Freude an der Arbeit und Verantwortungsbewusstsein bei allem, was wir tun – so arbeiten wir. Als TOP‑Arbeitgeber schafft unsere Bank dafür die besten Rahmenbedingungen. Rund 650 engagierte Mitarbeitende und eine Bilanzsumme von etwa 5,2 Milliarden Euro machen uns zu einer der großen Regionalbanken im Westmünsterland: Hier sind wir verwurzelt, hier setzen wir uns ein – für eine starke Wirtschaft, eine nachhaltige Lebensqualität und ein persönlich-digitales Banking. Wir begleiten Mitglieder und Kunden auch Durch anspruchsvollste Themen. Unser Geschäftsgebiet erstreckt sich über das westliche und südliche Münsterland bis an die Grenze des Ruhrgebiets.</p>\n<h2>Aufgaben</h2>\n<p><strong>Das können Sie bei uns gestalten:</strong></p>\n<ul>\n<li>Erstellung von Markt- und Beleihungswertgutachten für wohnwirtschaftliche und gewerbliche Immobilien im Inland nach geltenden gesetzlichen und aufsichtsrechtlichen Vorgaben.</li>\n<li>Durchführung von Objektbesichtigungen im Rahmen der Objektbewertung.</li>\n<li>Beobachtung des Immobilien- und Grundstücksmarktes, Analyse von Preis- und Zinsentwicklungen sowie von gesetzlichen Rahmenbedingungen.</li>\n<li>Plausibilitätsprüfung von externen Gutachten für Immobilien im Inland.</li>\n<li>Wertüberprüfung von Gutachten nach gesetzlichen Vorgaben.</li>\n<li>Zusammenarbeit mit Markt‑ und Marktfolgebereichen sowie Unterstützung bei komplexen Finanzierungsstrukturen.</li>\n<li>Mitwirkung an der Weiterentwicklung von Bewertungsprozessen und an der Qualitätssicherung im Gutachterwesen.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das macht Sie aus:</strong></p>\n<ul>\n<li>Abgeschlossene Ausbildung als Bankkaufmann/‑frau, ein technisches Studium (z. B. Bauingenieurwesen, Architektur) oder eine vergleichbare Qualifikation.</li>\n<li>Langjährige Berufserfahrung, idealerweise im Bankenumfeld und in der Immobilienbewertung bzw. Gutachtertätigkeit.</li>\n<li>Fundierte fachliche Expertise in der Erstellung von Beleihungswertgutachten.</li>\n<li>Gute Kenntnisse der relevanten Immobilienmärkte.</li>\n<li>Zusatzqualifikationen wie HypZert S oder F sind von Vorteil, aber kein Muss.</li>\n<li>Hohes analytisches Verständnis, Blick für das „große Ganze“ und eine strukturierte, verantwortungsbewusste Arbeitsweise.</li>\n<li>Ausgeprägte Teamfähigkeit, Eigenverantwortung und ein professionelles Auftreten in der Zusammenarbeit mit internen Schnittstellen.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Was Sie von uns erwarten dürfen:</strong></p>\n<ul>\n<li>Bei uns erwartet Sie eine Arbeitskultur, in der Vielfalt, Gleichberechtigung und Fairness selbstverständlich sind.  Die Unterzeichnungen der Charta der Vielfalt, der Charta des Ehrenamts und der Charta der Pflege unterstreichen dieses Selbstverständnis.</li>\n<li>Wir leben ein kollegiales, wertschätzendes Miteinander in einem engagierten, professionellen Team.</li>\n<li>Sie finden flexible, familienfreundliche Arbeitszeit‑ und Arbeitsortmodelle – weil Lebensentwürfe unterschiedlich sind.</li>\n<li>Wir bieten Ihnen attraktive und bedarfsgerechte Weiterbildungs- und Entwicklungsmöglichkeiten.</li>\n<li>Sie arbeiten beim TOP Employer 2026; übrigens wurden wir nun schon zum 19. Mal ausgezeichnet.</li>\n<li>Auf Sie warten interessante Benefits z.B. Bike-Leasing, Deutschlandticket als Jobticket, Essenschecks, PC-Leasing, Mitgliedschaft im Fitnessstudio (EGYM Wellpass) etc.</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Mit Freude an der Arbeit und Verantwortungsbewusstsein bei allem, was wir tun – so arbeiten wir. Als TOP‑Arbeitgeber schafft unsere Bank dafür die besten Rahmenbedingungen. Rund 650 engagierte Mitarbeitende und eine Bilanzsumme von etwa 