(1135, NULL, 'api', NULL, 'Entry Level Administrative Assistant', 'RecruitLytixs Hires', 'Ø§ÙÙINSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1136, NULL, 'api', NULL, 'Operations Support Manager', 'The Chartered Institute for Securities &amp; Investment (The CISI)', 'Ø§ÙØ±ÙØ§Ø¶, Ø§ÙØ±ÙØ§Ø¶ Ø§ÙØ³Ø¹ÙØ¯ÙØ©', 'https://remoteOK.com/remote-jobs/remote-operations-support-manager-the-chartered-institute-for-securities-amp-investment-the-cisi-1133565', '<p><strong>Job Title: Operations Support Manager</strong></p><p><strong>Location:</strong> Riyadh</p><p><br></p><p><strong>About Us:</strong> The Chartered Institute for Securities &amp; Investment (CISI) is the leading professional body for securities, investment, wealth, and financial planning professionals. As a not-for-profit organisation, we represent 52,000 members globally. Due to the importance of our strategic partnership with the Financial Academy we are creating a full-time presence in Riyadh. Join us and be part of a team that is making a significant impact with professionalism globally.</p><p><br></p><p><strong>Role Overview:</strong> Are you a customer centric and self-driven professional? We are looking for an Operations Support Manager to join our team, based in Riyadh, Saudi Arabia. In this role, you will be responsible for working closely with our key Partner The Financial Academy, supporting operational requirements and identifying opportunities to improve our service offering and exam candidate experiences. The role will involve market travel.</p><p><br></p><p><strong>Key Responsibilities:</strong></p><ul><li>Support and coordinate end-to-end operational experiences for candidates sitting examinations through the Financial Academy, acting as a liaison between our delivery partners and the CISI operations team.</li><li>Maintain and strengthen relationships with key stakeholders.</li><li>Provide exceptional service and support to our partners and members, ensuring all aspects of the customer experience are seamless.</li><li>Collaborate with internal teams to deliver high-quality customer experiences.</li><li>Create and identify opportunities for improvements and service development.</li><li>Regular engagements at events with members and stakeholders.</li></ul><p><br></p><p><strong>Personal Attributes:</strong></p><ul><li>Arabic language essential.</li><li>Customer centric, with excellent communication and interpersonal skills.</li><li>Strong organisational skills and resilience.</li><li>Attention to detail and problem-solving skills.</li><li>A pro-active and positive attitude.</li><li>Ability to work independently and as part of a high-performing team.</li><li>Previous experience in a Operations/Customer Service role.</li><li>Project management experience.</li><li>Familiar with analysis of business processes and customer journeys (desirable).</li></ul><p><br></p><p><strong>Commitment to Integrity and Ethical Conduct:</strong></p><ul><li>Uphold the highest standards of integrity and ethical conduct in all interactions.</li><li>Ensure compliance with CISI\'s code of ethics and professional standards.</li><li>Promote a culture of transparency, honesty, and accountability.</li></ul><p></p><br/><br/>Please mention the word **DEFENDER** and tag RMTU5LjE5OC42Ni4xNjM= when applying to show you read the job post completely (#RMTU5LjE5OC42Ni4xNjM=). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', '<p><strong>Job Title: Operations Support Manager</strong></p><p><strong>Location:</strong> Riyadh</p><p><br></p><p><strong>About Us:</strong> The Chartered Institute for Securities &amp; Investment (CISI) is the leading professional body for securities, investment, wealth, and financial planning professionals. As a not-for-profit organisation, we represent 52,000 members globally. Due to the importance of our strategic partnership with the Financial Academy we are creating a full-time presence in Riyadh. Join us and be part of a team that is making a significant impact with professionalism globally.</p><p><br></p><p><strong>Role Overview:</strong> Are you a customer centric and self-driven professional? We are looking for an Operations Support Manager to join our team, based in Riyadh, Saudi Arabia. In this role, you will be responsible for working closely with our key Partner The Financial Academy, supporting operational requirements and identifying opportunities to improve our service offering and exam candidate experiences. The role will involve market travel.</p><p><br></p><p><strong>Key Responsibilities:</strong></p><ul><li>Support and coordinate end-to-end operational experiences for candidates sitting examinations through the Financial Academy, acting as a liaison between our delivery partners and the CISI operations team.</li><li>Maintain and strengthen relationships with key stakeholders.</li><li>Provide exceptional service and support to our partners and members, ensuring all aspects of the customer experience are seamless.</li><li>Collaborate with internal teams to deliver high-quality customer experiences.</li><li>Create and identify opportunities for improvements and service development.</li><li>Regular engagements at events with members and stakeholders.</li></ul><p><br></p><p><strong>Personal Attributes:</strong></p><ul><li>Arabic language essential.</li><li>Customer centric, with excellent communication and interpersonal skills.</li><li>Strong organisational skills and resilience.</li><li>Attention to detail and problem-solving skills.</li><li>A pro-active and positive attitude.</li><li>Ability to work independently and as part of a high-performing team.</li><li>Previous experience in a Operations/Customer Service role.</li><li>Project management experience.</li><li>Familiar with analysis of business processes and customer journeys (desirable).</li></ul><p><br></p><p><strong>Commitment to Integrity and Ethical Conduct:</strong></p><ul><li>Uphold the highest standards of integrity and ethical conduct in all interactions.</li><li>Ensure compliance with CISI\'s code of ethics and professional standards.</li><li>Promote a culture of transparency, honesty, and accountability.</li></ul><p></p><br/><br/>Please mention the word **DEFENDER** and tag RMTU5LjE5OC42Ni4xNjM= when applying to show you read the job post completely (#RMTU5LjE5OC42Ni4xNjM=). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', 'new', NULL, '2026-06-18 13:43:28.741', '2026-06-18 13:43:28.741', '', '', 'Remote', 'Europe', '', 'RemoteOK', 'API', 'READY', '', '', '', 'api', 'https://remoteOK.com/remote-jobs/remote-operations-support-manager-the-chartered-institute-for-securities-amp-investment-the-cisi-1133565', 'https://remoteOK.com/remote-jobs/remote-operations-support-manager-the-chartered-institute-for-securities-amp-investment-the-cisi-1133565', '[{\"url\":\"https://remoteOK.com/remote-jobs/remote-operations-support-manager-the-chartered-institute-for-securities-amp-investment-the-cisi-1133565\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1137, NULL, 'api', NULL, 'Head of Content', 'OnTheGoSystems', 'Lisboa, Lisboa, Lisboa, Portugal', 'https://remoteOK.com/remote-jobs/remote-head-of-content-onthegosystems-1133539', 'At OnTheGoSystems (creators of WPML and PTC), content is a key driver of how hundreds of thousands of people discover, understand, and choose to use our translation and localization products.<br><br>We\'re looking for a Head of Content who starts by doing the work - learning the product, writing, figuring out what actually moves the needle, and then builds from there.<br><br>We are especially interested in people who already think beyond traditional content marketing and understand how AI can support research, SEO/GEO monitoring, planning, drafting, publishing, and operational workflows - while still keeping strong human ownership and quality control.<br><br>You won\'t inherit a polished strategy or a big team to manage. You\'ll earn your influence by producing content that works. From there, you\'ll shape what we do, what we stop doing, and how content contributes to real business outcomes.<br><br>If you\'re used to owning results, not just producing content, this role is a great fit for you.<br><br><strong>What You\'ll Do<br><br></strong><ul><li>Write and edit high-quality content across formats: landing pages, product pages, articles, tutorials, and emails</li><li>Own content end-to-end: research, production, publishing, analysis, and iteration</li><li>Work closely with product, support, and development teams to turn customer problems into useful content</li><li>Use SEO, GEO, analytics, AI-search visibility, and customer feedback to guide decisions</li><li>Build AI-assisted workflows that improve speed and efficiency while maintaining quality</li><li>Review and validate AI-generated content for accuracy and reliability</li><li>Take ownership of content direction across the team based on real business goals<br><br></li></ul><strong>Requirements<br><br></strong><ul><li>Have worked in a 