INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1163, NULL, 'api', NULL, 'Blockchain Developer - Base', 'Spoon', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/spoon/blockchain-developer-base-berlin-449610', '<p>We are building a stealth-stage consumer platform that combines AI-powered data extraction, a token-based incentive layer, and on-chain data verification. The product is built around a mobile-optimised web application through which users contribute structured, verified real-world data and are rewarded with tokens.</p>\n<p>We have completed the proof-of-concept phase: a working barcode scanner, multi-image capture flow, AI extraction pipeline, and product database are all in production. The MVP phase adds the blockchain and token reward layer on top of this foundation. The engineer joining this role will not be rebuilding anything that already exists — the scope is additive.</p>\n<p>Full details of the product, market, and roadmap are shared under NDA during the interview process.</p>\n<h2>Tasks</h2>\n<p>We are looking for an experienced blockchain engineer to own the full blockchain integration scope of our MVP. This is a hands-on, individual contributor role with direct accountability to the founding team. The engagement runs for at least five months, with the possibility of a continued relationship depending on the outcome of the MVP phase. You will work closely with the full-stack developer who built our PoC on integration touchpoints, and you will have direct access to the project management team for architectural decisions.</p>\n<h2>Requirements</h2>\n<ul>\n<li>Smart contracts: design, write, and deploy an ERC-20 token contract on Base with minting restricted to the backend signing wallet.</li>\n<li>Batch jobs: implement a Batch Anchor Job (collect unanchored scans, compute hash, submit on-chain) and a Batch Token Distribution Job (multi-send accrued balances to all eligible wallets).</li>\n<li>Backend integration: extend the current schema with models for blockchain status, anchor batches, user wallets, and token rewards via a migration that does not disrupt the live extraction pipeline. Build blockchain status and balance API endpoints.</li>\n<li>Frontend wallet layer: integrate wagmi v2 + viem into the existing Next.js frontend. Implement wallet connect/disconnect, token balance display (accrued vs. distributed), and error handling for network mismatch, missing extension, and rejected connections. Scanning must remain functional without a connected wallet.</li>\n<li>Security: backend signing key in secrets manager, rate limiting on scan endpoints, no raw message signing from user wallets, and a documented key rotation runbook before mainnet.</li>\n<li>QA and load testing: extend the regression suite to cover batch flows and blockchain status transitions; run load tests at 500 and 1,000-product anchor batches.</li>\n</ul>\n<p>We are currently operating in stealth. Candidates advancing to interviews will be asked to sign a mutual NDA before full project details are disclosed. To apply, please send your CV and a short cover letter to info@appspoon(dot)io, or connect with Chuanshan Huang(<a href=\"https://www.linkedin.com/in/chuanshan-huang-617b23115/\">https://www.linkedin.com/in/chuanshan-huang-617b23115/</a>) on LinkedIn if you\'d like to chat informally first.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>We are building a stealth-stage consumer platform that combines AI-powered data extraction, a token-based incentive layer, and on-chain data verification. The product is built around a mobile-optimised web application through which users contribute structured, verified real-world data and are rewarded with tokens.</p>\n<p>We have completed the proof-of-concept phase: a working barcode scanner, multi-image capture flow, AI extraction pipeline, and product database are all in production. The MVP phase adds the blockchain and token reward layer on top of this foundation. The engineer joining this role will not be rebuilding anything that already exists — the scope is additive.</p>\n<p>Full details of the product, market, and roadmap are shared under NDA during the interview process.</p>\n<h2>Tasks</h2>\n<p>We are looking for an experienced blockchain engineer to own the full blockchain integration scope of our MVP. This is a hands-on, individual contributor role with direct accountability to the founding team. The engagement runs for at least five months, with the possibility of a continued relationship depending on the outcome of the MVP phase. You will work closely with the full-stack developer who built our PoC on integration touchpoints, and you will have direct access to the project management team for architectural decisions.</p>\n<h2>Requirements</h2>\n<ul>\n<li>Smart contracts: design, write, and deploy an ERC-20 token contract on Base with minting restricted to the backend signing wallet.</li>\n<li>Batch jobs: implement a Batch Anchor Job (collect unanchored scans, compute hash, submit on-chain) and a Batch Token Distribution Job (multi-send accrued balances to all eligible wallets).</li>\n<li>Backend integration: extend the current schema with models for blockchain status, anchor batches, user wallets, and token rewards via a migration that does not disrupt the live extraction pipeline. Build blockchain status and balance API endpoints.</li>\n<li>Frontend wallet layer: integrate wagmi v2 + viem into the existing Next.js frontend. Implement wallet connect/disconnect, token balance display (accrued vs. distributed), and error handling for network mismatch, missing extension, and rejected connections. Scanning must remain functional without a connected wallet.</li>\n<li>Security: backend signing key in secrets manager, rate limiting on scan endpoints, no raw message signing from user wallets, and a documented key rotation runbook before mainnet.</li>\n<li>QA and load testing: extend the regression suite to cover batch flows and blockchain status transitions; run load tests at 500 and 1,000-product anchor batches.</li>\n</ul>\n<p>We are currently operating in stealth. Candidates advancing to interviews will be asked to sign a mutual NDA before full project details are disclosed. To apply, please send your CV and a short cover letter to info@appspoon(dot)io, or connect with Chuanshan Huang(<a href=\"https://www.linkedin.com/in/chuanshan-huang-617b23115/\">https://www.linkedin.com/in/chuanshan-huang-617b23115/</a>) on LinkedIn if you\'d like to chat informally first.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-19 01:41:52.958', '2026-06-19 01:41:52.958', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/spoon/blockchain-developer-base-berlin-449610', 'https://www.arbeitnow.com/jobs/companies/spoon/blockchain-developer-base-berlin-449610', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/spoon/blockchain-developer-base-berlin-449610\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1164, NULL, 'api', NULL, 'Werkstudent Marketing-Kommunikation / Content-Management (m/w/d)', 'Labtagon GmbH', 'Mönchengladbach', 'https://www.arbeitnow.com/jobs/companies/labtagon-gmbh/werkstudent-marketing-kommunikation-content-management-monchengladbach-314970', '<p><strong>Marketing-Kommunikation und Contenterstellung im IT-Umfeld mitgestalten</strong></p>\n<p><strong>Standort:</strong> Mönchengladbach (HQ) / Mobile Office<br>\n<strong>Umfang:</strong> Werkstudententätigkeit (längerfristige Mitarbeit)<br>\n<strong>Arbeitszeit:</strong> Ca. 20 Stunden/Woche (Zeiten und Umfang individuell abstimmbar)</p>\n<p>Marketing in einem IT-Unternehmen ist eine besondere Herausforderung, allerdings nicht so trocken, wie man möglicherweise meint. Hinter den digitalen Lösungen der Labtagon stecken viel Strategie, Struktur und Technik, aber genauso viel Kommunikation, Kreativität und Teamarbeit. <strong>Damit unsere Botschaften ankommen, braucht es verständlichen, präzisen und zielgruppengerechten Content.</strong></p>\n<p><strong>Als Werkstudent (m/w/d) im Bereich Marketing-Kommunikation und Content-Management arbeitest du direkt im Herzen unserer Marketing-Abteilung.</strong> Du unterstützt unser Team langfristig dabei, unsere Kommunikationskanäle zu bespielen, die Redaktionsplanung aktiv mitzugestalten und kreativen Content von der ersten Idee bis zur Veröffentlichung zu entwickeln und zu optimieren.</p>\n<p>Dabei lernst du nicht nur <strong>strategisches B2B-Marketing</strong> kennen, sondern übernimmst Schritt für Schritt eigene Aufgaben im Content-Management und der Contenterstellung. Uns ist wichtig, dass wir uns persönlich kennenlernen. Deshalb gehört bei uns ein gemeinsamer Praxistag oder eine Probearbeit ganz selbstverständlich zum Bewerbungsprozess dazu.</p>\n<h2>Aufgaben</h2>\n<p><strong>Gestalte unsere Kommunikation aktiv mit</strong></p>\n<ul>\n<li><strong>Contenterstellung:</strong> Konzeption und Schreiben von Texten für unsere Website, den Blog, Social Media und Newsletter.</li>\n<li><strong>Redaktionsplanung:</strong> Unterstützung bei der Planung, Strukturierung und Pflege unseres redaktionellen Content-Kalenders.</li>\n<li><strong>Content-Management:</strong> Eigenständiges Einpflegen von Inhalten in unser Content-Management-System (CMS) und Betreuung der Social-Media-Kanäle.</li>\n<li><strong>Kampagnen &#x26; Konzepte:</strong> Mitarbeit an der Entwicklung von Kommunikationskonzepten, Zielgruppenansprachen und Präsentationen.</li>\n<li><strong>Kreativer Freiraum:</strong> Einbringen eigener Ideen zur Weiterentwicklung unserer Markenstimme und visuellen Content-Formate.</li>\n<li><strong>Erfolgsmessung:</strong> Unterstützung bei der Analyse von Content-Kennzahlen und Ableitung von Optimierungen.</li>\n<li><strong>Schnittstellenarbeit:</strong> Enge Zusammenarbeit mit dem internen Marketing-Team und Abstimmung zu Fachthemen.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Dein Profil: Spaß an Sprache, digitalem Content und Struktur</strong></p>\n<ul>\n<li><strong>Laufendes Studium:</strong> Wirtschaftswissenschaften, Marketing, Kommunikations-/Medienwissenschaften, Journalismus, Germanistik oder ein vergleichbarer Studiengang.</li>\n<li><strong>Langfristiges Interesse:</strong> Du suchst eine Werkstudententätigkeit, bei der du über mehrere Semester wachsen und theoretisches Wissen in die Praxis umsetzen kannst.</li>\n<li><strong>Sprachgefühl &#x26; Textstärke:</strong> Exzellente Ausdrucksweise in Deutsch, ein Blick für guten Content und die Fähigkeit, komplexe IT-Themen einfach zu erklären.</li>\n<li><strong>Strukturierte Arbeitsweise:</strong> Organisationstalent, um Redaktionsplanung und Termine zuverlässig im Blick zu behalten.</li>\n<li><strong>Erste Tools-Kenntnisse:</strong> Idealerweise erste Berührungspunkte mit CMS-Systemen (z. B. WordPress), Social-Media-Tools oder Design-Plattformen (z. B. Canva).</li>\n<li><strong>Eigeninitiative:</strong> Neugier, Motivation und Lust, dich aktiv mit eigenen Ideen in das Content-Management einzubringen.</li>\n<li><strong>Sprachkenntnisse:</strong> Sehr gute Deutsch- und gute Englischkenntnisse.</li>\n</ul>\n<p><em>Hinweis:</em> Wir erwarten keine perfekten \"Hardskills\" ab Tag eins. Wenn du allerdings ein passendes Hobby hast (z. B. einen eigenen Blog, einen aktiven Social-Media-Kanal oder kreative Schreibprojekte), lass es uns in deiner Bewerbung wissen!</p>\n<h2>Benefits</h2>\n<p><strong>Warum Werkstudent (m/w/d) bei Labtagon</strong></p>\n<p><strong>Praxiserfahrung, Verantwortung und persönliche Entwicklung</strong></p>\n<ul>\n<li><strong>Aktive Mitgestaltung:</strong> Mitarbeit in einem wachsenden IT-Unternehmen mit viel Vertrauen, kurzen Wegen und Aufgaben auf Augenhöhe.</li>\n<li><strong>Ganzheitlicher Einblick:</strong> Breites Spektrum von operativer Contenterstellung bis zu strategisch-konzeptionellen Marketingthemen.</li>\n<li><strong>Flexibilität:</strong> Arbeitszeiten mit ausreichend Flexibilität, damit sich Studium, Prüfungsphasen und Arbeit perfekt vereinbaren lassen.</li>\n<li><strong>Teamkultur:</strong> Ein Team, das sein Wissen gerne teilt, dich aktiv begleitet und Raum für deine persönliche Weiterentwicklung bietet.</li>\n<li><strong>Moderne Arbeitswelt:</strong> Zeitgemäße Arbeitsweisen, moderne Tools und die Möglichkeit zur flexiblen Arbeit im Mobile Office.</li>\n<li><strong>Zukunftsperspektive:</strong> Die Option, deine Bachelor- oder Masterarbeit bei uns zu schreiben und nach dem Studium fest bei Labtagon einzusteigen.</li>\n</ul>\n<p>Wir freuen uns über Deine Bewerbung!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Marketing-Kommunikation und Contenterstellung im IT-Umfeld mitgestalten</strong></p>\n<p><strong>Standort:</strong> Mönchengladbach (HQ) / Mobile Office<br>\n<strong>Umfang:</strong> Werkstudententätigkeit (längerfristige Mitarbeit)<br>\n<strong>Arbeitszeit:</strong> Ca. 20 Stunden/Woche (Zeiten und Umfang individuell abstimmbar)</p>\n<p>Marketing in einem IT-Unternehmen ist eine besondere Herausforderung, allerdings nicht so trocken, wie man möglicherweise meint. Hinter den digitalen Lösungen der Labtagon stecken viel Strategie, Struktur und Technik, aber genauso viel Kommunikation, Kreativität und Teamarbeit. <strong>Damit unsere Botschaften ankommen, braucht es verständlichen, präzisen und zielgruppengerechten Content.</strong></p>\n<p><strong>Als Werkstudent (m/w/d) im Bereich Marketing-Kommunikation und Content-Management arbeitest du direkt im Herzen unserer Marketing-Abteilung.</strong> Du unterstützt unser Team langfristig dabei, unsere Kommunikationskanäle zu bespielen, die Redaktionsplanung aktiv mitzugestalten und kreativen Content von der ersten Idee bis zur Veröffentlichung zu entwickeln und zu optimieren.</p>\n<p>Dabei lernst du nicht nur <strong>strategisches B2B-Marketing</strong> kennen, sondern übernimmst Schritt für Schritt eigene Aufgaben im Content-Management und der Contenterstellung. Uns ist wichtig, dass wir uns persönlich kennenlernen. Deshalb gehört bei uns ein gemeinsamer Praxistag oder eine Probearbeit ganz selbstverständlich zum Bewerbungsprozess dazu.</p>\n<h2>Aufgaben</h2>\n<p><strong>Gestalte unsere Kommunikation aktiv mit</strong></p>\n<ul>\n<li><strong>Contenterstellung:</strong> Konzeption und Schreiben von Texten für unsere Website, den Blog, Social Media und Newsletter.</li>\n<li><strong>Redaktionsplanung:</strong> Unterstützung bei der Planung, Strukturierung und Pflege unseres redaktionellen Content-Kalenders.</li>\n<li><strong>Content-Management:</strong> Eigenständiges Einpflegen von Inhalten in unser Content-Management-System (CMS) und Betreuung der Social-Media-Kanäle.</li>\n<li><strong>Kampagnen &#x26; Konzepte:</strong> Mitarbeit an der Entwicklung von Kommunikationskonzepten, Zielgruppenansprachen und Präsentationen.</li>\n<li><strong>Kreativer Freiraum:</strong> Einbringen eigener Ideen zur Weiterentwicklung unserer Markenstimme und visuellen Content-Formate.</li>\n<li><strong>Erfolgsmessung:</strong> Unterstützung bei der Analyse von Content-Kennzahlen und Ableitung von Optimierungen.</li>\n<li><strong>Schnittstellenarbeit:</strong> Enge Zusammenarbeit mit dem internen Marketing-Team und Abstimmung zu Fachthemen.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Dein Profil: Spaß an Sprache, digitalem Content und Struktur</strong></p>\n<ul>\n<li><strong>Laufendes Studium:</strong> Wirtschaftswissenschaften, Marketing, Kommunikations-/Medienwissenschaften, Journalismus, Germanistik oder ein vergleichbarer Studiengang.</li>\n<li><strong>Langfristiges Interesse:</strong> Du suchst eine Werkstudententätigkeit, bei der du über mehrere Semester wachsen und theoretisches Wissen in die Praxis umsetzen kannst.</li>\n<li><strong>Sprachgefühl &#x26; Textstärke:</strong> Exzellente Ausdrucksweise in Deutsch, ein Blick für guten Content und die Fähigkeit, komplexe IT-Themen einfach zu erklären.</li>\n<li><strong>Strukturierte Arbeitsweise:</strong> Organisationstalent, um Redaktionsplanung und Termine zuverlässig im Blick zu behalten.</li>\n<li><strong>Erste Tools-Kenntnisse:</strong> Idealerweise erste Berührungspunkte mit CMS-Systemen (z. B. WordPress), Social-Media-Tools oder Design-Plattformen (z. B. Canva).</li>\n<li><strong>Eigeninitiative:</strong> Neugier, Motivation und Lust, dich aktiv mit eigenen Ideen in das Content-Management einzubringen.</li>\n<li><strong>Sprachkenntnisse:</strong> Sehr gute Deutsch- und gute Englischkenntnisse.</li>\n</ul>\n<p><em>Hinweis:</em> Wir erwarten keine perfekten \"Hardskills\" ab Tag eins. Wenn du allerdings ein passendes Hobby hast (z. B. einen eigenen Blog, einen aktiven Social-Media-Kanal oder kreative Schreibprojekte), lass es uns in deiner Bewerbung wissen!</p>\n<h2>Benefits</h2>\n<p><strong>Warum Werkstudent (m/w/d) bei Labtagon</strong></p>\n<p><strong>Praxiserfahrung, Verantwortung und persönliche Entwicklung</strong></p>\n<ul>\n<li><strong>Aktive Mitgestaltung:</strong> Mitarbeit in einem wachsenden IT-Unternehmen mit viel Vertrauen, kurzen Wegen und Aufgaben auf Augenhöhe.</li>\n<li><strong>Ganzheitlicher Einblick:</strong> Breites Spektrum von operativer Contenterstellung bis zu strategisch-konzeptionellen Marketingthemen.</li>\n<li><strong>Flexibilität:</strong> Arbeitszeiten mit ausreichend Flexibilität, damit sich Studium, Prüfungsphasen und Arbeit perfekt vereinbaren lassen.</li>\n<li><strong>Teamkultur:</strong> Ein Team, das sein Wissen gerne teilt, dich aktiv begleitet und Raum für deine persönliche Weiterentwicklung bietet.</li>\n<li><strong>Moderne Arbeitswelt:</strong> Zeitgemäße Arbeitsweisen, moderne Tools und die Möglichkeit zur flexiblen Arbeit im Mobile Office.</li>\n<li><strong>Zukunftsperspektive:</strong> Die Option, deine Bachelor- oder Masterarbeit bei uns zu schreiben und nach dem Studium fest bei Labtagon einzusteigen.</li>\n</ul>\n<p>Wir freuen uns über Deine Bewerbung!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-19 01:42:00.617', '2026-06-19 01:42:00.617', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/labtagon-gmbh/werkstudent-marketing-kommunikation-content-management-monchengladbach-314970', 'https://www.arbeitnow.com/jobs/companies/labtagon-gmbh/werkstudent-marketing-kommunikation-content-management-monchengladbach-314970', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/labtagon-gmbh/werkstudent-marketing-kommunikation-content-management-monchengladbach-314970\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1165, NULL, 'api', NULL, 'Social Media Manager (m/w/d) Vollzeit', 'B:O:S Engergieberatung', 'Augsburg', 'https://www.arbeitnow.com/jobs/companies/bos-engergieberatung/social-media-manager-vollzeit-augsburg-304629', '<p>Werde Teil von BOS Energieberatung</p>\n<p>Die BOS Energieberatung ist ein wachsendes Unternehmen im Bereich erneuerbare Energien. Wir beraten Hausbesitzer und Unternehmen rund um <strong>Photovoltaikanlagen, Wärmepumpen und staatliche Förderungen</strong>.</p>\n<p>Um unsere Marke weiter auszubauen, suchen wir zum nächstmöglichen Zeitpunkt einen <strong>Social Media Manager (m/w/d) in Vollzeit</strong>, der unsere Projekte, Kunden und Erfolge kreativ auf TikTok, Instagram, YouTube und weiteren Plattformen präsentiert.</p>\n<h2>Aufgaben</h2>\n<p>Deine Aufgaben</p>\n<ul>\n<li></li>\n</ul>\n<p>Planung, Erstellung und Veröffentlichung von Content für TikTok, Instagram, YouTube, Facebook und LinkedIn</p>\n<ul>\n<li></li>\n</ul>\n<p>Entwicklung kreativer Content-Strategien und neuer Ideen</p>\n<ul>\n<li></li>\n</ul>\n<p>Erstellung von Reels, Shorts und TikToks</p>\n<ul>\n<li></li>\n</ul>\n<p>Begleitung von Photovoltaik- und Wärmepumpenprojekten vor Ort</p>\n<ul>\n<li></li>\n</ul>\n<p>Filmen von Baustellen, Kundenstimmen, Team-Events und Unternehmensalltag</p>\n<ul>\n<li></li>\n</ul>\n<p>Videoschnitt und Nachbearbeitung von Bild- und Videomaterial</p>\n<ul>\n<li></li>\n</ul>\n<p>Community Management und Interaktion mit Followern</p>\n<ul>\n<li></li>\n</ul>\n<p>Analyse und Optimierung von Reichweiten, Engagement und Kampagnen</p>\n<ul>\n<li></li>\n</ul>\n<p>Aufbau und Stärkung unserer Arbeitgebermarke</p>\n<ul>\n<li></li>\n</ul>\n<p>Zusammenarbeit mit Vertrieb und Geschäftsführung</p>\n<h2>Qualifikation</h2>\n<p>Das bringst du mit</p>\n<ul>\n<li></li>\n</ul>\n<p>Erfahrung im Bereich Social Media Marketing oder Content Creation</p>\n<ul>\n<li></li>\n</ul>\n<p>Sicherer Umgang mit TikTok, Instagram und YouTube</p>\n<ul>\n<li></li>\n</ul>\n<p>Kenntnisse in CapCut, Adobe Premiere Pro, Canva oder vergleichbaren Programmen</p>\n<ul>\n<li></li>\n</ul>\n<p>Kreativität, Eigeninitiative und Gespür für aktuelle Trends</p>\n<ul>\n<li></li>\n</ul>\n<p>Gute Kommunikationsfähigkeiten</p>\n<ul>\n<li></li>\n</ul>\n<p>Führerschein Klasse B</p>\n<ul>\n<li></li>\n</ul>\n<p>Sehr gute Deutschkenntnisse in Wort und Schrift</p>\n<h2>Benefits</h2>\n<p>Das bieten wir</p>\n<ul>\n<li></li>\n</ul>\n<p>Unbefristete Festanstellung in Vollzeit</p>\n<ul>\n<li></li>\n</ul>\n<p>Attraktive Vergütung, 2.700 € bis 4.500 € brutto pro Monat</p>\n<ul>\n<li></li>\n</ul>\n<p>Viel Gestaltungsfreiheit und eigene Verantwortung</p>\n<ul>\n<li></li>\n</ul>\n<p>Kurze Entscheidungswege</p>\n<ul>\n<li></li>\n</ul>\n<p>Ein motiviertes Team in einem stark wachsenden Zukunftsmarkt</p>\n<p>Arbeitsort</p>\n<p>BOS Energieberatung GmbH</p>\n<p><strong>Arbeitsmodell:</strong> Hybrid (Büro &#x26; Homeoffice)</p>\n<p>Je nach Aufgabenbereich und Abstimmung im Team ist eine Kombination aus Präsenzarbeit und Homeoffice möglich. Für Content-Aufnahmen bei Kunden, Baustellen und Firmenevents ist eine regelmäßige Anwesenheit vor Ort erforderlich.</p>\n<p>Bewerbung</p>\n<p>Bitte sende uns deinen Lebenslauf sowie – falls vorhanden – Referenzen, Social-Media-Profile, Arbeitsproben oder ein Portfolio deiner bisherigen Projekte an:</p>\n<p><a ----- ----------\n<p>Wir freuen uns auf kreative Köpfe, die gemeinsam mit uns die Themen Photovoltaik, Wärmepumpen und erneuerbare Energien auf Social Media sichtbar machen.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Werde Teil von BOS Energieberatung</p>\n<p>Die BOS Energieberatung ist ein wachsendes Unternehmen im Bereich erneuerbare Energien. Wir beraten Hausbesitzer und Unternehmen rund um <strong>Photovoltaikanlagen, Wärmepumpen und staatliche Förderungen</strong>.</p>\n<p>Um unsere Marke weiter auszubauen, suchen wir zum nächstmöglichen Zeitpunkt einen <