INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1168, NULL, 'api', NULL, 'People & Office Manager (m/w/d)', 'Ordio GmbH', 'Cologne', 'https://www.arbeitnow.com/jobs/companies/ordio-gmbh/people-office-manager-cologne-388758', '<p>Weltweit arbeiten 80% aller Beschäftigten nicht am Schreibtisch – aber fast die gesamte Software ist für Schreibtisch-Nutzer:innen gebaut 🤯 Mit Ordio 💙 ändern wir das: eine „all in one\"-Plattform, die genau diese Menschen in den Fokus stellt und ihren Arbeitsalltag organisiert – von der Schichtplanung über die Zeiterfassung bis hin zu Payroll. 2026 haben wir eine Series-A-Finanzierung über 12 Mio. € erhalten und wachsen Markt für Markt über Deutschland hinaus 🚀</p>\n<p>Damit unser Team dabei den Rücken frei hat, suchen wir dich als <strong>Team Assistant &#x26; People Operations (m/w/d)</strong> in Teilzeit (ca. 20 Std./Woche). Du bist die gute Seele im Hintergrund: Du hältst unsere People- und HR-Prozesse am Laufen, sorgst dafür, dass neue Mitarbeitende einen reibungslosen Start haben, kümmerst dich um unser Office im WeWork in Köln und bist die erste Ansprechperson für organisatorische Themen aus dem Team. Eine vielseitige Rolle für jemanden, der gerne organisiert, mitdenkt und Dinge einfach erledigt – mit viel Eigenverantwortung von Tag Eins an.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>📄 <strong>HR &#x26; Verträge.</strong> Du erstellst und verwaltest Arbeitsverträge und unterstützt bei administrativen HR-Themen.</li>\n<li>🤝 <strong>On- &#x26; Offboarding.</strong> Du organisierst einen reibungslosen Start für neue Teammitglieder in Köln oder Remote und einen sauberen Abschied, wenn jemand geht.</li>\n<li>💻 <strong>Tech-Organisation.</strong> Du kümmerst dich um die Ausstattung des Teams: MacBooks und Equipment bestellen, vorbereiten und versenden.</li>\n<li>🎉 <strong>Team-Events.</strong> Du planst und organisierst unsere regelmäßigen Team-Events, die das Team zusammenbringen.</li>\n<li>🧾 <strong>People Operations.</strong> Du bist die erste Ansprechperson für organisatorische Anliegen aus dem Team – zum Beispiel Fragen zu Tools oder Reisekostenabrechnungen.</li>\n<li>🗂️ <strong>Assistenz &#x26; Administration.</strong> Du übernimmst vielfältige administrative und organisatorische Assistenztätigkeiten und behältst dabei den Überblick.</li>\n<li>📮 <strong>Office Management.</strong> Du sorgst für die Organisation unseres WeWork-Office in Köln – von der allgemeinen Büroorganisation über die Postbearbeitung bis zum Paketversand</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>✅ Erste Erfahrung in einer ähnlichen Rolle – ob People Operations, HR, Office Management oder Team-Assistenz.</li>\n<li>🧭 Organisationstalent: Du arbeitest strukturiert, zuverlässig und behältst auch bei vielen parallelen Themen den Überblick.</li>\n<li>💪 Hands-on-Mentalität: Du packst eigenständig an, denkst mit und wartest nicht auf detaillierte Anweisungen.</li>\n<li>😊 Kommunikationsstärke und eine freundliche, serviceorientierte Art – du bist gern Ansprechperson fürs Team.</li>\n<li>🤐 Diskretion und Sorgfalt im Umgang mit vertraulichen Informationen (Verträge, Personaldaten).</li>\n<li>🇩🇪 🇬🇧 Sehr gute Deutsch- und gute Englisch-Kenntnisse.</li>\n<li>🤖 Du hast ein Auge dafür, wiederkehrende Aufgaben zu automatisieren, und arbeitest mit Begeisterung mit KI-Tools, um Prozesse effizienter zu machen</li>\n<li>📍 Du bist in oder rund um Köln und kannst regelmäßig vor Ort im Office sein.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>🚀 Von Anfang an dabei sein und Ordio 💙 als eines der am schnellsten wachsenden Startups in unserem Feld mitskalieren</li>\n<li>💡 Mitwirken an innovativen Lösungen und Produkten</li>\n<li>😌 Eine offene und erfolgreiche Unternehmenskultur mitgestalten</li>\n<li>🤩 Junges &#x26; motiviertes Team</li>\n<li>🏝️ Maximale Flexibilität – Home-Office-Antei und flexible Arbeitszeiten</li>\n<li>🌃 Modernes Büro im Herzen von Köln</li>\n<li>📱 Modernste technische Ausstattung</li>\n<li>🥳 Coole Teamevents</li>\n<li>🐶 Hund am Arbeitsplatz erwünscht</li>\n<li>🏋️ Urban Sports Club Mitgliedschaft</li>\n<li>🚲 Jobrad</li>\n</ul>\n<p>Wir bei <strong>Ordio</strong> 💙 suchen Menschen, die mehr sein wollen als nur ein weiterer Mitarbeiter: ehrgeizige, vorausschauende Denker, bereit, unser junges Start-up zu formen und wachsen zu lassen 🚀</p>\n<p><strong>Ordio</strong> 💙 ist eine webbasierte HR-Software, die es ermöglicht Mitarbeiter, die nicht an einem Schreibtisch arbeiten, zentral zu managen - von der Anmeldung bis zur Schichtplanung, Zeiterfassung und Dokumentenmanagement oder Abwesenheitsmanagement 🧑‍💻</p>\n<p>Wir glauben, dass wir die Probleme der Welt gemeinsam besser lösen können, wenn wir die Menschen mit den besten Tools ausstatten, um ihre eigenen Probleme zu lösen. Wir sind immer auf der Suche nach talentierten Menschen, die daran interessiert sind, die Zukunft gemeinsam zu gestalten - gestalte sie mit uns 💙</p>\n<p>Klingt das nach einer spannenden Herausforderung für Dich?</p>\n<p>Dann schreib uns einfach.</p>\n<p>Wir freuen uns auf Dich! 😌</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Weltweit arbeiten 80% aller Beschäftigten nicht am Schreibtisch – aber fast die gesamte Software ist für Schreibtisch-Nutzer:innen gebaut 🤯 Mit Ordio 💙 ändern wir das: eine „all in one\"-Plattform, die genau diese Menschen in den Fokus stellt und ihren Arbeitsalltag organisiert – von der Schichtplanung über die Zeiterfassung bis hin zu Payroll. 2026 haben wir eine Series-A-Finanzierung über 12 Mio. € erhalten und wachsen Markt für Markt über Deutschland hinaus 🚀</p>\n<p>Damit unser Team dabei den Rücken frei hat, suchen wir dich als <strong>Team Assistant &#x26; People Operations (m/w/d)</strong> in Teilzeit (ca. 20 Std./Woche). Du bist die gute Seele im Hintergrund: Du hältst unsere People- und HR-Prozesse am Laufen, sorgst dafür, dass neue Mitarbeitende einen reibungslosen Start haben, kümmerst dich um unser Office im WeWork in Köln und bist die erste Ansprechperson für organisatorische Themen aus dem Team. Eine vielseitige Rolle für jemanden, der gerne organisiert, mitdenkt und Dinge einfach erledigt – mit viel Eigenverantwortung von Tag Eins an.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>📄 <strong>HR &#x26; Verträge.</strong> Du erstellst und verwaltest Arbeitsverträge und unterstützt bei administrativen HR-Themen.</li>\n<li>🤝 <strong>On- &#x26; Offboarding.</strong> Du organisierst einen reibungslosen Start für neue Teammitglieder in Köln oder Remote und einen sauberen Abschied, wenn jemand geht.</li>\n<li>💻 <strong>Tech-Organisation.</strong> Du kümmerst dich um die Ausstattung des Teams: MacBooks und Equipment bestellen, vorbereiten und versenden.</li>\n<li>🎉 <strong>Team-Events.</strong> Du planst und organisierst unsere regelmäßigen Team-Events, die das Team zusammenbringen.</li>\n<li>🧾 <strong>People Operations.</strong> Du bist die erste Ansprechperson für organisatorische Anliegen aus dem Team – zum Beispiel Fragen zu Tools oder Reisekostenabrechnungen.</li>\n<li>🗂️ <strong>Assistenz &#x26; Administration.</strong> Du übernimmst vielfältige administrative und organisatorische Assistenztätigkeiten und behältst dabei den Überblick.</li>\n<li>📮 <strong>Office Management.</strong> Du sorgst für die Organisation unseres WeWork-Office in Köln – von der allgemeinen Büroorganisation über die Postbearbeitung bis zum Paketversand</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>✅ Erste Erfahrung in einer ähnlichen Rolle – ob People Operations, HR, Office Management oder Team-Assistenz.</li>\n<li>🧭 Organisationstalent: Du arbeitest strukturiert, zuverlässig und behältst auch bei vielen parallelen Themen den Überblick.</li>\n<li>💪 Hands-on-Mentalität: Du packst eigenständig an, denkst mit und wartest nicht auf detaillierte Anweisungen.</li>\n<li>😊 Kommunikationsstärke und eine freundliche, serviceorientierte Art – du bist gern Ansprechperson fürs Team.</li>\n<li>🤐 Diskretion und Sorgfalt im Umgang mit vertraulichen Informationen (Verträge, Personaldaten).</li>\n<li>🇩🇪 🇬🇧 Sehr gute