INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1265, NULL, 'api', NULL, 'Head of Creative Campaigns (m/f/d - Remote)', 'Weflow', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/weflow/head-of-creative-campaigns-remote-berlin-245358', '<p>Weflow\'s Revenue AI Platform automates Salesforce data capture and provides full visibility into deal, pipeline, and forecast health.</p>\n<p>200+ fast-growing companies like Retool, Abridge, and IDnow use Weflow to improve team productivity, sales performance, and revenue predictability.</p>\n<p>Weflow is backed by Gradient Ventures, Cherry Ventures, and renowned angel investors – and run by repeat founders Philipp Stelzer and Janis Zech.</p>\n<h2>Tasks</h2>\n<p>As our Head of Creative Campaigns, you\'ll be the person who puts Weflow on the map - through creative campaigns, events, and activations that make revenue teams stop scrolling and start paying attention.</p>\n<p>You\'ll own the full campaign lifecycle: from the initial idea to the moment it lands in front of an audience. That means conceiving the concept, producing the assets, coordinating the moving parts, and driving distribution - all the way through to measuring what worked.</p>\n<p>You\'ll work directly with the GTM team and have real creative latitude to experiment with formats and channels others in B2B haven\'t touched yet.</p>\n<p>But you\'re not starting from zero. Weflow already has an engaged audience, an active community, a podcast, and a steady drumbeat of LinkedIn thought leadership content.</p>\n<p>Your job is to take that foundation and turn it into campaigns that create buzz - the kind that generate pipeline and word-of-mouth at the same time.</p>\n<p>This role suits someone who\'s produced standout events, run bold campaigns, or created moments that generated genuine word-of-mouth. B2C background? Even better - we want someone who knows what it feels like to build something people actually talk about.</p>\n<p>What You\'ll Do</p>\n<ul>\n<li>Develop and execute creative campaign concepts across events, content, social, partnerships, and formats we haven\'t tried yet</li>\n<li>Plan and run events of all shapes and sizes - intimate executive roundtables, community meetups, virtual summits - with an eye on both experience and pipeline impact</li>\n<li>Take campaigns from zero to live: brief, produce, coordinate, distribute, and report</li>\n<li>Find and pursue distribution opportunities others overlook - communities, partnerships, media, influencers, co-marketing</li>\n<li>Collaborate with the founding team to turn product news and market moments into compelling campaign hooks</li>\n<li>Build repeatable playbooks from what works so successful campaigns can scale</li>\n</ul>\n<h2>Requirements</h2>\n<p>Who We\'re Looking For:</p>\n<ul>\n<li>Proven track record producing campaigns or events that created real buzz - scale matters less than impact</li>\n<li>Strong creative instincts paired with the operational discipline to actually ship things</li>\n<li>You move fast and figure things out: no playbook, no problem</li>\n<li>Comfortable writing - briefs, copy, recaps - and working with designers to bring creative concepts to life</li>\n<li>Experience in B2B SaaS is not necessary, we care more about your creative track record than your industry background</li>\n<li>Fluent in English</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Remote-first company setup</li>\n<li>Regular in-person meetups</li>\n<li>Top-of-the-line equipment</li>\n<li>Experienced, distributed, and diverse team</li>\n<li>Competitive package including stock options</li>\n</ul>\n<p>We look forward to hearing from you!</p>\n<p>We value the diversity of perspective and seek to build an inclusive workplace that welcomes people from all different backgrounds.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Weflow\'s Revenue AI Platform automates Salesforce data capture and provides full visibility into deal, pipeline, and forecast health.</p>\n<p>200+ fast-growing companies like Retool, Abridge, and IDnow use Weflow to improve team productivity, sales performance, and revenue predictability.</p>\n<p>Weflow is backed by Gradient Ventures, Cherry Ventures, and renowned angel investors – and run by repeat founders Philipp Stelzer and Janis Zech.</p>\n<h2>Tasks</h2>\n<p>As our Head of Creative Campaigns, you\'ll be the person who puts Weflow on the map - through creative campaigns, events, and activations that make revenue teams stop scrolling and start paying attention.</p>\n<p>You\'ll own the full campaign lifecycle: from the initial idea to the moment it lands in front of an audience. That means conceiving the concept, producing the assets, coordinating the moving parts, and driving distribution - all the way through to measuring what worked.</p>\n<p>You\'ll work directly with the GTM team and have real creative latitude to experiment with formats and channels others in B2B haven\'t touched yet.</p>\n<p>But you\'re not starting from zero. Weflow already has an engaged audience, an active community, a podcast, and a steady drumbeat of LinkedIn thought leadership content.</p>\n<p>Your job is to take that foundation and turn it into campaigns that create buzz - the kind that generate pipeline and word-of-mouth at the same time.</p>\n<p>This role suits someone who\'s produced standout events, run bold campaigns, or created moments that generated genuine word-of-mouth. B2C background? Even better - we want someone who knows what it feels like to build something people actually talk about.</p>\n<p>What You\'ll Do</p>\n<ul>\n<li>Develop and execute creative campaign concepts across events, content, social, partnerships, and formats we haven\'t tried yet</li>\n<li>Plan and run events of all shapes and sizes - intimate executive roundtables, community meetups, virtual summits - with an eye on both experience and pipeline impact</li>\n<li>Take campaigns from zero to live: brief, produce, coordinate, distribute, and report</li>\n<li>Find and pursue distribution opportunities others overlook - communities, partnerships, media, influencers, co-marketing</li>\n<li>Collaborate with the founding team to turn product news and market moments into compelling campaign hooks</li>\n<li>Build repeatable playbooks from what works so successful campaigns can scale</li>\n</ul>\n<h2>Requirements</h2>\n<p>Who We\'re Looking For:</p>\n<ul>\n<li>Proven track record producing campaigns or events that created real buzz - scale matters less than impact</li>\n<li>Strong creative instincts paired with the operational discipline to actually ship things</li>\n<li>You move fast and figure things out: no playbook, no problem</li>\n<li>Comfortable writing - briefs, copy, recaps - and working with designers to bring creative concepts to life</li>\n<li>Experience in B2B SaaS is not necessary, we care more about your creative track record than your industry background</li>\n<li>Fluent in English</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Remote-first company setup</li>\n<li>Regular in-person meetups</li>\n<li>Top-of-the-line equipment</li>\n<li>Experienced, distributed, and diverse team</li>\n<li>Competitive package including stock options</li>\n</ul>\n<p>We look forward to hearing from you!</p>\n<p>We value the diversity of perspective and seek to build an inclusive workplace that welcomes people from all different backgrounds.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-20 13:39:52.522', '2026-06-20 13:39:52.522', '', '', 'Remote', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/weflow/head-of-creative-campaigns-remote-berlin-245358', 'https://www.arbeitnow.com/jobs/companies/weflow/head-of-creative-campaigns-remote-berlin-245358', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/weflow/head-of-creative-campaigns-remote-berlin-245358\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1266, NULL, 'api', NULL, 'Werkstudent (m/w/d) Power BI & Power Apps', 'S01 Projektmanagement GmbH', 'Eschborn', 'https://www.arbeitnow.com/jobs/companies/s01-projektmanagement-gmbh/werkstudent-power-bi-power-apps-eschborn-10783', '<p>Die S01 Projektmanagement GmbH (ausgesprochen <em>Es Null Eins Projektmanagement</em>) ist ein modernes, wachstumsorientiertes Projektmanagement- und Consultingunternehmen mit Fokus auf Energieinfrastrukturprojekte.</p>\n<p>Wir suchen Persönlichkeiten, die Energie spürbar machen wollen – durch Denken in Lösungen, Leidenschaft für Fortschritt und den Mut, Verantwortung zu übernehmen.</p>\n<p>Für ein zeitlich befristetes Projekt suchen wir eine engagierte Unterstützung im Bereich Reporting, Digitalisierung und Automatisierung. Du unterstützt bei der Prozess- und Datenautomatisierung rund um SharePoint, Power Apps/Power Automate und Excel.</p>\n<p>Wir freuen uns besonders über Kandidat:innen mit <strong>Entrepreneur-Mentality</strong>, die über ihre Aufgaben hinausdenken und aktiv beim Aufbau sowie bei der Weiterentwicklung unserer Prozesse und Lösungen mitwirken möchten.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Erstellung von Power Apps Anwendungen zur Unterstützung operativer Projektprozesse</li>\n<li>Automatisierung von Workflows mit Power Automate</li>\n<li>Datenmodellierung und -aufbereitung (z. B. aus Excel und Projektmanagement-Tools)</li>\n<li>Unterstützung beim Aufbau eines integrierten Projektcontrolling-Systems</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erste Erfahrung mit Power BI, Power Apps oder vergleichbaren Tools</li>\n<li>Grundkenntnisse in Datenanalyse, Datenmodellierung und Reporting</li>\n<li>Starkes Interesse an Microsoft-Technologien und der Motivation, dich gezielt in Richtung Microsoft-Experte (z. B. im Power Platform Umfeld) weiterzuentwickeln</li>\n<li>Strukturierte und analytische Denkweise</li>\n<li>Selbstständige Arbeitsweise und hohe Lernbereitschaft</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Direkte Mitarbeit an praxisrelevanten Projekten – keine Übungsaufgaben, sondern echter Einsatz in laufenden Projekten</li>\n<li>Flexible Arbeitszeiten und Möglichkeit zu Remote Work</li>\n<li>Aufbau von praxisnahen Skills in Power BI, Power Apps und Projektmanagement im Strommarkt</li>\n</ul>\n<p>Gestalte unser Wachstum aktiv mit – wir bieten dir Raum für Ideen, Eigeninitiative und die Chance, neue Geschäftsfelder zu entwickeln und dich in Richtung Project Management, Product Management oder Business Development zu entfalten.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Die S01 Projektmanagement GmbH (ausgesprochen <em>Es Null Eins Projektmanagement</em>) ist ein modernes, wachstumsorientiertes Projektmanagement- und Consultingunternehmen mit Fokus auf Energieinfrastrukturprojekte.</p>\n<p>Wir suchen Persönlichkeiten, die Energie spürbar machen wollen – durch Denken in Lösungen, Leidenschaft für Fortschritt und den Mut, Verantwortung zu übernehmen.</p>\n<p>Für ein zeitlich befristetes Projekt suchen wir eine engagierte Unterstützung im Bereich Reporting, Digitalisierung und Automatisierung. Du unterstützt bei der Prozess- und Datenautomatisierung rund um SharePoint, Power Apps/Power Automate und Excel.</p>\n<p>Wir freuen uns besonders über Kandidat:innen mit <strong>Entrepreneur-Mentality</strong>, die über ihre Aufgaben hinausdenken und aktiv beim Aufbau sowie bei der Weiterentwicklung unserer Prozesse und Lösungen mitwirken möchten.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Erstellung von Power Apps Anwendungen zur Unterstützung operativer Projektprozesse</li>\n<li>Automatisierung von Workflows mit Power Automate</li>\n<li>Datenmodellierung und -aufbereitung (z. B. aus Excel und Projektmanagement-Tools)</li>\n<li>Unterstützung beim Aufbau eines integrierten Projektcontrolling-Systems</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erste Erfahrung mit Power BI, Power Apps oder vergleichbaren Tools</li>\n<li>Grundkenntnisse in Datenanalyse, Datenmodellierung und Reporting</li>\n<li>Starkes Interesse an Microsoft-Technologien und der Motivation, dich gezielt in Richtung Microsoft-Experte (z. B. im Power Platform Umfeld) weiterzuentwickeln</li>\n<li>Strukturierte und analytische Denkweise</li>\n<li>Selbstständige Arbeitsweise und hohe Lernbereitschaft</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Direkte Mitarbeit an praxisrelevanten Projekten – keine Übungsaufgaben, sondern echter Einsatz in laufenden Projekten</li>\n<li>Flexible Arbeitszeiten und Möglichkeit zu Remote Work</li>\n<li>Aufbau von praxisnahen Skills in Power BI, Power Apps und Projektmanagement im Strommarkt</li>\n</ul>\n<p>Gestalte unser Wachstum aktiv mit – wir bieten dir Raum für Ideen, Eigeninitiative und die Chance, neue Geschäftsfelder zu entwickeln und dich in Richtung Project Management, Product Management oder Business Development zu entfalten.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-20 13:40:00.127', '2026-06-20 13:40:00.127', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/s01-projektmanagement-gmbh/werkstudent-power-bi-power-apps-eschborn-10783', 'https://www.arbeitnow.com/jobs/companies/s01-projektmanagement-gmbh/werkstudent-power-bi-power-apps-eschborn-10783', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/s01-projektmanagement-gmbh/werkstudent-power-bi-power-apps-eschborn-10783\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1267, NULL, 'api', NULL, 'Praktikant (m/w/d) im Office der Geschäftsführung', 'CERTA', 'Cologne', 'https://www.arbeitnow.com/jobs/companies/certa/praktikant-im-office-der-geschaftsfuhrung-cologne-494403', '<h2>Ihre Aufgaben</h2>\n<p><strong>Eigenes Projekt von Tag 1:</strong> Du bekommst direkt Verantwortung für ein abgegrenztes Vorhaben, z. B. die Einführung eines neuen Tools, eine Marktanalyse für eine neue Region oder ein internes Automatisierungsprojekt.</p>\n<p><strong>Strategische Mitarbeit:</strong> Du unterstützt die Geschäftsführung bei Quartals-Reviews, OKR-Planungen und der Vorbereitung von Investorengesprächen.</p>\n<p><strong>KI in der Praxis anwenden:</strong> Du nutzt moderne KI-Tools nicht nur, um schneller zu arbeiten, sondern um neue Lösungen für unsere Kunden und unsere internen Prozesse zu bauen.</p>\n<p><strong>Operative Exzellenz:</strong> Du analysierst Prozesse, identifizierst Engpässe und treibst konkrete Verbesserungen voran, gemeinsam mit den Bereichsleitern.</p>\n<p><strong>End-to-End-Verantwortung:</strong> Du strukturierst Fragestellungen, setzt um und verantwortest den Erfolg Deines Projekts, inklusive harter Zahlen.</p>\n<h2>Ihr Profil</h2>\n<p>Du studierst im Bachelor oder Master oder befindest Dich in der Übergangsphase zwischen beiden Abschlüssen.</p>\n<p>Du bringst sehr gute Studienleistungen mit und idealerweise erste Erfahrung aus Praktika in Beratung, Investmentbanking, Private Equity oder Start-ups.</p>\n<p><strong>Echte Begeisterung für KI und Technologie:</strong> Du arbeitest selbstverständlich mit Tools wie ChatGPT, Claude, Cursor &#x26; Co., probierst Neues aus und schreckst nicht zurück, wenn ein Projekt technisches Neuland ist. Du musst kein Entwickler sein, aber Du solltest verstehen wollen, was unter der Haube passiert.</p>\n<p><strong>Keine Angst vor technischen Herausforderungen:</strong> Wenn ein Workflow automatisiert werden muss oder eine Datenanalyse ansteht, legst Du los und holst Dir die Hilfe, die Du brauchst.</p>\n<p>Ausgeprägtes analytisches Denkvermögen, Hands-on-Mentalität und unternehmerisches Gespür.</p>\n<p>Hohes Maß an Eigenverantwortung, Umsetzungsstärke und Ergebnisorientierung.</p>\n<p>Verhandlungssichere Deutschkenntnisse in Wort und Schrift.</p>\n<h2>Warum wir?</h2>\n<p>Unser Ziel: ein faires, datengetriebenes Wertgutachten für jede Immobilie in Deutschland. Bei Certa ersetzen wir das klassische Sachverständigenwesen durch eine KI-gestützte Bewertungsplattform, die schneller, präziser und transparenter ist als alles, was der Markt heute kennt.</p>\n<p>Suchst Du ein Praktikum, in dem Du in drei bis sechs Monaten mehr lernst als manche in zwei Jahren Konzern? Bei uns bist Du Teil der Geschäftsführungs-Crew und verantwortest reale Projekte mit messbarem Impact.</p>\n<p>Das Office der Geschäftsführung arbeitet direkt mit den beiden Gründern und Geschäftsführern (Alexander Rausch &#x26; Matthias Mertens) an den Top-Themen, die Certa als Unternehmen entscheidend voranbringen. Vom OKR-Framework über Marktexpansion und Operational Excellence bis zum Aufbau skalierbarer Backoffice-Strukturen. Trotz der Nähe zur Geschäftsführung leben wir eine entrepreneuriale, pragmatische Arbeitskultur: kurze Wege, schnelle Entscheidungen, hohe Umsetzungstiefe.</p>\n<p><strong>Echter Gestaltungsspielraum:</strong> Certa ist kein Konzern-Praktikum. Was Du baust, geht live, und Du siehst die Wirkung in Umsatz, Prozessen und Team.</p>\n<p><strong>Direkte Linie zu den Gründern:</strong> Du arbeitest täglich mit den beiden Gründern und Geschäftsführern. Keine Layer, keine Politik, keine Slide-Schlachten.</p>\n<p><strong>Spielwiese für KI-Enthusiasten:</strong> Bei uns ist KI kein Buzzword, sondern Arbeitsalltag. Du bekommst Zugang zu allen relevanten Tools und Modellen.</p>\n<p><strong>Lernkurve wie in keiner Beratung:</strong> Du erlebst, wie Strategie, Tech, Vertrieb und Operations wirklich zusammenspielen.</p>\n<p><strong>Überdurchschnittliche Vergütung:</strong> Wir glauben nicht an unbezahlte Lernerfahrungen. Praktika werden bei uns fair vergütet.</p>\n<p><strong>Übernahmeperspektive:</strong> Bei Erfolg gibt es ein klares Angebot, ob als Werkstudent während des weiteren Studiums oder als Festangestellter nach dem Abschluss.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<h2>Ihre Aufgaben</h2>\n<p><strong>Eigenes Projekt von Tag 1:</strong> Du bekommst direkt Verantwortung für ein abgegrenztes Vorhaben, z. B. die Einführung eines neuen Tools, eine Marktanalyse für eine neue Region oder ein internes Automatisierungsprojekt.</p>\n<p><strong>Strategische Mitarbeit:</strong> Du unterstützt die Geschäftsführung bei Quartals-Reviews, OKR-Planungen und der Vorbereitung von Investorengesprächen.</p>\n<p><strong>KI in der Praxis anwenden:</strong> Du nutzt moderne KI-Tools nicht nur, um schneller zu arbeiten, sondern um neue Lösungen für unsere Kunden und unsere internen Prozesse zu bauen.</p>\n<p><strong>Operative Exzellenz:</strong> Du analysierst Prozesse, identifizierst Engpässe und treibst konkrete Verbesserungen voran, gemeinsam mit den Bereichsleitern.</p>\n<p><strong>End-to-End-Verantwortung:</strong> Du strukturierst Fragestellungen, setzt um und verantwortest den Erfolg Deines Projekts, inklusive harter Zahlen.</p>\n<h2>Ihr Profil</h2>\n<p>Du studierst im Bachelor oder Master oder befindest Dich in der Übergangsphase zwischen beiden Abschlüssen.</p>\n<p>Du bringst sehr gute Studienleistungen mit und idealerweise erste Erfahrung aus Praktika in Beratung, Investmentbanking, Private Equity oder Start-ups.</p>\n<p><strong>Echte Begeisterung für KI und Technologie:</strong> Du arbeitest selbstverständlich mit Tools wie ChatGPT, Claude, Cursor &#x26; Co., probierst Neues aus und schreckst nicht zurück, wenn ein Projekt technisches Neuland ist. Du musst kein Entwickler sein, aber Du solltest verstehen wollen, was unter der Haube passiert.</p>\n<p><strong>Keine Angst vor technischen Herausforderungen:</strong> Wenn ein Workflow automatisiert werden muss oder eine Datenanalyse ansteht, legst Du los und holst Dir die Hilfe, die Du brauchst.</p>\n<p>Ausgeprägtes analytisches Denkvermögen, Hands-on-Mentalität und unternehmerisches Gespür.</p>\n<p>Hohes Maß an Eigenverantwortung, Umsetzungsstärke und Ergebnisorientierung.</p>\n<p>Verhandlungssichere Deutschkenntnisse in Wort und Schrift.</p>\n<h2>Warum wir?</h2>\n<p>Unser Ziel: ein faires, datengetriebenes Wertgutachten für jede Immobilie in Deutschland. Bei Certa ersetzen wir das klassische Sachverständigenwesen durch eine KI-gestützte Bewertungsplattform, die schneller, präziser und transparenter ist als alles, was der Markt heute kennt.</p>\n<p>Suchst Du ein Praktikum, in dem Du in drei bis sechs Monaten mehr lernst als manche in zwei Jahren Konzern? Bei uns bist Du Teil der Geschäftsführungs-Crew und verantwortest reale Projekte mit messbarem Impact.</p>\n<p>Das Office der Geschäftsführung arbeitet direkt mit den beiden Gründern und Geschäftsführern (Alexander Rausch &#x26; Matthias Mertens) an den Top-Themen, die Certa als Unternehmen entscheidend voranbringen. Vom OKR-Framework über Marktexpansion und Operational Excellence bis zum Aufbau skalierbarer Backoffice-Strukturen. Trotz der Nähe zur Geschäftsführung leben wir eine entrepreneuriale, pragmatische Arbeitskultur: kurze Wege, schnelle Entscheidungen, hohe Umsetzungstiefe.</p>\n<p><strong>Echter Gestaltungsspielraum:</strong> Certa ist kein Konzern-Praktikum. Was Du baust, geht live, und Du siehst die Wirkung in Umsatz, Prozessen und Team.</p>\n<p><strong>Direkte Linie zu den Gründern:</strong> Du arbeitest täglich mit den beiden Gründern und Geschäftsführern. Keine Layer, keine Politik, keine Slide-Schlachten.</p>\n<p><strong>Spielwiese für KI-Enthusiasten:</strong> Bei uns ist KI kein Buzzword, sondern Arbeitsalltag. Du bekommst Zugang zu allen relevanten Tools und Modellen.</p>\n<p><strong>Lernkurve wie in keiner Beratung:</strong> Du erlebst, wie Strategie, Tech, Vertrieb und Operations wirklich zusammenspielen.</p>\n<p><strong>Überdurchschnittliche Vergütung:</strong> Wir glauben nicht an unbezahlte Lernerfahrungen. Praktika werden bei uns fair vergütet.</p>\n<p><strong>Übernahmeperspektive:</strong> Bei Erfolg gibt es ein klares Angebot, ob als Werkstudent während des weiteren Studiums oder als Festangestellter nach dem Abschluss.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-20 13:40:07.722', '2026-06-20 13:40:07.722', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/certa/praktikant-im-office-der-geschaftsfuhrung-cologne-494403', 'https://www.arbeitnow.com/jobs/companies/certa/praktikant-im-office-der-geschaftsfuhrung-cologne-494403', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/certa/praktikant-im-office-der-geschaftsfuhrung-cologne-494403\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1268, NULL, 'api', NULL, 'Design Manager (Data Centres)', 'Black & White Engineering', 'Frankfurt am Main', 'https://www.arbeitnow.com/jobs/companies/black-white-engineering/design-manager-data-centres-frankfurt-am-main-162572', '<p><strong>Ready to Lead the Delivery of Europe\'s Most Advanced Data Centre Projects?</strong></p>\n<p>This is a unique opportunity to relocate to <strong>Frankfurt, Europe\'s leading data centre market</strong>, and take ownership of the design management and coordination of some of the region\'s most technically complex and high-profile mission-critical developments.</p>\n<p>We\'re looking for an experienced <strong>Design Manager</strong> with a strong background in <strong>data centres, mission-critical infrastructure, or major technical construction projects</strong> who can drive collaboration, manage design delivery, and ensure engineering excellence across multidisciplinary teams.</p>\n<p><strong>Why Frankfurt?</strong></p>\n<p>As one of the world\'s most active data centre markets, Frankfurt offers unrivalled exposure to hyperscale, colocation and large-scale digital infrastructure projects.</p>\n<p>By relocating, you\'ll be at the centre of a growing industry, working alongside leading clients, contractors and consultants to deliver facilities that underpin the world\'s digital economy.</p>\n<h2>Tasks</h2>\n<p><strong>What\'s in It for You?</strong></p>\n<p><strong>Lead Landmark Data Centre Projects</strong> - Take ownership of design management activities on major mission-critical developments, ensuring coordination, quality and programme alignment from concept through to construction.</p>\n<p><strong>Influence Project Success</strong> - Act as the focal point between clients, engineers, contractors and stakeholders, driving collaboration and ensuring project objectives are achieved efficiently and effectively.</p>\n<p><strong>Work Across Multiple Disciplines</strong> - Coordinate complex design packages across Mechanical, Electrical, Civil, Structural and specialist engineering disciplines, helping deliver fully integrated solutions.</p>\n<p><strong>Technical and Commercial Exposure</strong> - Gain visibility across every stage of project delivery, balancing technical excellence with programme requirements, risk management and client expectations.</p>\n<p><strong>Build Trusted Client Relationships</strong> - Develop strong partnerships with clients and project teams, providing confidence and leadership throughout the design and delivery process.</p>\n<p><strong>International Collaboration</strong> - Work with multidisciplinary teams across Black &#x26; White Engineering\'s global offices, sharing expertise and best practice on some of the industry\'s most exciting projects.</p>\n<p><strong>Grow Your Career</strong> - Whether your ambitions lie in senior design management, project leadership or business leadership, you\'ll have genuine opportunities to develop within a rapidly growing international consultancy.</p>\n<h2>Requirements</h2>\n<p><strong>What We\'re Looking For</strong></p>\n<ul>\n<li>Proven experience as a <strong>Design Manager</strong>, Design Lead or Design Coordinator within data centres, mission-critical projects, building services or major construction developments.</li>\n<li>Strong understanding of multidisciplinary design coordination across MEP, Civil and Structural disciplines.</li>\n<li>Experience managing design programmes, technical deliverables and stakeholder expectations.</li>\n<li>Ability to identify and manage design risks, interfaces and project dependencies.</li>\n<li>Excellent communication and leadership skills with the confidence to engage directly with clients, contractors and consultants.</li>\n<li>Strong understanding of design management processes across all project stages.</li>\n<li>Experience working in the UK or European construction and consultancy environment.</li>\n<li>Degree qualified in Engineering, Construction Management, Architecture or a related discipline.</li>\n<li>Willingness to relocate to Frankfurt, Germany (relocation support available).</li>\n</ul>\n<p><strong>German language skills are advantageous but not essential</strong>, and support can be provided to help you settle into both the role and location.</p>\n<p><strong>About Black &#x26; White Engineering</strong></p>\n<p>Black &#x26; White Engineering is a multi-award-winning engineering consultancy with offices across the UK, Europe, the Middle East and Asia-Pacific.</p>\n<p>As specialists within the data centre sector, we deliver world-class engineering services across Mechanical, Electrical and Public Health (MEP), Civil &#x26; Structural Engineering, Power Systems, Sustainability, BIM, Design Management and specialist infrastructure disciplines.</p>\n<p>Our teams support clients throughout the full project lifecycle, creating practical, buildable and operationally efficient solutions that deliver long-term value.</p>\n<p>As one of the industry\'s fastest-growing consultancies, we provide genuine opportunities for career progression. Many of our engineers have developed into senior technical and leadership positions as the business continues to expand globally.</p>\n<p>Join Black &#x26; White Engineering and become part of a business where your expertise is recognised, your development is supported, and your impact is felt on some of the world\'s most exciting data centre projects.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Ready to Lead the Delivery of Europe\'s Most Advanced Data Centre Projects?</strong></p>\n<p>This is a unique opportunity to relocate to <strong>Frankfurt, Europe\'s leading data centre market</strong>, and take ownership of the design management and coordination of some of the region\'s most technically complex and high-profile mission-critical developments.</p>\n<p>We\'re looking for an experienced <strong>Design Manager</strong> with a strong background in <strong>data centres, mission-critical infrastructure, or major technical construction projects</strong> who can drive collaboration, manage design delivery, and ensure engineering excellence across multidisciplinary teams.</p>\n<p><strong>Why Frankfurt?</strong></p>\n<p>As one of the world\'s most active data centre markets, Frankfurt offers unrivalled exposure to hyperscale, colocation and large-scale digital infrastructure projects.</p>\n<p>By relocating, you\'ll be at the centre of a growing industry, working alongside leading clients, contractors and consultants to deliver facilities that underpin the world\'s digital economy.</p>\n<h2>Tasks</h2>\n<p><strong>What\'s in It for You?</strong></p>\n<p><strong>Lead Landmark Data Centre Projects</strong> - Take ownership of design management activities on major mission-critical developments, ensuring coordination, quality and programme alignment from concept through to construction.</p>\n<p><strong>Influence Project Success</strong> - Act as the focal point between clients, engineers, contractors and stakeholders, driving collaboration and ensuring project objectives are achieved efficiently and effectively.</p>\n<p><strong>Work Across Multiple Disciplines</strong> - Coordinate complex design packages across Mechanical, Electrical, Civil, Structural and specialist engineering disciplines, helping deliver fully integrated solutions.</p>\n<p><strong>Technical and Commercial Exposure</strong> - Gain visibility across every stage of project delivery, balancing technical excellence with programme requirements, risk management and client expectations.</p>\n<p><strong>Build Trusted Client Relationships</strong> - Develop strong partnerships with clients and project teams, providing confidence and leadership throughout the design and delivery process.</p>\n<p><strong>International Collaboration</strong> - Work with multidisciplinary teams across Black &#x26; White Engineering\'s global offices, sharing expertise and best practice on some of the industry\'s most exciting projects.</p>\n<p><strong>Grow Your Career</strong> - Whether your ambitions lie in senior design management, project leadership or business leadership, you\'ll have genuine opportunities to develop within a rapidly growing international consultancy.</p>\n<h2>Requirements</h2>\n<p><strong>What We\'re Looking For</strong></p>\n<ul>\n<li>Proven experience as a <strong>Design Manager</strong>, Design Lead or Design Coordinator within data centres, mission-critical projects, building services or major construction developments.</li>\n<li>Strong understanding of multidisciplinary design coordination across MEP, Civil and Structural disciplines.</li>\n<li>Experience managing design programmes, technical deliverables and stakeholder expectations.</li>\n<li>Ability to identify and manage design risks, interfaces and project dependencies.</li>\n<li>Excellent communication and leadership skills with the confidence to engage directly with clients, contractors and consultants.</li>\n<li>Strong understanding of design management processes across all project stages.</li>\n<li>Experience working in the UK or European construction and consultancy environment.</li>\n<li>Degree qualified in Engineering, Construction Management, Architecture or a related discipline.</li>\n<li>Willingness to relocate to Frankfurt, Germany (relocation support available).</li>\n</ul>\n<p><strong>German language skills are advantageous but not essential</strong>, and support can be provided to help you settle into both the role and location.</p>\n<p><strong>About Black &#x26; White Engineering</strong></p>\n<p>Black &#x26; White Engineering is a multi-award-winning engineering consultancy with offices across the UK, Europe, the Middle East and Asia-Pacific.</p>\n<p>As specialists within the data centre sector, we deliver world-class engineering services across Mechanical, Electrical and Public Health (MEP), Civil &#x26; Structural Engineering, Power Systems, Sustainability, BIM, Design Management and specialist infrastructure disciplines.</p>\n<p>Our teams support clients throughout the full project lifecycle, creating practical, buildable and operationally efficient solutions that deliver long-term value.</p>\n<p>As one of the industry\'s fastest-growing consultancies, we provide genuine opportunities for career progression. Many of our engineers have developed into senior technical and leadership positions as the business continues to expand globally.</p>\n<p>Join Black &#x26; White Engineering and become part of a business where your expertise is recognised, your development is supported, and your impact is felt on some of the world\'s most exciting data centre projects.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-20 13:40:16.522', '2026-06-20 13:40:16.522', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/black-white-engineering/design-manager-data-centres-frankfurt-am-main-162572', 'https://www.arbeitnow.com/jobs/companies/black-white-engineering/design-manager-data-centres-frankfurt-am-main-162572', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/black-white-engineering/design-manager-data-centres-frankfurt-am-main-162572\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1269, NULL, 'api', NULL, 'Senior Credit Risk Specialist', 'Gratitude Jobs Ahead HR INC', 'Herford', 'https://www.arbeitnow.com/jobs/companies/gratitude-jobs-ahead-hr-inc/senior-credit-risk-specialist-herford-310523', '<p>Credit Analyst</p>\n<p>Gütersloh &#x26; Herford / North Rhine-Westphalia / Germany</p>\n<p>Hybrid &#x26; Remote, Full Time</p>\n<p>€85.000</p>\n<p>German C1</p>\n<p>About the Job Posting</p>\n<p>Lead and oversee distressed loan risk management for complex corporate and investor exposures, delivering recovery strategies within legal and regulatory frameworks.</p>\n<p>Language Requirements</p>\n<p>German C1</p>\n<h2>Tasks</h2>\n<p>Responsibilities</p>\n<ul>\n<li>You manage complex corporate and investor engagements in high-risk lending involving distressed loans, including restructurings, forbearance arrangements, and recovery actions.</li>\n<li>You develop results-oriented concepts for consensual or enforced debt recovery, considering legal and economic factors.</li>\n<li>You utilize available discretion and competencies in negotiation and actively shape contractual agreements within distress loan management.</li>\n<li>You represent the bank in lending consortia, creditor committees or meetings and support the implementation of enforcement measures.</li>\n<li>You maintain and review claims and collateral, assess them from realisation and risk provisioning perspectives, and execute collateral disposal as needed.</li>\n<li>You support the team as an internal point of contact for technical issues and contribute to reporting and quality assurance.</li>\n<li>You contribute to the ongoing development of processes in credit risk management with a focus on quality and efficiency.</li>\n</ul>\n<h2>Requirements</h2>\n<p>Requirements</p>\n<ul>\n<li>You hold a completed banking apprenticeship and/or a comparable qualification, or a degree in law, with professional experience in managing distressed loans and insolvencies.</li>\n<li>Strong knowledge of the legal and regulatory framework governing lending.</li>\n<li>Analytical thinking, strong coordination skills, a process-oriented approach, and effective self-management.</li>\n<li>Reliability, resilience, and a high sense of responsibility.</li>\n</ul>\n<h2>Benefits</h2>\n<p>Core Benefits</p>\n<ul>\n<li>Balanced work-life with flexible hours and remote work options.</li>\n<li>30 vacation days, two additional bank holidays, special leave for certain events, plus unpaid leave.</li>\n<li>Option of paid leave within a lifetime working time account.</li>\n<li>Active health management: fitness resources, digital classes, health checks, and mobile massage.</li>\n<li>Bike leasing and travel subsidies, plus employee discounts and meal allowances.</li>\n<li>Tailored professional development opportunities.</li>\n</ul>\n<p>Required Experience</p>\n<p>Minimum 5 years of relevant experience in credit risk or distressed debt management.</p>\n<p>Employment Type</p>\n<p>Full-time</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Credit Analyst</p>\n<p>Gütersloh &#x26; Herford / North Rhine-Westphalia / Germany</p>\n<p>Hybrid &#x26; Remote, Full Time</p>\n<p>€85.000</p>\n<p>German C1</p>\n<p>About the Job Posting</p>\n<p>Lead and oversee distressed loan risk management for complex corporate and investor exposures, delivering recovery strategies within legal and regulatory frameworks.</p>\n<p>Language Requirements</p>\n<p>German C1</p>\n<h2>Tasks</h2>\n<p>Responsibilities</p>\n<ul>\n<li>You manage complex corporate and investor engagements in high-risk lending involving distressed loans, including restructurings, forbearance arrangements, and recovery actions.</li>\n<li>You develop results-oriented concepts for consensual or enforced debt recovery, considering legal and economic factors.</li>\n<li>You utilize available discretion and competencies in negotiation and actively shape contractual agreements within distress loan management.</li>\n<li>You represent the bank in lending consortia, creditor committees or meetings and support the implementation of enforcement measures.</li>\n<li>You maintain and review claims and collateral, assess them from realisation and risk provisioning perspectives, and execute collateral disposal as needed.</li>\n<li>You support the team as an internal point of contact for technical issues and contribute to reporting and quality assurance.</li>\n<li>You contribute to the ongoing development of processes in credit risk management with a focus on quality and efficiency.</li>\n</ul>\n<h2>Requirements</h2>\n<p>Requirements</p>\n<ul>\n<li>You hold a completed banking apprenticeship and/or a comparable qualification, or a degree in law, with professional experience in managing distressed loans and insolvencies.</li>\n<li>Strong knowledge of the legal and regulatory framework governing lending.</li>\n<li>Analytical thinking, strong coordination skills, a process-oriented approach, and effective self-management.</li>\n<li>Reliability, resilience, and a high sense of responsibility.</li>\n</ul>\n<h2>Benefits</h2>\n<p>Core Benefits</p>\n<ul>\n<li>Balanced work-life with flexible hours and remote work options.</li>\n<li>30 vacation days, two additional bank holidays, special leave for certain events, plus unpaid leave.</li>\n<li>Option of paid leave within a lifetime working time account.</li>\n<li>Active health management: fitness resources, digital classes, health checks, and mobile massage.</li>\n<li>Bike leasing and travel subsidies, plus employee discounts and meal allowances.</li>\n<li>Tailored professional development opportunities.</li>\n</ul>\n<p>Required Experience</p>\n<p>Minimum 5 years of relevant experience in credit risk or distressed debt management.</p>\n<p>Employment Type</p>\n<p>Full-time</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-20 13:40:25.013', '2026-06-20 13:40:25.013', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/gratitude-jobs-ahead-hr-inc/senior-credit-risk-specialist-herford-310523', 'https://www.arbeitnow.com/jobs/companies/gratitude-jobs-ahead-hr-inc/senior-credit-risk-specialist-herford-310523', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/gratitude-jobs-ahead-hr-inc/senior-credit-risk-specialist-herford-310523\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1270, NULL, 'api', NULL, 'Steuerberater (m/w/d) in Flein, auf Wunsch mit Partnerperspektive, gesucht - mindestens 90.000€', 'Taxtalente.de', 'Flein', 'https://www.arbeitnow.com/jobs/companies/taxtalentede/steuerberater-in-flein-auf-wunsch-mit-partnerperspektive-gesucht-mindestens-90000eur-269162', '<p>TaxTalente ist die Nr. 1 Job-Matching Plattform für Jobsuchende in der Steuerberatung.</p>\n<p>Sie suchen eine positive berufliche Veränderung? Sie möchten den nächsten Schritt in Ihrer Karriere gehen und streben möglicherweise sogar eine Partnerschaft in einer zukunftsorientierten Kanzlei an? Sie möchten endlich wieder in einem positiven Arbeitsumfeld arbeiten, in dem Sie finanziell und persönlich wertgeschätzt werden? Sie suchen nach Tätigkeiten, die Sie auch wirklich weiterbringen?</p>\n<p>Sofern Sie sich in mindestens einem der genannten Punkte wiederfinden, sollten Sie sich bei uns melden. Wir haben die attraktivsten Arbeitgeber der Steuerberatungsbranche in unserem Netzwerk und bringen zusammen, was zusammengehört. Grenzenlose Entwicklungschancen mit Partnermöglichkeiten, vielschichtige Tätigkeitsbereiche, Gehälter wie in der Industrie und vieles mehr – melden Sie sich bei uns und wir unterstützen Sie auf Ihrem weiteren Karriereweg!</p>\n<p>Derzeit suchen wir nach einem Steuerberater (m/w/d) für eine unserer Partner-Kanzleien in Flein</p>\n<p>Bei <strong>Rückfragen</strong> kannst du dich gerne <strong>jederzeit</strong> (auch nach deinem Feierabend) direkt telefonisch an <strong>Herrn Becker-Koch</strong> über folgende Nummer wenden: <strong>015901431130</strong></p>\n<h2>Aufgaben</h2>\n<p>Wir bringen zusammen, was zusammengehört. Dabei spielt das passende Tätigkeitsprofil natürlich eine entscheidende Rolle. Bei unserer Partnerkanzlei können Sie sich Ihren Aufgabenbereich auf Basis Ihrer persönlichen Stärken und Schwächen selbst zusammenstellen.</p>\n<ul>\n<li><strong>Erstellung</strong> und Review von <strong>Jahresabschlüssen</strong></li>\n<li><strong>Erstellung</strong> von <strong>Steuererklärungen</strong> für Personen- und Kapitalgesellschaften</li>\n<li><strong>Steuerliche Sonderberatungsprojekte</strong> auf Basis <strong>individueller Qualifikationen</strong>B. in den Bereichen der Erbschaftsteuer oder des Umwandlungssteuerrechts</li>\n<li><strong>Begleitung</strong> von <strong>Betriebsprüfungen</strong></li>\n<li>Teamleitung und <strong>Personalverantwortung</strong> (optional)</li>\n<li><strong>Weitere</strong> individuell <strong>wählbare Tätigkeitsbereiche</strong>, die Ihnen Freude bringen</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Am Ende sollte es für beide Seiten passen. Deshalb wäre es gut, wenn Sie sich in den folgenden Punkten wiederfinden.</p>\n<ul>\n<li><strong>Kommunikative Art</strong> und Freude am Austausch mit Mandanten</li>\n<li><strong>Sorgfältige</strong>, effiziente und <strong>gewissenhafte Arbeitsweise</strong></li>\n<li>Offen für eine <strong>digitale Arbeitsweise</strong></li>\n<li><strong>Führungsverständnis</strong> und <strong>Verantwortungsbewusstsein</strong> gegenüber Mitarbeitern (optional)</li>\n<li>Ein erfolgreich abgeschlossenes <strong>Steuerberaterexamen</strong></li>\n<li><strong>Leidenschaft</strong> für <strong>steuerliche Themen</strong></li>\n</ul>\n<h2>Benefits</h2>\n<p>Sie haben genug von 0815 Benefits, von denen Sie nicht wirklich profitieren? Dann sollten Sie einen Blick auf die nachfolgenden Benefits werfen.</p>\n<ul>\n<li>Außerordentliche Vergütung von <strong>90.000 € bis 130.000 €</strong> / Jahr, auf Wunsch auch <strong>Partnerperspektive</strong></li>\n<li><strong>Flexible</strong> Gestaltung der <strong>Arbeitszeiten</strong> sowie die Option auf <strong>Home-Office</strong></li>\n<li><strong>Nettolohnoptimierung</strong> mit monatlichen 50,00€ Sachbezugsgutscheinen</li>\n<li>Umfangreiche Unterstützung bei <strong>Weiterbildungsmaßnahmen</strong> wie z.B. Fachberater Qualifikationen</li>\n<li><strong>Modernste Ausstattung</strong> mit digitalen Prozessen</li>\n<li><strong>Starker Teamzusammenhalt</strong> und regelmäßige Teamevents</li>\n</ul>\n<p>Schnell, unkompliziert und effizient Ihren Traumjob finden – ein Versprechen an Sie, dass wir aufgrund unseres selektiven, breit gefächerten und deutschlandweiten Kanzleinetzwerks halten werden. lhre Vorteile mit uns auf einen Blick:</p>\n<ul>\n<li>Sie führen <strong>keine unsinnigen Bewerbungsgespräche</strong> mehr, bei denen Sie während des Bewerbungsprozesses merken, dass es (bspw. wegen des Gehalts) sowieso nicht passt - wir klären vor Ihrem Bewerbungsgespräch all Ihre mit uns besprochenen Kriterien mit der Kanzlei ab.</li>\n<li><strong>Wir führen Ihre Gehaltsverhandlungen</strong> und kennen die Gehaltsstrukturen der Branche dabei bestens.</li>\n<li><strong>100% Anonymität</strong> – solange Sie uns nicht das „Go“ geben und einem Kennenlernen mit Ihrem neuen potentiellen Arbeitgeber zustimmen, erfährt niemand von Ihrem Namen oder Ihren bisherigen Arbeitgebern – Ihre Ihnen wichtigen Kriterien können wir auch zunächst anonym mit unseren Partnerkanzleien klären.</li>\n<li><strong>Attraktive Kanzleien</strong> – die Kanzleien in unserem breit gefächerten Kanzleinetzwerk sind selektiv ausgewählt und heben sich klar von “normalen” Kanzleien ab (z.B. hinsichtlich der Vergütung, Benefits, Hierarchien, Digitalisierungsgrad, Ausstattung etc.).</li>\n<li>Und das Beste: Unser gesamter Service ist <strong>unverbindlich und völlig kostenfrei</strong> für Sie.</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>TaxTalente ist die Nr. 1 Job-Matching Plattform für Jobsuchende in der Steuerberatung.</p>\n<p>Sie suchen eine positive berufliche Veränderung? Sie möchten den nächsten Schritt in Ihrer Karriere gehen und streben möglicherweise sogar eine Partnerschaft in einer zukunftsorientierten Kanzlei an? Sie möchten endlich wieder in einem positiven Arbeitsumfeld arbeiten, in dem Sie finanziell und persönlich wertgeschätzt werden? Sie suchen