INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1325, NULL, 'api', NULL, 'Senior Test Engineer (m/w/d)', 'Falk Defence GmbH', 'Leipzig', 'https://www.arbeitnow.com/jobs/companies/falk-defence-gmbh/senior-test-engineer-leipzig-256947', '<p>Falk Defence entwickelt hochmoderne Technologien für Raketen, Lenkflugkörper und Startsysteme im militärischen Umfeld. Wir verbinden Innovationskraft, technische Exzellenz und Zuverlässigkeit und liefern einsatzkritische Systeme auf höchstem Qualitätsniveau – und leisten damit einen unmittelbaren Beitrag zur Verteidigungsfähigkeit Deutschlands und seiner Verbündeten.</p>\n<h2>Aufgaben</h2>\n<p>Als Senior Test Engineer verantwortest du die Erprobung unserer Flugkörper- und Startsysteme – von der Komponente bis zum Gesamtsystem. Du planst Testkampagnen, baust Prüfstände auf und bringst unsere Systeme unter realitätsnahen Bedingungen an ihre Grenzen, damit sie im Einsatz höchste Anforderungen an Performance, Robustheit und Zuverlässigkeit erfüllen.</p>\n<ul>\n<li>Du entwickelst Testpläne und Testprozeduren auf Komponenten-, Subsystem- und Systemebene</li>\n<li>Du konzipierst, baust und nimmst Prüfstände und Messsysteme in Betrieb</li>\n<li>Du planst, führst und wertest Entwicklungs-, Qualifikations- und Abnahmetests aus</li>\n<li>Du koordinierst Tests mit externen Testeinrichtungen und Flugtest-Ranges</li>\n<li>Du stellst eine vollständige, nachvollziehbare Testdokumentation und lückenlose Nachverfolgbarkeit sicherDu unterstützt Flugtestkampagnen und führst strukturierte Fehler- und Ursachenanalysen durch</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Abgeschlossenes Studium der Elektrotechnik, Luft- und Raumfahrttechnik, Maschinenbau oder eines vergleichbaren Fachgebiets</li>\n<li>Ausgeprägte Hands-on-Mentalität und eine strukturierte, sicherheitsbewusste Arbeitsweise</li>\n<li>Hohe Reisebereitschaft, auch für mehrwöchige Einsätze auf Test-Ranges</li>\n<li>Erfahrung mit Raketen-, Flugkörper- oder Luftfahrtsystemen ist von Vorteil</li>\n<li>Kenntnisse von Flight-Test-Ranges und deren Anforderungen sind von Vorteil</li>\n<li>Erfahrung im Umgang mit pyrotechnischen Systemen und Raketenmotoren sowie die Befähigung zum Umgang mit Explosivstoffen sind von Vorteil</li>\n<li>Kenntnisse in Messtechnik, Datenerfassung und Datenauswertung sind von Vorteil</li>\n<li>Kenntnisse militärischer Test- und Qualifikationsstandards (z. B. MIL-STD, AECTP, STANAG) sind von Vorteil</li>\n<li>Sehr gute Deutschkenntnisse (mindestens C1) sowie gute Englischkenntnisse</li>\n<li>Staatsangehörigkeit eines EU- oder NATO-Mitgliedstaats (ausgenommen USA) sowie Bereitschaft zur Sicherheitsüberprüfung nach SÜG</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Eine Schlüsselrolle in der Erprobung einsatzkritischer Systeme mit direkter Sichtbarkeit im Flugtest</li>\n<li>Mitarbeit an hochmodernen Flugkörper- und Startsystemen mit realer sicherheitspolitischer Bedeutung</li>\n<li>Flache Hierarchien, kurze Entscheidungswege und hohe Eigenverantwortung ab dem ersten Tag</li>\n<li>Die Chance, ein neues europäisches Defence-Tech-Unternehmen von Grund auf mitzugestalten</li>\n<li>Ein hochmotiviertes, interdisziplinäres Team aus erfahrenen Ingenieurinnen und Ingenieuren</li>\n<li>Unbefristete Anstellung und flexible Arbeitszeitmodelle</li>\n</ul>\n<p>Werde Teil von Falk Defence und gestalte mit uns die nächste Generation moderner Verteidigungssysteme.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Falk Defence entwickelt hochmoderne Technologien für Raketen, Lenkflugkörper und Startsysteme im militärischen Umfeld. Wir verbinden Innovationskraft, technische Exzellenz und Zuverlässigkeit und liefern einsatzkritische Systeme auf höchstem Qualitätsniveau – und leisten damit einen unmittelbaren Beitrag zur Verteidigungsfähigkeit Deutschlands und seiner Verbündeten.</p>\n<h2>Aufgaben</h2>\n<p>Als Senior Test Engineer verantwortest du die Erprobung unserer Flugkörper- und Startsysteme – von der Komponente bis