INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1449, NULL, 'api', NULL, 'Sales Manager (w/m/d) Wärmepumpe & PV', 'Enter by baupal GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/enter-by-baupal-gmbh/sales-manager-warmepumpe-pv-berlin-203836', '<h2>FIXING THE PLANET BY MAKING HOMES CARBON-FREE!</h2>\n<p>Enter ist die Antwort auf eine Frage, die sich gerade Millionen Hausbesitzer stellen: Nicht ob ihr Haus elektrifiziert wird – sondern wie, und mit wem.</p>\n<p>Als Deutschlands führender Energieberater begleiten wir energetische Sanierungen ganzheitlich: von der ersten Frage bis zur installierten Wärmepumpe oder PV-Anlage. 2025 haben wir dieses Wissen konsequent in den Vertrieb gebracht – jedes Haus ein Einzelfall, jede Lösung passgenau.<br>\nDas Ergebnis: ein Angebot, das Kunden wollen. Mit über 40 Millionen Euro Funding und 80 Mitarbeitern wachsen wir in einem Markt, der gerade erst so richtig losgeht. Die Frage ist, ob Du dabei bist.</p>\n<p>Als Sales Manager (w/m/d) bei Enter berätst Du Kunden zur passenden Wärmepumpe oder PV-Anlage und überzeugst, weil Du Dein Handwerk kannst.</p>\n<p>Sieben Abschlüsse im Monat klingen dabei für Dich nach Quote, nicht nach Ziel? Gut. Reden wir.</p>\n<h2>Unser Angebot</h2>\n<ul>\n<li>Du musst niemanden überzeugen, dass er mit Dir reden will. Das haben wir schon erledigt. <strong>Mindestens 4 qualifizierte Videocalls am Tag</strong></li>\n<li>36.000 € p.a. base. 70.000 € p.a. OTE bei 7 Abschlüssen im Monat. <strong>Kein Deckel nach oben.</strong> Wer mehr bringt, verdient mehr</li>\n<li><strong>Klarheit statt Rätselraten</strong>: Der Weg zum Senior – und bis zu 80.000 € p.a. OTE – ist klar definiert, genau wie der nächste Schritt danach: Führung oder Spezialisierung</li>\n<li>Dein Team Lead hat selbst verkauft, bevor er Dich coacht. Das heißt kein Management vom Schreibtisch aus, sondern Leute die wissen, wie sich ein Nein anhört</li>\n<li>Greentech ist der Markt, in dem sich gerade entscheidet, wer vorne mitspielt. Du bist früh genug dabei, dass Dein Beitrag noch zählt</li>\n</ul>\n<h2>Dein Spielfeld</h2>\n<ul>\n<li>Du führst vorterminierte Verkaufsgespräche mit Eigenheimbesitzern per Video – mit Methodik und Wissen, nicht vom Blatt</li>\n<li>Du berätst bedarfsgerecht zu Wärmepumpe und PV-Anlage und holst Dir den Abschluss</li>\n<li>Du pflegst Deine Pipeline eigenständig in HubSpot: saubere Doku, konsequente Nachverfolgung, verbindliche Folgetermine</li>\n</ul>\n<h2>So passt du in\'s Team</h2>\n<ul>\n<li>Du hast mind. 1–2 Jahre B2C-Closing-Erfahrung mit erklärungsbedürftigem Produkt, und deine Ziele hast Du dabei nicht nur gesehen, sondern erreicht</li>\n<li>Du führst Gespräche aus dem Stand, ohne Leitfaden, aber mit Charisma</li>\n<li>Du organisierst Dich selbst: Deine Pipeline, Deine Folgetermine, Deine Prioritäten</li>\n<li>Zwei Tage Homeoffice nimmst Du mit – den Rest willst Du dort sein, wo Coaching und Energie live passieren: auf dem Sales Floor</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Spreeblick statt Hinterhof: unser Büro liegt direkt am Wasser, mitten in Kreuzberg</li>\n<li>Zwei Remote-Tage pro Woche, der Rest live mit dem Team</li>\n<li>Ein Learning-Budget, das auf Deine Entwicklung einzahlt – fachlich oder querbeet</li>\n<li>Urban Sports Club, Jobticket, Kita-Zuschuss – je nach dem, was in Deinem Leben gerade zählt</li>\n<li>Betriebliche Altersvorsorge</li>\n<li>Du begleitest Menschen dabei, ihre Häuser nachhaltiger zu machen und leistest so einen echten Beitrag - Energiewende zum anfassen</li>\n</ul>\n<h2>Bewirb Dich</h2>\n<p>Kathi (Interim Talent Acquisition Manager) ist Deine Ansprechpartnerin für diese Rolle. Wir bauen das Team gerade aktiv aus – heißt: Du kannst sofort starten. Lebenslauf reicht. Wenn Du ein paar echte Sätze über Dich ergänzen willst, gerne – lieber als ein durchformuliertes Anschreiben.</p>\n<p>So geht\'s weiter:</p>\n<ol>\n<li><strong>45 Minuten Erstgespräch mit Kathi</strong> (virtuell) – innerhalb einer Woche nach deiner Bewerbung</li>\n<li>90 Minuten mit Cevin oder Steve, unseren Sales Leads (virtuell)</li>\n<li><strong>45 Minuten persönlich</strong> bei uns im Büro in Kreuzberg</li>\n</ol>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>FIXING THE PLANET BY MAKING HOMES CARBON-FREE!</h2>\n<p>Enter ist die Antwort auf eine Frage, die sich gerade Millionen Hausbesitzer stellen: Nicht ob ihr Haus elektrifiziert wird – sondern wie, und mit wem.</p>\n<p>Als Deutschlands führender Energieberater begleiten wir energetische Sanierungen ganzheitlich: von der ersten Frage bis zur installierten Wärmepumpe oder PV-Anlage. 2025 haben wir dieses Wissen konsequent in den Vertrieb gebracht – jedes Haus ein Einzelfall, jede Lösung passgenau.<br>\nDas Ergebnis: ein Angebot, das Kunden wollen. Mit über 40 Millionen Euro Funding und 80 Mitarbeitern wachsen wir in einem Markt, der gerade erst so richtig losgeht. Die Frage ist, ob Du dabei bist.</p>\n<p>Als Sales Manager (w/m/d) bei Enter berätst Du Kunden zur passenden Wärmepumpe oder PV-Anlage und überzeugst, weil Du Dein Handwerk kannst.</p>\n<p>Sieben Abschlüsse im Monat klingen dabei für Dich nach Quote, nicht nach Ziel? Gut. Reden wir.</p>\n<h2>Unser Angebot</h2>\n<ul>\n<li>Du musst niemanden überzeugen, dass er mit Dir reden will. Das haben wir schon erledigt. <strong>Mindestens 4 qualifizierte Videocalls am Tag</strong></li>\n<li>36.000 € p.a. base. 70.000 € p.a. OTE bei 7 Abschlüssen im Monat. <strong>Kein Deckel nach oben.</strong> Wer mehr bringt, verdient mehr</li>\n<li><strong>Klarheit statt Rätselraten</strong>: Der Weg zum Senior – und bis zu 80.000 € p.a. OTE – ist klar definiert, genau wie der nächste Schritt danach: Führung oder Spezialisierung</li>\n<li>Dein Team Lead hat selbst verkauft, bevor er Dich coacht. Das heißt kein Management vom Schreibtisch aus, sondern Leute die wissen, wie sich ein Nein anhört</li>\n<li>Greentech ist der Markt, in dem sich gerade entscheidet, wer vorne mitspielt. Du bist früh genug dabei, dass Dein Beitrag noch zählt</li>\n</