INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1572, NULL, 'api', NULL, 'Software Engineer, Platform - Berlin, Germany', 'Speechify', 'Berlin, Berlin, Germany', 'https://www.arbeitnow.com/jobs/companies/speechify/software-engineer-platform-berlin-germany-468519', '<p>The mission of Speechify is to make sure that reading is never a barrier to learning.</p>\n<p>Over 50 million people use Speechify\'s text-to-speech products to turn whatever they\'re reading – PDFs, books, Google Docs, news articles, websites – into audio, so they can read faster, read more, and remember more. Speechify\'s text-to-speech reading products include its iOS app, Android App, Mac App, Chrome Extension, and Web App. Google recently named Speechify the Chrome Extension of the Year and Apple named Speechify its 2025 Design Award winner for Inclusivity.&nbsp;&nbsp;</p>\n<p>Today, nearly 200 people around the globe work on Speechify in a 100% distributed setting – Speechify has no office. These include frontend and backend engineers, AI research scientists, and others from Amazon, Microsoft, and Google, leading PhD programs like Stanford, high growth startups like Stripe, Vercel, Bolt, and many founders of their own companies.</p>\n<p><strong>Overview</strong></p>\n<p data-speechify-sentence=\"\">The responsibilities of our Platform team include building and maintaining all backend services, including, but not limited to, payments, analytics, subscriptions, new products, text to speech, and external APIs.</p>\n<p data-speechify-sentence=\"\">This is a key role and ideal for someone who thinks strategically, enjoys fast-paced environments, is passionate about making product decisions, and has experience building great user experiences that delight users.</p>\n<p data-speechify-sentence=\"\">We are a flat organization that allows anyone to become a leader by showing excellent technical skills and delivering results consistently and fast. Work ethic, solid communication skills, and obsession with winning are paramount.&nbsp;</p>\n<p data-speechify-sentence=\"\">Our interview process involves several technical interviews and we aim to complete them within 1 week.&nbsp;</p>\n<p><strong>What Yo</strong><strong>u\'</strong><strong>ll Do</strong></p>\n<ul>\n<li data-speechify-sentence=\"\">Design, develop, and maintain robust APIs including public TTS API, internal APIs like Payment, Subscription, Auth and Consumption Tracking, ensuring they meet business and scalability requirements</li>\n<li data-speechify-sentence=\"\">Oversee the full backend API landscape, enhancing and optimizing for performance and maintainability</li>\n<li data-speechify-sentence=\"\">Collaborate on B2B solutions, focusing on customization and integration needs for enterprise clients</li>\n<li data-speechify-sentence=\"\">Work closely with cross-functional teams to align backend architecture with overall product strategy and user experience</li>\n</ul>\n<p><strong>An Ideal Candidate Should Have</strong></p>\n<ul>\n<li>Proven experience in backend development: TS/Node (required)</li>\n<li>Direct experience with GCP and knowledge of AWS, Azure, or other cloud providers</li>\n<li>Efficiency in ideation and implementation, prioritizing tasks based on urgency and impact</li>\n<li>Preferred: Experience with Docker and containerized deployments</li>\n<li>Preferred: Proficiency in deploying high availability applications on Kubernetes</li>\n</ul>\n<p data-speechify-sentence=\"\"><strong>What We Offer </strong></p>\n<ul>\n<li>A dynamic environment where your contributions shape the company and its products</li>\n<li>A team that values innovation, intuition, and drive</li>\n<li>Autonomy, fostering focus and creativity</li>\n<li>The opportunity to have a significant impact in a revolutionary industry</li>\n<li>Competitive compensation, a welcoming atmosphere, and a commitment to an exceptional asynchronous work culture</li>\n<li>The privilege of working on a product that changes lives, particularly for those with learning differences like dyslexia, ADD, and more</li>\n<li>An active role at the intersection of artificial intelligence and audio – a rapidly evolving tech domain</li>\n</ul>\n<p><strong>The Germany Based </strong>Salary range for this role is: 30,000-120,000 USD/Year + Bonus + Stock depending on experience.</p>\n<p><strong>Think you\'re a good fit for this job?&nbsp;</strong></p>\n<p>Tell us more about yourself and why you\'re interested in the role when you apply. <br>And don\'t forget to include links to your portfolio and LinkedIn.</p>\n<p><strong>Not looking but know someone who would make a great fit?&nbsp;</strong></p>\n<p>Refer them!&nbsp;</p>\n<p><strong>Speechify is committed to a diverse and inclusive workplace.&nbsp;</strong></p>\n<p>Speechify does not discriminate on the basis of race, national origin, gender, gender identity, sexual orientation, protected veteran status, disability, age, or other legally protected status.</p><p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>The mission of Speechify is to make sure that reading is never a barrier to learning.</p>\n<p>Over 50 million people use Speechify\'s text-to-speech products to turn whatever they\'re reading – PDFs, books, Google Docs, news articles, websites – into audio, so they can read faster, read more, and remember more. Speechify\'s text-to-speech reading products include its iOS app, Android App, Mac App, Chrome Extension, and Web App. Google recently named Speechify the Chrome Extension of the Year and Apple named Speechify its 2025 Design Award winner for Inclusivity.&nbsp;&nbsp;</p>\n<p>Today, nearly 200 people around the globe work on Speechify in a 100% distributed setting – Speechify has no office. These include frontend and backend engineers, AI research scientists, and others from Amazon, Microsoft, and Google, leading PhD programs like Stanford, high growth startups like Stripe, Vercel, Bolt, and many founders of their own companies.</p>\n<p><strong>Overview</strong></p>\