INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1712, NULL, 'api', NULL, 'Personalsachbearbeiter u./o. Entgeltabrechner (w/m/d) für sehr bekanntes Unternehmen', 'Fischer & Partner Gesellschaft für Personal mbH', 'Stuttgart', 'https://www.arbeitnow.com/jobs/companies/fischer-partner-gesellschaft-fur-personal-mbh/personalsachbearbeiter-u-o-entgeltabrechner-fur-sehr-bekanntes-unternehmen-stuttgart-211181', '<p>Für ein regional fest verwurzeltes und sehr bekanntes Unternehmen mit ca. 500 Mitarbeitenden und mit Sitz <strong>im Raum Waiblingen</strong> suchen wir Sie als</p>\n<p><strong>Personalsachbearbeiter u./o. Entgeltabrechner (w/m/d) mit Berufserfahrung.</strong></p>\n<p>In Abhängigkeit von Ihrer Qualifikation und Berufserfahrung können Sie hier <strong>bis zu 65.000 € p.a.</strong> verdienen.</p>\n<p>Die <strong>Vollzeitstelle</strong> ist im Rahmen der Personalvermittlung zu besetzen. Bedeutet also: Sie haben von Anfang an ein festes Anstellungsverhältnis mit Ihrem neuen Arbeitgeber, der Sie gerne viele Jahre beschäftigen möchte.</p>\n<p>Der besseren Lesbarkeit wegen richten sich alle folgenden Bezeichnungen an alle Geschlechter.</p>\n<h2>Aufgaben</h2>\n<p><strong>Voilà, so sieht Ihr neuer Job aus!</strong></p>\n<ul>\n<li>Ihr Aufgabenbereich umfasst die Themen Personal (60-70 %) und Entgeltabrechnung (30-40 %)</li>\n<li>U. a. erstellen Sie Arbeitsverträge, Vertragsänderungen, Abmahnungen und Arbeitszeugnisse</li>\n<li>Dabei überwachen Sie auch Fristen</li>\n<li>Für die ca. 500 Mitarbeitenden erstellen Sie die Gehalts- und Lohnabrechnungen inkl. Zuschlägen (auch geringfügig Beschäftigte) und veranlassen die Überweisungen</li>\n<li>Dazu übernehmen Sie das Melde- und Bescheinigungswesen und sind Schnittstelle zu Sozial- und Rentenversicherungsträgern</li>\n<li>Für die von Ihnen betreuten Mitarbeiter sind Sie kompetenter und freundlicher Ansprechpartner</li>\n<li>Sie beraten die Geschäftsführung in arbeits-, steuer- und sozialversicherungsrechtlichen Fragen</li>\n<li>Abschließend übernehmen Sie die Erstellung monatlicher Statistiken.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringen Sie mit</strong>:</p>\n<ul>\n<li>Gute Laune, Lust auf nette Kollegen und Teamarbeit!</li>\n<li>Sie sollten Berufserfahrung entweder in der Entgeltabrechnung oder in der Personalsachbearbeitung mitbringen, idealerweise in beiden Themen. Wenn Sie aber eines der beiden Themen nicht mitbringen, werden Sie darin eingearbeitet</li>\n<li>Sie verfügen über sehr gute Deutschkenntnisse in Wort und Schrift</li>\n<li>Wir verzichten gerne auf die an dieser Stelle üblichen persönlichen Attribute und möchten Sie als Person kennenlernen. Wichtig ist zunächst, dass Sie Lust auf nette Kollegen haben und ein absoluter Teamplayer sind, der sich fachlich gerne weiter entwickeln möchte</li>\n<li>Uns ist klar, dass kaum jemand alle Anforderungen erfüllen wird. Auch Bewerbungen, in denen das nicht der Fall ist, sind herzlich willkommen.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Das bietet Ihnen Ihr neuer Arbeitgeber:</strong></p>\n<ul>\n<li>Flexible Arbeitszeiten</li>\n<li>vermögenswirksame Leistungen</li>\n<li>eine betriebliche Altersvorsorge (bAV)</li>\n<li>einen steuerfreien Personalrabatt</li>\n<li>die gratis Nutzung des betriebsinternen Fitnessstudios</li>\n<li>einen modernen Arbeitsplatz.</li>\n</ul>\n<p><strong>In 3 einfachen Schritten zu Ihrer neuen Anstellung:</strong></p>\n<p>1.) Bewerbungsunterlagen als PDF abspeichern (Verzichten Sie gerne auf ein Anschreiben).</p>\n<p>2.) Bewerbung hier absenden</p>\n<p>3.) Wir setzen uns sehr zeitnah mit Ihnen in Verbindung.</p>\n<p>Bei Fragen steht Ihnen unsere Personalberater Uli Davidsson unter der Rufnummer 0711 / 528 509 - 16 jederzeit gerne zur Verfügung.</p>\n<p><strong>Kann man uns vertrauen? Wir meinen JA!</strong></p>\n<p>Fischer &#x26; Partner ist zum besten Personalvermittler der DACH-Region (Deutschland, Österreich, Schweiz) ausgezeichnet worden. Weiterempfehlungsrate: glatte 100%. Weitere Informationen unter:</p>\n<p><a href=\"https://www.kununu.com/de/fischer-partner-gesellschaft-fuer-personal-mbh/bewerbung?sort=newest\">https://www.kununu.com/de/fischer-partner-gesellschaft-fuer-personal-mbh/bewerbung?sort=newest</a></p>\n<p><strong>Was Sie sonst noch über uns wissen sollten:</strong></p>\n<p>Falls diese Stelle nicht zu Ihnen passen sollte, bewerben Sie sich bitte trotzdem: Wir können Ihnen Stellen als Entgeltabrechner in der Region Stuttgart immer wieder vorschlagen, ebenso als Bilanzbuchhalter, Finanzbuchhalter und Controller.</p>\n<p><strong>Finden Sie weitere attraktive Stellenangebote auf unserer Homepage.</strong></p>\n<p>Für Sie als Bewerber arbeiten wir kostenfrei und mit höchster Diskretion. Bevor wir Sie bei potenziellen Arbeitgebern in anonymisierter Form vorschlagen, sprechen wir immer zuerst mit Ihnen über die jeweilige Stelle! Ohne Ihre Zustimmung unternehmen wir keinen Schritt. Ihre Daten sind bei uns sicher!</p>\n<p><strong>Unser Qualitätsversprechen:</strong> Wir beantworten jede Bewerbung sehr zuverlässig innerhalb von max. drei Werktagen, i.d.R. schneller. Wenn Sie also nach drei Werktagen nichts von uns gehört haben, kann es technische Gründe dafür geben. Bitte haken Sie in diesem Fall bei uns nach.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Für ein regional fest verwurzeltes und sehr bekanntes Unternehmen mit ca. 500 Mitarbeitenden und mit Sitz <strong>im Raum Waiblingen</strong> suchen wir Sie als</p>\n<p><strong>Personalsachbearbeiter u./o. Entgeltabrechner (w/m/d) mit Berufserfahrung.</strong></p>\n<p>In Abhängigkeit von Ihrer Qualifikation und Berufserfahrung können Sie hier <strong>bis zu 65.000 € p.a.</strong> verdienen.</p>\n<p>Die <strong>Vollzeitstelle</strong> ist im Rahmen der Personalvermittlung zu besetzen. Bedeutet also: Sie haben von Anfang an ein festes Anstellungsverhältnis mit Ihrem neuen Arbeitgeber, der Sie gerne viele Jahre beschäftigen möchte.</p>\n<p>Der besseren Lesbarkeit wegen richten sich alle folgenden Bezeichnungen an alle Geschlechter.</p>\n<h2>Aufgaben</h2>\n<p><strong>Voilà, so sieht Ihr neuer Job aus!</strong></p>\n<ul>\n<li>Ihr Aufgabenbereich umfasst die Themen Personal (60-70 %) und Entgeltabrechnung (30-40 %)</li>\n<li>U. a. erstellen Sie Arbeitsverträge, Vertragsänderungen, Abmahnungen und Arbeitszeugnisse</li>\n<li>Dabei überwachen Sie auch Fristen</li>\n<li>Für die ca. 500 Mitarbeitenden erstellen Sie die Gehalts- und Lohnabrechnungen inkl. Zuschlägen (auch geringfügig Beschäftigte) und veranlassen die Überweisungen</li>\n<li>Dazu übernehmen Sie das Melde- und Bescheinigungswesen und sind Schnittstelle zu Sozial- und Rentenversicherungsträgern</li>\n<li>Für die von Ihnen betreuten Mitarbeiter sind Sie kompetenter und freundlicher Ansprechpartner</li>\n<li>Sie beraten die Geschäftsführung in arbeits-, steuer- und sozialversicherungsrechtlichen Fragen</li>\n<li>Abschließend übernehmen Sie die Erstellung monatlicher Statistiken.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringen Sie mit</strong>:</p>\n<ul>\n<li>Gute Laune, Lust auf nette Kollegen und Teamarbeit!</li>\n<li>Sie sollten Berufserfahrung entweder in der Entgeltabrechnung oder in der Personalsachbearbeitung mitbringen, idealerweise in beiden Themen. Wenn Sie aber eines der beiden Themen nicht mitbringen, werden Sie darin eingearbeitet</li>\n<li>Sie verfügen über sehr gute Deutschkenntnisse in Wort und Schrift</li>\n<li>Wir verzichten gerne auf die an dieser Stelle üblichen persönlichen Attribute und möchten Sie als Person kennenlernen. Wichtig ist zunächst, dass Sie Lust auf nette Kollegen haben und ein absoluter Teamplayer sind, der sich fachlich gerne weiter entwickeln möchte</li>\n<li>Uns ist klar, dass kaum jemand alle Anforderungen erfüllen wird. Auch Bewerbungen, in denen das nicht der Fall ist, sind herzlich willkommen.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Das bietet Ihnen Ihr neuer Arbeitgeber:</strong></p>\n<ul>\n<li>Flexible Arbeitszeiten</li>\n<li>vermögenswirksame Leistungen</li>\n<li>eine betriebliche Altersvorsorge (bAV)</li>\n<li>einen steuerfreien Personalrabatt</li>\n<li>die gratis Nutzung des betriebsinternen Fitnessstudios</li>\n<li>einen modernen Arbeitsplatz.</li>\n</ul>\n<p><strong>In 3 einfachen Schritten zu Ihrer neuen Anstellung:</strong></p>\n<p>1.) Bewerbungsunterlagen als PDF abspeichern (Verzichten Sie gerne auf ein Anschreiben).</p>\n<p>2.) Bewerbung hier absenden</p>\n<p>3.) Wir setzen uns sehr zeitnah mit Ihnen in Verbindung.</p>\n<p>Bei Fragen steht Ihnen unsere Personalberater Uli Davidsson unter der Rufnummer 0711 / 528 509 - 16 jederzeit gerne zur Verfügung.</p>\n<p><strong>Kann man uns vertrauen? Wir meinen JA!</strong></p>\n<p>Fischer &#x26; Partner ist zum besten Personalvermittler der DACH-Region (Deutschland, Österreich, Schweiz) ausgezeichnet worden. Weiterempfehlungsrate: glatte 100%. Weitere Informationen unter:</p>\n<p><a href=\"https://www.kununu.com/de/fischer-partner-gesellschaft-fuer-personal-mbh/bewerbung?sort=newest\">https://www.kununu.com/de/fischer-partner-gesellschaft-fuer-personal-mbh/bewerbung?sort=newest</a></p>\n<p><strong>Was Sie sonst noch über uns wissen sollten:</strong></p>\n<p>Falls diese Stelle nicht zu Ihnen passen sollte, bewerben Sie sich bitte trotzdem: Wir können Ihnen Stellen als Entgeltabrechner in der Region Stuttgart immer wieder vorschlagen, ebenso als Bilanzbuchhalter, Finanzbuchhalter und Controller.</p>\n<p><strong>Finden Sie weitere attraktive Stellenangebote auf unserer Homepage.</strong></p>\n<p>Für Sie als Bewerber arbeiten wir kostenfrei und mit höchster Diskretion. Bevor wir Sie bei potenziellen Arbeitgebern in anonymisierter Form vorschlagen, sprechen wir immer zuerst mit Ihnen über die jeweilige Stelle! Ohne Ihre Zustimmung unternehmen wir keinen Schritt. Ihre Daten sind bei uns sicher!</p>\n<p><strong>Unser Qualitätsversprechen:</strong> Wir beantworten jede Bewerbung sehr zuverlässig innerhalb von max. drei Werktagen, i.d.R. schneller. Wenn Sie also nach drei Werktagen nichts von uns gehört haben, kann es technische Gründe dafür geben. Bitte haken Sie in diesem Fall bei uns nach.</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-26 13:42:56.725', '2026-06-26 13:42:56.725', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/fischer-partner-gesellschaft-fur-personal-mbh/personalsachbearbeiter-u-o-entgeltabrechner-fur-sehr-bekanntes-unternehmen-stuttgart-211181', 'https://www.arbeitnow.com/jobs/companies/fischer-partner-gesellschaft-fur-personal-mbh/personalsachbearbeiter-u-o-entgeltabrechner-fur-sehr-bekanntes-unternehmen-stuttgart-211181', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/fischer-partner-gesellschaft-fur-personal-mbh/personalsachbearbeiter-u-o-entgeltabrechner-fur-sehr-bekanntes-unternehmen-stuttgart-211181\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1713, NULL, 'api', NULL, 'Leiter Cashmanagement & Liquiditätssteuerung & Finanzen (w/m/d) aus der Immobilienbranche', 'Fischer & Partner Gesellschaft für Personal mbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/fischer-partner-gesellschaft-fur-personal-mbh/leiter-cashmanagement-liquiditatssteuerung-finanzen-aus-der-immobilienbranche-berlin-402676', '<p>Für ein inhabergeführtes Unternehmen, das am Standort Berlin mit ca. 70 Mitarbeitenden überwiegend in der Vermietung und Betreuung von Immobilien tätig ist, ebenso in weiteren Branchen, suchen wir Sie als</p>\n<p><strong>Leiter Cashmanagement &#x26; Liquiditätssteuerung &#x26; Finanzen (w/m/d) mit Berufserfahrung aus der Immobilienprojektentwicklung.</strong></p>\n<p>In Abhängigkeit von Ihrer Berufserfahrung und Ihren Kenntnissen können Sie hier <strong>bis zu 110.000 € p.a.</strong> (20 % variabel) verdienen.</p>\n<p>Die <strong>Vollzeitstelle</strong> ist im Rahmen der Personalvermittlung zu besetzen. Bedeutet also: Sie haben von Anfang an ein festes Anstellungsverhältnis mit Ihrem neuen Arbeitgeber, der Sie gerne viele Jahre beschäftigen möchte.</p>\n<p>Der besseren Lesbarkeit wegen richten sich alle folgenden Bezeichnungen an alle Geschlechter.</p>\n<h2>Aufgaben</h2>\n<p><strong>Voilà, so sieht Ihr neuer Job aus!</strong></p>\n<ul>\n<li>Sie übernehmen die kaufmännische Gesamtverantwortung für einige der verbundenen Unternehmen und sind erster Ansprechpartner rund um die Finanzen und Zahlungsströme der Unternehmensgruppe</li>\n<li>Sie planen und steuern die Liquidität und disponieren die Finanzmittel der verbundenen Unternehmen und überwachen die Bankkonten</li>\n<li>Entsprechend sind die großen Zahlungsströme der Unternehmensgruppe sind bei Ihnen in zuverlässigen Händen</li>\n<li>Sie sind der kompetente Vorbereiter und Verhandler mit den Banken, wenn es um Finanzierungen geht (zwei Abstimmungsgespräche pro Jahr)</li>\n<li>Die Monats- und Jahresabschlüsse, die beim externen Steuerberater erstellt werden, bereiten Sie weitgehend vor. Zudem wirken Sie hands-on mit in der laufenden Finanzbuchhaltung</li>\n<li>Zudem überwachen Sie die Miteinnahmen</li>\n<li>Ergänzend führen und entwickeln Sie ein Team von acht Mitarbeitenden</li>\n<li>Abschließend sind Sie sowohl der kompetente Ansprech- und Sparringspartner für die Geschäftsführung als auch für einige der Geschäftsführer der verbundenen Unternehme</li>\n<li>Ihre Entwicklungsperspektive: Weil sich Unternehmen weiterentwickelt, werden Sie im Laufe der Zeit in weitere Aufgaben hineinwachsen. Nach erfolgreicher Einarbeitung ergibt sich perspektivisch die Übernahme von Geschäftsführungen bei Beteiligungs- bzw. Objektgesellschaften.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringen Sie mit:</strong></p>\n<ul>\n<li>Sie verfügen über mindestens fünf Jahre Berufserfahrung in einer vergleichbaren Position, z. B. als Treasurer</li>\n<li>Ergänzend haben Sie Berufserfahrung in der Immobilienbranche gesammelt</li>\n<li>Sie bringen ein gutes Buchhaltungsverständnis mit, auch auf Grund praktischer Erfahrungen in Zusammenhang mit den Abschlusserstellungen und der laufenden Finanzbuchhaltung</li>\n<li>Für das Vertragswesen bringen Sie zumindest ein gutes Grundverständnis mit oder haben idealerweise praktische Erfahrungen</li>\n<li>Juristisches Verständnis und Kenntnisse im Immobilienrecht wären die Kirsche auf der Torte!</li>\n<li>Sie kommunizieren mündlich und schriftlich in sehr gutem Deutsch</li>\n<li>Wir verzichten gerne auf die an dieser Stelle üblichen persönlichen Attribute und möchten Sie als Person kennenlernen. Wichtig ist zunächst, dass Sie angesichts der Verantwortung äußerst zuverlässig und diskret sind.</li>\n</ul>\n<p><strong>In 3 einfachen Schritten zu Ihrer neuen Anstellung:</strong></p>\n<p>1.) Bewerbungsunterlagen als PDF abspeichern (Verzichten Sie gerne und guten Gewissens auf ein Anschreiben).</p>\n<p>2.) Bewerbung absenden</p>\n<p>3.) Wir setzen uns sehr zeitnah mit Ihnen in Verbindung.</p>\n<p>Bei Fragen steht Ihnen unser Personalberater Herr Uli Davidsson unter der Rufnummer 0711 / 528 509 - 16 jederzeit gerne zur Verfügung.</p>\n<p><strong>Kann man uns vertrauen? Wir meinen JA!</strong></p>\n<p>Fischer &#x26; Partner ist zum besten Personalvermittler der DACH-Region (Deutschland, Österreich, Schweiz) ausgezeichnet worden. Weiterempfehlungsrate: glatte 100%. Weitere Informationen unter:</p>\n<p><a href=\"https://www.kununu.com/de/fischer-partner-gesellschaft-fuer-personal-mbh/bewerbung?sort=newest\">https://www.kununu.com/de/fischer-partner-gesellschaft-fuer-personal-mbh/bewerbung?sort=newest</a></p>\n<p><strong>Was Sie sonst noch über uns wissen sollten:</strong></p>\n<p>Für Sie als Bewerber arbeiten wir <strong>kostenfrei und mit höchster Diskretion</strong>. Bevor wir Sie bei potenziellen Arbeitgebern in anonymisierter Form vorschlagen, sprechen wir immer zuerst mit Ihnen über die jeweilige Stelle! Ohne Ihre Zustimmung unternehmen wir keinen Schritt. Ihre Daten sind bei uns sicher!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Für ein inhabergeführtes Unternehmen, das am Standort Berlin mit ca. 70 Mitarbeitenden überwiegend in der Vermietung und Betreuung von Immobilien tätig ist, ebenso in weiteren Branchen, suchen wir Sie als</p>\n<p><strong>Leiter Cashmanagement &#x26; Liquiditätssteuerung &#x26; Finanzen (w/m/d) mit Berufserfahrung aus der Immobilienprojektentwicklung.</strong></p>\n<p>In Abhängigkeit von Ihrer Berufserfahrung und Ihren Kenntnissen können Sie hier <strong>bis zu 110.000 € p.a.</strong> (20 % variabel) verdienen.</p>\n<p>Die <strong>Vollzeitstelle</strong> ist im Rahmen der Personalvermittlung zu besetzen. Bedeutet also: Sie haben von Anfang an ein festes Anstellungsverhältnis mit Ihrem neuen Arbeitgeber, der Sie gerne viele Jahre beschäftigen möchte.</p>\n<p>Der besseren Lesbarkeit wegen richten sich alle folgenden Bezeichnungen an alle Geschlechter.</p>\n<h2>Aufgaben</h2>\n<p><strong>Voilà, so sieht Ihr neuer Job aus!</strong></p>\n<ul>\n<li>Sie übernehmen die kaufmännische Gesamtverantwortung für einige der verbundenen Unternehmen und sind erster Ansprechpartner rund um die Finanzen und Zahlungsströme der Unternehmensgruppe</li>\n<li>Sie planen und steuern die Liquidität und disponieren die Finanzmittel der verbundenen Unternehmen und überwachen die Bankkonten</li>\n<li>Entsprechend sind die großen Zahlungsströme der Unternehmensgruppe sind bei Ihnen in zuverlässigen Händen</li>\n<li>Sie sind der kompetente Vorbereiter und Verhandler mit den Banken, wenn es um Finanzierungen geht (zwei Abstimmungsgespräche pro Jahr)</li>\n<li>Die Monats- und Jahresabschlüsse, die beim externen Steuerberater erstellt werden, bereiten Sie weitgehend vor. Zudem wirken Sie hands-on mit in der laufenden Finanzbuchhaltung</li>\n<li>Zudem überwachen Sie die Miteinnahmen</li>\n<li>Ergänzend führen und entwickeln Sie ein Team von acht Mitarbeitenden</li>\n<li>Abschließend sind Sie sowohl der kompetente Ansprech- und Sparringspartner für die Geschäftsführung als auch für einige der Geschäftsführer der verbundenen Unternehme</li>\n<li>Ihre Entwicklungsperspektive: Weil sich Unternehmen weiterentwickelt, werden Sie im Laufe der Zeit in weitere Aufgaben hineinwachsen. Nach erfolgreicher Einarbeitung ergibt sich perspektivisch die Übernahme von Geschäftsführungen bei Beteiligungs- bzw. Objektgesellschaften.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringen Sie mit:</strong></p>\n<ul>\n<li>Sie verfügen über mindestens fünf Jahre Berufserfahrung in einer vergleichbaren Position, z. B. als Treasurer</li>\n<li>Ergänzend haben Sie Berufserfahrung in der Immobilienbranche gesammelt</li>\n<li>Sie bringen ein gutes Buchhaltungsverständnis mit, auch auf Grund praktischer Erfahrungen in Zusammenhang mit den Abschlusserstellungen und der laufenden Finanzbuchhaltung</li>\n<li>Für das Vertragswesen bringen Sie zumindest ein gutes Grundverständnis mit oder haben idealerweise praktische Erfahrungen</li>\n<li>Juristisches Verständnis und Kenntnisse im Immobilienrecht wären die Kirsche auf der Torte!</li>\n<li>Sie kommunizieren mündlich und schriftlich in sehr gutem Deutsch</li>\n<li>Wir verzichten gerne auf die an dieser Stelle üblichen persönlichen Attribute und möchten Sie als Person kennenlernen. Wichtig ist zunächst, dass Sie angesichts der Verantwortung äußerst zuverlässig und diskret sind.</li>\n</ul>\n<p><strong>In 3 einfachen Schritten zu Ihrer neuen Anstellung:</strong></p>\n<p>1.) Bewerbungsunterlagen als PDF abspeichern (Verzichten Sie gerne und guten Gewissens auf ein Anschreiben).</p>\n<p>2.) Bewerbung absenden</p>\n<p>3.) Wir setzen uns sehr zeitnah mit Ihnen in Verbindung.</p>\n<p>Bei Fragen steht Ihnen unser Personalberater Herr Uli Davidsson unter der Rufnummer 0711 / 528 509 - 16 jederzeit gerne zur Verfügung.</p>\n<p><strong>Kann man uns vertrauen? Wir meinen JA!</strong></p>\n<p>Fischer &#x26; Partner ist zum besten Personalvermittler der DACH-Region (Deutschland, Österreich, Schweiz) ausgezeichnet worden. Weiterempfehlungsrate: glatte 100%. Weitere Informationen unter:</p>\n<p><a href=\"https://www.kununu.com/de/fischer-partner-gesellschaft-fuer-personal-mbh/bewerbung?sort=newest\">https://www.kununu.com/de/fischer-partner-gesellschaft-fuer-personal-mbh/bewerbung?sort=newest</a></p>\n<p><strong>Was Sie sonst noch über uns wissen sollten:</strong></p>\n<p>Für Sie als Bewerber arbeiten wir <strong>kostenfrei und mit höchster Diskretion</strong>. Bevor wir Sie bei potenziellen Arbeitgebern in anonymisierter Form vorschlagen, sprechen wir immer zuerst mit Ihnen über die jeweilige Stelle! Ohne Ihre Zustimmung unternehmen wir keinen Schritt. Ihre Daten sind bei uns sicher!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-26 13:43:04.206', '2026-06-26 13:43:04.206', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/fischer-partner-gesellschaft-fur-personal-mbh/leiter-cashmanagement-liquiditatssteuerung-finanzen-aus-der-immobilienbranche-berlin-402676', 'https://www.arbeitnow.com/jobs/companies/fischer-partner-gesellschaft-fur-personal-mbh/leiter-cashmanagement-liquiditatssteuerung-finanzen-aus-der-immobilienbranche-berlin-402676', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/fischer-partner-gesellschaft-fur-personal-mbh/leiter-cashmanagement-liquiditatssteuerung-finanzen-aus-der-immobilienbranche-berlin-402676\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1714, NULL, 'api', NULL, 'IT-Systemadministrator (m/w/d)', 'Nord-Ostsee Automobile', 'Neumünster', 'https://www.arbeitnow.com/jobs/companies/nord-ostsee-automobile/it-systemadministrator-neumunster-236820', '<h3>Lust auf Leistung</h3><p><span style=\"color: #111111\">Nord-Ostsee Automobile ist Teil der internationalen Van Mossel Automotive Group, einer der erfolgreichsten Automobilhandelsgruppen Europas. Gemeinsam verbinden wir regionale Stärke mit internationaler Kompetenz und gestalten die Mobilität von morgen.</span></p><p><span style=\"color: #111111\"> </span></p><p><span style=\"color: #111111\">Mit den Marken Mercedes-Benz, AMG, Aston Martin, Hyundai, smart, IVECO und weiteren starken Partnern bieten wir unseren Kundinnen und Kunden ein umfassendes Mobilitätsangebot. Dabei stehen für uns exzellenter Service, Innovation und nachhaltige Kundenbeziehungen im Mittelpunkt.</span></p><p><span style=\"color: #111111\"> </span></p><p><span style=\"color: #111111\">Als Arbeitgeber setzen wir auf Vertrauen, Eigenverantwortung und Entwicklungsmöglichkeiten. Wir schaffen ein Umfeld, in dem Menschen ihre Stärken einbringen, sich weiterentwickeln und gemeinsam Erfolge erzielen können.</span></p><h4></h4><h3>Werden Sie Teil unseres IT-Teams und gestalten Sie die digitale Zukunft unseres Unternehmens aktiv mit.</h3><p><span style=\"color: #000000\">Moderne IT-Infrastrukturen, stabile Systeme und innovative Technologien begeistern Sie? Dann bringen Sie Ihr Know-how bei uns ein. Als IT-Systemadministrator (m/w/d) sorgen Sie gemeinsam mit unserem Team dafür, dass unsere IT-Landschaft zuverlässig, sicher und zukunftsfähig bleibt. Sie übernehmen Verantwortung für den Betrieb unserer Systeme, unterstützen unsere Anwenderinnen und Anwender bei komplexen Fragestellungen und treiben die Weiterentwicklung unserer IT aktiv voran. Bewerben Sie sich jetzt und werden Sie Teil unseres starken und wachsenden IT-Bereichs innerhalb der Van Mossel Automotive Group.<br /></span></p><p style=\";\"></p><h3 style=\"text-align: center;\"><strong><span style=\"color: #ffc320\">Das ist Ihr Auftrag</span></strong></h3><p style=\";\"></p><ul><li><p><strong><span style=\"color: #000000\">Technischer Support auf hohem Niveau</span></strong><span style=\"color: #000000\"><br />Sie übernehmen den Second- und Third-Level-Support für komplexe technische Anfragen und sorgen für nachhaltige und effiziente Lösungen.</span></p></li><li><p><strong><span style=\"color: #000000\">Administration unserer IT-Systeme</span></strong><span style=\"color: #000000\"><br />Sie betreuen und administrieren unsere Windows-Serverlandschaft, Active Directory-Strukturen sowie zentrale Applikationen innerhalb einer virtualisierten IT-Umgebung.</span></p></li><li><p><strong><span style=\"color: #000000\">Analyse und Fehlerbehebung</span></strong><span style=\"color: #000000\"><br />Sie analysieren komplexe IT-Störungen, identifizieren Ursachen und begleiten Anwenderinnen und Anwender bis zur erfolgreichen Problemlösung.</span></p></li><li><p><strong><span style=\"color: #000000\">Automatisierung und Optimierung</span></strong><span style=\"color: #000000\"><br />Sie entwickeln und optimieren Prozesse durch den Einsatz von PowerShell-Skripten und tragen so zur Effizienzsteigerung unserer IT bei.</span></p></li><li><p><strong><span style=\"color: #000000\">Mitwirkung an IT-Projekten</span></strong><span style=\"color: #000000\"><br />Sie unterstützen bei der Planung, Umsetzung und Weiterentwicklung unternehmensweiter IT-Projekte und bringen eigene Ideen zur Modernisierung unserer Systemlandschaft ein.</span></p></li><li><p><strong><span style=\"color: #000000\">Netzwerk- und Hardwarebetreuung</span></strong><span style=\"color: #000000\"><br />Sie betreuen unser Unternehmensnetzwerk, konfigurieren und warten IT-Hardware und begleiten die Einführung neuer Systeme und Komponenten.</span></p></li><li><p><strong><span style=\"color: #000000\">Dokumentation und Wissensmanagement</span></strong><span style=\"color: #000000\"><br />Sie dokumentieren Lösungen, Prozesse und Fehlerbilder strukturiert und schaffen damit eine nachhaltige Wissensbasis für das gesamte Team.</span></p><p style=\";\"></p></li></ul><br /><br /><h3 style=\"text-align: center;\"><strong><span style=\"\">Das bringen Sie mit</span></strong></h3><p style=\";\"></p><ul><li><p><span style=\"color: #000000\">Sie verfügen über eine abgeschlossene Ausbildung im IT-Bereich, beispielsweise als Fachinformatiker für Systemintegration (m/w/d), oder über eine vergleichbare Qualifikation.</span></p></li><li><p><span style=\"color: #000000\">Sie konnten bereits Berufserfahrung in der Systemadministration oder im IT-Support sammeln.</span></p></li><li><p><span style=\"color: #000000\">Sie besitzen fundierte Kenntnisse im Umgang mit Windows-Server-Systemen, Active Directory und Virtualisierungstechnologien.</span></p></li><li><p><span style=\"color: #000000\">Erfahrungen mit PowerShell-Scripting sowie der Automatisierung von Prozessen sind wünschenswert.</span></p></li><li><p><span style=\"color: #000000\">Sie arbeiten strukturiert, verantwortungsbewusst und behalten auch bei mehreren parallelen Aufgaben den Überblick.</span></p></li><li><p><span style=\"color: #000000\">Komplexe technische Zusammenhänge können Sie verständlich erklären und adressatengerecht kommunizieren.</span></p></li><li><p><span style=\"color: #000000\">Sie zeichnen sich durch eine hohe Serviceorientierung, Lösungsstärke und Eigeninitiative aus.</span></p></li><li><p><span style=\"color: #000000\">Neuen Technologien und Veränderungen stehen Sie offen gegenüber und bringen sich aktiv in die Weiterentwicklung unserer IT-Landschaft ein.</span></p></li><li><p><span style=\"color: #000000\">Teamarbeit ist für Sie selbstverständlich. Gleichzeitig bringen Sie Eigeninitiative mit, denken lösungsorientiert und gehen neue Aufgaben offen und engagiert an.</span></p></li><li><p><span style=\"color: #000000\">Sie haben Freude daran, Service auf hohem Niveau zu bieten und möchten gemeinsam mit uns jeden Tag ein positives Kundenerlebnis schaffen.</span></p></li><li><p><span style=\"color: #000000\">Sie haben Lust auf Leistung und sehen Veränderungen als Chancen.</span></p><p style=\";\"></p></li></ul><h3 style=\"text-align: center;\"><strong><span style=\"\">Mehr als ein Job – das erwartet Sie bei uns</span></strong></h3><p style=\";\"></p><p><span style=\"color: #020202\">Nord-Ostsee Automobile steht für Qualität, Innovation und Premium-Service – und genau das leben wir jeden Tag. Bei uns erwartet Sie ein Umfeld, das Leistung fördert, Entwicklung ermöglicht und Wertschätzung spürbar macht.</span></p><p><span style=\"color: #020202\"> </span></p><ul><li><p><span style=\"color: #020202\">Zukunftsorientiertes Arbeiten: Ein modernes Arbeitsumfeld mit neuester Technik und digitalen Tools</span></p></li><li><p><span style=\"color: #020202\">Weiterkommen statt stehen bleiben: Individuelle Weiterbildungen, Schulungen und echte Entwicklungsperspektiven in einem wachsenden Unternehmen</span></p></li><li><p><span style=\"color: #020202\">Mehr drin für Sie: Attraktive Vergütung nach Haustarif, Urlaubs- und Weihnachtsgeld, betriebliche Altersvorsorge, vermögenswirksame Leistungen, &amp; Corporate Benefits sowie exklusive Mitarbeiterrabatte auf Fahrzeuge, Teile und Services</span></p></li><li><p><span style=\"color: #020202\">Auch mal abschalten: 30 Tage Urlaub sowie Zusatzurlaub bei besonderen Lebensereignissen</span></p></li><li><p><span style=\"color: #020202\">Gesund &amp; fit im Alltag: Betriebliches Gesundheitsmanagement, Gesundheitsangebote, Sportevents, Mental Health Coaching, Bike-Leasing sowie kostenlose Getränke und frisches Obst</span></p></li><li><p><span style=\"color: #020202\">Auch an morgen gedacht: Ausbildungsplatzgarantie für die Kinder unserer Mitarbeitenden</span></p></li><li><p><span style=\"color: #020202\">Gut ankommen im Team: Strukturierte Einarbeitung und Onboarding-Day für neue Kolleginnen und Kollegen</span></p></li><li><p><span style=\"color: #020202\">Ein Team, das zusammenhält: Mitarbeiterevents (z. B. Weihnachtsfeier, Grillen, Teamevents) und ein kollegiales Arbeitsumfeld mit starkem Teamgeist</span></p></li><li><p><span style=\"color: #121317\">Langfristige Perspektive: Ein</span><span style=\"color: #020202\"> sicherer Arbeitsplatz in einem erfolgreichen Unternehmen</span></p><p style=\";\"></p></li></ul><h3 style=\"text-align: center;\"><strong><span style=\"\">Gestalten Sie mit uns Mobilität auf hohem Niveau</span></strong></h3><p style=\";\"></p><p><span style=\"color: #121317\">Klingt nach dem richtigen Umfeld für Sie? Dann freuen wir uns darauf, Sie kennenzulernen! </span></p><p><span style=\"color: #020202\">Bewerben Sie sich jetzt hier über unsere Karriereseite mit Ihren vollständigen Unterlagen und werden Sie Teil unseres Teams.</span></p><br /><br /><p>Typ: Angestellte/r</p><p>Marke: Allgemein</p><p>Erfahrungsniveau: Mittleres Niveau</p><p>Kontaktstelle: .</p><p>Besetzung ab: 2026-07-01</p><p>Ansprechpartner Recruiting: Sina Pluth</p><p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<h3>Lust auf Leistung</h3><p><span style=\"color: #111111\">Nord-Ostsee Automobile ist Teil der internationalen Van Mossel Automotive Group, einer der erfolgreichsten Automobilhandelsgruppen Europas. Gemeinsam verbinden wir regionale Stärke mit internationaler Kompetenz und gestalten die Mobilität von morgen.</span></p><p><span style=\"color: #111111\"> </span></p><p><span style=\"color: #111111\">Mit den Marken Mercedes-Benz, AMG, Aston Martin, Hyundai, smart, IVECO und weiteren starken Partnern bieten wir unseren Kundinnen und Kunden ein umfassendes Mobilitätsangebot. Dabei stehen für uns exzellenter Service, Innovation und nachhaltige Kundenbeziehungen im Mittelpunkt.</span></p><p><span style=\"color: #111111\"> </span></p><p><span style=\"color: #111111\">Als Arbeitgeber setzen wi