(1874, NULL, 'api', NULL, 'SAP Success Factors Consultant', 'Pertemps ERP', 'Frankfurt am Main', 'https://www.arbeitnow.com/jobs/companies/pertemps-erp/sap-success-factors-consultant-frankfurt-am-main-336790', '<p>Remote in Deutschland | Vollzeit</p>\n<p>Für unseren Kunden, ein international führendes IT- und Beratungsunternehmen, suchen wir einen erfahrenen <strong>SAP SuccessFactors Solution Architect (m/w/d)</strong> zur Unterstützung spannender HR-Transformationsprojekte.</p>\n<p><strong>Das Angebot</strong></p>\n<ul>\n<li>100 % Remote-Arbeit innerhalb Deutschlands</li>\n<li>Spannende nationale und internationale Projekte</li>\n<li>Attraktive Vergütung und Entwicklungsmöglichkeiten</li>\n<li>Modernes Arbeitsumfeld mit neuesten SAP-Technologien</li>\n</ul>\n<h2>Aufgaben</h2>\n<ul>\n<li>Verantwortung für die Lösungsarchitektur in SAP SuccessFactors-Projekten</li>\n<li>Analyse von Kundenanforderungen und Entwicklung von End-to-End-Lösungen</li>\n<li>Konzeption von Integrationen zu SAP S/4HANA, SAP HCM und Drittsystemen</li>\n<li>Steuerung und Abstimmung architektonischer Themen über mehrere Module hinweg</li>\n<li>Durchführung von Workshops und Präsentationen für Kunden und Projektteams</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Mehrjährige Erfahrung mit SAP SuccessFactors, idealerweise als Solution Architect oder Lead Consultant</li>\n<li>Fundierte Kenntnisse der SuccessFactors Suite und deren Integrationsmöglichkeiten</li>\n<li>Erfahrung mit SAP S/4HANA oder SAP HCM</li>\n<li>Ausgeprägte Kommunikations- und Beratungsfähigkeiten</li>\n<li>Sehr gute Deutsch- und Englischkenntnisse</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Remote in Deutschland | Vollzeit</p>\n<p>Für unseren Kunden, ein international führendes IT- und Beratungsunternehmen, suchen wir einen erfahrenen <strong>SAP SuccessFactors Solution Architect (m/w/d)</strong> zur Unterstützung spannender HR-Transformationsprojekte.</p>\n<p><strong>Das Angebot</strong></p>\n<ul>\n<li>100 % Remote-Arbeit innerhalb Deutschlands</li>\n<li>Spannende nationale und internationale Projekte</li>\n<li>Attraktive Vergütung und Entwicklungsmöglichkeiten</li>\n<li>Modernes Arbeitsumfeld mit neuesten SAP-Technologien</li>\n</ul>\n<h2>Aufgaben</h2>\n<ul>\n<li>Verantwortung für die Lösungsarchitektur in SAP SuccessFactors-Projekten</li>\n<li>Analyse von Kundenanforderungen und Entwicklung von End-to-End-Lösungen</li>\n<li>Konzeption von Integrationen zu SAP S/4HANA, SAP HCM und Drittsystemen</li>\n<li>Steuerung und Abstimmung architektonischer Themen über mehrere Module hinweg</li>\n<li>Durchführung von Workshops und Präsentationen für Kunden und Projektteams</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Mehrjährige Erfahrung mit SAP SuccessFactors, idealerweise als Solution Architect oder Lead Consultant</li>\n<li>Fundierte Kenntnisse der SuccessFactors Suite und deren Integrationsmöglichkeiten</li>\n<li>Erfahrung mit SAP S/4HANA oder SAP HCM</li>\n<li>Ausgeprägte Kommunikations- und Beratungsfähigkeiten</li>\n<li>Sehr gute Deutsch- und Englischkenntnisse</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-29 13:42:50.796', '2026-06-29 13:42:50.796', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/pertemps-erp/sap-success-factors-consultant-frankfurt-am-main-336790', 'https://www.arbeitnow.com/jobs/companies/pertemps-erp/sap-success-factors-consultant-frankfurt-am-main-336790', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/pertemps-erp/sap-success-factors-consultant-frankfurt-am-main-336790\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
