(1879, NULL, 'api', NULL, 'Shopify Entwickler:in / Shopify Programmer (m/w/d)', 'Nature Heart GmbH & Co KG', 'Nidderau', 'https://www.arbeitnow.com/jobs/companies/nature-heart-gmbh-co-kg/shopify-entwicklerin-shopify-programmer-nidderau-179293', '<h2>Deine Aufgaben</h2>\n<ul>\n<li>Entwicklung und Wartung von Shopify Apps (Custom Apps &#x26; Erweiterungen)</li>\n<li>Umsetzung von Backend-Logiken (z. B. Warenkorb-Logik, Bundles, Upsells, Discounts, Automationen)</li>\n<li>Arbeit mit Shopify APIs (REST &#x26; GraphQL), Webhooks und externen Services</li>\n<li>Anbindung und Integration externer Tools, Payment-, Versand- oder Marketing-Systeme</li>\n<li>Technische Konzeption neuer Features inkl. Datenmodellierung</li>\n<li>Frontend-Umsetzung der entwickelten Logiken in Shopify Themes (Liquid, JS, CSS)</li>\n<li>Enge Zusammenarbeit mit Design, Marketing &#x26; Produkt</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>Erfahrung in der Shopify App- oder Backend-Entwicklung</li>\n<li>Sehr gute Kenntnisse in Shopify APIs, Webhooks &#x26; App-Architekturen</li>\n<li>Erfahrung mit Backend-Stacks wie Node.js oder vergleichbar</li>\n<li>Sicherer Umgang mit Liquid, JavaScript, CSS &#x26; HTML für die Frontend-Integration</li>\n<li>Verständnis für E-Commerce-Flows, Performance &#x26; Skalierbarkeit</li>\n<li>Strukturierte, saubere und dokumentierte Arbeitsweise</li>\n<li>Eigenständiges Denken, Lösungsorientierung und hoher Qualitätsanspruch</li>\n<li>Erfahrung mit Git, CI/CD und modernen Entwicklungsprozessen von Vorteil</li>\n</ul>\n<h2>Wir bieten</h2>\n<ul>\n<li>100 % Remote-Arbeit</li>\n<li>Faire, leistungsorientierte Bezahlung</li>\n<li>Langfristige Zusammenarbeit in einem wachsenden Premium-Brand</li>\n<li>Technisch anspruchsvolle Projekte mit viel Gestaltungsspielraum</li>\n<li>Klare Prozesse, kurze Entscheidungswege, keine Agentur-Hektik</li>\n<li>Zusammenarbeit auf Augenhöhe in einem fokussierten, motivierten Team</li>\n<li>Möglichkeit, Kernsysteme und Architektur aktiv mitzugestalten</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<h2>Deine Aufgaben</h2>\n<ul>\n<li>Entwicklung und Wartung von Shopify Apps (Custom Apps &#x26; Erweiterungen)</li>\n<li>Umsetzung von Backend-Logiken (z. B. Warenkorb-Logik, Bundles, Upsells, Discounts, Automationen)</li>\n<li>Arbeit mit Shopify APIs (REST &#x26; GraphQL), Webhooks und externen Services</li>\n<li>Anbindung und Integration externer Tools, Payment-, Versand- oder Marketing-Systeme</li>\n<li>Technische Konzeption neuer Features inkl. Datenmodellierung</li>\n<li>Frontend-Umsetzung der entwickelten Logiken in Shopify Themes (Liquid, JS, CSS)</li>\n<li>Enge Zusammenarbeit mit Design, Marketing &#x26; Produkt</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>Erfahrung in der Shopify App- oder Backend-Entwicklung</li>\n<li>Sehr gute Kenntnisse in Shopify APIs, Webhooks &#x26; App-Architekturen</li>\n<li>Erfahrung mit Backend-Stacks wie Node.js oder vergleichbar</li>\n<li>Sicherer Umgang mit Liquid, JavaScript, CSS &#x26; HTML für die Frontend-Integration</li>\n<li>Verständnis für E-Commerce-Flows, Performance &#x26; Skalierbarkeit</li>\n<li>Strukturierte, saubere und dokumentierte Arbeitsweise</li>\n<li>Eigenständiges Denken, Lösungsorientierung und hoher Qualitätsanspruch</li>\n<li>Erfahrung mit Git, CI/CD und modernen Entwicklungsprozessen von Vorteil</li>\n</ul>\n<h2>Wir bieten</h2>\n<ul>\n<li>100 % Remote-Arbeit</li>\n<li>Faire, leistungsorientierte Bezahlung</li>\n<li>Langfristige Zusammenarbeit in einem wachsenden Premium-Brand</li>\n<li>Technisch anspruchsvolle Projekte mit viel Gestaltungsspielraum</li>\n<li>Klare Prozesse, kurze Entscheidungswege, keine Agentur-Hektik</li>\n<li>Zusammenarbeit auf Augenhöhe in einem fokussierten, motivierten Team</li>\n<li>Möglichkeit, Kernsysteme und Architektur aktiv mitzugestalten</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-30 01:39:48.658', '2026-06-30 01:39:48.658', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/nature-heart-gmbh-co-kg/shopify-entwicklerin-shopify-programmer-nidderau-179293', 'https://www.arbeitnow.com/jobs/companies/nature-heart-gmbh-co-kg/shopify-entwicklerin-shopify-programmer-nidderau-179293', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/nature-heart-gmbh-co-kg/shopify-entwicklerin-shopify-programmer-nidderau-179293\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1880, NULL, 'api', NULL, 'Communication Manager – Brand, Content & Technology  (60 – 100%)', 'Ing Plus AG', 'Fürth', 'https://www.arbeitnow.com/jobs/companies/ing-plus-ag/communication-manager-brand-content-technology-60-100-furth-476860', '<p>Ing.Plus ist Spezialist für intelligente Prozessautomatisierung im Tiefbau und unterstützt Netzbetreiber sowie Ingenieurbüros mit einsatzbereiten, datengetriebenen Lösungen für das sichere, effiziente und nachhaltige Management von Infrastrukturnetzen.</p>\n<p>Durch den Einsatz moderner Technologien verwandeln wir komplexe Informationen in transparente und nutzbare Daten, die eine präzise Entscheidungsfindung und strategische Handlungsempfehlungen ermöglichen. Von der Zustandserfassung bis zum reibungslosen Betrieb helfen unsere Lösungen dabei, Abläufe zu vereinfachen, Personal zu entlasten sowie wertvolle Zeit und Ressourcen einzusparen.</p>\n<p>Dabei setzen wir auf einen ganzheitlichen Ansatz aus digitaler und persönlicher Unterstützung. Unser hybrides Service-Konzept garantiert umfassende Entlastung bei der Datenarbeit sowie kompetente Beratung durch langjährige Erfahrung und tiefgreifendes Fachwissen im Bereich Geoinformationssysteme.</p>\n<p><strong>Wir denken heute die Infrastruktur von morgen und suchen Teamplayer, die Verantwortung übernehmen und mit uns etwas bewegen wollen. Für die Weiterentwicklung unserer B2G-Marken- und Vertriebskommunikation besetzen wir eine zentrale Schnittstelle zwischen Sales und Design. Du übersetzt komplexe Technologien in verständliche Kommunikation und gestaltest die Markenbotschaften sowie die strategische Weiterentwicklung unserer Kommunikation aktiv mit.</strong></p>\n<p><strong>Dein Aufgabenbereich</strong></p>\n<ul>\n<li><strong>Markenkommunikation</strong><br>\nDu schärfst unsere Markenkommunikation und stärkst eine konsistente Brand Voice über alle Kanäle hinweg</li>\n<li><strong>Strategie &#x26; Positionierung</strong><br>\nDu entwickelst bestehende Content-, Messaging-, Positionierungs- und Kommunikationsstrukturen kontinuierlich weiter</li>\n<li><strong>Technologieübersetzung</strong><br>\nDu übersetzt komplexe Marken-, Produkt- und Prozessinhalte sowie Funktionen und Anwendungsfälle unserer Softwarelösungen zielgerichtet in klar strukturierte und verständliche Sprache</li>\n<li><strong>Content &#x26; Copywriting</strong><br>\nDu formulierst fachlich fundierte Inhalte, entwickelst prägnante Botschaften und vermittelst technologische Zusammenhänge durch zielgruppengerechtes Copywriting verständlich und präzise</li>\n<li><strong>Kommunikationsmanagement</strong><br>\nDu erkennst Kommunikationsbedarf frühzeitig und entwickelst proaktiv Lösungsansätze</li>\n<li><strong>Kanal- &#x26; Formatentwicklung</strong><br>\nDu konzipierst und erstellst hochwertige Inhalte für Unternehmens-, Produkt- und Vertriebskommunikation – von Website und LinkedIn über Fachbeiträge bis hin zu Präsentationen und Pitchdecks</li>\n<li><strong>Interdisziplinäre Zusammenarbeit</strong><br>\nDu arbeitest eng mit Sales und Design zusammen und sorgst dafür, dass Inhalt und Gestaltung präzise ineinandergreifen</li>\n</ul>\n<p><strong>Dein Profil</strong></p>\n<ul>\n<li><strong>Kommunikationsexpertise</strong><br>\nDu bringst mehrjährige Erfahrung in Unternehmenskommunikation, Corporate Communications, Content Marketing, Redaktion oder Technologiemarketing mit – idealerweise im Umfeld erklärungsbedürftiger Technologien, Softwarelösungen oder datengetriebener Anwendungen</li>\n<li><strong>Marketingverständnis</strong><br>\nDu denkst Kommunikation nicht nur inhaltlich, sondern auch aus Marketing- und Vertriebsperspektive</li>\n<li><strong>Technologieaffinität</strong><br>\nDu besitzt eine ausgeprägte Technologieaffinität und hast Freude daran, digitale Produkte, Softwarefunktionen und technische Zusammenhänge zu verstehen und verständlich zu kommunizieren</li>\n<li><strong>Sprachkompetenz</strong><br>\nDu verfügst über ein sehr gutes Sprachgefühl sowie Ausdrucksvermögen und schaffst durch strukturierte Kommunikation und klares Storytelling Verständlichkeit und Vertrauen</li>\n<li><strong>Zielgruppenverständnis</strong><br>\nDu kannst unterschiedliche Kommunikationsebenen gezielt bedienen – von verständlicher Orientierung bis zur fachlichen und technologischen Tiefe</li>\n<li><strong>Arbeitsweise</strong><br>\nDu arbeitest eigenständig, strukturiert und denkst in Zusammenhängen statt in Aufgabenlisten</li>\n<li><strong>Qualitätsanspruch</strong><br>\nDu hast einen sehr hohen Qualitätsanspruch und ein starkes Auge fürs Detail</li>\n<li><strong>Zusatzkenntnisse</strong><br>\nGrundkenntnisse in Figma sowie UX-Writing und SEO von Vorteil</li>\n</ul>\n<p><strong>Unsere Benefits</strong></p>\n<p>Bei Ing.Plus ist jedes Teammitglied von großer Bedeutung für gemeinsame Erfolge. Deshalb engagieren wir uns nicht nur für ressourcenschonende Umweltziele, sondern auch für nachhaltige Arbeitskonzepte – ausgerichtet an den Eckpfeilern moderner New Work Methoden. Ob flexible Arbeitszeiten für eine ausgewogene Work-Life-Balance oder Gestaltungsspielraum für persönliches Wachstum – wir verstehen, dass Bedürfnisse ebenso vielfältig sind wie die Menschen selbst und gestalten individuell und dynamisch.</p>\n<p><strong>Freiheit &#x26; Flexibilität:</strong></p>\n<ul>\n<li><strong>Flexible Arbeitszeiten</strong><br>\nOrganisiere deinen Arbeitstag nach deinen Bedürfnissen und Präferenzen</li>\n<li><strong>Mobiles Arbeiten</strong><br>\nGenieße die Freiheit, von überall aus zu arbeiten – sei es von zu Hause, im Büro oder unterwegs</li>\n<li><strong>Gleitzeit</strong><br>\nPasse deine Arbeitszeiten flexibel an, um persönliche Termine und Verpflichtungen zu berücksichtigen</li>\n<li><strong>Urlaub</strong><br>\nVerfüge über 30 Urlaubstage, um deine Erholung und Freizeit zu genießen und neue Energie zu tanken</li>\n<li><strong>Workation</strong><br>\nEntdecke die Welt und verbinde Arbeiten mit Urlaubsreisen</li>\n<li><strong>Arbeitszeitkonto</strong><br>\nBaue Überstunden flexibel ab, wann immer du es brauchst</li>\n<li><strong>Teilzeit oder Vollzeit</strong><br>\nVon 60 bis 100% – vereinbare deinen Beruf mit deinem individuellen Lebensmodell</li>\n</ul>\n<p><strong>Entwicklung &#x26; Förderung:</strong></p>\n<ul>\n<li><strong>Kurse &#x26; Workshops</strong><br>\nNutze Weiterbildungsangebote, um neue Fähigkeiten zu erlernen</li>\n<li><strong>Zertifizierungen</strong><br>\nErhalte finanzielle Unterstützung für das Erreichen anerkannter beruflicher Qualifikationen</li>\n</ul>\n<p><strong>Gesundheit &#x26; Vorsorge:</strong></p>\n<ul>\n<li><strong>Betriebliche Krankenversicherung</strong><br>\nSorge aktiv für dich vor und freue dich über zahlreiche zusätzliche Leistungen</li>\n<li><strong>Private Unfallversicherung</strong><br>\nSichere dich ab und bewahre dir deine finanzielle Stabilität</li>\n<li><strong>Berufliche Altersvorsorge</strong><br>\nInvestiere in deine Zukunft und zähle dabei auf unsere Unterstützung</li>\n<li><strong>JobRad®</strong><br>\nLease dein Wunschrad mit steuerlichen Vorteilen und monatlichem Zuschuss</li>\n</ul>\n<p><strong>Gemeinschaft &#x26; Miteinander:</strong></p>\n<ul>\n<li><strong>Teamgeist</strong><br>\nNimm an Sommerfesten, Weihnachtsfeiern und Team-Ausflügen teil, um den Zusammenhalt zu stärken</li>\n<li><strong>Innovationsprojekte</strong><br>\nEngagiere dich in Innovationsprojekten und bringe deine Ideen aktiv ein</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Ing.Plus ist Spezialist für intelligente Prozessautomatisierung im Tiefbau und unterstützt Netzbetreiber sowie Ingenieurbüros mit einsatzbereiten, datengetriebenen Lösungen für das sichere, effiziente und nachhaltige Management von Infrastrukturnetzen.</p>\n<p>Durch den Einsatz moderner Technologien verwandeln wir komplexe Informationen in transparente und nutzbare Daten, die eine präzise Entscheidungsfindung und strategische Handlungsempfehlungen ermöglichen. Von der Zustandserfassung bis zum reibungslosen Betrieb helfen unsere Lösungen dabei, Abläufe zu vereinfachen, Personal zu entlasten sowie wertvolle Zeit und Ressourcen einzusparen.</p>\n<p>Dabei setzen wir auf einen ganzheitlichen Ansatz aus digitaler und persönlicher Unterstützung. Unser hybrides Service-Konzept garantiert umfassende Entlastung bei der Datenarbeit sowie kompetente Beratung durch langjährige Erfahrung und tiefgreifendes Fachwissen im Bereich Geoinformationssysteme.</p>\n<p><strong>Wir denken heute die Infrastruktur von morgen und suchen Teamplayer, die Verantwortung übernehmen und mit uns etwas bewegen wollen. Für die Weiterentwicklung unserer B2G-Marken- und Vertriebskommunikation besetzen wir eine zentrale Schnittstelle zwischen Sales und Design. Du übersetzt komplexe Technologien in verständliche Kommunikation und gestaltest die Markenbotschaften sowie die strategische Weiterentwicklung unserer Kommunikation aktiv mit.</strong></p>\n<p><strong>Dein Aufgabenbereich</strong></p>\n<ul>\n<li><strong>Markenkommunikation</strong><br>\nDu schärfst unsere Markenkommunikation und stärkst eine konsistente Brand Voice über alle Kanäle hinweg</li>\n<li><strong>Strategie &#x26; Positionierung</strong><br>\nDu entwickelst bestehende Content-, Messaging-, Positionierungs- und Kommunikationsstrukturen kontinuierlich weiter</li>\n<li><strong>Technologieübersetzung</strong><br>\nDu übersetzt komplexe Marken-, Produkt- und Prozessinhalte sowie Funktionen und Anwendungsfälle unserer Softwarelösungen zielgerichtet in klar strukturierte und verständliche Sprache</li>\n<li><strong>Content &#x26; Copywriting</strong><br>\nDu formulierst fachlich fundierte Inhalte, entwickelst prägnante Botschaften und vermittelst technologische Zusammenhänge durch zielgruppengerechtes Copywriting verständlich und präzise</li>\n<li><strong>Kommunikationsmanagement</strong><br>\nDu erkennst Kommunikationsbedarf frühzeitig und entwickelst proaktiv Lösungsansätze</li>\n<li><strong>Kanal- &#x26; Formatentwicklung</strong><br>\nDu konzipierst und erstellst hochwertige Inhalte für Unternehmens-, Produkt- und Vertriebskommunikation – von Website und LinkedIn über Fachbeiträge bis hin zu Präsentationen und Pitchdecks</li>\n<li><strong>Interdisziplinäre Zusammenarbeit</strong><br>\nDu arbeitest eng mit Sales und Design zusammen und sorgst dafür, dass Inhalt und Gestaltung präzise ineinandergreifen</li>\n</ul>\n<p><strong>Dein Profil</strong></p>\n<ul>\n<li><strong>Kommunikationsexpertise</strong><br>\nDu bringst mehrjährige Erfahrung in Unternehmenskommunikation, Corporate Communications, Content Marketing, Redaktion oder Technologiemarketing mit – idealerweise im Umfeld erklärungsbedürftiger Technologien, Softwarelösungen oder datengetriebener Anwendungen</li>\n<li><strong>Marketingverständnis</strong><br>\nDu denkst Kommunikation nicht nur inhaltlich, sondern auch aus Marketing- und Vertriebsperspektive</li>\n<li><strong>Technologieaffinität</strong><br>\nDu besitzt eine ausgeprägte Technologieaffinität und hast Freude daran, digitale Produkte, Softwarefunktionen und technische Zusammenhänge zu verstehen und verständlich zu kommunizieren</li>\n<li><strong>Sprachkompetenz</strong><br>\nDu verfügst über ein sehr gutes Sprachgefühl sowie Ausdrucksvermögen und schaffst durch strukturierte Kommunikation und klares Storytelling Verständlichkeit und Vertrauen</li>\n<li><strong>Zielgruppenverständnis</strong><br>\nDu kannst unterschiedliche Kommunikationsebenen gezielt bedienen – von verständlicher Orientierung bis zur fachlichen und technologischen Tiefe</li>\n<li><strong>Arbeitsweise</strong><br>\nDu arbeitest eigenständig, strukturiert und denkst in Zusammenhängen statt in Aufgabenlisten</li>\n<li><strong>Qualitätsanspruch</strong><br>\nDu hast einen sehr hohen Qualitätsanspruch und ein starkes Auge fürs Detail</li>\n<li><strong>Zusatzkenntnisse</strong><br>\nGrundkenntnisse in Figma sowie UX-Writing und SEO von Vorteil</li>\n</ul>\n<p><strong>Unsere Benefits</strong></p>\n<p>Bei Ing.Plus ist jedes Teammitglied von großer Bedeutung für gemeinsame Erfolge. Deshalb engagieren wir uns nicht nur für ressourcenschonende Umweltziele, sondern auch für nachhaltige Arbeitskonzepte – ausgerichtet an den Eckpfeilern moderner New Work Methoden. Ob flexible Arbeitszeiten für eine ausgewogene Work-Life-Balance oder Gestaltungsspielraum für persönliches Wachstum – wir verstehen, dass Bedürfnisse ebenso vielfältig sind wie die Menschen selbst und gestalten individuell und dynamisch.</p>\n<p><strong>Freiheit &#x26; Flexibilität:</strong></p>\n<ul>\n<li><strong>Flexible Arbeitszeiten</strong><br>\nOrganisiere deinen Arbeitstag nach deinen Bedürfnissen und Präferenzen</li>\n<li><strong>Mobiles Arbeiten</strong><br>\nGenieße die Freiheit, von überall aus zu arbeiten – sei es von zu Hause, im Büro oder unterwegs</li>\n<li><strong>Gleitzeit</strong><br>\nPasse deine Arbeitszeiten flexibel an, um persönliche Termine und Verpflichtungen zu berücksichtigen</li>\n<li><strong>Urlaub</strong><br>\nVerfüge über 30 Urlaubstage, um deine Erholung und Freizeit zu genießen und neue Energie zu tanken</li>\n<li><strong>Workation</strong><br>\nEntdecke die Welt und verbinde Arbeiten mit Urlaubsreisen</li>\n<li><strong>Arbeitszeitkonto</strong><br>\nBaue Überstunden flexibel ab, wann immer du es brauchst</li>\n<li><strong>Teilzeit oder Vollzeit</strong><br>\nVon 60 bis 100% – vereinbare deinen Beruf mit deinem individuellen Lebensmodell</li>\n</ul>\n<p><strong>Entwicklung &#x26; Förderung:</strong></p>\n<ul>\n<li><strong>Kurse &#x26; Workshops</strong><br>\nNutze Weiterbildungsangebote, um neue Fähigkeiten zu erlernen</li>\n<li><strong>Zertifizierungen</strong><br>\nErhalte finanzielle Unterstützung für das Erreichen anerkannter beruflicher Qualifikationen</li>\n</ul>\n<p><strong>Gesundheit &#x26; Vorsorge:</strong></p>\n<ul>\n<li><strong>Betriebliche Krankenversicherung</strong><br>\nSorge aktiv für dich vor und freue dich über zahlreiche zusätzliche Leistungen</li>\n<li><strong>Private Unfallversicherung</strong><br>\nSichere dich ab und bewahre dir deine finanzielle Stabilität</li>\n<li><strong>Berufliche Altersvorsorge</strong><br>\nInvestiere in deine Zukunft und zähle dabei auf unsere Unterstützung</li>\n<li><strong>JobRad®</strong><br>\nLease dein Wunschrad mit steuerlichen Vorteilen und monatlichem Zuschuss</li>\n</ul>\n<p><strong>Gemeinschaft &#x26; Miteinander:</strong></p>\n<ul>\n<li><strong>Teamgeist</strong><br>\nNimm an Sommerfesten, Weihnachtsfeiern und Team-Ausflügen teil, um den Zusammenhalt zu stärken</li>\n<li><strong>Innovationsprojekte</strong><br>\nEngagiere dich in Innovationsprojekten und bringe deine Ideen aktiv ein</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-30 01:39:57.818', '2026-06-30 01:39:57.818', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/ing-plus-ag/communication-manager-brand-content-technology-60-100-furth-476860', 'https://www.arbeitnow.com/jobs/companies/ing-plus-ag/communication-manager-brand-content-technology-60-100-furth-476860', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/ing-plus-ag/communication-manager-brand-content-technology-60-100-furth-476860\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1881, NULL, 'api', NULL, 'Key Account Manager Süddeutschland  F/M/D', 'ICAPE GROUP', 'Munich', 'https://www.arbeitnow.com/jobs/companies/icape-group/key-account-manager-suddeutschland-munich-1794', '<h2>Key Account Manager <strong>Süddeutschland</strong> (m/f/d)</h2>\n<p><strong>Remote position | Germany</strong></p>\n<p>To strengthen our growth in Germany, we are looking for a <strong>Key Account Manager Süddeutschland (m/f/d)</strong> with solid experience in <strong>electronics sales</strong> and customer relationship management.</p>\n<p>This is a <strong>full‑time, remote role</strong>, with frequent travel to customers.</p>\n<p>Your role</p>\n<p>You will be responsible for <strong>managing and developing key customer relationships</strong> in Germany and driving sustainable revenue growth.<br>\nYou will act as a trusted partner for your clients, offering <strong>custom‑made technical solutions</strong> and coordinating closely with internal teams.</p>\n<p>Our solutions include:</p>\n<ul>\n<li>Printed Circuit Boards (PCBs)</li>\n<li>Custom-made electro‑mechanical parts</li>\n<li>Cable assemblies, displays, keypads, metal &#x26; plastic parts</li>\n</ul>\n<p>Your responsibilities</p>\n<ul>\n<li>Prospect and develop <strong>new companies and business opportunities</strong></li>\n<li>Manage and grow <strong>existing key accounts</strong></li>\n<li>Achieve and exceed <strong>sales and revenue targets</strong></li>\n<li>Prepare quotations and lead <strong>commercial negotiations</strong> with clients and suppliers</li>\n<li>Coordinate communication between customers and internal departments<br>\n(Engineering, Quality, Customer Service, Supply Chain)</li>\n<li>Monitor and improve <strong>customer satisfaction</strong></li>\n<li><strong>Frequent weekly travel</strong> to visit customers and prospects</li>\n<li>Report regularly to management on <strong>sales performance, targets and pipeline</strong></li>\n</ul>\n<p>Your profile</p>\n<ul>\n<li><strong>Minimum 5 years of sales experience</strong>, ideally in electronics</li>\n<li>Bachelor’s degree preferred; technical background is a plus</li>\n<li><strong>Fluent German and English</strong> (spoken and written)</li>\n<li>Strong communication and relationship‑building skills</li>\n<li>Proven ability in <strong>Key Account Management</strong></li>\n<li>Structured, well‑organized and detail‑oriented</li>\n<li>Able to work under pressure and meet deadlines</li>\n<li>Comfortable working in an <strong>international, multicultural environment</strong></li>\n<li>Willingness to travel frequently</li>\n</ul>\n<p>What ICAPE Group offers</p>\n<ul>\n<li><strong>Permanent full‑time contract</strong></li>\n<li>Competitive salary based on experience – <em>show us what you can do</em></li>\n<li>Company car also available for private use</li>\n<li>Bonus potential</li>\n<li><strong>Fully remote position</strong></li>\n<li>Challenging projects in a dynamic, collaborative environment</li>\n<li>Real <strong>career development opportunities</strong> and internal promotion</li>\n<li>Position open to applicants with disabilities</li>\n</ul>\n<p>Why ICAPE Group?</p>\n<p>ICAPE Group is the <strong>European leader in Printed Circuit Boards and custom-made electro‑mechanical parts</strong>.<br>\nWith <strong>34 subsidiaries worldwide</strong>, <strong>+3,650 customers in over 60 countries</strong>, and <strong>+650 employees</strong>, we combine technology, service and international reach.</p>\n<p><strong>Interested? Apply now and share your salary expectations.</strong></p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>Key Account Manager <strong>Süddeutschland</strong> (m/f/d)</h2>\n<p><strong>Remote position | Germany</strong></p>\n<p>To strengthen our growth in Germany, we are looking for a <strong>Key Account Manager Süddeutschland (m/f/d)</strong> with solid experience in <strong>electronics sales</strong> and customer relationship management.</p>\n<p>This i