(1895, NULL, 'api', NULL, 'Projektleiter Elektrotechnik', 'TechPlanen', 'Stuttgart', 'https://www.arbeitnow.com/jobs/companies/techplanen/projektleiter-elektrotechnik-stuttgart-109946', '<p>Gesucht wird ein Projektleiter Elektrotechnik für ein Ingenieursbüro, welches auf die Planung von industriellen Energiesystemen spezialisiert ist.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Aufgaben</strong></p>\n<ul>\n<li>Planung technischer Anlagen</li>\n<li>Erstellung von technischen Berechnungen, Auslegungen und Leistungsverzeichnungen</li>\n<li>Kostenverantwortung</li>\n<li>Erstellen von Energiekonzepten</li>\n<li>Schnittstellenkoordination</li>\n<li>Projektdokumentation</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Dein Profil</strong></p>\n<ul>\n<li>Elektrotechnische Ausbildung oder Studium (Ingenieur, Techniker, Meister oder gleichwertig)</li>\n<li>Teamfähig, gut organisiert und selbstständig arbeitend</li>\n<li>In der Lage Bauprojekte umsetzen zu können und erste Berührungspunkte mit HOAI</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Das bieten wir</strong></p>\n<ul>\n<li>Flexible Arbeitszeiten und bis zu 4 Tage pro Woche Work-From-Home möglich</li>\n<li>4-Tage-Woche (40h) möglich</li>\n<li>Ein Team welches großen Wert auf Menschlichkeit legt (flache Hierachie - keine Konzernnummer)</li>\n<li>31 Urlaubstage</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Gesucht wird ein Projektleiter Elektrotechnik für ein Ingenieursbüro, welches auf die Planung von industriellen Energiesystemen spezialisiert ist.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Aufgaben</strong></p>\n<ul>\n<li>Planung technischer Anlagen</li>\n<li>Erstellung von technischen Berechnungen, Auslegungen und Leistungsverzeichnungen</li>\n<li>Kostenverantwortung</li>\n<li>Erstellen von Energiekonzepten</li>\n<li>Schnittstellenkoordination</li>\n<li>Projektdokumentation</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Dein Profil</strong></p>\n<ul>\n<li>Elektrotechnische Ausbildung oder Studium (Ingenieur, Techniker, Meister oder gleichwertig)</li>\n<li>Teamfähig, gut organisiert und selbstständig arbeitend</li>\n<li>In der Lage Bauprojekte umsetzen zu können und erste Berührungspunkte mit HOAI</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Das bieten wir</strong></p>\n<ul>\n<li>Flexible Arbeitszeiten und bis zu 4 Tage pro Woche Work-From-Home möglich</li>\n<li>4-Tage-Woche (40h) möglich</li>\n<li>Ein Team welches großen Wert auf Menschlichkeit legt (flache Hierachie - keine Konzernnummer)</li>\n<li>31 Urlaubstage</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-30 01:42:06.652', '2026-06-30 01:42:06.652', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/techplanen/projektleiter-elektrotechnik-stuttgart-109946', 'https://www.arbeitnow.com/jobs/companies/techplanen/projektleiter-elektrotechnik-stuttgart-109946', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/techplanen/projektleiter-elektrotechnik-stuttgart-109946\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1896, NULL, 'api', NULL, 'Founding Marketing / Brand (m/w/d)', 'acemate.ai', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/acemateai/founding-marketing-brand-berlin-434076', '<p><em>Du baust acemates Außenwahrnehmung auf, von der Landingpage über Content und Events bis zur Community.</em></p>\n<p>acemate baut die KI-Infrastruktur der Bildung von morgen. Wir haben unsere erste Finanzierungsrunde abgeschlossen und stehen vor einer spannenden Wachstumsphase. Dafür suchen wir dich als ersten dedizierten Marketing-Hire.</p>\n<p><strong>Über acemate</strong></p>\n<p>Jeder Mensch lernt anders, aber kaum jemand bekommt Unterricht, der sich daran anpasst. acemate ändert das: wir entwickeln die KI-Infrastruktur für die Bildung von morgen und verwandeln bestehende Inhalte in interaktive Lernbegleiter mit Chat, Übungen, Karteikarten, Zusammenfassungen, Lernpfaden und Analytics. So lernen Schüler, Studierende und Berufstätige schneller und gezielter, während Lehrende, Hochschulen, Akademien und Verlage personalisierte Lernerfahrungen in großem Maßstab gestalten, ohne ihre Inhalte oder ihre didaktische Qualität aus der Hand zu geben.</p>\n<p>2024 in Berlin gegründet, nutzen heute Lernende in über 150 Ländern acemate. Wir arbeiten mit mehr als 30 Hochschulen in Deutschland, der Schweiz und den Niederlanden und entwickeln mit den 79 deutschen Industrie- und Handelskammern die nächste Generation beruflicher Bildung. Nach der ersten Finanzierungsrunde geht es jetzt in die nächste Phase, schnell, pragmatisch und direkt.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Aufgaben</strong></p>\n<p>Brand und Außenwahrnehmung: Unsere Landingpage pflegen und weiterentwickeln sowie für ein konsistentes Erscheinungsbild über alle Kanäle hinweg sorgen. Das Besondere bei acemate: Wir treten gleichzeitig als nahbare Brand für Studierende und als seriöser Infrastrukturpartner im B2B auf.</p>\n<ul>\n<li>D2C-Growth: Social Media (organisch, paid, Influencer), SEO, SEA und GEO sowie Referral-Loops und Ambassador-Programme.</li>\n<li>B2B-Demand: Awareness für acemate als SaaS- und KI-Partner steigern, unter anderem auf LinkedIn und Messen, und dem Vertrieb passendes Material bereitstellen.</li>\n<li>Content und Produktion: Videos und Fotos selbst produzieren sowie Social-Content, Case Studies und Website-Texte erstellen.</li>\n<li>Events: Formate für Lehrende und Kunden konzipieren und hosten, von Webinaren über Roundtables bis hin zu Messeauftritten.</li>\n<li>Kampagnen: Kampagnen konzipieren, umsetzen und auswerten.</li>\n<li>Analytics: Datenbasiert aus deinen Aktivitäten lernen und iterativ Best Practices entwickeln.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringst du mit</strong></p>\n<ul>\n<li>Einschlägige Erfahrung in Marketing, Brand oder Content, idealerweise in einem Startup oder als früher Marketing-Hire.</li>\n<li>Hands-on-Mentalität, konzeptionelles Denken und Kreativität: Du produzierst selbst (Video, Foto, Copy, Social) und denkst gern kreativ oder out of the box. Aus einem technischen Produkt machst du mit deinem Gespür für Storytelling und Positioning eine Geschichte, die hängen bleibt.</li>\n<li>Affinität für Daten und Analytics: Du triffst Entscheidungen faktenbasiert und wertest den Erfolg z. B. von Experimenten und Kampagnen analytisch aus.</li>\n<li>Du arbeitest AI-native und testest neue Tools und Kanäle schnell.</li>\n<li>Du sprichst sehr gutes Deutsch und Englisch.</li>\n<li>Du hast Lust, grundsätzlich vor Ort mit dem Team in Berlin-Mitte zu arbeiten.</li>\n<li>Bonus: Du hast bereits ein eigenes Projekt, eine Community oder einen Side-Hustle aufgebaut.</li>\n</ul>\n<p><strong>Wir passen weniger gut zusammen, wenn …</strong></p>\n<ul>\n<li>Du dich mit detaillierten Vorgaben und vordefinierten Aufgaben am wohlsten fühlst.</li>\n<li>Du davor zurückschreckst, Verantwortung mit Tragweite zu übernehmen.</li>\n<li>Du lieber in der Theorie als in der Praxis unterwegs bist.</li>\n<li>Du ausschließlich remote arbeiten möchtest.</li>\n<li>Du einen standardisierten Nine-to-Five-Job mit Corporate-Feeling suchst.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Was wir bieten</strong></p>\n<ul>\n<li>Eine Founding-Marketing-Rolle mit klarem Entwicklungspfad zum Marketing- und Brand-Lead.</li>\n<li>Direkten Draht zu den Foundern und umfangreiche Ownership ab Tag eins.</li>\n<li>Faire, marktorientierte Vergütung, Jobticket und Jobrad.</li>\n<li>Budget für die AI-Tools, die dich produktiver machen.</li>\n<li>Ein cooles Team, ein Büro in Berlin-Mitte und einen Office-Dog (Bieni).</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p><em>Du baust acemates Außenwahrnehmung auf, von der Landingpage über Content und Events bis zur Community.</em></p>\n<p>acemate baut die KI-Infrastruktur der Bildung von morgen. Wir haben unsere erste Finanzierungsrunde abgeschlossen und stehen vor einer spannenden Wachstumsphase. Dafür suchen wir dich als ersten dedizierten Marketing-Hire.</p>\n<p><strong>Über acemate</strong></p>\n<p>Jeder Mensch lernt anders, aber kaum jemand bekommt Unterricht, der sich daran anpasst. acemate ändert das: wir entwickeln die KI-Infrastruktur für die Bildung von morgen und verwandeln bestehende Inhalte in interaktive Lernbegleiter mit Chat, Übungen, Karteikarten, Zusammenfassungen, Lernpfaden und Analytics. So lernen Schüler, Studierende und Berufstätige schneller und gezielter, während Lehrende, Hochschulen, Akademien und Verlage personalisierte Lernerfahrungen in großem Maßstab gestalten, ohne ihre Inhalte oder ihre didaktische Qualität aus der Hand zu geben.</p>\n<p>2024 in Berlin gegründet, nutzen heute Lernende in über 150 Ländern acemate. Wir arbeiten mit mehr als 30 Hochschulen in Deutschland, der Schweiz und den Niederlanden und entwickeln mit den 79 deutschen Industrie- und Handelskammern die nächste Generation beruflicher Bildung. Nach der ersten Finanzierungsrunde geht es jetzt in die nächste Phase, schnell, pragmatisch und direkt.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Aufgaben</strong></p>\n<p>Brand und Außenwahrnehmung: Unsere Landingpage pflegen und weiterentwickeln sowie für ein konsistentes Erscheinungsbild über alle Kanäle hinweg sorgen. Das Besondere bei acemate: Wir treten gleichzeitig als nahbare Brand für Studierende und als seriöser Infrastrukturpartner im B2B auf.</p>\n<ul>\n<li>D2C-Growth: Social Media (organisch, paid, Influencer), SEO, SEA und GEO sowie Referral-Loops und Ambassador-Programme.</li>\n<li>B2B-Demand: Awareness für acemate als SaaS- und KI-Partner steigern, unter anderem auf LinkedIn und Messen, und dem Vertrieb passendes Material bereitstellen.</li>\n<li>Content und Produktion: Videos und Fotos selbst produzieren sowie Social-Content, Case Studies und Website-Texte erstellen.</li>\n<li>Events: Formate für Lehrende und Kunden konzipieren und hosten, von Webinaren über Roundtables bis hin zu Messeauftritten.</li>\n<li>Kampagnen: Kampagnen konzipieren, umsetzen und auswerten.</li>\n<li>Analytics: Datenbasiert aus deinen Aktivitäten lernen und iterativ Best Practices entwickeln.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringst du mit</strong></p>\n<ul>\n<li>Einschlägige Erfahrung in Marketing, Brand oder Content, idealerweise in einem Startup oder als früher Marketing-Hire.</li>\n<li>Hands-on-Mentalität, konzeptionelles Denken und Kreativität: Du produzierst selbst (Video, Foto, Copy, Social) und denkst gern kreativ oder out of the box. Aus einem technischen Produkt machst du mit deinem Gespür für Storytelling und Positioning eine Geschichte, die hängen bleibt.</li>\n<li>Affinität für Daten und Analytics: Du triffst Entscheidungen faktenbasiert und wertest den Erfolg z. B. von Experimenten und Kampagnen analytisch aus.</li>\n<li>Du arbeitest AI-native und testest neue Tools und Kanäle schnell.</li>\n<li>Du sprichst sehr gutes Deutsch und Englisch.</li>\n<li>Du hast Lust, grundsätzlich vor Ort mit dem Team in Berlin-Mitte zu arbeiten.</li>\n<li>Bonus: Du hast bereits ein eigenes Projekt, eine Community oder einen Side-Hustle aufgebaut.</li>\n</ul>\n<p><strong>Wir passen weniger gut zusammen, wenn …</strong></p>\n<ul>\n<li>Du dich mit detaillierten Vorgaben und vordefinierten Aufgaben am wohlsten fühlst.</li>\n<li>Du davor zurückschreckst, Verantwortung mit Tragweite zu übernehmen.</li>\n<li>Du lieber in der Theorie als in der Praxis unterwegs bist.</li>\n<li>Du ausschließlich remote arbeiten möchtest.</li>\n<li>Du einen standardisierten Nine-to-Five-Job mit Corporate-Feeling suchst.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Was wir bieten</strong></p>\n<ul>\n<li>Eine Founding-Marketing-Rolle mit klarem Entwicklungspfad zum Marketing- und Brand-Lead.</li>\n<li>Direkten Draht zu den Foundern und umfangreiche Ownership ab Tag eins.</li>\n<li>Faire, marktorientierte Vergütung, Jobticket und Jobrad.</li>\n<li>Budget für die AI-Tools, die dich produktiver machen.</li>\n<li>Ein cooles Team, ein Büro in Berlin-Mitte und einen Office-Dog (Bieni).</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-30 01:42:13.835', '2026-06-30 01:42:13.835', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/acemateai/founding-marketing-brand-berlin-434076', 'https://www.arbeitnow.com/jobs/companies/acemateai/founding-marketing-brand-berlin-434076', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/acemateai/founding-marketing-brand-berlin-434076\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1897, NULL, 'api', NULL, 'Senior Project Manager (all genders) - Event', 'LIGANOVA GmbH', 'Stuttgart', 'https://www.arbeitnow.com/jobs/companies/liganova-gmbh/senior-project-manager-all-genders-event-stuttgart-372500', '<h2>JOIN US</h2>\n<p><em>Ab sofort suchen wir für Alicias Team am Standort Stuttgart einen Senior Project Manager (all genders) im Bereich Events und Live Experiences.</em><br>\n<em>Werde Teil unserer Community – wir freuen uns auf dich!</em></p>\n<h2>WHAT YOU DO</h2>\n<ul>\n<li>Eigenständige Planung und Durchführung von Events und Projekten unter strikter Einhaltung von Zeitplänen und Budgets</li>\n<li>Gesamtverantwortung für die Abwicklung – von der ersten Kalkulation und Angebotserstellung bis hin zur laufenden Kostenkontrolle und finalen Abrechnung</li>\n<li>Als erfahrene und souveräne Schnittstelle koordinierst du interne Teams, Kooperationspartner:innen sowie externe Produktions- und Logistik-Dienstleister:innen</li>\n<li>Strategische Betreuung und Weiterentwicklung von spannenden Brands und Kunden aus verschiedenen Branchen als zentrale:r Ansprechpartner:in und Verantwortung über die operative Umsetzung ihrer Anforderungen</li>\n<li>Steuerung sämtlicher Projektabläufe sowie Sicherung und Weiterentwicklung von Qualitätsstandards über alle Projektphasen hinweg</li>\n</ul>\n<h2>WHO YOU ARE</h2>\n<ul>\n<li>Mind. 4-5 Jahre relevante Berufserfahrung im Projektmanagement, idealerweise mit Fokus auf Event oder Live Experience</li>\n<li>Erste Erfahrung in der Koordination von Projektteams sowie ein ausgeprägtes kaufmännisches Denken und ganzheitliche Beratungskompetenz</li>\n<li>Du liebst die Abwechslung durch diverse Kundenprojekte und kannst dich schnell auf neue Challenges ein stellen– vom Konzept bis zur Umsetzung</li>\n<li>Du denkst interdisziplinär, arbeitest leidenschaftlich gern im Team und behältst auch in intensiven Projektphasen stets die Übersicht</li>\n<li>Starke Präsentations- und Kommunikations-Skills, sowie Verhandlungsgeschick</li>\n<li>Sehr gute MS-Office-Kenntnisse und sehr gute Deutsch- sowie Englischkenntnisse</li>\n</ul>\n<h2>WHAT TO EXPECT</h2>\n<ul>\n<li>DIVERSITY &#x26; PEOPLE: Come as you are! Bei LIGANOVA wird eine Kultur der Inklusion gelebt und Diversity fasziniert uns. Einzigartigkeit wird zelebriert und gefördert, weshalb uns die gemeinsame Mission „Create the best version of yourself“ eint. Denn wir finden, dass gerade Vielfalt das größte kreative Potential birgt.</li>\n<li>GREEN MINDSET: Innovative Lösungen und unser Green Board geben Impulse für mehr Nachhaltigkeit im Office und darüber hinaus. Mit der Initiative Green Campaign Cycle führen wir unsere Kunden proaktiv an das Thema Green Transformation heran und stehen bei der Umsetzung mit unserer Expertise zur Seite.</li>\n<li>INTERNATIONALITY: Neben unserem HQ in Stuttgart sind auch unsere Offices in Berlin und Amsterdam zu vollständigen Dependancen gewachsen. Wir bieten Dir Vernetzung und regelmäßigen Austausch innerhalb der Units, fernab von starren Teamstrukturen.</li>\n</ul>\n<h2>Is it a Match?</h2>\n<p>Contact me:<br>\nLhea<br>\nTeam Leader People<br>\n+49 152 01876821</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>JOIN US</h2>\n<p><em>Ab sofort suchen wir für Alicias Team am Standort Stuttgart einen Senior Project Manager (all genders) im Bereich Events und Live Experiences.</em><br>\n<em>Werde Teil unserer Community – wir freuen uns auf dich!</em></p>\n<h2>WHAT YOU DO</h2>\n<ul>\n<li>Eigenständige Planung und Durchführung von Events und Projekten unter strikter Einhaltung von Zeitplänen und Budgets</li>\n<li>Gesamtverantwortung für die Abwicklung – von der ersten Kalkulation und Angebotserstellung bis hin zur laufenden Kostenkontrolle und finalen Abrechnung</li>\n<li>Als erfahrene und souveräne Schnittstelle koordinierst du interne Teams, Kooperationspartner:innen sowie externe Produktions- und Logistik-Dienstleister:innen</li>\n<li>Strategische Betreuung und Weiterentwicklung von spannenden Brands und Kunden aus verschiedenen Branchen als zentrale:r Ansprechpartner:in und Verantwortung über die operative Umsetzung ihrer Anforderungen</li>\n<li>Steuerung sämtlicher Projektabläufe sowie Sicherung und Weiterentwicklung von Qualitätsstandards über alle Projektphasen hinweg</li>\n</ul>\n<h2>WHO YOU ARE</h2>\n<ul>\n<li>Mind. 4-5 Jahre relevante Berufserfahrung im Projektmanagement, idealerweise mit Fokus auf Event oder Live Experience</li>\n<li>Erste Erfahrung in der Koordination von Projektteams sowie ein ausgeprägtes kaufmännisches Denken und ganzheitliche Beratungskompetenz</li>\n<li>Du liebst die Abwechslung durch diverse Kundenprojekte und kannst dich schnell auf neue Challenges ein stellen– vom Konzept bis zur Umsetzung</li>\n<li>Du denkst interdisziplinär, arbeitest leidenschaftlich gern im Team und behältst auch in intensiven Projektphasen stets die Übersicht</li>\n<li>Starke Präsentations- und Kommunikations-Skills, sowie Verhandlungsgeschick</li>\n<li>Sehr gute MS-Office-Kenntnisse und sehr gute Deutsch- sowie Englischkenntnisse</li>\n</ul>\n<h2>WHAT TO EXPECT</h2>\n<ul>\n<li>DIVERSITY &#x26; PEOPLE: Come as you are! Bei LIGANOVA wird eine Kultur der Inklusion gelebt und Diversity fasziniert uns. Einzigartigkeit wird zelebriert und gefördert, weshalb uns die gemeinsame Mission „Create the best version of yourself“ eint. Denn wir finden, dass gerade Vielfalt das größte kreative Potential birgt.</li>\n<li>GREEN MINDSET: Innovative Lösungen und unser Green Board geben Impulse für mehr Nachhaltigkeit im Office und darüber hinaus. Mit der Initiative Green Campaign Cycle führen wir unsere Kunden proaktiv an das Thema Green Transformation heran und stehen bei der Umsetzung mit unserer Expertise zur Seite.</li>\n<li>INTERNATIONALITY: Neben unserem HQ in Stuttgart sind auch unsere Offices in Berlin und Amsterdam zu vollständigen Dependancen gewachsen. Wir bieten Dir Vernetzung und regelmäßigen Austausch innerhalb der Units, fernab von starren Teamstrukturen.</li>\n</ul>\n<h2>Is it a Match?</h2>\n<p>Contact me:<br>\nLhea<br>\nTeam Leader People<br>\n+49 152 01876821</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-30 01:42:23.397', '2026-06-30 01:42:23.397', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/liganova-gmbh/senior-project-manager-all-genders-event-stuttgart-372500', 'https://www.arbeitnow.com/jobs/companies/liganova-gmbh/senior-project-manager-all-genders-event-stuttgart-372500', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/liganova-gmbh/senior-project-manager-all-genders-event-stuttgart-372500\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1898, NULL, 'api', NULL, 'Customer Success Manager (m/w/d) B2B SaaS-Lösung', 'Mendato GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/mendato-gmbh/customer-success-manager-b2b-saas-losung-berlin-136594', '<p>Wir sind ein Berliner Software-Startup und entwickeln eine moderne <strong>B2B SaaS-Lösung für Gebäudedienstleister</strong>. Unsere Software hilft Unternehmen dabei, ihre täglichen Abläufe zu digitalisieren und deutlich effizienter zu gestalten.</p>\n<p>Um unsere Kunden optimal bei der Einführung und täglichen Nutzung unserer Lösung zu unterstützen, suchen wir eine engagierte Person, die den Erfolg unserer Kunden aktiv vorantreibt und eine langfristige, vertrauensvolle Zusammenarbeit aufbaut.</p>\n<p>Als <strong>Customer Success Manager</strong> bist du die erste Ansprechperson für unsere Neukunden und Bestandskunden. Du begleitest sie bei der Einführung unserer Software, schulst Teams und sorgst dafür, dass sie unsere Lösung bestmöglich nutzen. Durch deine Nähe zum Kunden trägst du maßgeblich zu hoher Zufriedenheit, nachhaltiger Nutzung und kontinuierlicher Produktverbesserung bei.</p>\n<p>Du arbeitest eng mit den Gründern und dem Support zusammen und bringst Kundenbedürfnisse klar und strukturiert ein.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Begleitung von Neukunden während der gesamten Onboarding-Phase – von der Einführung bis zum erfolgreichen Live-Betrieb</li>\n<li>Beratung zu digitalen Abläufen, Arbeitsprozessen und optimaler Nutzung unserer Software</li>\n<li>Durchführung von Kundenschulungen (remote &#x26; vor Ort)</li>\n<li>Proaktive Betreuung von Bestandskunden zur Steigerung von Zufriedenheit, Nutzung und Kundenbindung</li>\n<li>Enge Zusammenarbeit mit dem Produktteam: Weitergabe von Nutzeranforderungen und praktischen Verbesserungsimpulsen</li>\n<li>Unterstützung bei der Weiterentwicklung interner Customer-Success-Prozesse</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erste Berufserfahrung im <strong>Customer Success, Account Management, Kundenbetreuung oder Vertrieb</strong></li>\n<li><strong>Technische Affinität</strong> – du findest dich in neuer Software schnell zurecht und arbeitest dich zügig in neue Tools ein</li>\n<li><strong>Emotionale Intelligenz</strong> – du gehst sensibel auf unterschiedliche Persönlichkeiten ein und weißt, wie du Vertrauen aufbaust</li>\n<li>Sicher im Umgang mit verschiedenen Gesprächspartnern – vom <strong>Geschäftsführer</strong> bis zum <strong>operativen Team</strong></li>\n<li><strong>Strukturierte, eigenverantwortliche Arbeitsweise</strong></li>\n<li>Gutes Gespür für <strong>Kundenbedürfnisse</strong> und Begeisterung für <strong>Digitalisierung</strong></li>\n<li><strong>Fließende Deutschkenntnisse</strong> in Wort und Schrift</li>\n<li>Wohnsitz in <strong>Berlin</strong> oder Bereitschaft, regelmäßig im Büro zu arbeiten</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Ein <strong>kleines, motiviertes Team</strong> mit kurzen Entscheidungswegen</li>\n<li><strong>Viel Gestaltungsfreiheit</strong> und die Chance, unser <strong>Produkt aktiv mitzuprägen</strong></li>\n<li><strong>26 Tage Urlaub,</strong> steigt jedes Jahr um einen Tag</li>\n<li><strong>Modernes Büro</strong> im pulsierenden Friedrichshain</li>\n<li><strong>Jobticket</strong> für deine bequeme und nachhaltige Mobilität</li>\n<li><strong>Urban Sports Club</strong> für einen aktiven Ausgleich zum Arbeitsalltag</li>\n</ul>\n<p><strong>Bewerbungsprozess</strong></p>\n<p><strong>1. Telefonisches Erstgespräch</strong> – Wir lernen uns kennen &#x26; klären erste Fragen</p>\n<p><strong>2. Zoom-Call mit deinem zukünftigen Teamlead</strong> – Besprechung deiner Aufgaben &#x26; Erwartungen</p>\n<p><strong>3. Persönliches Treffen in Berlin</strong> – Lerne das Team &#x26; unser Büro kennen</p>\n<p><strong>4. Willkommen im Team!</strong> Jetzt bewerben – wir freuen uns auf dich!</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Wir sind ein Berliner Software-Startup und entwickeln eine moderne <strong>B2B SaaS-Lösung für Gebäudedienstleister</strong>. Unsere Software hilft Unternehmen dabei, ihre täglichen Abläufe zu digitalisieren und deutlich effizienter zu gestalten.</p>\n<p>Um unsere Kunden optimal bei der Einführung und täglichen Nutzung unserer Lösung zu unterstützen, suchen wir eine engagierte Person, die den Erfolg unserer Kunden aktiv vorantreibt und eine langfristige, vertrauensvolle Zusammenarbeit aufbaut.</p>\n<p>Als <strong>Customer Success Manager</strong> bist du die erste Ansprechperson für unsere Neukunden und Bestandskunden. Du begleitest sie bei der Einführung unserer Software, schulst Teams und sorgst dafür, dass sie unsere Lösung bestmöglich nutzen. Durch deine Nähe zum Kunden trägst du maßgeblich zu hoher Zufriedenheit, nachhaltiger Nutzung und kontinuierlicher Produktverbesserung bei.</p>\n<p>Du arbeitest eng mit den Gründern und dem Support zusammen und bringst Kundenbedürfnisse klar und strukturiert ein.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Begleitung von Neukunden während der gesamten Onboarding-Phase – von der Einführung bis zum erfolgreichen Live-Betrieb</li>\n<li>Beratung zu digitalen Abläufen, Arbeitsprozessen und optimaler Nutzung unserer Software</li>\n<li>Durchführung von Kundenschulungen (remote &#x26; vor Ort)</li>\n<li>Proaktive Betreuung von Bestandskunden zur Steigerung von Zufriedenheit, Nutzung und Kundenbindung</li>\n<li>Enge Zusammenarbeit mit dem Produktteam: Weitergabe von Nutzeranforderungen und praktischen Verbesserungsimpulsen</li>\n<li>Unterstützung bei der Weiterentwicklung interner Customer-Success-Prozesse</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erste Berufserfahrung im <strong>Customer Success, Account Management, Kundenbetreuung oder Vertrieb</strong></li>\n<li><strong>Technische Affinität</strong> – du findest dich in neuer Software schnell zurecht und arbeitest dich zügig in neue Tools ein</li>\n<li><strong>Emotionale Intelligenz</strong> – du gehst sensibel auf unterschiedliche Persönlichkeiten ein und weißt, wie du Vertrauen aufbaust</li>\n<li>Sicher im Umgang mit verschiedenen Gesprächspartnern – vom <strong>Geschäftsführer</strong> bis zum <strong>operativen Team</strong></li>\n<li><strong>Strukturierte, eigenverantwortliche Arbeitsweise</strong></li>\n<li>Gutes Gespür für <strong>Kundenbedürfnisse</strong> und Begeisterung für <strong>Digitalisierung</strong></li>\n<li><strong>Fließende Deutschkenntnisse</strong> in Wort und Schrift</li>\n<li>Wohnsitz in <strong>Berlin</strong> oder Bereitschaft, regelmäßig im Büro zu arbeiten</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Ein <strong>kleines, motiviertes Team</strong> mit kurzen Entscheidungswegen</li>\n<li><strong>Viel Gestaltungsfreiheit</strong> und die Chance, unser <strong>Produkt aktiv mitzuprägen</strong></li>\n<li><strong>26 Tage Urlaub,</strong> steigt jedes Jahr um einen Tag</li>\n<li><strong>Modernes Büro</strong> im pulsierenden Friedrichshain</li>\n<li><strong>Jobticket</strong> für deine bequeme und nachhaltige Mobilität</li>\n<li><strong>Urban Sports Club</strong> für einen aktiven Ausgleich zum Arbeitsalltag</li>\n</ul>\n<p><strong>Bewerbungsprozess</strong></p>\n<p><strong>1. Telefonisches Erstgespräch</strong> – Wir lernen uns kennen &#x26; klären erste Fragen</p>\n<p><strong>2. Zoom-Call mit deinem zukünftigen Teamlead</strong> – Besprechung deiner Aufgaben &#x26; Erwartungen</p>\n<p><strong>3. Persönliches Treffen in Berlin</strong> – Lerne das Team &#x26; unser Büro kennen</p>\n<p><strong>4. Willkommen im Team!</strong> Jetzt bewerben – wir freuen uns auf dich!</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-06-30 01:42:31.579', '2026-06-30 01:42:31.579', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/mendato-gmbh/customer-success-manager-b2b-saas-losung-berlin-136594', 'https://www.arbeitnow.com/jobs/companies/mendato-gmbh/customer-success-manager-b2b-saas-losung-berlin-136594', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/mendato-gmbh/customer-success-manager-b2b-saas-losung-berlin-136594\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1899, NULL, 'api', NULL, '(Senior) Campaign Manager (m/f/d)', 'Quantum- Systems GmbH', 'Gilching', 'https://www.arbeitnow.com/jobs/companies/quantum-systems-gmbh/senior-campaign-manager-gilching-378534', '<p>As a <strong>(Senior) Campaign Manager</strong>, you will take on a key strategic role within Quantum Systems’ marketing team, <strong>designing and driving integrated campaigns</strong> that generate demand, build pipeline, and create memorable brand experiences for our target audiences. You will play a leading role in <strong>shaping and scaling our global campaign</strong> and demand generation strategy. You will report directly to the Marketing Team Lead.</p><p>As a powerhouse for unmanned systems, Quantum Systems develops holistic and scalable solutions for multi-domain operations. By seamlessly integrating platforms, software, and AI into one operational ecosystem, we enable real-world performance in complex mission environments. You will bring this positioning to life through targeted, multi-channel marketing campaigns.</p><p>You will work closely with stakeholders from Sales, Product Marketing, and Customer Success to generate high-quality leads and build long-term customer relationships.<br /><br /></p><h4><strong>Your Responsibilities:</strong></h4><ul><li><p>Lead the strategic planning, execution, and optimization of integrated, multi-channel marketing campaigns with a strong focus on demand generation and brand positioning</p></li><li><p>Develop scalable campaign concepts aligned with our multi-domain product and software portfolio</p></li><li><p>Orchestrate campaigns across digital and offline channels (email, paid media, social, web, content, and account-based marketing), ensuring consistent messaging across every touchpoint</p></li><li><p>Collaborate closely with Content, Product Marketing, Sales, Customer Success, and international teams to ensure a consistent and high-impact global presence</p></li><li><p>Support and guide sales teams and partners in activating campaigns and messaging in local markets worldwide</p></li><li><p>Serve as a point of contact for internal stakeholders across Marketing, Strategic Communications, Sales, Product, and Leadership, aligning campaign goals, priorities, and messaging across teams</p></li><li><p>Drive end-to-end project management of campaigns, owning briefs, timelines, dependencies, and deliverables to ensure on-time, on-budget execution</p></li><li><p>Manage marketing automation and CRM workflows, including lead nurturing, scoring, and segmentation</p></li><li><p>Track and analyze campaign performance (KPIs, pipeline contribution, ROI) and derive data-driven improvements</p></li><li><p>Select, manage, and negotiate with external vendors, agencies, and freelancers</p></li><li><p>Own and further develop the global campaign asset pool, messaging frameworks, and creative templates</p></li><li><p>Ensure brand consistency in line with corporate identity across all campaigns</p></li><li><p>Own campaign budgets, including planning, tracking, and controlling</p></li></ul><br /><br /><h4><strong><br /></strong></h4><h4><strong>Your Profile:</strong><br /></h4><ul><li><p>Bachelor’s degree in Marketing, Communications, Business Administration, or a comparable qualification</p></li><li><p>Minimum 5 years of experience in campaign management, demand generation, or integrated marketing, ideally within a B2B tech, defence, or software environment</p></li><li><p>Proven track record in planning and executing complex, multi-channel campaigns that drive measurable pipeline</p></li><li><p>Strong project management skills with the ability to coordinate cross-functional stakeholders and manage multiple projects in a fast-paced environment</p></li><li><p>Analytical, data-driven mindset with a focus on performance and ROI</p></li><li><p>Hands-on experience with marketing automation and CRM tools (e.g., HubSpot)</p></li><li><p>Excellent communication and stakeholder management skills</p></li><li><p>Creative thinker with a strategic mindset for developing innovative campaign formats</p></li><li><p>High level of ownership, hands-on mentality, and strong organizational skills</p></li><li><p>Fluent in German and English, both written and spoken</p></li><li><p>Willingness to travel internationally on occasion</p></li></ul><p><br /></p><h4><strong>Why Quantum-Systems:</strong></h4><ul><li><p>Be part of one of Europe’s most dynamic dual-use tech companies, with real-world impact</p></li><li><p>Work in a fast-paced environment with flat hierarchies and a global outlook</p></li><li><p>Grow and take ownership in an expanding team</p></li><li><p>Join a collaborative, mission-driven company culture</p></li></ul><p><strong><br /></strong></p><h4><strong>Our benefits:</strong></h4><ul><li><p><strong>Company pension scheme: </strong>We support you so that you can already make provisions for later.</p></li><li><p><strong>Flexible working hours: </strong>With trust-based working hours, you are not only responsible for your working hours, but also for your work-life balance.</p></li><li><p><strong>Mobile Work:</strong> If things get a little busy in the office, you have the option to work remotely one flexible day per week to create the right balance.</p></li><li><p><strong>Stay active:</strong> With EGYM Wellpass, you get access to thousands of fitness and sports facilities — and of course, we subsidize the membership.</p></li><li><p><strong>Bike-Leasing: </strong>We support you in staying environmentally mobile and healthy.</p></li><li><p><strong>Corporate Benefits: </strong>Your opportunity for attractive offers and discounts from well-known suppliers and brands, e.g. Adidas, Apple, Expedia.</p></li><li><p><strong>Employee events: </strong>We not only want to grow together, but also celebrate our successes together.</p></li><li><p><strong>Lunch-Card: </strong>Be powerful with delicious energy, daily lunch budget is sponsored.</p></li><li><p><strong>Company Shuttle:</strong> Enjoy our convenient shuttle service that picks you up from Laim in Munich and brings you to our location, with return trips at the end of the workday.</p></li></ul><p><br /></p><h4><strong>About us:</strong></h4><p>Quantum Systems is at the forefront of AI-powered unmanned systems. The company’s advanced (electric) vertical take-off and landing (VTOL) family of systems, combined with own software, edge computing, real-time AI-driven data, and drone port solutions, are designed to enable operators to make informed decisions with unmatched speed and precision. Founded in 2015 and headquartered near Munich, Quantum Systems operates globally with locations in the United States, Australia, Ukraine, Romania, and in the UK.</p><p style=\";\"></p><p style=\";\"></p><p><br /></p><h4><strong>Our commitment:</strong></h4><p>We are an open-minded company that not only values diversity, but actively promotes it. Regardless of gender, age, ethnic origin, religion, sexual orientation or disability, we firmly believe that the diversity of our employees is an essential part of our success.</p><p>At our company, every voice is heard and every perspective is valued. We believe that our differences enrich us and help us to find creative solutions and generate innovative ideas. We pride ourselves on creating an inclusive work environment where all employees can reach their full potential.</p><p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>As a <strong>(Senior) Campaign Manager</strong>, you will take on a key strategic role within Quantum Systems’ marketing team, <strong>designing and driving integrated campaigns</strong> that generate demand, build pipeline, and create memorable brand experiences for our target audiences. You will play a leading role in <strong>shaping and scaling our global campaign</strong> and demand generation strategy. You will report directly to the Marketing Team Lead.</p