INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1951, NULL, 'api', NULL, 'Deputy Quality Manager Defence (a) - 100% | Region: Stuttgart, Deutschland', 'CONCAPE', 'Heilbronn', 'https://www.arbeitnow.com/jobs/companies/concape/deputy-quality-manager-defence-a-100-region-stuttgart-deutschland-heilbronn-148942', '<p><strong>Warum diese Stelle besonders ist</strong></p>\n<p>Diese Rolle geht über klassisches Qualitätsmanagement hinaus: sie verbindet operative Umsetzung mit strategischer Verantwortung im regulierten Luftfahrtumfeld. Mit direktem Einfluss auf sicherheitskritische Produkte und der Perspektive zur stellvertretenden Leitung bietet sie echten Gestaltungsspielraum statt reiner Administration.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Verantwortung für die Weiterentwicklung und Umsetzung von Qualitätsstandards nach internationalen Normen (EN 9100, ISO 9001, EASA Part 21G/145).</li>\n<li>Stellvertretende Leitung des Qualitätsmanagements und Koordination von Audits, inklusive Nachverfolgung von Maßnahmen.</li>\n<li>Optimierung der Prozesslandschaft, Sicherstellung der Aktualität und Effizienz qualitätsrelevanter Abläufe.</li>\n<li>Begleitung von Entwicklungs- und Änderungsprojekten in enger Zusammenarbeit mit technischen Teams.</li>\n<li>Schnittstellenmanagement mit Behörden, Kunden und Konzernpartnern bei Audits und Qualitätsfragen.</li>\n<li>Initiieren neuer Qualitätsthemen und kontinuierliche Verbesserung bestehender Prozesse.</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Technisches Studium oder vergleichbare Qualifikation mit relevanter Berufserfahrung im Qualitätsmanagement.</li>\n<li>Erfahrung im Umgang mit internationalen Qualitätsnormen und Regularien, vorzugsweise aus Luftfahrt oder High-Tech-Industrie.</li>\n<li>Auditorenkenntnisse vorhanden oder Bereitschaft zur Qualifikation.</li>\n<li>Methodenkompetenz: 8D, 5Why, Ishikawa, Root Cause Analysis.</li>\n<li>Erfahrung in internationalen Konzernstrukturen und technikorientierten Umfeldern.</li>\n<li>Kommunikationsstark in Deutsch und Englisch, weitere Sprachen von Vorteil.</li>\n<li>Analytisches Denken, strukturierte Arbeitsweise und sicheres Auftreten im Umgang mit internen und externen Stakeholdern.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Direktanstellung bei einem etablierten, global tätigen Technologiekonzern im Aerospace-Bereich in Deutschland</li>\n<li>Anspruchsvolle Aufgaben auf höchstem technischem Niveau — keine Serienware, sondern Spezialarbeit</li>\n<li>Moderner Arbeitsplatz mit professioneller Infrastruktur</li>\n<li>Attraktive Anstellungsbedingungen mit Entwicklungsperspektive</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Warum diese Stelle besonders ist</strong></p>\n<p>Diese Rolle geht über klassisches Qualitätsmanagement hinaus: sie verbindet operative Umsetzung mit strategischer Verantwortung im regulierten Luftfahrtumfeld. Mit direktem Einfluss auf sicherheitskritische Produkte und der Perspektive zur stellvertretenden Leitung bietet sie echten Gestaltungsspielraum statt reiner Administration.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Verantwortung für die Weiterentwicklung und Umsetzung von Qualitätsstandards nach internationalen Normen (EN 9100, ISO 9001, EASA Part 21G/145).</li>\n<li>Stellvertretende Leitung des Qualitätsmanagements und Koordination von Audits, inklusive Nachverfolgung von Maßnahmen.</li>\n<li>Optimierung der Prozesslandschaft, Sicherstellung der Aktualität und Effizienz qualitätsrelevanter Abläufe.</li>\n<li>Begleitung von Entwicklungs- und Änderungsprojekten in enger Zusammenarbeit mit technischen Teams.</li>\n<li>Schnittstellenmanagement mit Behörden, Kunden und Konzernpartnern bei Audits und Qualitätsfragen.</li>\n<li>Initiieren neuer Qualitätsthemen und kontinuierliche Verbesserung bestehender Prozesse.</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Technisches Studium oder vergleichbare Qualifikation mit relevanter Berufserfahrung im Qualitätsmanagement.</li>\n<li>Erfahrung im Umgang mit internationalen Qualitätsnormen und Regularien, vorzugsweise aus Luftfahrt oder High-Tech-Industrie.</li>\n<li>Auditorenkenntnisse vorhanden oder Bereitschaft zur Qualifikation.</li>\n<li>Methodenkompetenz: 8D, 5Why, Ishikawa, Root Cause Analysis.</li>\n<li>Erfahrung in internationalen Konzernstrukturen und technikorientierten Umfeldern.</li>\n<li>Kommunikationsstark in Deutsch und Englisch, weitere Sprachen von Vorteil.</li>\n<li>Analytisches Denken, strukturierte Arbeitsweise und sicheres Auftreten im Umgang mit internen und externen Stakeholdern.</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Direktanstellung bei einem etablierten, global tätigen Technologiekonzern im Aerospace-Bereich in Deutschland</li>\n<li>Anspruchsvolle Aufgaben auf höchstem technischem Niveau — keine Serienware, sondern Spezialarbeit</li>\n<li>Moderner Arbeitsplatz mit professioneller Infrastruktur</li>\n<li>Attraktive Anstellungsbedingungen mit Entwicklungsperspektive</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 01:41:04.454', '2026-07-01 01:41:04.454', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/concape/deputy-quality-manager-defence-a-100-region-stuttgart-deutschland-heilbronn-148942', 'https://www.arbeitnow.com/jobs/companies/concape/deputy-quality-manager-defence-a-100-region-stuttgart-deutschland-heilbronn-148942', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/concape/deputy-quality-manager-defence-a-100-region-stuttgart-deutschland-heilbronn-148942\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1952, NULL, 'api', NULL, 'Leiter Operations & Produktion (Site Director) | Region: Bodensee, Deutschland', 'CONCAPE', 'Oldenburg', 'https://www.arbeitnow.com/jobs/companies/concape/leiter-operations-produktion-site-director-region-bodensee-deutschland-oldenburg-326701', '<p>CONCAPE ist eine spezialisierte Personalberatung (Direktvermittlung), die sich auf die Personalvermittlung in den Kernregionen der Schweiz und Liechtensteins sowie in führenden europäischen Nischenmärkten konzentriert.</p>\n<p>Wir rekrutieren exklusiv für ein traditionsreiches, familiengeführtes Produktionsunternehmen in der Lebensmittelindustrie an Ihrem Standort in der Bodenseeregion.</p>\n<p><strong>Region: Bodensee, Deutschland</strong></p>\n<h2>Aufgaben</h2>\n<p>Sie übernehmen die Gesamtverantwortung für die Produktionswerke am Standort, mit direkter Berichtslinie an die Geschäftsführung und klarem Schwerpunkt auf Operations. Gesucht wird eine erfahrene Führungspersönlichkeit mit Standing und Gestaltungswillen, die operativ wirksam ist und gleichzeitig den Standort strategisch weiterentwickelt. Die Rolle bietet echte unternehmerische Verantwortung mit Perspektive.</p>\n<p>Im Kern bedeutet das:</p>\n<ul>\n<li>Operative und strategische Gesamtverantwortung für die Produktionswerke</li>\n<li>Direkte Führung und Entwicklung der lokalen Führungsteams</li>\n<li>Sicherstellung eines effizienten, stabilen und wirtschaftlichen Betriebs</li>\n<li>Verantwortung für KPIs, Budget und Ergebnisentwicklung</li>\n<li>Identifikation und Umsetzung von Optimierungspotenzialen entlang der gesamten Wertschöpfungskette</li>\n<li>Enge Zusammenarbeit mit zentralen Funktionen und bereichsübergreifende Abstimmung</li>\n<li>Treiben von Veränderungsprozessen und kontinuierlicher Verbesserung</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Mehrjährige Führungserfahrung in einer vergleichbaren Gesamtverantwortung. Idealerweise in der Pharma, Lebensmittelindustrie (FMCG).</li>\n<li>Ausgeprägter Operations-Fokus mit nachweisbarer Erfahrung in der Steuerung und Optimierung von Produktionsprozessen</li>\n<li>Fundierte Kenntnisse in Qualitäts- und Hygienestandards (z.B. IFS, HACCP) oder vergleichbarem reguliertem Umfeld</li>\n<li>Strategisches Denkvermögen bei gleichzeitiger operativer Wirksamkeit</li>\n<li>Hands-on-Mentalität, hohe Umsetzungsorientierung, strukturierte Arbeitsweise</li>\n<li>Ausgeprägte Führungs- und Kommunikationsstärke, Erfahrung in der Teamentwicklung</li>\n<li>Erfahrung im Change Management und kontinuierlicher Verbesserung</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>CONCAPE ist eine spezialisierte Personalberatung (Direktvermittlung), die sich auf die Personalvermittlung in den Kernregionen der Schweiz und Liechtensteins sowie in führenden europäischen Nischenmärkten konzentriert.</p>\n<p>Wir rekrutieren exklusiv für ein traditionsreiches, familiengeführtes Produktionsunternehmen in der Lebensmittelindustrie an Ihrem Standort in der Bodenseeregion.</p>\n<p><strong>Region: Bodensee, Deutschland</strong></p>\n<h2>Aufgaben</h2>\n<p>Sie übernehmen die Gesamtverantwortung für die Produktionswerke am Standort, mit direkter Berichtslinie an die Geschäftsführung und klarem Schwerpunkt auf Operations. Gesucht wird eine erfahrene Führungspersönlichkeit mit Standing und Gestaltungswillen, die operativ wirksam ist und gleichzeitig den Standort strategisch weiterentwickelt. Die Rolle bietet echte unternehmerische Verantwortung mit Perspektive.</p>\n<p>Im Kern bedeutet das:</p>\n<ul>\n<li>Operative und strategische Gesamtverantwortung für die Produktionswerke</li>\n<li>Direkte Führung und Entwicklung der lokalen Führungsteams</li>\n<li>Sicherstellung eines effizienten, stabilen und wirtschaftlichen Betriebs</li>\n<li>Verantwortung für KPIs, Budget und Ergebnisentwicklung</li>\n<li>Identifikation und Umsetzung von Optimierungspotenzialen entlang der gesamten Wertschöpfungskette</li>\n<li>Enge Zusammenarbeit mit zentralen Funktionen und bereichsübergreifende Abstimmung</li>\n<li>Treiben von Veränderungsprozessen und kontinuierlicher Verbesserung</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Mehrjährige Führungserfahrung in einer vergleichbaren Gesamtverantwortung. Idealerweise in der Pharma, Lebensmittelindustrie (FMCG).</li>\n<li>Ausgeprägter Operations-Fokus mit nachweisbarer Erfahrung in der Steuerung und Optimierung von Produktionsprozessen</li>\n<li>Fundierte Kenntnisse in Qualitäts- und Hygienestandards (z.B. IFS, HACCP) oder vergleichbarem reguliertem Umfeld</li>\n<li>Strategisches Denkvermögen bei gleichzeitiger operativer Wirksamkeit</li>\n<li>Hands-on-Mentalität, hohe Umsetzungsorientierung, strukturierte Arbeitsweise</li>\n<li>Ausgeprägte Führungs- und Kommunikationsstärke, Erfahrung in der Teamentwicklung</li>\n<li>Erfahrung im Change Management und kontinuierlicher Verbesserung</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 01:41:11.390', '2026-07-01 01:41:11.390', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/concape/leiter-operations-produktion-site-director-region-bodensee-deutschland-oldenburg-326701', 'https://www.arbeitnow.com/jobs/companies/concape/leiter-operations-produktion-site-director-region-bodensee-deutschland-oldenburg-326701', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/concape/leiter-operations-produktion-site-director-region-bodensee-deutschland-oldenburg-326701\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
