INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(1963, NULL, 'api', NULL, 'Fullstack Developer Laravel & React/Vue (m/w/d)', 'MintCode Solutions GmbH', 'Haselünne', 'https://www.arbeitnow.com/jobs/companies/mintcode-solutions-gmbh/fullstack-developer-laravel-react-vue-haselunne-216684', '<p>Wir bauen Software, die echte Probleme löst, statt aufgeblähter Konzern-Tools, mit denen am Ende keiner gern arbeitet. Dazu gehört unser eigenes ERP-Produkt, komplexe Entwicklungsprojekte zusammen mit unseren Kunden und jede Menge Automatisierung mit modernen KI-Tools. Kein Legacy-Ballast, keine endlosen Abstimmungsrunden. Sauberer Code, schnelle Iteration, und am Ende läuft das Ding auch wirklich.</p>\n<p>Ob du schon Senior bist oder gerade richtig Fahrt aufnimmst, ist uns ehrlich gesagt zweitrangig. Bei uns zählt, was du baust und wie du an Probleme rangehst. Du bekommst echte Verantwortung, einen kurzen Draht zur Geschäftsführung und die Möglichkeit, dich so schnell weiterzuentwickeln, wie du selbst Gas gibst.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Du entwickelst unser eigenes ERP- und Software-Produkt weiter (Laravel im Backend, React oder Vue im Frontend)</li>\n<li>Du setzt komplexe Projekte gemeinsam mit unseren Kunden um, von der ersten Anforderung bis zum Go-live</li>\n<li>Du bindest Drittsysteme und bestehende IT-Landschaften über APIs an und dokumentierst die Schnittstellen so, dass auch der nächste durchblickt</li>\n<li>Du konzipierst und baust interne Automatisierungen und KI-Tools, etwa Workflow-Automatisierung oder LLM-Anbindungen</li>\n<li>Du redest bei Architektur, Tech-Stack und unseren Abläufen aktiv mit</li>\n<li>Du verantwortest deine Features von Anfang bis Ende, Code Reviews und sauberer Code gehören für dich einfach dazu</li>\n<li>Du sprichst bei Bedarf auch direkt mit Kunden, wenn es um Anforderungen und Lösungen geht</li>\n</ul>\n<p><strong>Wir wollen wachsen und unser Produkt mit uns. Wenn du Lust hast, am Fundament mitzubauen, bist du bei uns genau richtig.</strong></p>\n<p>Und keine Sorge, du sitzt mit deinen Problemen nicht allein da. Egal ob kniffliger Bug, Architekturentscheidung, die du hinterfragen willst, oder einfach mal kurz Gedanken sortieren: Es ist immer jemand da, der mit dir draufschaut.</p>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erfahrung mit PHP und Laravel im Backend. Solide Grundlagen reichen, tiefe Routine ist natürlich auch super</li>\n<li>Du fühlst dich im Frontend mit React oder Vue wohl</li>\n<li>Sauberer Code, relationale Datenbanken und der Umgang mit APIs sind für dich keine Fremdworte</li>\n<li>Du hast Bock auf KI, LLM-Integration und Automatisierung. Die Tiefe baust du bei uns weiter aus</li>\n<li>Du lernst gern dazu, packst Dinge selbst an und bleibst auch dran, wenn es mal hakt</li>\n<li>Herausforderungen schrecken dich nicht ab, sondern reizen dich eher</li>\n<li>Du übernimmst gern Verantwortung und triffst Entscheidungen, statt auf Ansagen zu warten</li>\n<li>Teamgeist ist für dich kein Buzzword, sondern Alltag</li>\n<li>Du bist ehrlich und sagst, was du denkst</li>\n</ul>\n<p>Für uns zählen Persönlichkeit, Motivation und Potenzial mehr als ein dicker Stapel Zeugnisse. Ob Junior oder Senior: Wichtig ist, dass du gut baust und Lust hast, besser zu werden.</p>\n<h2>Benefits</h2>\n<p><strong>Hardware, die Spaß macht.</strong> Leistungsstarke Workstations und lokale KI-Power statt Standard-Office-Laptop. Du arbeitest mit Technik, die zu deinem Anspruch passt.</p>\n<p><strong>Moderne Tooling-Kultur.</strong> Aktueller Stack, KI-gestützte Entwicklung (unter anderem mit Claude Code) und kein Altlast-Ballast, der dich ausbremst.</p>\n<p><strong>Wellpass oder Streaming-Abo.</strong> Sport in tausenden Studios deutschlandweit oder Spotify bzw. Netflix auf uns. Such dir aus, was zu dir passt.</p>\n<p><strong>30 Tage Urlaub.</strong> Volle 30 Tage, ohne Diskussion. Erholung gehört genauso dazu wie gute Arbeit.</p>\n<p><strong>Bildungsurlaub ist willkommen.</strong> Kein unangenehmes Gespräch, kein schlechtes Gewissen. Wer sich weiterbilden will, hat unsere volle Unterstützung.</p>\n<p><strong>Start-up-Flair.</strong> Kurze Entscheidungswege, echte Eigenverantwortung und eine Atmosphäre, in der Ideen mehr zählen als Hierarchien.</p>\n<p><strong>Flexible Arbeitszeiten.</strong> Leben und Arbeit muss man manchmal jonglieren. Dafür hast du bei uns Verständnis und Spielraum.</p>\n<p><strong>Home-Office.</strong> Nach der Einarbeitung arbeitest du da, wo du am produktivsten bist. Ob zu Hause oder im Büro, das entscheidest du.</p>\n<p>Wenn du Teil eines Unternehmens sein möchtest, das nicht nur Wert auf technische Exzellenz legt, sondern auch auf deine persönliche Entwicklung, dann gestalte mit uns die Zukunft der IT!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Wir bauen Software, die echte Probleme löst, statt aufgeblähter Konzern-Tools, mit denen am Ende keiner gern arbeitet. Dazu gehört unser eigenes ERP-Produkt, komplexe Entwicklungsprojekte zusammen mit unseren Kunden und jede Menge Automatisierung mit modernen KI-Tools. Kein Legacy-Ballast, keine endlosen Abstimmungsrunden. Sauberer Code, schnelle Iteration, und am Ende läuft das Ding auch wirklich.</p>\n<p>Ob du schon Senior bist oder gerade richtig Fahrt aufnimmst, ist uns ehrlich gesagt zweitrangig. Bei uns zählt, was du baust und wie du an Probleme rangehst. Du bekommst echte Verantwortung, einen kurzen Draht zur Geschäftsführung und die Möglichkeit, dich so schnell weiterzuentwickeln, wie du selbst Gas gibst.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Du entwickelst unser eigenes ERP- und Software-Produkt weiter (Laravel im Backend, React oder Vue im Frontend)</li>\n<li>Du setzt komplexe Projekte gemeinsam mit unseren Kunden um, von der ersten Anforderung bis zum Go-live</li>\n<li>Du bindest Drittsysteme und bestehende IT-Landschaften über APIs an und dokumentierst die Schnittstellen so, dass auch der nächste durchblickt</li>\n<li>Du konzipierst und baust interne Automatisierungen und KI-Tools, etwa Workflow-Automatisierung oder LLM-Anbindungen</li>\n<li>Du redest bei Architektur, Tech-Stack und unseren Abläufen aktiv mit</li>\n<li>Du verantwortest deine Features von Anfang bis Ende, Code Reviews und sauberer Code gehören für dich einfach dazu</li>\n<li>Du sprichst bei Bedarf auch direkt mit Kunden, wenn es um Anforderungen und Lösungen geht</li>\n</ul>\n<p><strong>Wir wollen wachsen und unser Produkt mit uns. Wenn du Lust hast, am Fundament mitzubauen, bist du bei uns genau richtig.</strong></p>\n<p>Und keine Sorge, du sitzt mit deinen Problemen nicht allein da. Egal ob kniffliger Bug, Architekturentscheidung, die du hinterfragen willst, oder einfach mal kurz Gedanken sortieren: Es ist immer jemand da, der mit dir draufschaut.</p>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erfahrung mit PHP und Laravel im Backend. Solide Grundlagen reichen, tiefe Routine ist natürlich auch super</li>\n<li>Du fühlst dich im Frontend mit React oder Vue wohl</li>\n<li>Sauberer Code, relationale Datenbanken und der Umgang mit APIs sind für dich keine Fremdworte</li>\n<li>Du hast Bock auf KI, LLM-Integration und Automatisierung. Die Tiefe baust du bei uns weiter aus</li>\n<li>Du lernst gern dazu, packst Dinge selbst an und bleibst auch dran, wenn es mal hakt</li>\n<li>Herausforderungen schrecken dich nicht ab, sondern reizen dich eher</li>\n<li>Du übernimmst gern Verantwortung und triffst Entscheidungen, statt auf Ansagen zu warten</li>\n<li>Teamgeist ist für dich kein Buzzword, sondern Alltag</li>\n<li>Du bist ehrlich und sagst, was du denkst</li>\n</ul>\n<p>Für uns zählen Persönlichkeit, Motivation und Potenzial mehr als ein dicker Stapel Zeugnisse. Ob Junior oder Senior: Wichtig ist, dass du gut baust und Lust hast, besser zu werden.</p>\n<h2>Benefits</h2>\n<p><strong>Hardware, die Spaß macht.</strong> Leistungsstarke Workstations und lokale KI-Power statt Standard-Office-Laptop. Du arbeitest mit Technik, die zu deinem Anspruch passt.</p>\n<p><strong>Moderne Tooling-Kultur.</strong> Aktueller Stack, KI-gestützte Entwicklung (unter anderem mit Claude Code) und kein Altlast-Ballast, der dich ausbremst.</p>\n<p><strong>Wellpass oder Streaming-Abo.</strong> Sport in tausenden Studios deutschlandweit oder Spotify bzw. Netflix auf uns. Such dir aus, was zu dir passt.</p>\n<p><strong>30 Tage Urlaub.</strong> Volle 30 Tage, ohne Diskussion. Erholung gehört genauso dazu wie gute Arbeit.</p>\n<p><strong>Bildungsurlaub ist willkommen.</strong> Kein unangenehmes Gespräch, kein schlechtes Gewissen. Wer sich weiterbilden will, hat unsere volle Unterstützung.</p>\n<p><strong>Start-up-Flair.</strong> Kurze Entscheidungswege, echte Eigenverantwortung und eine Atmosphäre, in der Ideen mehr zählen als Hierarchien.</p>\n<p><strong>Flexible Arbeitszeiten.</strong> Leben und Arbeit muss man manchmal jonglieren. Dafür hast du bei uns Verständnis und Spielraum.</p>\n<p><strong>Home-Office.</strong> Nach der Einarbeitung arbeitest du da, wo du am produktivsten bist. Ob zu Hause oder im Büro, das entscheidest du.</p>\n<p>Wenn du Teil eines Unternehmens sein möchtest, das nicht nur Wert auf technische Exzellenz legt, sondern auch auf deine persönliche Entwicklung, dann gestalte mit uns die Zukunft der IT!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 01:42:29.391', '2026-07-01 01:42:29.391', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/mintcode-solutions-gmbh/fullstack-developer-laravel-react-vue-haselunne-216684', 'https://www.arbeitnow.com/jobs/companies/mintcode-solutions-gmbh/fullstack-developer-laravel-react-vue-haselunne-216684', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/mintcode-solutions-gmbh/fullstack-developer-laravel-react-vue-haselunne-216684\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1964, NULL, 'api', NULL, 'Junior Marketing Manager (m/w/d)', 'Omnora GmbH', 'Frankfurt am Main', 'https://www.arbeitnow.com/jobs/companies/omnora-gmbh/junior-marketing-manager-frankfurt-am-main-364563', '<h2>Introduction</h2>\n<p>Du suchst nach deinem Studium eine Herausforderung mit echtem Impact? Willst Dinge nicht nur umsetzen, sondern aktiv mitgestalten? Dann bist du bei uns genau richtig.</p>\n<p>Wir sind Omnora, eine B2B SaaS-Company aus Frankfurt. Wir helfen Unternehmen wie DB, AOK und ADAC dabei, ihr Wissen zu sichern, zu strukturieren und nutzbar zu machen - mit KI.</p>\n<p>Als Junior Marketing Manager (m/w/d) übernimmst du bei Omnora die Verantwortung für unser komplettes Marketing. Von Content über Performance bis hin zu Marketing Automation und allem, was sonst noch ansteht. Du arbeitest eng mit unserer externen Agentur zusammen, nimmst dir Schritt für Schritt mehr Verantwortung und bist mittelfristig die zentrale Figur, die unser Marketing steuert.</p>\n<p>Bei uns gibt es noch kein eingespieltes Marketing-Team und keinen Senior, der dir alles vorgibt – dafür aber jede Menge Raum, dir Themen selbst zu erschließen und eigene Lösungen zu finden. Genau dieser Pfadfinder-Spirit ist es, der dich bei uns weiterbringt.</p>\n<h2>What\'s in it for me</h2>\n<ul>\n<li><strong>Impact statt Hamsterrad:</strong> Du übernimmst als zentrale Figur echte Verantwortung für unser komplettes Marketing.</li>\n<li><strong>Blitzschnelles Lernen:</strong> Du tauchst in alle Disziplinen ein - von Content über Performance bis Automation - und lernst in Monaten, wofür andere Jahre brauchen.</li>\n<li><strong>Gestaltungsfreiraum:</strong> Statt festgefahrener Prozesse erwartet dich maximaler Freiraum, Dinge auszuprobieren.</li>\n<li><strong>Kurze Wege, großer Einfluss:</strong> Du arbeitest eng mit der Geschäftsführung zusammen und siehst, wie deine Arbeit das Unternehmen bewegt.</li>\n<li><strong>Hybrides Arbeiten:</strong> Was zählt, ist dein Beitrag - nicht wo du sitzt. Wir arbeiten hybrid aus Frankfurt mit flexiblen Home-Office-Möglichkeiten.</li>\n<li><strong>Der perfekte Einstiegszeitpunkt:</strong> Mit marktreifem Produkt und starken Referenzen stehen wir vor dem nächsten Wachstumsschritt - der ideale Moment, um einzusteigen und mitzugestalten.</li>\n</ul>\n<h2>How you can make an impact</h2>\n<ul>\n<li><strong>Omni-Channel Marketing:</strong> Du entwickelst und steuerst Kampagnen über alle Kanäle hinweg - von Paid Ads über organischen Content bis hin zu ABM-Ansätzen auf LinkedIn.</li>\n<li><strong>Content &#x26; Formate:</strong> Du testest kontinuierlich, analysierst die Ergebnisse und leitest daraus ab, welche Inhalte und Formate bei unseren Zielgruppen wirklich performen - datenbasiert statt Bauchgefühl.</li>\n<li><strong>Agentur-Lead:</strong> Du bist zentraler Ansprechpartner für unsere Marketing-Agentur, briefst Kampagnen, gibst Feedback und stellst sicher, dass Ergebnisse geliefert werden.</li>\n<li><strong>Marketing-Infrastruktur:</strong> Du baust eine skalierbare Infrastruktur auf - von HubSpot-Automation über Lead-Tracking bis hin zu einem verlässlichen Reporting.</li>\n<li><strong>Daten &#x26; Zahlen:</strong> Du baust ein Dashboard auf, das unsere wichtigsten Marketing-KPIs auf einen Blick zeigt. Aber das ist nur der Anfang: Du interpretierst die Zahlen, erkennst Muster und leitest konkrete Optimierungen ab – Daten sind für dich kein Reporting-Pflichtprogramm, sondern dein wichtigstes Werkzeug.</li>\n<li><strong>KI &#x26; Automatisierung:</strong> Du nutzt aktiv KI-Tools, um Prozesse zu automatisieren – von der Content-Produktion bis hin zu personalisierten Kampagnen.</li>\n</ul>\n<h2>Skills to be successful</h2>\n<ul>\n<li><strong>Akademischer Hintergrund:</strong> Abschluss einer Top-Universität oder mit überdurchschnittlichen Noten in Marketing, BWL, Kommunikation o. ä. – oder du stehst kurz davor.</li>\n<li><strong>Erste Marketing-Berührungspunkte:</strong> Erste Praxiserfahrung durch Praktika, eigene Projekte oder Werkstudenten-Erfahrung - idealerweise im Tech-, SaaS- oder Startup-Umfeld. Kein Muss, aber ein klares Plus.</li>\n<li><strong>Erkundungsinstinkt statt Komfortzone:</strong> Du eignest dir neue Themen selbst an, suchst aktiv nach Lösungen und lässt dich von einer verschlossenen Tür nicht aufhalten, sondern findest den Weg drumherum.</li>\n<li><strong>Kreatives Auge:</strong> Du hast ein Gespür für ansprechendes Design und kannst auch selbst Visuals erstellen, die im Feed herausstechen. Erfahrung mit Tools wie Canva oder Adobe Creative Cloud ist ein Plus.</li>\n<li><strong>Zahlenaffinität:</strong> Bei uns wird alles gemessen und getrackt. Du scheust dich nicht vor Dashboards und KPIs, sondern nutzt sie als Kompass für deine tägliche Arbeit. Zahlen sind für dich die Basis jeder Entscheidung, nicht lästige Pflicht.</li>\n<li>Kommunikationsstärke: Du hast ein Gespür für Sprache und Botschaften, die ankommen - egal ob für LinkedIn-Posts oder interne Meetings. Verhandlungssicheres Englisch ist ein Plus.</li>\n<li><strong>Extreme Ownership:</strong> Du brauchst niemanden, der dir sagt was zu tun ist. Wenn du eine Chance siehst, ergreifst du sie. Wenn Hindernisse kommen, überspringst du sie. Du gehst voran.</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>Introduction</h2>\n<p>Du suchst nach deinem Studium eine Herausforderung mit echtem Impact? Willst Dinge nicht nur umsetzen, sondern aktiv mitgestalten? Dann bist du bei uns genau richtig.</p>\n<p>Wir sind Omnora, eine B2B SaaS-Company aus Frankfurt. Wir helfen Unternehmen wie DB, AOK und ADAC dabei, ihr Wissen zu sichern, zu strukturieren und nutzbar zu machen - mit KI.</p>\n<p>Als Junior Marketing Manager (m/w/d) übernimmst du bei Omnora die Verantwortung für unser komplettes Marketing. Von Content über Performance bis hin zu Marketing Automation und allem, was sonst noch ansteht. Du arbeitest eng mit unserer externen Agentur zusammen, nimmst dir Schritt für Schritt mehr Verantwortung und bist mittelfristig die zentrale Figur, die unser Marketing steuert.</p>\n<p>Bei uns gibt es noch kein eingespieltes Marketing-Team und keinen Senior, der dir alles vorgibt – dafür aber jede Menge Raum, dir Themen selbst zu erschließen und eigene Lösungen zu finden. Genau dieser Pfadfinder-Spirit ist es, der dich bei uns weiterbringt.</p>\n<h2>What\'s in it for me</h2>\n<ul>\n<li><strong>Impact statt Hamsterrad:</strong> Du übernimmst als zentrale Figur echte Verantwortung für unser komplettes Marketing.</li>\n<li><strong>Blitzschnelles Lernen:</strong> Du tauchst in alle Disziplinen ein - von Content über Performance bis Automation - und lernst in Monaten, wofür andere Jahre brauchen.</li>\n<li><strong>Gestaltungsfreiraum:</strong> Statt festgefahrener Prozesse erwartet dich maximaler Freiraum, Dinge auszuprobieren.</li>\n<li><strong>Kurze Wege, großer Einfluss:</strong> Du arbeitest eng mit der Geschäftsführung zusammen und siehst, wie deine Arbeit das Unternehmen bewegt.</li>\n<li><strong>Hybrides Arbeiten:</strong> Was zählt, ist dein Beitrag - nicht wo du sitzt. Wir arbeiten hybrid aus Frankfurt mit flexiblen Home-Office-Möglichkeiten.</li>\n<li><strong>Der perfekte Einstiegszeitpunkt:</strong> Mit marktreifem Produkt und starken Referenzen stehen wir vor dem nächsten Wachstumsschritt - der ideale Moment, um einzusteigen und mitzugestalten.</li>\n</ul>\n<h2>How you can make an impact</h2>\n<ul>\n<li><strong>Omni-Channel Marketing:</strong> Du entwickelst und steuerst Kampagnen über alle Kanäle hinweg - von Paid Ads über organischen Content bis hin zu ABM-Ansätzen auf LinkedIn.</li>\n<li><strong>Content &#x26; Formate:</strong> Du testest kontinuierlich, analysierst die Ergebnisse und leitest daraus ab, welche Inhalte und Formate bei unseren Zielgruppen wirklich performen - datenbasiert statt Bauchgefühl.</li>\n<li><strong>Agentur-Lead:</strong> Du bist zentraler Ansprechpartner für unsere Marketing-Agentur, briefst Kampagnen, gibst Feedback und stellst sicher, dass Ergebnisse geliefert werden.</li>\n<li><strong>Marketing-Infrastruktur:</strong> Du baust eine skalierbare Infrastruktur auf - von HubSpot-Automation über Lead-Tracking bis hin zu einem verlässlichen Reporting.</li>\n<li><strong>Daten &#x26; Zahlen:</strong> Du baust ein Dashboard auf, das unsere wichtigsten Marketing-KPIs auf einen Blick zeigt. Aber das ist nur der Anfang: Du interpretierst die Zahlen, erkennst Muster und leitest konkrete Optimierungen ab – Daten sind für dich kein Reporting-Pflichtprogramm, sondern dein wichtigstes Werkzeug.</li>\n<li><strong>KI &#x26; Automatisierung:</strong> Du nutzt aktiv KI-Tools, um Prozesse zu automatisieren – von der Content-Produktion bis hin zu personalisierten Kampagnen.</li>\n</ul>\n<h2>Skills to be successful</h2>\n<ul>\n<li><strong>Akademischer Hintergrund:</strong> Abschluss einer Top-Universität oder mit überdurchschnittlichen Noten in Marketing, BWL, Kommunikation o. ä. – oder du stehst kurz davor.</li>\n<li><strong>Erste Marketing-Berührungspunkte:</strong> Erste Praxiserfahrung durch Praktika, eigene Projekte oder Werkstudenten-Erfahrung - idealerweise im Tech-, SaaS- oder Startup-Umfeld. Kein Muss, aber ein klares Plus.</li>\n<li><strong>Erkundungsinstinkt statt Komfortzone:</strong> Du eignest dir neue Themen selbst an, suchst aktiv nach Lösungen und lässt dich von einer verschlossenen Tür nicht aufhalten, sondern findest den Weg drumherum.</li>\n<li><strong>Kreatives Auge:</strong> Du hast ein Gespür für ansprechendes Design und kannst auch selbst Visuals erstellen, die im Feed herausstechen. Erfahrung mit Tools wie Canva oder Adobe Creative Cloud ist ein Plus.</li>\n<li><strong>Zahlenaffinität:</strong> Bei uns wird alles gemessen und getrackt. Du scheust dich nicht vor Dashboards und KPIs, sondern nutzt sie als Kompass für deine tägliche Arbeit. Zahlen sind für dich die Basis jeder Entscheidung, nicht lästige Pflicht.</li>\n<li>Kommunikationsstärke: Du hast ein Gespür für Sprache und Botschaften, die ankommen - egal ob für LinkedIn-Posts oder interne Meetings. Verhandlungssicheres Englisch ist ein Plus.</li>\n<li><strong>Extreme Ownership:</strong> Du brauchst niemanden, der dir sagt was zu tun ist. Wenn du eine Chance siehst, ergreifst du sie. Wenn Hindernisse kommen, überspringst du sie. Du gehst voran.</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 01:42:38.268', '2026-07-01 01:42:38.268', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/omnora-gmbh/junior-marketing-manager-frankfurt-am-main-364563', 'https://www.arbeitnow.com/jobs/companies/omnora-gmbh/junior-marketing-manager-frankfurt-am-main-364563', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/omnora-gmbh/junior-marketing-manager-frankfurt-am-main-364563\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1965, NULL, 'api', NULL, 'Accommodation Administrator FIFO 14 7 Roster Cairns Queensland', 'Sodexo', 'Queensland, Queensland, Australia', 'https://remoteOK.com/remote-jobs/remote-accommodation-administrator-fifo-14-7-roster-cairns-queensland-sodexo-1134252', '<strong>Job Description<br><br></strong><strong>Help create a home away from home<br><br></strong><ul><li>14 days on, 7 days off roster</li><li>Immediate Start available</li><li>Opportunity to join the 18th largest employer globally and leader in quality of life services <br><br></li></ul><strong>About The Job<br><br></strong>Due to our continued growth Sodexo is seeking an experienced Accommodation Administrator to work across our Far North Queensland sites. Reporting to the Integrated Services Manger, your main responsibilities will entail high volume accommodation check-ins and flight bookings, data entry, database maintenance and receptionist duties.<br><br>This is a local hire role meaning you need to live in Weipa and surrounding suburbs however we will consider fly in fly out from Cairns for the right applicant.<br><br><strong>About You<br><br></strong>You will consider yourself a well organised, self-motivated individual and hospitality professional with the ability to the below criteria:<br><br><ul><li>Accommodation reservation experience (In-flight) preferable in a remote village, resort or similar environment</li><li>Administration experience supporting a very fast paced team</li><li>Inflight Accommodation system knowledge desirable but not essential</li><li>Intermediate to advanced proficiency in MS Office Suite </li><li>Excellent written and verbal communication skills are essential</li><li>Proven ability to listen to customer needs, exceed expectations and provide outstanding customer service in a friendly manner</li><li>Open C class Driver Licences is essential<br><br></li></ul><strong>So what next? <br><br></strong>If this sounds like the right job for you, please apply.<br><br><strong>About So