(1992, NULL, 'api', NULL, 'Performance Marketing Manager B2B (m/w/d), 100 % remote', 'Leadeffect GmbH', 'Hamburg', 'https://www.arbeitnow.com/jobs/companies/leadeffect-gmbh/performance-marketing-manager-b2b-100-remote-hamburg-194741', '<p><strong>Über uns:</strong><br>\nDie Leadeffect GmbH mit Sitz in Hamburg unterstützt mehr als 70 IT-Unternehmen als langfristiger Online-Marketing-Partner; schwerpunktmäßig in den Bereichen Webdesign, SEO, SEA, LinkedIn und E-Mail-Marketing.</p>\n<p><strong>Projektbeschreibung:</strong><br>\nBist du der Typ, der gern datengetrieben arbeitet, bei den Kanälen immer auf dem neuesten Stand ist und Kampagnen nicht nur umsetzt, sondern strategisch vorantreibt? Bei uns übernimmst du die Verantwortung auf Kanalebene: Du planst, steuerst und optimierst die Kampagnen unserer Kunden und entwickelst passende Strategien zielgerichtet, performanceorientiert und mit vollem Ownership.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Aufgaben:</strong></p>\n<p><strong>Strategie für den Kunden auf Kanalebene entwickeln</strong></p>\n<p><strong>Google Ads Kampagnen</strong></p>\n<ul>\n<li>SEA Keyword Analysen</li>\n<li>SEA Kampagnen planen, aufsetzen, optimieren und auswerten</li>\n<li>Ad Copies schreiben</li>\n<li>Reportings erstellen</li>\n</ul>\n<p><strong>LinkedIn Kampagnen</strong></p>\n<ul>\n<li>Kampagnen planen und aufsetzen</li>\n<li>Monitoring und Optimierung, Nurturing</li>\n<li>Reporting und Auswertungen</li>\n</ul>\n<p><strong>Conversion Tracking mit dem Google Tag Manager und Analytics</strong></p>\n<ul>\n<li>Tracking Konzepte für Webseiten</li>\n<li>Erstellung von Analytics Reports</li>\n</ul>\n<p><strong>Nutzerfunnel und Conversion Optimierung (konzeptionell, keine Entwicklung)</strong></p>\n<ul>\n<li>Auswertung des Nutzerverhaltens auf der Webseite</li>\n<li>Conversion Optimierung von Landing Pages und der Website</li>\n<li>Landing Page Entwürfe</li>\n<li>Optimierung des Nutzers Funnels hinsichtlich Conversions</li>\n</ul>\n<p><strong>E Mail Outreach</strong></p>\n<ul>\n<li>Entwerfen von E-Mails/Sequenzen mit Apollo oder ähnlichen Tools</li>\n<li>Optimierung und Auswertung</li>\n</ul>\n<p><strong>Weiterentwicklung von Kanälen</strong></p>\n<ul>\n<li>neue Trends und Möglichkeiten finden</li>\n</ul>\n<p><strong>Zusammenarbeit mit dem Projekt Manager</strong></p>\n<ul>\n<li>Erstellen von Reportings, Analysen und Dokumentationen</li>\n<li>Kundensupport</li>\n<li>vereinzelt: Teilnahme an Kunden-Meetings</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Must-haves</strong></p>\n<ul>\n<li>Erfahrung im Online-Marketing (mindestens 2 Jahre) und</li>\n<li>Kenntnisse im Umgang mit digitalen Tools und Plattformen</li>\n<li>proaktives und analytisches Mindset, lösungsorientiertes Denken</li>\n<li>lernbereit, schnelle Auffassungsgabe</li>\n<li>Offenheit, Kontaktfreude und Kommunikationsstärke</li>\n<li>zuverlässige und detailorientierte Arbeitsweise</li>\n<li>hohe IT-Affinität</li>\n<li>Deutsch: am besten C1, bist du bei B2 - zahlen wir deinen Kurs, wenn du Lust hast, weiterzulernen; Englisch Business Level</li>\n</ul>\n<p><strong>Nice-to-haves</strong></p>\n<ul>\n<li>Erfahrung im B2B Marketing (idealerweise im IT-Bereich)</li>\n<li>Google Ads-Erfahrung, fundiertes Wissen in Keyword-Recherchen, Kampagnen- Optimierung</li>\n<li>Erfahrung in LinkedIn Leadgenerierung</li>\n<li>Erfahrung mit E-Mail Copywriting (Apollo oder ähnliche Tools)</li>\n</ul>\n<p><strong>Wenn du nicht alle Kriterien erfüllst, bilden wir dich gern aus.</strong></p>\n<h2>Benefits</h2>\n<p><strong>Projektrahmen und Benefits</strong></p>\n<ul>\n<li>Zusammenarbeit als Festanstellung oder auf Freelancer-Basis</li>\n<li>Start: so bald wie möglich</li>\n<li>mind. 20 Stunden pro Woche bis Vollzeit</li>\n<li>100 % remote</li>\n<li>Kommunikation in Zeitzone CET (Berlin) erwartet, max. +/- 2 Stunden</li>\n<li>partnerschaftliche Zusammenarbeit (strategisch steht immer ein Projekt Manager zur Seite)</li>\n<li>Zugang zu unserer eigenen Ausbildungsplattform für B2B-Marketing, für kontinuierliche Weiterbildung und den Ausbau deiner Marketing-Expertise</li>\n</ul>\n<p><strong>So bewirbst du dich:</strong></p>\n<p>über diese Plattform</p>\n<p>Sende uns bitte</p>\n<ul>\n<li>eine kurze Vorstellung deiner Person</li>\n<li>deine relevanten Erfahrungen</li>\n<li>deine Verfügbarkeit und Gehalts- oder Honorarvorstellung</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Über uns:</strong><br>\nDie Leadeffect GmbH mit Sitz in Hamburg unterstützt mehr als 70 IT-Unternehmen als langfristiger Online-Marketing-Partner; schwerpunktmäßig in den Bereichen Webdesign, SEO, SEA, LinkedIn und E-Mail-Marketing.</p>\n<p><strong>Projektbeschreibung:</strong><br>\nBist du der Typ, der gern datengetrieben arbeitet, bei den Kanälen immer auf dem neuesten Stand ist und Kampagnen nicht nur umsetzt, sondern strategisch vorantreibt? Bei uns übernimmst du die Verantwortung auf Kanalebene: Du planst, steuerst und optimierst die Kampagnen unserer Kunden und entwickelst passende Strategien zielgerichtet, performanceorientiert und mit vollem Ownership.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Aufgaben:</strong></p>\n<p><strong>Strategie für den Kunden auf Kanalebene entwickeln</strong></p>\n<p><strong>Google Ads Kampagnen</strong></p>\n<ul>\n<li>SEA Keyword Analysen</li>\n<li>SEA Kampagnen planen, aufsetzen, optimieren und auswerten</li>\n<li>Ad Copies schreiben</li>\n<li>Reportings erstellen</li>\n</ul>\n<p><strong>LinkedIn Kampagnen</strong></p>\n<ul>\n<li>Kampagnen planen und aufsetzen</li>\n<li>Monitoring und Optimierung, Nurturing</li>\n<li>Reporting und Auswertungen</li>\n</ul>\n<p><strong>Conversion Tracking mit dem Google Tag Manager und Analytics</strong></p>\n<ul>\n<li>Tracking Konzepte für Webseiten</li>\n<li>Erstellung von Analytics Reports</li>\n</ul>\n<p><strong>Nutzerfunnel und Conversion Optimierung (konzeptionell, keine Entwicklung)</strong></p>\n<ul>\n<li>Auswertung des Nutzerverhaltens auf der Webseite</li>\n<li>Conversion Optimierung von Landing Pages und der Website</li>\n<li>Landing Page Entwürfe</li>\n<li>Optimierung des Nutzers Funnels hinsichtlich Conversions</li>\n</ul>\n<p><strong>E Mail Outreach</strong></p>\n<ul>\n<li>Entwerfen von E-Mails/Sequenzen mit Apollo oder ähnlichen Tools</li>\n<li>Optimierung und Auswertung</li>\n</ul>\n<p><strong>Weiterentwicklung von Kanälen</strong></p>\n<ul>\n<li>neue Trends und Möglichkeiten finden</li>\n</ul>\n<p><strong>Zusammenarbeit mit dem Projekt Manager</strong></p>\n<ul>\n<li>Erstellen von Reportings, Analysen und Dokumentationen</li>\n<li>Kundensupport</li>\n<li>vereinzelt: Teilnahme an Kunden-Meetings</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Must-haves</strong></p>\n<ul>\n<li>Erfahrung im Online-Marketing (mindestens 2 Jahre) und</li>\n<li>Kenntnisse im Umgang mit digitalen Tools und Plattformen</li>\n<li>proaktives und analytisches Mindset, lösungsorientiertes Denken</li>\n<li>lernbereit, schnelle Auffassungsgabe</li>\n<li>Offenheit, Kontaktfreude und Kommunikationsstärke</li>\n<li>zuverlässige und detailorientierte Arbeitsweise</li>\n<li>hohe IT-Affinität</li>\n<li>Deutsch: am besten C1, bist du bei B2 - zahlen wir deinen Kurs, wenn du Lust hast, weiterzulernen; Englisch Business Level</li>\n</ul>\n<p><strong>Nice-to-haves</strong></p>\n<ul>\n<li>Erfahrung im B2B Marketing (idealerweise im IT-Bereich)</li>\n<li>Google Ads-Erfahrung, fundiertes Wissen in Keyword-Recherchen, Kampagnen- Optimierung</li>\n<li>Erfahrung in LinkedIn Leadgenerierung</li>\n<li>Erfahrung mit E-Mail Copywriting (Apollo oder ähnliche Tools)</li>\n</ul>\n<p><strong>Wenn du nicht alle Kriterien erfüllst, bilden wir dich gern aus.</strong></p>\n<h2>Benefits</h2>\n<p><strong>Projektrahmen und Benefits</strong></p>\n<ul>\n<li>Zusammenarbeit als Festanstellung oder auf Freelancer-Basis</li>\n<li>Start: so bald wie möglich</li>\n<li>mind. 20 Stunden pro Woche bis Vollzeit</li>\n<li>100 % remote</li>\n<li>Kommunikation in Zeitzone CET (Berlin) erwartet, max. +/- 2 Stunden</li>\n<li>partnerschaftliche Zusammenarbeit (strategisch steht immer ein Projekt Manager zur Seite)</li>\n<li>Zugang zu unserer eigenen Ausbildungsplattform für B2B-Marketing, für kontinuierliche Weiterbildung und den Ausbau deiner Marketing-Expertise</li>\n</ul>\n<p><strong>So bewirbst du dich:</strong></p>\n<p>über diese Plattform</p>\n<p>Sende uns bitte</p>\n<ul>\n<li>eine kurze Vorstellung deiner Person</li>\n<li>deine relevanten Erfahrungen</li>\n<li>deine Verfügbarkeit und Gehalts- oder Honorarvorstellung</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 13:41:52.074', '2026-07-01 13:41:52.074', '', '', 'Remote', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/leadeffect-gmbh/performance-marketing-manager-b2b-100-remote-hamburg-194741', 'https://www.arbeitnow.com/jobs/companies/leadeffect-gmbh/performance-marketing-manager-b2b-100-remote-hamburg-194741', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/leadeffect-gmbh/performance-marketing-manager-b2b-100-remote-hamburg-194741\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
