(1998, NULL, 'api', NULL, 'Working Student IT Consulting - weclapp ERP', 'BOLD & EPIC GmbH', 'Stuttgart', 'https://www.arbeitnow.com/jobs/companies/bold-epic-gmbh/working-student-it-consulting-weclapp-erp-stuttgart-222008', '<h2>Beschreibung</h2>\n<p>BOLD &#x26; EPIC Systems ist der führende Implementierungspartner für weclapp ERP im DACH-Raum. Wir begleiten Start-ups sowie kleine und mittelständische Unternehmen von der Einführung bis zur laufenden Optimierung – inklusive eigener Plugins und Schnittstellen, die weclapp genau auf die jeweiligen Prozesse zuschneiden. Künstliche Intelligenz ist dabei kein Add-on, sondern fester Bestandteil unserer Arbeit: Wir setzen Claude in Entwicklung, Datenanalyse und internen Workflows ein und integrieren KI tief in unsere Beratungs- und Entwicklungsleistungen.</p>\n<h2>Deine Aufgaben</h2>\n<ul>\n<li>Du unterstützt unsere Consultants bei der Einführung von weclapp ERP sowie der Schulung der Anwender</li>\n<li>Du wirkst bei der Umsetzung von Schnittstellen- und Plugin-Projekten mit</li>\n<li>Du analysierst eigenständig Kundenprozesse, Datenstrukturen und Anforderungen und übersetzt sie in saubere, praxistaugliche Konfigurationen</li>\n<li>Du dokumentierst Prozesse und Konfigurationen KI-gestützt – verständlich und nachvollziehbar für Kollegen und Kunden</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>Du studierst Wirtschaftsinformatik, BWL oder ein vergleichbares Fach</li>\n<li>Du denkst analytisch, arbeitest strukturiert und behältst auch bei komplexen Themen den Überblick</li>\n<li>Du achtest auf Genauigkeit und hast ein Auge fürs Detail</li>\n<li>Du bist teamfähig, kommunikationsstark und trittst sicher gegenüber Kollegen und Kunden auf</li>\n<li>Du bringst hohe Eigenmotivation mit und arbeitest dich eigenständig in neue Themen ein</li>\n<li>Du hast eine starke Affinität zu Systemen, Daten und KI-gestützten Prozessen</li>\n<li>Idealerweise hast du bereits mit Claude oder vergleichbaren KI-Tools gearbeitet</li>\n</ul>\n<h2>Wir bieten</h2>\n<ul>\n<li>Spannende, abwechslungsreiche Projekte</li>\n<li>Ein erfolgreicher Start – dafür arbeiten wir dich praxisnah, individuell und intensiv ein</li>\n<li>Viel Spielraum um dich selbst zu entfalten</li>\n<li>Moderner Arbeitsplatz mit flachen Hierarchien und kurzen Wegen</li>\n<li>Fahrradleasing über Lease-a-bike</li>\n<li>Flexible, ortsunabhängige Arbeitszeiten</li>\n<li>Klimatisiertes Office mit Dachterrasse mitten in der Stuttgarter City</li>\n</ul>\n<h2>Deine Bewerbung</h2>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>Beschreibung</h2>\n<p>BOLD &#x26; EPIC Systems ist der führende Implementierungspartner für weclapp ERP im DACH-Raum. Wir begleiten Start-ups sowie kleine und mittelständische Unternehmen von der Einführung bis zur laufenden Optimierung – inklusive eigener Plugins und Schnittstellen, die weclapp genau auf die jeweiligen Prozesse zuschneiden. Künstliche Intelligenz ist dabei kein Add-on, sondern fester Bestandteil unserer Arbeit: Wir setzen Claude in Entwicklung, Datenanalyse und internen Workflows ein und integrieren KI tief in unsere Beratungs- und Entwicklungsleistungen.</p>\n<h2>Deine Aufgaben</h2>\n<ul>\n<li>Du unterstützt unsere Consultants bei der Einführung von weclapp ERP sowie der Schulung der Anwender</li>\n<li>Du wirkst bei der Umsetzung von Schnittstellen- und Plugin-Projekten mit</li>\n<li>Du analysierst eigenständig Kundenprozesse, Datenstrukturen und Anforderungen und übersetzt sie in saubere, praxistaugliche Konfigurationen</li>\n<li>Du dokumentierst Prozesse und Konfigurationen KI-gestützt – verständlich und nachvollziehbar für Kollegen und Kunden</li>\n</ul>\n<h2>Dein Profil</h2>\n<ul>\n<li>Du studierst Wirtschaftsinformatik, BWL oder ein vergleichbares Fach</li>\n<li>Du denkst analytisch, arbeitest strukturiert und behältst auch bei komplexen Themen den Überblick</li>\n<li>Du achtest auf Genauigkeit und hast ein Auge fürs Detail</li>\n<li>Du bist teamfähig, kommunikationsstark und trittst sicher gegenüber Kollegen und Kunden auf</li>\n<li>Du bringst hohe Eigenmotivation mit und arbeitest dich eigenständig in neue Themen ein</li>\n<li>Du hast eine starke Affinität zu Systemen, Daten und KI-gestützten Prozessen</li>\n<li>Idealerweise hast du bereits mit Claude oder vergleichbaren KI-Tools gearbeitet</li>\n</ul>\n<h2>Wir bieten</h2>\n<ul>\n<li>Spannende, abwechslungsreiche Projekte</li>\n<li>Ein erfolgreicher Start – dafür arbeiten wir dich praxisnah, individuell und intensiv ein</li>\n<li>Viel Spielraum um dich selbst zu entfalten</li>\n<li>Moderner Arbeitsplatz mit flachen Hierarchien und kurzen Wegen</li>\n<li>Fahrradleasing über Lease-a-bike</li>\n<li>Flexible, ortsunabhängige Arbeitszeiten</li>\n<li>Klimatisiertes Office mit Dachterrasse mitten in der Stuttgarter City</li>\n</ul>\n<h2>Deine Bewerbung</h2>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 13:42:52.596', '2026-07-01 13:42:52.596', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/bold-epic-gmbh/working-student-it-consulting-weclapp-erp-stuttgart-222008', 'https://www.arbeitnow.com/jobs/companies/bold-epic-gmbh/working-student-it-consulting-weclapp-erp-stuttgart-222008', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/bold-epic-gmbh/working-student-it-consulting-weclapp-erp-stuttgart-222008\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(1999, NULL, 'api', NULL, 'Personaldisponent / OnSite Manager (gn) - gerne mit Polnisch- oder Rumänischkenntnissen', 'MatchingCompany®', 'Hamburg', 'https://www.arbeitnow.com/jobs/companies/matchingcompany/personaldisponent-onsite-manager-gn-gerne-mit-polnisch-oder-rumanischkenntnissen-hamburg-92375', '<p><strong>Du liebst die Arbeit mit Menschen und vereinst Kenntnisse der PD-Branche mit einer operativen Macher-Mentalität? Dann suchen wir vielleicht genau dich!</strong></p>\n<p><strong>Kurz zu uns:</strong><br>\nDie MatchingCompany® ist auf die branchenübergreifende Direktvermittlung von Fach- und Führungskräften in den Bereichen Rec2Rec und Corporate Functions spezialisiert. Dabei sind wir Berater aus Leidenschaft: Unser Anspruch ist es, Expertise mit Empathie zu verbinden und schauen dabei hinter den CV. Wir hinterfragen, hören zu und wir erkennen Potenziale, die auf dem Papier oft unsichtbar bleiben.</p>\n<p>Im Mandantenauftrag suchen wir für ein Projekt in <strong>Hamburg</strong> einen <strong>Personaldisponenten / Onsite Manager (gn)</strong> - gerne mit Polnisch- oder Rumänischkenntnissen für den gewerblich-technischen Bereich.</p>\n<h2>Aufgaben</h2>\n<p>Eigenverantwortliche Steuerung sowie organisatorische und administrative Abwicklung des Kundenprojekts:</p>\n<ul>\n<li>Rekrutierung neuer Mitarbeiter (gn) für Einsätze im Rahmen der Arbeitnehmerüberlassung über diverse Kanäle</li>\n<li>Abwicklung des gesamten Personalmanagements inkl. Vertragsgestaltung</li>\n<li>Passende Disposition der Mitarbeiter (gn) entsprechend der definierten Kundenanforderungen</li>\n<li>Einsatzplanung und Betreuung der Mitarbeiter im Schichtmodell</li>\n<li>Analyse und fortlaufende Optimierung der Arbeitsabläufe und -prozesse</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erfolgreich abgeschlossene Ausbildung</li>\n<li>Erfahrung in der Personaldienstleistungsbranche (Arbeitnehmerüberlassung) im generalistischen bzw. gewerblich-technischen Bereich und gerne auch in der Logistikbranche</li>\n<li>Fließende Deutschkenntnisse in Wort und Schrift</li>\n<li>Ein Plus: Polnisch- oder Rumänischkenntnisse zur Betreuung der internationalen Fachkräfte</li>\n<li>Freude am Umgang mit Menschen und Spaß an Projektarbeit</li>\n<li>Hohe Eigenverantwortung und ausgeprägter Dienstleistungsgedanke</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Unbefristetes Arbeitsverhältnis</li>\n<li>Leistungsgerechte Bezahlung sowie Bonusvereinbarungen und Beteiligung am Unternehmenserfolg</li>\n<li>Mind. 30 Tage Urlaub</li>\n<li>Umfangreiches Onboarding und kontinuierliche Weiterbildungen</li>\n<li>Gestaltungsspielraum sowie individuelle Entwicklungsmöglichkeiten</li>\n<li>Weitere Corporate Benefits hinsichtlich Gesundheit, Familie und Altersvorsorge</li>\n</ul>\n<p><strong>Klingt nach einem möglichen \"Match\"?</strong> 🎯</p>\n<p>Dann freuen wir uns auf deine Bewerbung - professioneller Umgang mit deinen Daten ist für uns selbstverständlich.</p>\n<p>Du interessierst dich für eine alternative Position, einen anderen Standort oder möchtest dich initiativ bewerben? Ruf uns gerne an oder schreib uns eine E-Mail, wir antworten garantiert! 🙂</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Du liebst die Arbeit mit Menschen und vereinst Kenntnisse der PD-Branche mit einer operativen Macher-Mentalität? Dann suchen wir vielleicht genau dich!</strong></p>\n<p><strong>Kurz zu uns:</strong><br>\nDie MatchingCompany® ist auf die branchenübergreifende Direktvermittlung von Fach- und Führungskräften in den Bereichen Rec2Rec und Corporate Functions spezialisiert. Dabei sind wir Berater aus Leidenschaft: Unser Anspruch ist es, Expertise mit Empathie zu verbinden und schauen dabei hinter den CV. Wir hinterfragen, hören zu und wir erkennen Potenziale, die auf dem Papier oft unsichtbar bleiben.</p>\n<p>Im Mandantenauftrag suchen wir für ein Projekt in <strong>Hamburg</strong> einen <strong>Personaldisponenten / Onsite Manager (gn)</strong> - gerne mit Polnisch- oder Rumänischkenntnissen für den gewerblich-technischen Bereich.</p>\n<h2>Aufgaben</h2>\n<p>Eigenverantwortliche Steuerung sowie organisatorische und administrative Abwicklung des Kundenprojekts:</p>\n<ul>\n<li>Rekrutierung neuer Mitarbeiter (gn) für Einsätze im Rahmen der Arbeitnehmerüberlassung über diverse Kanäle</li>\n<li>Abwicklung des gesamten Personalmanagements inkl. Vertragsgestaltung</li>\n<li>Passende Disposition der Mitarbeiter (gn) entsprechend der definierten Kundenanforderungen</li>\n<li>Einsatzplanung und Betreuung der Mitarbeiter im Schichtmodell</li>\n<li>Analyse und fortlaufende Optimierung der Arbeitsabläufe und -prozesse</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erfolgreich abgeschlossene Ausbildung</li>\n<li>Erfahrung in der Personaldienstleistungsbranche (Arbeitnehmerüberlassung) im generalistischen bzw. gewerblich-technischen Bereich und gerne auch in der Logistikbranche</li>\n<li>Fließende Deutschkenntnisse in Wort und Schrift</li>\n<li>Ein Plus: Polnisch- oder Rumänischkenntnisse zur Betreuung der internationalen Fachkräfte</li>\n<li>Freude am Umgang mit Menschen und Spaß an Projektarbeit</li>\n<li>Hohe Eigenverantwortung und ausgeprägter Dienstleistungsgedanke</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Unbefristetes Arbeitsverhältnis</li>\n<li>Leistungsgerechte Bezahlung sowie Bonusvereinbarungen und Beteiligung am Unternehmenserfolg</li>\n<li>Mind. 30 Tage Urlaub</li>\n<li>Umfangreiches Onboarding und kontinuierliche Weiterbildungen</li>\n<li>Gestaltungsspielraum sowie individuelle Entwicklungsmöglichkeiten</li>\n<li>Weitere Corporate Benefits hinsichtlich Gesundheit, Familie und Altersvorsorge</li>\n</ul>\n<p><strong>Klingt nach einem möglichen \"Match\"?</strong> 🎯</p>\n<p>Dann freuen wir uns auf deine Bewerbung - professioneller Umgang mit deinen Daten ist für uns selbstverständlich.</p>\n<p>Du interessierst dich für eine alternative Position, einen anderen Standort oder möchtest dich initiativ bewerben? Ruf uns gerne an oder schreib uns eine E-Mail, wir antworten garantiert! 🙂</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 13:43:01.928', '2026-07-01 13:43:01.928', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/matchingcompany/personaldisponent-onsite-manager-gn-gerne-mit-polnisch-oder-rumanischkenntnissen-hamburg-92375', 'https://www.arbeitnow.com/jobs/companies/matchingcompany/personaldisponent-onsite-manager-gn-gerne-mit-polnisch-oder-rumanischkenntnissen-hamburg-92375', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/matchingcompany/personaldisponent-onsite-manager-gn-gerne-mit-polnisch-oder-rumanischkenntnissen-hamburg-92375\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2000, NULL, 'api', NULL, 'Praktikant (m/w/d) Human Resources am Standort Leipzig', 'allaboutHRLaw GmbH', 'Leipzig', 'https://www.arbeitnow.com/jobs/companies/allabouthrlaw-gmbh/praktikant-human-resources-am-standort-leipzig-18291', '<p><strong>allaboutHRLaw</strong> GmbH ist ein dynamisches, stark wachsendes Beratungsunternehmen, welches für Start-ups, kleine und mittelständische Unternehmen ganz oder teilweise die Personalarbeit übernimmt, als HR as a service. Wir haben bereits namhafte Start-ups auf dem Weg zum „erwachsenen“ Unternehmen begleitet und betreuen unsere Kunden über Jahre hinweg. Referenzen kannst du auf unserer Website  einsehen.</p>\n<p>Wir sind ein Team von hochmotivierten bundesweit tätigen HRlern mit Fokus auf die Ballungsräume Berlin, Hamburg, Frankfurt/Main, Leipzig, Düsseldorf und München und einem coolen Büro in Leipzig, das alle internen Aufgaben abdeckt.</p>\n<h2>Aufgaben</h2>\n<p>Du hast Lust, in die Welt der Personalentwicklung einzutauchen und möchtest uns als Praktikant (m/w/d) im Bereich Human Resources tatkräftig unterstützen? Dann suchen wir genau DICH, um unser wachsendes Team zu bereichern!</p>\n<p><strong>Deine Aufgaben:</strong></p>\n<ul>\n<li><strong>Recruiting Support</strong>: Du hilfst bei der Stellenschaltung und -aktualisierung und unterstützt uns im gesamten Recruiting-Prozess.</li>\n<li><strong>Bewerbermanagement</strong>: Vom ersten Kontakt bis zum Bewerbungsgespräch – Du organisierst und koordinierst den gesamten Ablauf und nimmst aktiv am Auswahlprozess teil.</li>\n<li><strong>Administrative Tätigkeiten</strong>: Du pflegst Personalakten, bearbeitest Anfragen und kümmerst dich um die Anforderung von Personalunterlagen.</li>\n<li><strong>Onboarding</strong>: Du gestaltest unseren Onboarding-Prozess aktiv mit und unterstützt die neuen Teammitglieder bei ihrem Start.</li>\n<li><strong>Projektarbeit</strong>: Du übernimmst eigenständig kleinere Projekte und bringst frische Ideen in unsere HR-Strategien ein.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringst Du mit:</strong></p>\n<ul>\n<li><strong>Strukturierte Arbeitsweise</strong>: Du arbeitest genau, selbstständig und behältst auch bei mehreren Aufgaben den Überblick.</li>\n<li><strong>Teamplayer</strong>: Du kannst gut mit anderen zusammenarbeiten und kommunizierst klar und offen.</li>\n<li><strong>Belastbarkeit und Freundlichkeit</strong>: Du bleibst auch in stressigen Phasen freundlich und lösungsorientiert.</li>\n<li><strong>Gute Office-Kenntnisse</strong>: Du beherrschst die gängigen Office-Programme und bist ein proaktiver Nutzer der digitalen Tools.</li>\n<li><strong>Zeit</strong>: Du solltest mindestens 3 Monate für das Praktikum einplanen.</li>\n<li><strong>Vorkenntnisse im HR-Bereich sind ein Plus</strong>, aber kein Muss!</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Das bieten wir Dir:</strong></p>\n<ul>\n<li><strong>Viel Raum für Deine Ideen</strong>: Gestalte aktiv mit und bringe Deine Ideen in unser Unternehmen ein.</li>\n<li><strong>Steile Lernkurve</strong>: Du wirst eine Menge lernen und erhältst einen tiefen Einblick in die Personalabteilung.</li>\n<li><strong>Flache Hierarchien</strong>: Wir bieten ein dynamisches Arbeitsumfeld mit schnellen Entscheidungswegen und einem motivierten Team.</li>\n<li><strong>Flexibilität</strong>: Nutze flexible Arbeitszeiten, um Familie und Beruf optimal miteinander zu vereinbaren.</li>\n</ul>\n<p><strong>Du bist überzeugt?</strong></p>\n<p>Dann freuen wir uns auf Deine vollständigen Bewerbungsunterlagen per E-Mail unter Angabe des Jobtitels, des Standorts, des möglichen Eintrittsdatums und der gewünschten Praktikumsdauer.</p>\n<p><strong>Bei Fragen</strong> erreichst Du uns auch telefonisch unter 089 6429 2900 oder per E-Mail.</p>\n<p>Werde Teil unserer Erfolgsgeschichte – wir freuen uns auf Dich!</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>allaboutHRLaw</strong> GmbH ist ein dynamisches, stark wachsendes Beratungsunternehmen, welches für Start-ups, kleine und mittelständische Unternehmen ganz oder teilweise die Personalarbeit übernimmt, als HR as a service. Wir haben bereits namhafte Start-ups auf dem Weg zum „erwachsenen“ Unternehmen begleitet und betreuen unsere Kunden über Jahre hinweg. Referenzen kannst du auf unserer Website  einsehen.</p>\n<p>Wir sind ein Team von hochmotivierten bundesweit tätigen HRlern mit Fokus auf die Ballungsräume Berlin, Hamburg, Frankfurt/Main, Leipzig, Düsseldorf und München und einem coolen Büro in Leipzig, das alle internen Aufgaben abdeckt.</p>\n<h2>Aufgaben</h2>\n<p>Du hast Lust, in die Welt der Personalentwicklung einzutauchen und möchtest uns als Praktikant (m/w/d) im Bereich Human Resources tatkräftig unterstützen? Dann suchen wir genau DICH, um unser wachsendes Team zu bereichern!</p>\n<p><strong>Deine Aufgaben:</strong></p>\n<ul>\n<li><strong>Recruiting Support</strong>: Du hilfst bei der Stellenschaltung und -aktualisierung und unterstützt uns im gesamten Recruiting-Prozess.</li>\n<li><strong>Bewerbermanagement</strong>: Vom ersten Kontakt bis zum Bewerbungsgespräch – Du organisierst und koordinierst den gesamten Ablauf und nimmst aktiv am Auswahlprozess teil.</li>\n<li><strong>Administrative Tätigkeiten</strong>: Du pflegst Personalakten, bearbeitest Anfragen und kümmerst dich um die Anforderung von Personalunterlagen.</li>\n<li><strong>Onboarding</strong>: Du gestaltest unseren Onboarding-Prozess aktiv mit und unterstützt die neuen Teammitglieder bei ihrem Start.</li>\n<li><strong>Projektarbeit</strong>: Du übernimmst eigenständig kleinere Projekte und bringst frische Ideen in unsere HR-Strategien ein.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Das bringst Du mit:</strong></p>\n<ul>\n<li><strong>Strukturierte Arbeitsweise</strong>: Du arbeitest genau, selbstständig und behältst auch bei mehreren Aufgaben den Überblick.</li>\n<li><strong>Teamplayer</strong>: Du kannst gut mit anderen zusammenarbeiten und kommunizierst klar und offen.</li>\n<li><strong>Belastbarkeit und Freundlichkeit</strong>: Du bleibst auch in stressigen Phasen freundlich und lösungsorientiert.</li>\n<li><strong>Gute Office-Kenntnisse</strong>: Du beherrschst die gängigen Office-Programme und bist ein proaktiver Nutzer der digitalen Tools.</li>\n<li><strong>Zeit</strong>: Du solltest mindestens 3 Monate für das Praktikum einplanen.</li>\n<li><strong>Vorkenntnisse im HR-Bereich sind ein Plus</strong>, aber kein Muss!</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Das bieten wir Dir:</strong></p>\n<ul>\n<li><strong>Viel Raum für Deine Ideen</strong>: Gestalte aktiv mit und bringe Deine Ideen in unser Unternehmen ein.</li>\n<li><strong>Steile Lernkurve</strong>: Du wirst eine Menge lernen und erhältst einen tiefen Einblick in die Personalabteilung.</li>\n<li><strong>Flache Hierarchien</strong>: Wir bieten ein dynamisches Arbeitsumfeld mit schnellen Entscheidungswegen und einem motivierten Team.</li>\n<li><strong>Flexibilität</strong>: Nutze flexible Arbeitszeiten, um Familie und Beruf optimal miteinander zu vereinbaren.</li>\n</ul>\n<p><strong>Du bist überzeugt?</strong></p>\n<p>Dann freuen wir uns auf Deine vollständigen Bewerbungsunterlagen per E-Mail unter Angabe des Jobtitels, des Standorts, des möglichen Eintrittsdatums und der gewünschten Praktikumsdauer.</p>\n<p><strong>Bei Fragen</strong> erreichst Du uns auch telefonisch unter 089 6429 2900 oder per E-Mail.</p>\n<p>Werde Teil unserer Erfolgsgeschichte – wir freuen uns auf Dich!</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 13:43:10.103', '2026-07-01 13:43:10.103', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/allabouthrlaw-gmbh/praktikant-human-resources-am-standort-leipzig-18291', 'https://www.arbeitnow.com/jobs/companies/allabouthrlaw-gmbh/praktikant-human-resources-am-standort-leipzig-18291', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/allabouthrlaw-gmbh/praktikant-human-resources-am-standort-leipzig-18291\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2001, NULL, 'api', NULL, 'Senior Freelance eazyBI & JIRA Reporting Specialist (Contract)', 'Deep Automation', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/deep-automation/senior-freelance-eazybi-jira-reporting-specialist-contract-berlin-459690', '<p>DeepAutomation is looking for an experienced <strong>eazyBI Reporting Specialist</strong> to support us on a contractual basis in building advanced reports and dashboards for a complex software platform. This is a hands-on implementation role focused on transforming data into meaningful insights through sophisticated reporting solutions.</p>\n<h2>Tasks</h2>\n<p>Train the team, Design, build, and optimize advanced reports and dashboards using <strong>eazyBI</strong><br>\nAnalyze with the team a complex program and data structure to develop meaningful reporting solutions</p>\n<p>Create with the team custom calculations, MDX formulas, and advanced visualizations</p>\n<p>Collaborate with the DeepAutomation team to understand reporting requirements and business needs</p>\n<p>Validate data accuracy and ensure high-quality reporting outputs</p>\n<p>Document report logic and provide knowledge transfer where required</p>\n<h2>Requirements</h2>\n<p>Proven experience with <strong>eazyBI</strong>, including advanced report development<br>\nStrong knowledge of <strong>MDX</strong> and multidimensional data analysis</p>\n<p>Experience working with complex project or program structures (preferably Jira-based)</p>\n<p>Ability to translate business requirements into intuitive dashboards and reports</p>\n<p>Strong analytical and problem-solving skills</p>\n<p>Ability to work independently and deliver results within agreed timelines</p>\n<p>Excellent English communication skills</p>\n<p>BigPicture Skills is a must</p>\n<h2>Benefits</h2>\n<p><strong>Freelance / ContractorOne-time project</strong> with a defined scope</p>\n<p>Remote work</p>\n<p>Immediate or short-term availability preferred</p>\n<p>This engagement is ideal for an experienced eazyBI consultant who enjoys solving complex reporting challenges and delivering high-quality analytics solutions in collaboration with an innovative software development company.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>DeepAutomation is looking for an experienced <strong>eazyBI Reporting Specialist</strong> to support us on a contractual basis in building advanced reports and dashboards for a complex software platform. This is a hands-on implementation role focused on transforming data into meaningful insights through sophisticated reporting solutions.</p>\n<h2>Tasks</h2>\n<p>Train the team, Design, build, and optimize advanced reports and dashboards using <strong>eazyBI</strong><br>\nAnalyze with the team a complex program and data structure to develop meaningful reporting solutions</p>\n<p>Create with the team custom calculations, MDX formulas, and advanced visualizations</p>\n<p>Collaborate with the DeepAutomation team to understand reporting requirements and business needs</p>\n<p>Validate data accuracy and ensure high-quality reporting outputs</p>\n<p>Document report logic and provide knowledge transfer where required</p>\n<h2>Requirements</h2>\n<p>Proven experience with <strong>eazyBI</strong>, including advanced report development<br>\nStrong knowledge of <strong>MDX</strong> and multidimensional data analysis</p>\n<p>Experience working with complex project or program structures (preferably Jira-based)</p>\n<p>Ability to translate business requirements into intuitive dashboards and reports</p>\n<p>Strong analytical and problem-solving skills</p>\n<p>Ability to work independently and deliver results within agreed timelines</p>\n<p>Excellent English communication skills</p>\n<p>BigPicture Skills is a must</p>\n<h2>Benefits</h2>\n<p><strong>Freelance / ContractorOne-time project</strong> with a defined scope</p>\n<p>Remote work</p>\n<p>Immediate or short-term availability preferred</p>\n<p>This engagement is ideal for an experienced eazyBI consultant who enjoys solving complex reporting challenges and delivering high-quality analytics solutions in collaboration with an innovative software development company.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 13:43:19.082', '2026-07-01 13:43:19.082', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/deep-automation/senior-freelance-eazybi-jira-reporting-specialist-contract-berlin-459690', 'https://www.arbeitnow.com/jobs/companies/deep-automation/senior-freelance-eazybi-jira-reporting-specialist-contract-berlin-459690', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/deep-automation/senior-freelance-eazybi-jira-reporting-specialist-contract-berlin-459690\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2002, NULL, 'api', NULL, 'Senior Manager für digitale Abrechnungsprozesse und Controlling (m/w/d) - erneuerbare Energien, Raum Paderborn / Brilon / Bad Arolsen', 'farmconnect', 'Marsberg', 'https://www.arbeitnow.com/jobs/companies/farmconnect/senior-manager-fur-digitale-abrechnungsprozesse-und-controlling-erneuerbare-energien-raum-paderborn-brilon-bad-arolsen-marsberg-321203', '<p>Du möchtest aktiv mitgestalten und hast Freude daran, Abrechnungs- und Controllingstrukturen neu aufzubauen, zu optimieren und im Tagesgeschäft erfolgreich umzusetzen? Neue gesetzliche Anforderungen – insbesondere im Umfeld der erneuerbaren Energien – analysierst Du kritisch, verstehst deren Auswirkungen und überführst sie in effiziente, praxisnahe Prozesse. Zudem begeisterst Du Dich für Digitalisierung und hast Freude daran, die Einführung moderner Softwarelösungen für Buchhaltung, Abrechnung und Controlling aktiv voranzutreiben.</p>\n<p>Dann suchen wir genau Dich als Senior Manager für digitale Abrechnungsprozesse und Controlling im Bereich erneuerbare Energien (m/w/d).</p>\n<p>Dieses wachsende Unternehmen im Bereich der erneuerbaren Energien unterstützt Betreiber von Windenergieanlagen mit datengetriebener Betriebsführung, intelligentem Monitoring und technischem Service. Das Unternehmen steht für Fortschritt, Innovation und nachhaltiges Wachstum. Flache Hierarchien, kurze Entscheidungswege und eine offene Kommunikation auf Augenhöhe schaffen ein Umfeld, in dem Ideen gehört werden und Veränderungen schnell umgesetzt werden können.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Neuaufbau, Optimierung und kontinuierliche Verbesserung von Prozessen (Buchhaltung, Controlling und Abrechnung)</li>\n<li>Analyse und Interpretation gesetzlicher Anforderungen (insb. im Bereich der Energiewirtschaft)</li>\n<li>Aufbau und Weiterentwicklung eines Controlling-Systems inkl. KPI-Strukturen und Management-Reportings</li>\n<li>Operative Umsetzung und Anwendung der Prozesse im Tagesgeschäft</li>\n<li>Mitwirkung bei der Einführung von Softwarelösungen für Buchhaltung, Abrechnung und Controlling</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Kaufmännische Ausbildung oder abgeschlossenes Studium mit mehrjähriger Berufserfahrung im Bereich Rechnungswesen, Controlling oder Finanzwesen</li>\n<li>Ausgeprägtes Prozessdenken sowie eine pragmatische Herangehensweise</li>\n<li>Strukturierte und lösungsorientierte Arbeitsweise</li>\n<li>Hohe Anpassungsfähigkeit und Veränderungsbereitschaft Sicherer Umgang mit Excel und MS Office sowie idealerweise Erfahrung mit ERP-, Buchhaltungs- oder Reporting-Software (z. B. SAP oder vergleichbar)</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Eine neu geschaffene Schlüsselposition mit großem Gestaltungs- und Entscheidungsspielraum</li>\n<li>Die Möglichkeit, Prozesse, Strukturen und digitale Lösungen eigenständig aufzubauen</li>\n<li>Entwicklungsmöglichkeiten in einem dynamischen und zukunftssicheren Wachstumsmarkt der erneuerbaren Energien</li>\n<li>Ein Arbeitsumfeld, in dem Ideen gehört und in die Umsetzung gebracht werden</li>\n<li>Direkte Zusammenarbeit mit der Geschäftsführung und kurze Entscheidungswege</li>\n<li>Fundierte Einarbeitung sowie enge Begleitung durch die Geschäftsführung</li>\n</ul>\n<p>Klingt spannend?<br>\nDann melde dich gerne bei uns - wir freuen uns auf deine Bewerbung!<br>\nSina Strothmeyer (0151/2977 2582)</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Du möchtest aktiv mitgestalten und hast Freude daran, Abrechnungs- und Controllingstrukturen neu aufzubauen, zu optimieren und im Tagesgeschäft erfolgreich umzusetzen? Neue gesetzliche Anforderungen – insbesondere im Umfeld der erneuerbaren Energien – analysierst Du kritisch, verstehst deren Auswirkungen und überführst sie in effiziente, praxisnahe Prozesse. Zudem begeisterst Du Dich für Digitalisierung und hast Freude daran, die Einführung moderner Softwarelösungen für Buchhaltung, Abrechnung und Controlling aktiv voranzutreiben.</p>\n<p>Dann suchen wir genau Dich als Senior Manager für digitale Abrechnungsprozesse und Controlling im Bereich erneuerbare Energien (m/w/d).</p>\n<p>Dieses wachsende Unternehmen im Bereich der erneuerbaren Energien unterstützt Betreiber von Windenergieanlagen mit datengetriebener Betriebsführung, intelligentem Monitoring und technischem Service. Das Unternehmen steht für Fortschritt, Innovation und nachhaltiges Wachstum. Flache Hierarchien, kurze Entscheidungswege und eine offene Kommunikation auf Augenhöhe schaffen ein Umfeld, in dem Ideen gehört werden und Veränderungen schnell umgesetzt werden können.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Neuaufbau, Optimierung und kontinuierliche Verbesserung von Prozessen (Buchhaltung, Controlling und Abrechnung)</li>\n<li>Analyse und Interpretation gesetzlicher Anforderungen (insb. im Bereich der Energiewirtschaft)</li>\n<li>Aufbau und Weiterentwicklung eines Controlling-Systems inkl. KPI-Strukturen und Management-Reportings</li>\n<li>Operative Umsetzung und Anwendung der Prozesse im Tagesgeschäft</li>\n<li>Mitwirkung bei der Einführung von Softwarelösungen für Buchhaltung, Abrechnung und Controlling</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Kaufmännische Ausbildung oder abgeschlossenes Studium mit mehrjähriger Berufserfahrung im Bereich Rechnungswesen, Controlling oder Finanzwesen</li>\n<li>Ausgeprägtes Prozessdenken sowie eine pragmatische Herangehensweise</li>\n<li>Strukturierte und lösungsorientierte Arbeitsweise</li>\n<li>Hohe Anpassungsfähigkeit und Veränderungsbereitschaft Sicherer Umgang mit Excel und MS Office sowie idealerweise Erfahrung mit ERP-, Buchhaltungs- oder Reporting-Software (z. B. SAP oder vergleichbar)</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Eine neu geschaffene Schlüsselposition mit großem Gestaltungs- und Entscheidungsspielraum</li>\n<li>Die Möglichkeit, Prozesse, Strukturen und digitale Lösungen eigenständig aufzubauen</li>\n<li>Entwicklungsmöglichkeiten in einem dynamischen und zukunftssicheren Wachstumsmarkt der erneuerbaren Energien</li>\n<li>Ein Arbeitsumfeld, in dem Ideen gehört und in die Umsetzung gebracht werden</li>\n<li>Direkte Zusammenarbeit mit der Geschäftsführung und kurze Entscheidungswege</li>\n<li>Fundierte Einarbeitung sowie enge Begleitung durch die Geschäftsführung</li>\n</ul>\n<p>Klingt spannend?<br>\nDann melde dich gerne bei uns - wir freuen uns auf deine Bewerbung!<br>\nSina Strothmeyer (0151/2977 2582)</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-01 13:43:27.578', '2026-07-01 13:43:27.578', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/farmconnect/senior-manager-fur-digitale-abrechnungsprozesse-und-controlling-erneuerbare-energien-raum-paderborn-brilon-bad-arolsen-marsberg-321203', 'https://www.arbeitnow.com/jobs/companies/farmconnect/senior-manager-fur-digitale-abrechnungsprozesse-und-controlling-erneuerbare-energien-raum-paderborn-brilon-bad-arolsen-marsberg-321203', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/farmconnect/senior-manager-fur-digitale-abrechnungsprozesse-und-controlling-erneuerbare-energien-raum-paderborn-brilon-bad-arolsen-marsberg-321203\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
