INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(2081, NULL, 'api', NULL, 'IT Infrastructure and Security Engineer', 'Zentso S GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/zentso-s-gmbh/it-infrastructure-and-security-engineer-berlin-498582', '<p>Zentso builds and operates CloudToolz, a revenue-critical SaaS platform layered on top of iMIS RiSE association management software, serving clients across the UK, Europe, United States, and Asia Pacific. The platform encompasses workflow automation, form building, CRM, CMS, and payment processing capabilities delivered to organisations in multiple sectors.</p>\n<p>We are seeking a motivated IT Infrastructure and Security Engineer to support the global infrastructure and security posture underpinning CloudToolz and Zentso\'s internal systems. This is a hands-on, junior-to-mid-level role working closely with the IT Infrastructure and Security Lead and the CTO, assisting with day-to-day operations, security tasks, and the ongoing migration toward a containerised, Kubernetes-based deployment model. The successful candidate will be comfortable working across a distributed, multi-region environment, contributing directly to uptime, security, and compliance outcomes for a production platform.</p>\n<p>A key part of this role is supporting Zentso\'s transition to Kubernetes and helping build out an observability practice around Grafana OSS, alongside contributing scripts and small applications that automate and support infrastructure operations.</p>\n<h2>Tasks</h2>\n<p><strong>Infrastructure and Platform Operations</strong></p>\n<ul>\n<li>Help manage global infrastructure spanning Windows Server 2022, SQL Server, MongoDB, Redis, and Cloudflare across four regions, supporting the availability, performance, and scalability of the revenue-critical CloudToolz platform.</li>\n<li>Support deployments of new CloudToolz releases (<a href=\"http://ASP.NET\">ASP.NET</a> Core, integrating with Dynamics, iMIS, Salesforce, and native CRM/CMS) and contribute to the Kubernetes migration, including cluster operations such as deployments, scaling, network policies, and RBAC.</li>\n<li>Help build and maintain a Grafana OSS observability stack — dashboards, alerting, and integration with metrics, logs, and traces.Assist with DNS, CDN, WAF, and DDoS protection via Cloudflare; monitor system performance and participate in incident response and recovery.</li>\n<li>Maintain documentation, runbooks, and disaster recovery procedures.</li>\n<li>Write shell scripts and small infrastructure-related applications (automation tools, monitoring utilities, internal dashboards) in coordination with the Infrastructure Lead.</li>\n</ul>\n<p><strong>Security Operations</strong></p>\n<ul>\n<li>Support identity and access management, endpoint protection, and vulnerability management.</li>\n<li>Help administer policies across Microsoft 365, Bitwarden, Bitdefender GravityZone, and KnowBe4.</li>\n<li>Contribute to GDPR/ISO 27001-aligned data protection policies, security awareness training, phishing simulations, and threat monitoring/response.</li>\n</ul>\n<p><strong>IT Systems Administration</strong></p>\n<ul>\n<li>Support Microsoft 365 administration (Exchange Online, SharePoint, Teams, Entra ID) and Salesforce administration within scope.</li>\n<li>Share responsibility for endpoint security and password management configuration.</li>\n</ul>\n<p><strong>Strategy and Continuous Improvement</strong></p>\n<ul>\n<li>Provide input on infrastructure scaling, architecture decisions, and the containerisation roadmap.</li>\n<li>Support infrastructure-as-code adoption and automate routine operations using PowerShell, shell scripting, and other languages.</li>\n<li>Contribute to sprint planning for environment-level requirements and participate in on-call rotation.</li>\n</ul>\n<h2>Requirements</h2>\n<p><strong>Essential</strong></p>\n<ul>\n<li>2+ years of experience in IT infrastructure, cloud operations, systems administration, or DevOps.</li>\n<li>Hands-on experience with Windows Server 2022, SQL Server, MongoDB, and Redis in operational contexts.Practical Cloudflare experience (DNS, WAF, CDN, security features).</li>\n<li>Working proficiency in Microsoft 365 administration, including Entra ID, Exchange Online, and SharePoint.</li>\n<li>Hands-on Kubernetes experience: workload deployment, basic cluster operations, networking (ingress, network policies), and RBAC.</li>\n<li>Solid understanding of networking fundamentals (firewalls, VPNs, DNS, access control).</li>\n<li>Working knowledge of GDPR and experience supporting compliance controls.</li>\n<li>Ability to write shell scripts and program in at least one modern language (e.g. Python, Go, C#, JavaScript/TypeScript), with willingness to build small infrastructure-related applications and tools.</li>\n<li>Strong communication skills and ability to work independently within a distributed, multi-time-zone team.</li>\n</ul>\n<p><strong>Preferred</strong></p>\n<ul>\n<li>Experience with Grafana OSS, Prometheus, and Loki.</li>\n<li>Familiarity with Docker, containerd, Helm, and kubectl.</li>\n<li>Certifications such as MCSA, CompTIA Security+, CKA, or equivalent.</li>\n<li>Familiarity with ISO 27001 audit/certification processes.</li>\n<li>PowerShell scripting for automation and reporting.</li>\n<li>Exposure to Terraform, Pulumi, Ansible, CI/CD, or GitOps.</li>\n<li>Salesforce administration experience.</li>\n</ul>\n<h2>Benefits</h2>\n<p>This is a full-time, permanent position based in Berlin, Germany, offered on a remote-first basis. The CloudToolz platform operates continuously across multiple regions; the role includes on-call and out-of-hours escalation responsibilities.</p>\n<p><strong>Salary range:</strong> €55,000 – €75,000 per year</p>\n<p><strong>Performance bonus:</strong> Discretionary, based on individual and company performance</p>\n<p><strong>Pension:</strong> Employer contribution in line with local requirements</p>\n<p><strong>Flexible working:</strong> Remote-first; flexible hours with availability for global coordination</p>\n<p><strong>Probation:</strong> 6 months</p>\n<p>Compensation is commensurate with demonstrable experience and the scope of the role. The range reflects a small-business context while remaining competitive for the Berlin IT market for this level of responsibility.</p>\n<p><strong>About Zentso</strong><br>\nZentso is a software company specialising in association management technology. We build and maintain the CloudToolz platform, which extends iMIS RiSE with advanced workflow automation, forms, analytics, CRM, CMS, and payment processing capabilities. Our clients include national professional associations, peak bodies, and member-based organisations across Australia, the UK, and the Asia Pacific region.</p>\n<p>We operate as a small, distributed team with a strong emphasis on technical ownership, direct communication, and pragmatic decision-making. The right person for this role will be someone who takes genuine satisfaction in keeping complex systems running reliably and securely, and who can operate with a high degree of autonomy.</p>\n<p><strong>Note: Please include a cover letter with your CV explaining why you believe your qualifications and experience make you a strong fit for this position.</strong></p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Zentso builds and operates CloudToolz, a revenue-critical SaaS platform layered on top of iMIS RiSE association management software, serving clients across the UK, Europe, United States, and Asia Pacific. The platform encompasses workflow automation, form building, CRM, CMS, and payment processing capabilities delivered to organisations in multiple sectors.</p>\n<p>We are seeking a motivated IT Infrastructure and Security Engineer to support the global infrastructure and security posture underpinning CloudToolz and Zentso\'s internal systems. This is a hands-on, junior-to-mid-level role working closely with the IT Infrastructure and Security Lead and the CTO, assisting with day-to-day operations, security tasks, and the ongoing migration toward a containerised, Kubernetes-based deployment model. The successful candidate will be comfortable working across a distributed, multi-region environment, contributing directly to uptime, security, and compliance outcomes for a production platform.</p>\n<p>A key part of this role is supporting Zentso\'s transition to Kubernetes and helping build out an observability practice around Grafana OSS, alongside contributing scripts and small applications that automate and support infrastructure operations.</p>\n<h2>Tasks</h2>\n<p><strong>Infrastructure and Platform Operations</strong></p>\n<ul>\n<li>Help manage global infrastructure spanning Windows Server 2022, SQL Server, MongoDB, Redis, and Cloudflare across four regions, supporting the availability, performance, and scalability of the revenue-critical CloudToolz platform.</li>\n<li>Support deployments of new CloudToolz releases (<a href=\"http://ASP.NET\">ASP.NET</a> Core, integrating with Dynamics, iMIS, Salesforce, and native CRM/CMS) and contribute to the Kubernetes migration, including cluster operations such as deployments, scaling, network policies, and RBAC.</li>\n<li>Help build and maintain a Grafana OSS observability stack — dashboards, alerting, and integration with metrics, logs, and traces.Assist with DNS, CDN, WAF, and DDoS protection via Cloudflare; monitor system performance and participate in incident response and recovery.</li>\n<li>Maintain documentation, runbooks, and disaster recovery procedures.</li>\n<li>Write shell scripts and small infrastructure-related applications (automation tools, monitoring utilities, internal dashboards) in coordination with the Infrastructure Lead.</li>\n</ul>\n<p><strong>Security Operations</strong></p>\n<ul>\n<li>Support identity and access management, endpoint protection, and vulnerability management.</li>\n<li>Help administer policies across Microsoft 365, Bitwarden, Bitdefender GravityZone, and KnowBe4.</li>\n<li>Contribute to GDPR/ISO 27001-aligned data protection policies, security awareness training, phishing simulations, and threat monitoring/response.</li>\n</ul>\n<p><strong>IT Systems Administration</strong></p>\n<ul>\n<li>Support Microsoft 365 administration (Exchange Online, SharePoint, Teams, Entra ID) and Salesforce administration within scope.</li>\n<li>Share responsibility for endpoint security and password management configuration.</li>\n</ul>\n<p><strong>Strategy and Continuous Improvement</strong></p>\n<ul>\n<li>Provide input on infrastructure scaling, architecture decisions, and the containerisation roadmap.</li>\n<li>Support infrastructure-as-code adoption and automate routine operations using PowerShell, shell scripting, and other languages.</li>\n<li>Contribute to sprint planning for environment-level requirements and participate in on-call rotation.</li>\n</ul>\n<h2>Requirements</h2>\n<p><strong>Essential</strong></p>\n<ul>\n<li>2+ years of experience in IT infrastructure, cloud operations, systems administration, or DevOps.</li>\n<li>Hands-on experience with Windows Server 2022, SQL Server, MongoDB, and Redis in operational contexts.Practical Cloudflare experience (DNS, WAF, CDN, security features).</li>\n<li>Working proficiency in Microsoft 365 administration, including Entra ID, Exchange Online, and SharePoint.</li>\n<li>Hands-on Kubernetes experience: workload deployment, basic cluster operations, networking (ingress, network policies), and RBAC.</li>\n<li>Solid understanding of networking fundamentals (firewalls, VPNs, DNS, access control).</li>\n<li>Working knowledge of GDPR and experience supporting compliance controls.</li>\n<li>Ability to write shell scripts and program in at least one modern language (e.g. Python, Go, C#, JavaScript/TypeScript), with willingness to build small infrastructure-related applications and tools.</li>\n<li>Strong communication skills and ability to work independently within a distributed, multi-time-zone team.</li>\n</ul>\n<p><strong>Preferred</strong></p>\n<ul>\n<li>Experience with Grafana OSS, Prometheus, and Loki.</li>\n<li>Familiarity with Docker, containerd, Helm, and kubectl.</li>\n<li>Certifications such as MCSA, CompTIA Security+, CKA, or equivalent.</li>\n<li>Familiarity with ISO 27001 audit/certification processes.</li>\n<li>PowerShell scripting for automation and reporting.</li>\n<li>Exposure to Terraform, Pulumi, Ansible, CI/CD, or GitOps.</li>\n<li>Salesforce administration experience.</li>\n</ul>\n<h2>Benefits</h2>\n<p>This is a full-time, permanent position based in Berlin, Germany, offered on a remote-first basis. The CloudToolz platform operates continuously across multiple regions; the role includes on-call and out-of-hours escalation responsibilities.</p>\n<p><strong>Salary range:</strong> €55,000 – €75,000 per year</p>\n<p><strong>Performance bonus:</strong> Discretionary, based on individual and company performance</p>\n<p><strong>Pension:</strong> Employer contribution in line with local requirements</p>\n<p><strong>Flexible working:</strong> Remote-first; flexible hours with availability for global coordination</p>\n<p><strong>Probation:</strong> 6 months</p>\n<p>Compensation is commensurate with demonstrable experience and the scope of the role. The range reflects a small-business context while remaining competitive for the Berlin IT market for this level of responsibility.</p>\n<p><strong>About Zentso</strong><br>\nZentso is a software company specialising in association management technology. We build and maintain the CloudToolz platform, which extends iMIS RiSE with advanced workflow automation, forms, analytics, CRM, CMS, and payment processing capabilities. Our clients include national professional associations, peak bodies, and member-based organisations across Australia, the UK, and the Asia Pacific region.</p>\n<p>We operate as a small, distributed team with a strong emphasis on technical ownership, direct communication, and pragmatic decision-making. The right person for this role will be someone who takes genuine satisfaction in keeping complex systems running reliably and securely, and who can operate with a high degree of autonomy.</p>\n<p><strong>Note: Please include a cover letter with your CV explaining why you believe your qualifications and experience make you a strong fit for this position.</strong></p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-03 01:39:47.184', '2026-07-03 01:39:47.184', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/zentso-s-gmbh/it-infrastructure-and-security-engineer-berlin-498582', 'https://www.arbeitnow.com/jobs/companies/zentso-s-gmbh/it-infrastructure-and-security-engineer-berlin-498582', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/zentso-s-gmbh/it-infrastructure-and-security-engineer-berlin-498582\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2082, NULL, 'api', NULL, 'Senior Product Marketing Manager (f/m/d)', 'SPREAD GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/spread-gmbh/senior-product-marketing-manager-berlin-345384', '<h2>Short Description</h2>\n<p>SPREAD builds engineering intelligence for the world\'s most complex products. Our AI-native platform gives automotive OEMs, defense primes, and industrial manufacturers a single source of product truth so engineering teams can make confident product decisions, fast. We work with companies like Volkswagen, BMW, Mercedes, Bosch, Stadler, and Rheinmetall. Backed by HV Capital, DTCP, La Famiglia / General Catalyst, and Salesforce.</p>\n<p>In this role, you own how SPREAD is positioned, messaged, and understood by engineering leaders at enterprise accounts. You translate a deeply technical product into narratives that win deals, arm Sales with competitive intelligence and enablement assets, and partner with Product and Engineering on go-to-market. This is a hands-on role in a small, senior marketing team alongside Growth, GTM Ops, and Design.</p>\n<h2>Your Mission</h2>\n<ul>\n<li>Own positioning and messaging for SPREAD\'s platform, turning engineering intelligence into value propositions that land with top engineering leaders.</li>\n<li>Build and maintain competitive intelligence across the PLM and engineering data landscape and turn it into battle cards and objection-handling guides that Sales uses daily.</li>\n<li>Create sales enablement assets that shorten enterprise sales cycles and improve win rates.</li>\n<li>Partner with Product and Engineering on go-to-market for product releases, connecting every launch to a measurable customer outcome.</li>\n<li>Develop thought leadership content that builds credibility with deeply technical audiences.</li>\n<li>Partner with Growth and GTM Ops on campaign messaging and account targeting so demand gen speaks the right language to the right pain points.</li>\n<li>Represent SPREAD at industry events and customer conversations where engineering leaders expect a peer-level discussion about their domain.</li>\n</ul>\n<h2>Your Experience</h2>\n<ul>\n<li>5+ years in B2B product marketing or technical product management for enterprise software or complex technical products, with hands-on ownership of positioning, messaging, and go-to-market.</li>\n<li>Technical fluency through an engineering or technical degree, or through deep experience managing or marketing highly technical products. You can hold a credible conversation about data architectures, PLM tool landscapes, or software-defined product development.</li>\n<li>Experience building sales enablement for complex enterprise deals (€100K+ ACV, 6-12-month cycles, multi-stakeholder buying committees).</li>\n<li>Strong competitive intelligence instinct. You track competitors, articulate differentiation in the buyer\'s language, and prepare sales teams for live objection handling.</li>\n<li>AI-native working style. You use AI tools daily to scale your output, from content creation to research to workflow automation. SPREAD is an AI-first company, and every team member operates accordingly.</li>\n<li>Identity as a product marketer. You partner with Product and Engineering, you speak their language, but your craft is marketing, not roadmaps or feature specs.</li>\n<li>Native or near-native English. Working-level German minimum. If German is your native language, strong English is sufficient.</li>\n<li>Based in Berlin or close enough for regular in-office collaboration, especially during the first months.</li>\n</ul>\n<h2>Why SPREAD?</h2>\n<ul>\n<li>Work on Agentic Engineering Intelligence that helps leading manufacturers master software-defined complexity. You market technology that engineering leaders genuinely care about.</li>\n<li>High ownership and measurable impact. You connect your positioning directly to deal outcomes and pipeline.</li>\n<li>A senior team that values craft, speed, and accountability over process and hierarchy.</li>\n<li>Strong overall package including attractive compensation and an annual learning budget.</li>\n<li>Mobility and wellbeing support through a Deutschlandticket mobility budget, bike-leasing and an Urban Sports partnership.</li>\n<li>Time off and flexibility with 30 vacation days, workation options, and one paid volunteering day per year.</li>\n</ul>\n<h2>Contact</h2>\n<p><strong>Dmytro İefymenko</strong></p>\n<p>Köpenicker Str. 40c | 10179 Berlin</p>\n<p>Stay connected—follow us on for the latest insights and updates</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<h2>Short Description</h2>\n<p>SPREAD builds engineering intelligence for the world\'s most complex products. Our AI-native platform gives automotive OEMs, defense primes, and industrial manufacturers a single source of product truth so engineering teams can make confident product decisions, fast. We work with companies like Volkswagen, BMW, Mercedes, Bosch, Stadler, and Rheinmetall. Backed by HV Capital, DTCP, La Famiglia / General Catalyst, and Salesforce.</p>\n<p>In this role, you own how SPREAD is positioned, messaged, and understood by engineering leaders at enterprise accounts. You translate a deeply technical product into narratives that win deals, arm Sales with competitive intelligence and enablement assets, and partner with Product and Engineering on go-to-market. This is a hands-on role in a small, senior marketing team alongside Growth, GTM Ops, and Design.</p>\n<h2>Your Mission</h2>\n<ul>\n<li>Own positioning and messaging for SPREAD\'s platform, turning engineering intelligence into value propositions that land with top engineering leaders.</li>\n<li>Build and maintain competitive intelligence across the PLM and engineering data landscape and turn it into battle cards and objection-handling guides that Sales uses daily.</li>\n<li>Create sales enablement assets that shorten enterprise sales cycles and improve win rates.</li>\n<li>Partner with Product and Engineering on go-to-market for product releases, connecting every launch to a measurable customer outcome.</li>\n<li>Develop thought leadership content that builds credibility with deeply technical audiences.</li>\n<li>Partner with Growth and GTM Ops on campaign messaging and account targeting so demand gen speaks the right language to the right pain points.</li>\n<li>Represent SPREAD at industry events and customer conversations where engineering leaders expect a peer-level discussion about their domain.</li>\n</ul>\n<h2>Your Experience</h2>\n<ul>\n<li>5+ years in B2B product marketing or technical product management for enterprise software or complex technical products, with hands-on ownership of positioning, messaging, and go-to-market.</li>\n<li>Technical fluency through an engineering or technical degree, or through deep experience managing or marketing highly technical products. You can hold a credible conversation about data architectures, PLM tool landscapes, or software-defined product development.</li>\n<li>Experience building sales enablement for complex enterprise deals (€100K+ ACV, 6-12-month cycles, multi-stakeholder buying committees).</li>\n<li>Strong competitive intelligence instinct. You track competitors, articulate differentiation in the buyer\'s language, and prepare sales teams for live objection handling.</li>\n<li>AI-native working style. You use AI tools daily to scale your output, from content creation to research to workflow automation. SPREAD is an AI-first company, and every team member operates accordingly.</li>\n<li>Identity as a product marketer. You partner with Product and Engineering, you speak their language, but your craft is marketing, not roadmaps or feature specs.</li>\n<li>Native or near-native English. Working-level German minimum. If German is your native language, strong English is sufficient.</li>\n<li>Based in Berlin or close enough for regular in-office collaboration, especially during the first months.</li>\n</ul>\n<h2>Why SPREAD?</h2>\n<ul>\n<li>Work on Agentic Engineering Intelligence that helps leading manufacturers master software-defined complexity. You market technology that engineering leaders genuinely care about.</li>\n<li>High ownership and measurable impact. You connect your positioning directly to deal outcomes and pipeline.</li>\n<li>A senior team that values craft, speed, and accountability over process and hierarchy.</li>\n<li>Strong overall package including attractive compensation and an annual learning budget.</li>\n<li>Mobility and wellbeing support through a Deutschlandticket mobility budget, bike-leasing and an Urban Sports partnership.</li>\n<li>Time off and flexibility with 30 vacation days, workation options, and one paid volunteering day per year.</li>\n</ul>\n<h2>Contact</h2>\n<p><strong>Dmytro İefymenko</strong></p>\n<p>Köpenicker Str. 40c | 10179 Berlin</p>\n<p>Stay connected—follow us on for the latest insights and updates</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-03 01:39:57.587', '2026-07-03 01:39:57.587', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/spread-gmbh/senior-product-marketing-manager-berlin-345384', 'https://www.arbeitnow.com/jobs/companies/spread-gmbh/senior-product-marketing-manager-berlin-345384', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/spread-gmbh/senior-product-marketing-manager-berlin-345384\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2083, NULL, 'api', NULL, 'Personalsachbearbeiter (M/W/D) Entgeltabrechnung / Payroll', 'Alfred Paulsen GmbH & Co. KG', 'Otterndorf', 'https://www.arbeitnow.com/jobs/companies/alfred-paulsen-gmbh-co-kg/personalsachbearbeiter-entgeltabrechnung-payroll-otterndorf-14831', '<p>Als mittelständisches Familienunternehmen in dritter Generation stehen wir seit über 100 Jahren für Lebensmittel in bester Qualität.</p>\n<p>Unser Sortiment ist vielfältig: knackige Gurken, feinwürziger Rot- und Grünkohl, frisches Sauerkraut, proteinreiche Hülsenfrüchte und vieles mehr. Zu unseren Marken zählen Paulsen, Nowka, Marschland Naturkost, Lipperland und Lüders. Darüber hinaus produzieren wir für zahlreiche bekannte Handelsmarken. Unsere regionalen Produkte exportieren wir heute in mehr als 25 Länder weltweit.</p>\n<p>Bereits vor über 30 Jahren gehörten wir zu den Pionieren im Bio-Bereich. Heute zählen wir zu den größten Bio-Produzenten Deutschlands und sind nach IFS, Bio, Bioland, Naturland sowie Demeter zertifiziert. Regionalität und langfristiger Vertragsanbau sind für uns selbstverständlich.</p>\n<p>Zur Verstärkung unseres Teams suchen wir zum nächstmöglichen Zeitpunkt für unsere Zentrale in 21762 Otterndorf eine engagierte Persönlichkeit als</p>\n<p>PERSONALSACHBEARBEITER (M/W/D) ENTGELTABRECHNUNG / PAYROLL</p>\n<p>Du betreust unsere Mitarbeitenden eigenverantwortlich in allen operativen Personalthemen und führst die monatliche Lohn- und Gehaltsabrechnung selbstständig durch.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Eigenverantwortliche Betreuung unserer Mitarbeitenden vom Eintritt bis zum Austritt</li>\n<li>Ansprechpartner für Mitarbeitende und Führungskräfte in personalrelevanten Fragestellungen</li>\n<li>Erstellung von Arbeitsverträgen, Bescheinigungen und Arbeitszeugnissen</li>\n<li>Pflege und Verwaltung der Personalstammdaten</li>\n<li>Eigenständige Durchführung der monatlichen Lohn- und Gehaltsabrechnung und Berücksichtigung lohnsteuer-, sozialversicherungs- und arbeitsrechtlichen Vorgaben</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erfolgreich abgeschlossene kaufmännische Ausbildung, z. B. als Steuerfachangestellte/r, Personalfachkraft, Lohn- und Gehaltsbuchhalter/in oder eine vergleichbare Qualifikation</li>\n<li>Mehrjährige Berufserfahrung in der Personalsachbearbeitung und Entgeltabrechnung</li>\n<li>Gute Kenntnisse im Lohnsteuer-, Sozialversicherungs- und idealerweise Arbeitsrecht</li>\n<li>Sicherer Umgang mit MS Office sowie idealerweise Erfahrung mit einer Lohn- und Personalsoftware</li>\n<li>Selbstständige, strukturierte und sorgfältige Arbeitsweise</li>\n<li>Hohe Diskretion, Verantwortungsbewusstsein und Zuverlässigkeit</li>\n<li>Sehr gute Deutschkenntnisse in Wort und Schrift</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Eine verantwortungsvolle Position mit individuellem Gestaltungsspielraum</li>\n<li>Möglichkeiten zur persönlichen und beruflichen Weiterentwicklung</li>\n<li>Kurze Entscheidungswege in einem familiengeführten Unternehmen</li>\n<li>Sicherer Arbeitsplatz in einem gesunden, expandierenden und innovativen Unternehmen</li>\n<li>Kollegiales und hilfsbereites Team mit niedriger Fluktuation</li>\n<li>Herstellung regionaler und nachhaltiger Produkte „zum Anfassen“</li>\n<li>Angenehmes Arbeiten im wunderschönen Nordseebad Otterndorf</li>\n</ul>\n<p>Wir freuen uns auf Deine aussagefähigen Bewerbungsunterlagen unter Angabe Deines frühestmöglichen Eintrittstermins und Deiner Gehaltsvorstellung – bevorzugt per E-Mail.</p>\n<p>Dein Ansprechpartner ist Marius Gillner (gillner@alfredpaulse,de)</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Als mittelständisches Familienunternehmen in dritter Generation stehen wir seit über 100 Jahren für Lebensmittel in bester Qualität.</p>\n<p>Unser Sortiment ist vielfältig: knackige Gurken, feinwürziger Rot- und Grünkohl, frisches Sauerkraut, proteinreiche Hülsenfrüchte und vieles mehr. Zu unseren Marken zählen Paulsen, Nowka, Marschland Naturkost, Lipperland und Lüders. Darüber hinaus produzieren wir für zahlreiche bekannte Handelsmarken. Unsere regionalen Produkte exportieren wir heute in mehr als 25 Länder weltweit.</p>\n<p>Bereits vor über 30 Jahren gehörten wir zu den Pionieren im Bio-Bereich. Heute zählen wir zu den größten Bio-Produzenten Deutschlands und sind nach IFS, Bio, Bioland, Naturland sowie Demeter zertifiziert. Regionalität und langfristiger Vertragsanbau sind für uns selbstverständlich.</p>\n<p>Zur Verstärkung unseres Teams suchen wir zum nächstmöglichen Zeitpunkt für unsere Zentrale in 21762 Otterndorf eine engagierte Persönlichkeit als</p>\n<p>PERSONALSACHBEARBEITER (M/W/D) ENTGELTABRECHNUNG / PAYROLL</p>\n<p>Du betreust unsere Mitarbeitenden eigenverantwortlich in allen operativen Personalthemen und führst die monatliche Lohn- und Gehaltsabrechnung selbstständig durch.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Eigenverantwortliche Betreuung unserer Mitarbeitenden vom Eintritt bis zum Austritt</li>\n<li>Ansprechpartner für Mitarbeitende und Führungskräfte in personalrelevanten Fragestellungen</li>\n<li>Erstellung von Arbeitsverträgen, Bescheinigungen und Arbeitszeugnissen</li>\n<li>Pflege und Verwaltung der Personalstammdaten</li>\n<li>Eigenständige Durchführung der monatlichen Lohn- und Gehaltsabrechnung und Berücksichtigung lohnsteuer-, sozialversicherungs- und arbeitsrechtlichen Vorgaben</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Erfolgreich abgeschlossene kaufmännische Ausbildung, z. B. als Steuerfachangestellte/r, Personalfachkraft, Lohn- und Gehaltsbuchhalter/in oder eine vergleichbare Qualifikation</li>\n<li>Mehrjährige Berufserfahrung in der Personalsachbearbeitung und Entgeltabrechnung</li>\n<li>Gute Kenntnisse im Lohnsteuer-, Sozialversicherungs- und idealerweise Arbeitsrecht</li>\n<li>Sicherer Umgang mit MS Office sowie idealerweise Erfahrung mit einer Lohn- und Personalsoftware</li>\n<li>Selbstständige, strukturierte und sorgfältige Arbeitsweise</li>\n<li>Hohe Diskretion, Verantwortungsbewusstsein und Zuverlässigkeit</li>\n<li>Sehr gute Deutschkenntnisse in Wort und Schrift</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Eine verantwortungsvolle Position mit individuellem Gestaltungsspielraum</li>\n<li>Möglichkeiten zur persönlichen und beruflichen Weiterentwicklung</li>\n<li>Kurze Entscheidungswege in einem familiengeführten Unternehmen</li>\n<li>Sicherer Arbeitsplatz in einem gesunden, expandierenden und innovativen Unternehmen</li>\n<li>Kollegiales und hilfsbereites Team mit niedriger Fluktuation</li>\n<li>Herstellung regionaler und nachhaltiger Produkte „zum Anfassen“</li>\n<li>Angenehmes Arbeiten im wunderschönen Nordseebad Otterndorf</li>\n</ul>\n<p>Wir freuen uns auf Deine aussagefähigen Bewerbungsunterlagen unter Angabe Deines frühestmöglichen Eintrittstermins und Deiner Gehaltsvorstellung – bevorzugt per E-Mail.</p>\n<p>Dein Ansprechpartner ist Marius Gillner (gillner@alfredpaulse,de)</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-03 01:40:07.224', '2026-07-03 01:40:07.224', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/alfred-paulsen-gmbh-co-kg/personalsachbearbeiter-entgeltabrechnung-payroll-otterndorf-14831', 'https://www.arbeitnow.com/jobs/companies/alfred-paulsen-gmbh-co-kg/personalsachbearbeiter-entgeltabrechnung-payroll-otterndorf-14831', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/alfred-paulsen-gmbh-co-kg/personalsachbearbeiter-entgeltabrechnung-payroll-otterndorf-14831\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2084, NULL, 'api', NULL, 'Full Stack Engineer (f/m/d)', 'Clariness', 'Hamburg, Hamburg, Germany', 'https://www.arbeitnow.com/jobs/companies/clariness/full-stack-engineer-hamburg-13081', '<p><span style=\"font-size: 12pt; color: rgb(230, 126, 35);\"><strong>Clariness is looking for a Full Stack Engineer (f/md/) based in Berlin or Hamburg.<br></strong><strong>- Full-time; unlimited -</strong></span></p>\n<p><span style=\"color: rgb(230, 126, 35); font-size: 12pt;\"><strong><span data-contrast=\"none\">About the role:</span></strong> </span></p>\n<p>As a Full Stack Engineer, you will help build and enhance Clariness\' digital platform supporting clinical trial recruitment and patient engagement. Working as part of a cross-functional product team, you will develop new features, improve application performance, and contribute to creating scalable, high-quality software that delivers value to our users.&nbsp;This role is ideal for someone who enjoys solving technical challenges, collaborating with multidisciplinary teams, and continuously improving both products and engineering practices.</p>\n<p><strong><span style=\"font-size: 12pt; color: rgb(230, 126, 35);\">As a Full Stack Engineer, you would be responsible for:</span></strong></p>\n<ul>\n<li>Designing, developing, and maintaining new features for our Next.js-based clinical trial platform.</li>\n<li>Taking full ownership of your code, features, and overall product quality.</li>\n<li>Optimizing application performance across APIs, databases, frontend rendering, and accessibility.</li>\n<li>Writing clean, maintainable, and well-tested code (unit, integration, and end-to-end).</li>\n<li>Collaborating closely with engineers, designers, and product managers in an agile environment.</li>\n<li>Participating in code reviews, technical discussions, and initiatives to reduce technical debt.</li>\n<li>Contributing to scalable engineering practices and the continuous improvement of our applications.</li>\n</ul>\n<p><span style=\"color: rgb(230, 126, 35); font-size: 12pt;\"><strong>We would like you to have:&nbsp;</strong></span></p>\n<ul>\n<li>2+ years of professional experience in JavaScript development, ideally with TypeScript.</li>\n<li>Experience with modern frontend frameworks such as Next.js, React, Angular, Vue, or Svelte.&nbsp;</li>\n<li>Experience building backend applications using technologies such as Node.js, Express, NestJS, or Next.js.</li>\n<li>Solid understanding of relational databases such as PostgreSQL or MySQL; experience with NoSQL databases is a plus.</li>\n<li>Experience with unit and integration testing (Jest, Karma, or similar) is a plus.</li>\n<li>Familiarity with containerized environments (Docker, Kubernetes) is a plus.</li>\n<li>Knowledge of CI/CD pipelines and build tools (GitLab CI, GitHub Actions, Jenkins) is a plus.</li>\n<li>Degree in Computer Science, Software Engineering, or a related field, or equivalent practical experience. Next.js or AWS certifications are a bonus.</li>\n<li>Fluency in English.</li>\n<li>Strong problem-solving, communication, and collaboration skills.</li>\n<li>Proactive, quality-focused mindset with a passion for continuous learning and improvement.</li>\n</ul>\n<p><span style=\"font-size: 12pt; color: rgb(230, 126, 35);\"><strong>You may ask now, why should I work for you? Let us give you a few reasons – <span data-teams=\"true\">and you\'ll learn more during the process.</span></strong></span></p>\n<ul>\n<li>A varied and exciting job with a lot of personal responsibility in an international company, where you can develop and expand your skills.</li>\n<li>Professional and personal development opportunities - incl. personal development budget.</li>\n<li>Flexible working hours and mobile working.</li>\n<li>Regular team events and open feedback culture.</li>\n<li>A versatile field of activity and challenging projects.</li>\n<li>A supportive and open company culture, providing the opportunity to collaborate with a diverse and professional team.</li>\n<li>Impact healthcare by accelerating medical innovation through improved access to clinical trials, potentially bringing needed treatments to patients faster.</li>\n</ul>\n<p><strong><span style=\"color: rgb(230, 126, 35); font-size: 12pt;\"><span data-contrast=\"none\">How to apply &amp; what to expect:</span><span data-ccp-props=\"{&quot;134233117&quot;:true,&quot;134233118&quot;:true,&quot;201341983&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></span></strong></p>\n<ul>\n<li data-leveltext=\"\" data-font=\"Symbol\" data-listid=\"23\" data-list-defn-props=\"{&quot;335552541&quot;:1,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"1\" data-aria-level=\"1\"><span data-contrast=\"auto\">Apply via link (CV only; no cover letter required).</span></li>\n<li data-leveltext=\"\" data-font=\"Symbol\" data-listid=\"23\" data-list-defn-props=\"{&quot;335552541&quot;:1,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"1\" data-aria-level=\"1\">Introductory call (30 min) → Technical interview →&nbsp; Take Home Test → Demo Day → Decision.</li>\n<li data-leveltext=\"\" data-font=\"Symbol\" data-listid=\"23\" data-list-defn-props=\"{&quot;335552541&quot;:1,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"1\" data-aria-level=\"1\">We aim to move promptly and keep you updated at every step.<span data-ccp-props=\"{&quot;134233117&quot;:false,&quot;134233118&quot;:false,&quot;201341983&quot;:0,&quot;335559738&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></li>\n</ul>\n<p><span class=\"TextRun SCXW169238394 BCX8\" lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun CommentStart CommentHighlightPipeClickedV2 CommentHighlightClicked SCXW169238394 BCX8\">At </span><span class=\"NormalTextRun CommentHighlightClicked SCXW169238394 BCX8\">Clariness</span><span class=\"NormalTextRun CommentHighlightClicked SCXW169238394 BCX8\">, we are proud to be an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees, regardless of race, religion, gender, sexual orientation, national origin, </span><span class=\"NormalTextRun CommentHighlightClicked SCXW169238394 BCX8\">disability</span><span class=\"NormalTextRun CommentHighlightClicked SCXW169238394 BCX8\"> or age.</span></span><span class=\"EOP CommentHighlightPipeClickedV2 SCXW169238394 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335551550&quot;:6,&quot;335551620&quot;:6,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\"> <br><br></span>For more information, feel free to reach out to <a ---------- class=\"content-conclusion\"><p><strong>Have we sparked your interest?</strong></p>\n<p>Would you like to become part of our dynamic, curious, and international culture with plenty of room for your ideas and creativity in an inspiring atmosphere? If so, we look forward to receiving your application with details of your desired salary and possible starting date, preferably via our application portal.<br><br></p>\n<p>Clariness GmbH will treat the above information strictly confidential and will especially observe the applicable provisions of the applicable data protection laws. Further information about the use of the applicant data, you will find in the data protection declaration online at&nbsp;<a href=\"https://www.clariness.com/privacy-policy/\">https://www.clariness.com/privacy-policy/</a></p></div><p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><span style=\"font-size: 12pt; color: rgb(230, 126, 35);\"><strong>Clariness is looking for a Full Stack Engineer (f/md/) based in Berlin or Hamburg.<br></strong><strong>- Full-time; unlimited -</strong></span></p>\n<p><span style=\"color: rgb(230, 126, 35); font-size: 12pt;\"><strong><span data-contrast=\"none\">About the role:</span></strong> </span></p>\n<p>As a Full Stack Engineer, you will help build and enhance Clariness\' digital platform supporting clinical trial recruitment and patient engagement. Working as part of a cross-functional product team, you will develop new features, improve application performance, and contribute to creating scalable, high-quality software that delivers value to our users.&nbsp;This role is ideal for someone who enjoys solving technical challenges, collaborating with multidisciplinary teams, and continuously improving both products and engineering practices.</p>\n<p><strong><span style=\"font-size: 12pt; color: rgb(230, 126, 35);\">As a Full Stack Engineer, you would be responsible for:</span></strong></p>\n<ul>\n<li>Designing, developing, and maintaining new features for our Next.js-based clinical trial platform.</li>\n<li>Taking full ownership of your code, features, and overall product quality.</li>\n<li>Optimizing application performance across APIs, databases, frontend rendering, and accessibility.</li>\n<li>Writing clean, maintainable, and well-tested code (unit, integration, and end-to-end).</li>\n<li>Collaborating closely with engineers, designers, and product managers in an agile environment.</li>\n<li>Participating in code reviews, technical discussions, and initiatives to reduce technical debt.</li>\n<li>Contributing to scalable engineering practices and the continuous improvement of our applications.</li>\n</ul>\n<p><span style=\"color: rgb(230, 126, 35); font-size: 12pt;\"><strong>We would like you to have:&nbsp;</strong></span></p>\n<ul>\n<li>2+ years of professional experience in JavaScript development, ideally with TypeScript.</li>\n<li>Experience with modern frontend frameworks such as Next.js, React, Angular, Vue, or Svelte.&nbsp;</li>\n<li>Experience building backend applications using technologies such as Node.js, Express, NestJS, or Next.js.</li>\n<li>Solid understanding of relational databases such as PostgreSQL or MySQL; experience with NoSQL databases is a plus.</li>\n<li>Experience with unit and integration testing (Jest, Karma, or similar) is a plus.</li>\n<li>Familiarity with containerized environments (Docker, Kubernetes) is a plus.</li>\n<li>Knowledge of CI/CD pipelines and build tools (GitLab CI, GitHub Actions, Jenkins) is a plus.</li>\n<li>Degree in Computer Science, Software Engineering, or a related field, or equivalent practical experience. Next.js or AWS certifications are a bonus.</li>\n<li>Fluency in English.</li>\n<li>Strong problem-solving, communication, and collaboration skills.</li>\n<li>Proactive, quality-focused mindset with a passion for continuous learning and improvement.</li>\n</ul>\n<p><span style=\"font-size: 12pt; color: rgb(230, 126, 35);\"><strong>You may ask now, why should I work for you? Let us give you a few reasons – <span data-teams=\"true\">and you\'ll learn more during the process.</span></strong></span></p>\n<ul>\n<li>A varied and exciting job with a lot of personal responsibility in an international company, where you can develop and expand your skills.</li>\n<li>Professional and personal development opportunities - incl. personal development budget.</li>\n<li>Flexible working hours and mobile working.</li>\n<li>Regular team events and open feedback culture.</li>\n<li>A versatile field of activity and challenging projects.</li>\n<li>A supportive and open company culture, providing the opportunity to collaborate with a diverse and professional team.</li>\n<li>Impact healthcare by accelerating medical innovation through improved access to clinical trials, potentially bringing needed treatments to patients faster.</li>\n</ul>\n<p><strong><span style=\"color: rgb(230, 126, 35); font-size: 12pt;\"><span data-contrast=\"none\">How to apply &amp; what to expect:</span><span data-ccp-props=\"{&quot;134233117&quot;:true,&quot;134233118&quot;:true,&quot;201341983&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></span></strong></p>\n<ul>\n<li data-leveltext=\"\" data-font=\"Symbol\" data-listid=\"23\" data-list-defn-props=\"{&quot;335552541&quot;:1,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"1\" data-aria-level=\"1\"><span data-contrast=\"auto\">Apply via link (CV only; no cover letter required).</span></li>\n<li data-leveltext=\"\" data-font=\"Symbol\" data-listid=\"23\" data-list-defn-props=\"{&quot;335552541&quot;:1,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"1\" data-aria-level=\"1\">Introductory call (30 min) → Technical interview →&nbsp; Take Home Test → Demo Day → Decision.</li>\n<li data-leveltext=\"\" data-font=\"Symbol\" data-listid=\"23\" data-list-defn-props=\"{&quot;335552541&quot;:1,&quot;335559685&quot;:720,&quot;335559991&quot;:360,&quot;469769226&quot;:&quot;Symbol&quot;,&quot;469769242&quot;:[8226],&quot;469777803&quot;:&quot;left&quot;,&quot;469777804&quot;:&quot;&quot;,&quot;469777815&quot;:&quot;hybridMultilevel&quot;}\" data-aria-posinset=\"1\" data-aria-level=\"1\">We aim to move promptly and keep you updated at every step.<span data-ccp-props=\"{&quot;134233117&quot;:false,&quot;134233118&quot;:false,&quot;201341983&quot;:0,&quot;335559738&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></li>\n</ul>\n<p><span class=\"TextRun SCXW169238394 BCX8\" lang=\"EN-US\" data-contrast=\"auto\"><span class=\"NormalTextRun CommentStart CommentHighlightPipeClickedV2 CommentHighlightClicked SCXW169238394 BCX8\">At </span><span class=\"NormalTextRun CommentHighlightClicked SCXW169238394 BCX8\">Clariness</span><span class=\"NormalTextRun CommentHighlightClicked SCXW169238394 BCX8\">, we are proud to be an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees, regardless of race, religion, gender, sexual orientation, national origin, </span><span class=\"NormalTextRun CommentHighlightClicked SCXW169238394 BCX8\">disability</span><span class=\"NormalTextRun CommentHighlightClicked SCXW169238394 BCX8\"> or age.</span></span><span class=\"EOP CommentHighlightPipeClickedV2 SCXW169238394 BCX8\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335551550&quot;:6,&quot;335551620&quot;:6,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\"> <br><br></span>For more information, feel free to reach out to <a ---------- class=\"content-conclusion\"><p><strong>Have we sparked your interest?</strong></p>\n<p>Would you like to become part of our dynamic, curious, and international culture with plenty of room for your ideas and creativity in an inspiring atmosphere? If so, we look forward to receiving your application with details of your desired salary and possible starting date, preferably via our application portal.<br><br></p>\n<p>Clariness GmbH will treat the above information strictly confidential and will especially observe the applicable provisions of the applicable data protection laws. Further information about the use of the applicant data, you will find in the data protection declaration online at&nbsp;<a href=\"https://www.clariness.com/privacy-policy/\">https://www.clariness.com/privacy-policy/</a></p></div><p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-03 01:40:17.313', '2026-07-03 01:40:17.313', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/clariness/full-stack-engineer-hamburg-13081', 'https://www.arbeitnow.com/jobs/companies/clariness/full-stack-engineer-hamburg-13081', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/clariness/full-stack-engineer-hamburg-13081\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
