INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(2132, NULL, 'api', NULL, 'Customer Success Manager (m/f/x)', 'PlanD: Die Software für Gebäudedienstleister', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/pland-die-software-fur-gebaudedienstleister/customer-success-manager-berlin-310691', '<p>TL;DR: Baue mit uns die Nr. 1 AI-ERP-Software des 30-Mrd.-€-Gebäudereinigungsmarkts in DACH. Wir haben PMF, über 600 Kunden, jetzt geht\'s ums Skalieren. Wir suchen jemanden, der Kunden glücklich machen möchte und mit Passion an unser Produkt heranführt.</p>\n<p><strong>Über PlanD und was wir bauen</strong></p>\n<p>PlanD ist die führende AI-ERP-Lösung für Gebäudereinigungsunternehmen im DACH-Raum. Nach knapp fünf Jahren Aufbau sind wir Marktführer. Jetzt beginnt die nächste Phase: Skalierung auf >10 Mio. ARR, Upmarket-Expansion und konsequentes AI-first Company Building.</p>\n<h2>Aufgaben</h2>\n<p><strong>Die Rolle und worum es geht</strong></p>\n<p>Du bist die erste Anlaufstelle für unsere Kunden und du sorgst dafür, dass sie schnell Erfolg mit PlanD haben. Du onboardest neue Nutzer und bleibst ihr Ansprechpartner, wenn Fragen auftauchen. Dein Feedback fließt direkt ins Produkt- und GTM-Team und gute Ideen zur Kundenbindung kannst du direkt eigenständig umsetzen.</p>\n<p>Deine Aufgaben:</p>\n<ul>\n<li>Onboarding neuer Kunden (online)</li>\n<li>Sicherstellen, dass Kunden schnell den Wert von PlanD erleben und die Software richtig nutzen</li>\n<li>Enger Draht zu Produkt und Team, um Kundenfeedback einzuspeisen</li>\n<li>Mitarbeit an der Weiterentwicklung unserer CS-Prozesse und -Strukturen</li>\n</ul>\n<p><strong>Was diese Rolle besonders macht</strong></p>\n<ul>\n<li>Du lernst, wie man AI/SaaS-Kunden wirklich in die Nutzung bringt und hält</li>\n<li>Direkte Zusammenarbeit mit einem effizienten, kleinen Team im Herzen von Berlin</li>\n<li>Hands-on: Gute Ideen werden direkt umgesetzt</li>\n<li>AI-Spielwiese: Wir bauen unsere CS-Prozesse gerade AI-first um, sei dabei und gestalte, wie Customer Success von morgen aussieht</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Was du mitbringen solltest</strong></p>\n<p>Must-haves</p>\n<ul>\n<li>Freude an Kundenkontakt und daran, dass Kunden Erfolg haben</li>\n<li>Hands-on Mindset: Du packst an, willst lernen und übernimmst Verantwortung</li>\n<li>Starker Kommunikator auf Deutsch (Englisch von Vorteil)</li>\n<li>Neugier, wie man ein Start-up auf >10M ARR mit schlankem Team skaliert</li>\n</ul>\n<p>Nice-to-haves</p>\n<ul>\n<li>Erste Erfahrung im Support, CS oder Startup-Umfeld</li>\n<li>Interesse an Automatisierung und AI-Tools</li>\n<li>Branchenbezug zu Gebäudereinigung, Handwerk oder Field Services</li>\n</ul>\n<p><strong>Diese Rolle ist ideal, wenn du</strong></p>\n<ul>\n<li>Lust hast, Kunden wirklich zu verstehen und ihnen zu helfen</li>\n<li>schnell lernst und dich in neue Produkte und Branchen reindenkst</li>\n<li>verstehen willst, wie modernes Customer Success in einem AI-first Startup funktioniert</li>\n</ul>\n<p><strong>Rahmenbedingungen</strong></p>\n<ul>\n<li>In Person in Berlin</li>\n<li>Vollzeit (ca. 40 Std./Woche)</li>\n<li>Ab August 2026</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>TL;DR: Baue mit uns die Nr. 1 AI-ERP-Software des 30-Mrd.-€-Gebäudereinigungsmarkts in DACH. Wir haben PMF, über 600 Kunden, jetzt geht\'s ums Skalieren. Wir suchen jemanden, der Kunden glücklich machen möchte und mit Passion an unser Produkt heranführt.</p>\n<p><strong>Über PlanD und was wir bauen</strong></p>\n<p>PlanD ist die führende AI-ERP-Lösung für Gebäudereinigungsunternehmen im DACH-Raum. Nach knapp fünf Jahren Aufbau sind wir Marktführer. Jetzt beginnt die nächste Phase: Skalierung auf >10 Mio. ARR, Upmarket-Expansion und konsequentes AI-first Company Building.</p>\n<h2>Aufgaben</h2>\n<p><strong>Die Rolle und worum es geht</strong></p>\n<p>Du bist die erste Anlaufstelle für unsere Kunden und du sorgst dafür, dass sie schnell Erfolg mit PlanD haben. Du onboardest neue Nutzer und bleibst ihr Ansprechpartner, wenn Fragen auftauchen. Dein Feedback fließt direkt ins Produkt- und GTM-Team und gute Ideen zur Kundenbindung kannst du direkt eigenständig umsetzen.</p>\n<p>Deine Aufgaben:</p>\n<ul>\n<li>Onboarding neuer Kunden (online)</li>\n<li>Sicherstellen, dass Kunden schnell den Wert von PlanD erleben und die Software richtig nutzen</li>\n<li>Enger Draht zu Produkt und Team, um Kundenfeedback einzuspeisen</li>\n<li>Mitarbeit an der Weiterentwicklung unserer CS-Prozesse und -Strukturen</li>\n</ul>\n<p><strong>Was diese Rolle besonders macht</strong></p>\n<ul>\n<li>Du lernst, wie man AI/SaaS-Kunden wirklich in die Nutzung bringt und hält</li>\n<li>Direkte Zusammenarbeit mit einem effizienten, kleinen Team im Herzen von Berlin</li>\n<li>Hands-on: Gute Ideen werden direkt umgesetzt</li>\n<li>AI-Spielwiese: Wir bauen unsere CS-Prozesse gerade AI-first um, sei dabei und gestalte, wie Customer Success von morgen aussieht</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Was du mitbringen solltest</strong></p>\n<p>Must-haves</p>\n<ul>\n<li>Freude an Kundenkontakt und daran, dass Kunden Erfolg haben</li>\n<li>Hands-on Mindset: Du packst an, willst lernen und übernimmst Verantwortung</li>\n<li>Starker Kommunikator auf Deutsch (Englisch von Vorteil)</li>\n<li>Neugier, wie man ein Start-up auf >10M ARR mit schlankem Team skaliert</li>\n</ul>\n<p>Nice-to-haves</p>\n<ul>\n<li>Erste Erfahrung im Support, CS oder Startup-Umfeld</li>\n<li>Interesse an Automatisierung und AI-Tools</li>\n<li>Branchenbezug zu Gebäudereinigung, Handwerk oder Field Services</li>\n</ul>\n<p><strong>Diese Rolle ist ideal, wenn du</strong></p>\n<ul>\n<li>Lust hast, Kunden wirklich zu verstehen und ihnen zu helfen</li>\n<li>schnell lernst und dich in neue Produkte und Branchen reindenkst</li>\n<li>verstehen willst, wie modernes Customer Success in einem AI-first Startup funktioniert</li>\n</ul>\n<p><strong>Rahmenbedingungen</strong></p>\n<ul>\n<li>In Person in Berlin</li>\n<li>Vollzeit (ca. 40 Std./Woche)</li>\n<li>Ab August 2026</li>\n</ul>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-03 13:40:21.259', '2026-07-03 13:40:21.259', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/pland-die-software-fur-gebaudedienstleister/customer-success-manager-berlin-310691', 'https://www.arbeitnow.com/jobs/companies/pland-die-software-fur-gebaudedienstleister/customer-success-manager-berlin-310691', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/pland-die-software-fur-gebaudedienstleister/customer-success-manager-berlin-310691\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2133, NULL, 'api', NULL, 'Online Marketing Manager / Digital Marketing Consultant (m/w/d)', 'Klickkonzept by Cosmo5', 'Frankfurt am Main', 'https://www.arbeitnow.com/jobs/companies/klickkonzept-by-cosmo5/online-marketing-manager-digital-marketing-consultant-frankfurt-am-main-177378', '<p><strong>Hallo!</strong></p>\n<p><strong>Schön, dass du hier bist.</strong></p>\n<p>Wir sind Klickkonzept, Teil der internationalen Cosmo5-Gruppe. Als KI-orientierte Performance-Agentur entwickeln wir in Frankfurt datengetriebene Lösungen für Brands, die wachsen wollen – von der Beauty-Industrie bis zum B2B-Sektor. Bei uns findest du keine starren Konzernstrukturen, sondern den Spirit einer Boutique-Agentur, gepaart mit der Power von weltweit 28 Partnerbüros in 17 Ländern.</p>\n<p>Wir suchen aktuell nach Verstärkung im Online Marketing. Aber um ehrlich zu sein: Wir suchen keine klassischen „Werkbank-Arbeiter\", die den ganzen Tag nur einzelne Kampagnen abarbeiten. Die Zeiten sind vorbei. Wir suchen T-Shaped Marketer. Wir suchen strategische Architekten von morgen. Wir suchen dich – als unseren neuen Umsatz-Designer.</p>\n<p>Warum „Umsatz-Designer\" und nicht einfach Online Marketing Manager?</p>\n<p>Weil sich die Welt des digitalen Marketings fundamental gedreht hat. Algorithmen und KI nehmen uns die kleinteilige Handarbeit ab. Das ist keine Gefahr, sondern die größte Chance unserer Branche! Es gibt uns endlich die Zeit, das große Ganze zu betrachten. Als T-Shaped Marketer bei uns baust du eine tiefe Expertise in Strategie und Kundenberatung auf (der vertikale Strich im „T\"). Aber du blickst auch nach links und rechts (der horizontale Strich): Du verstehst, wie SEA, Paid Social, SEO, Content und CRO zusammenspielen, und wie sich daraus für einen Kunden ein stimmiges Gesamtbild ergibt. Du gestaltest keine isolierten Maßnahmen, sondern ganzheitliche, umsatzgenerierende Ökosysteme für unsere Kunden.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Spielwiese (Das machst du bei uns):</strong></p>\n<ul>\n<li>Kundenberatung &#x26; Strategie: Du bist Ansprechpartner für deine Kunden und entwickelst gemeinsam mit deinem Squad datengetriebene Online-Marketing-Strategien über mehrere Kanäle hinweg. Du übernimmst schnell Verantwortung – mit einem erfahrenen Team im Rücken, das dich fördert.</li>\n<li>Kanalübergreifendes Denken: Du arbeitest nicht in Silos. Du verstehst, wie die einzelnen Disziplinen (SEA, Paid Social, SEO/GEO, Content, CRO, Web Analytics) ineinandergreifen, und orchestrierst sie zu einer konsistenten Customer Journey – vom ersten Klick bis zur Conversion.</li>\n<li>Datenanalyse &#x26; Reporting: Du behältst die relevanten KPIs im Blick (ROAS, CPA, Conversion Rate &#x26; Co.), erkennst Muster in GA4, Ads-Plattformen und Co. und übersetzt sie in klare, verständliche Handlungsempfehlungen für deine Kunden.</li>\n<li>Projektsteuerung: Du hältst in deinen Projekten die Fäden zusammen, koordinierst dich mit Spezialisten aus den einzelnen Kanälen und sorgst dafür, dass aus Strategie auch Umsetzung wird.</li>\n<li>KI-Enablement: In unserem eigenen „AI Lab\" identifizieren wir neue Use Cases. Du nutzt aktiv generative KI, um deine Workflows zu optimieren, Analysen und Konzepte zu iterieren und schneller zu besseren Entscheidungen zu kommen.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>Was du in deinem Werkzeugkoffer mitbringst:</strong></p>\n<ul>\n<li>Du hast ca. 1–3 Jahre praktische Erfahrung im Online Marketing – ob agentur- oder unternehmensseitig, ob generalistisch oder mit einem ersten Schwerpunkt (z. B. SEA, Paid Social, SEO oder Content).</li>\n<li>Du hast Freude an der Kundenberatung und daran, komplexe Sachverhalte verständlich aufzubereiten und zu präsentieren.</li>\n<li>Du denkst in Kennzahlen: ROAS, CPA, Conversion Rate und Customer Lifetime Value sind für dich keine Fremdwörter. Analytisches Denken und Datenliebe stecken in deiner DNA.</li>\n<li>Du bringst ein solides Grundverständnis über mehrere Marketingdisziplinen mit und willst verstehen, wie alles zusammenspielt – die Tiefe in einzelnen Kanälen baust du bei uns weiter aus.</li>\n<li>Du bist kommunikationsstark, präsentierst gerne und hast Freude daran, Daten in verständliche Geschichten zu übersetzen – auf Deutsch und Englisch.</li>\n<li>Du hast keine Angst vor Fehlern, denn du testest gerne hypothesenbasiert und lernst aus jedem Outcome.</li>\n<li>Vor allem aber: Du hast Lust, dich weiterzuentwickeln und über dich hinauszuwachsen.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Was wir dir bieten (Deine Opportunity):</strong></p>\n<ul>\n<li>Echte Flexibilität: Deine Work-Life-Integration ist uns heilig. Wir bieten dir flexible Arbeitszeiten und Homeoffice-Möglichkeiten.</li>\n<li>Personal Growth: Stillstand gibt es bei uns nicht. Wir investieren in deine Weiterbildung durch interne Trainings und externe Coaches – gerade in den ersten Jahren begleiten wir dich eng, damit du deine T-Shape kontinuierlich ausbauen kannst.</li>\n<li>Kultur &#x26; Wohlfühlfaktor: Flache Hierarchien, kurze Entscheidungswege, Teamevents und eine Kommunikation auf Augenhöhe. Und ja, Bürohunde sind bei uns nicht nur erlaubt, sondern absolut erwünscht!</li>\n<li>Fokus-Squads &#x26; Teamspirit: Wir arbeiten in agilen, 6–7-köpfigen Fokus-Squads direkt an unseren Kunden. Das bedeutet für dich: kurze Wege, ein intensives Teamgefühl und gemeinsamer Erfolg, den ihr als Einheit feiert.</li>\n<li>Globale Perspektive: Durch die Zugehörigkeit zur Labelium Group arbeitest du an internationalen Projekten und hast Zugang zum Wissen von über 1.200 hochkarätigen Spezialisten weltweit.</li>\n<li>Sicherheit: Betriebliche Altersvorsorge, Sachbezüge, Essenszulagen, Mitarbeiterrabatte und gute Verkehrsanbindungen an unseren Standort in Frankfurt.</li>\n</ul>\n<p><strong>Klingt das nach deinem nächsten Karriereschritt?</strong></p>\n<p>Dann vergiss das klassische Anschreiben. Schick uns einfach deinen Lebenslauf, dein LinkedIn-Profil oder ein kurzes Video, in dem du uns erzählst, welches Marketingproblem du zuletzt gelöst hast – oder was dich am Beraten von Kunden am meisten reizt.</p>\n<p>Wir freuen uns darauf, dich kennenzulernen!</p>\n<p>Bei uns zählt Vielfalt. Wir leben Inklusion, Respekt und Chancengleichheit.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Hallo!</strong></p>\n<p><strong>Schön, dass du hier bist.</strong></p>\n<p>Wir sind Klickkonzept, Teil der internationalen Cosmo5-Gruppe. Als KI-orientierte Performance-Agentur entwickeln wir in Frankfurt datengetriebene Lösungen für Brands, die wachsen wollen – von der Beauty-Industrie bis zum B2B-Sektor. Bei uns findest du keine starren Konzernstrukturen, sondern den Spirit einer Boutique-Agentur, gepaart mit der Power von weltweit 28 Partnerbüros in 17 Ländern.</p>\n<p>Wir suchen aktuell nach Verstärkung im Online Marketing. Aber um ehrlich zu sein: Wir suchen keine klassischen „Werkbank-Arbeiter\", die den ganzen Tag nur einzelne Kampagnen abarbeiten. Die Zeiten sind vorbei. Wir suchen T-Shaped Marketer. Wir suchen strategische Architekten von morgen. Wir suchen dich – als unseren neuen Umsatz-Designer.</p>\n<p>Warum „Umsatz-Designer\" und nicht einfach Online Marketing Manager?</p>\n<p>Weil sich die Welt des digitalen Marketings fundamental gedreht hat. Algorithmen und KI nehmen uns die kleinteilige Handarbeit ab. Das ist keine Gefahr, sondern die größte Chance unserer Branche! Es gibt uns endlich die Zeit, das große Ganze zu betrachten. Als T-Shaped Marketer bei uns baust du eine tiefe Expertise in Strategie und Kundenberatung auf (der vertikale Strich im „T\"). Aber du blickst auch nach links und rechts (der horizontale Strich): Du verstehst, wie SEA, Paid Social, SEO, Content und CRO zusammenspielen, und wie sich daraus für einen Kunden ein stimmiges Gesamtbild ergibt. Du gestaltest keine isolierten Maßnahmen, sondern ganzheitliche, umsatzgenerierende Ökosysteme für unsere Kunden.</p>\n<h2>Aufgaben</h2>\n<p><strong>Deine Spielwiese (Da