(2224, NULL, 'api', NULL, 'Remote Praktikum Lektorat & Korrektorat im Verlag (m/w/d)', 'Litura GmbH', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/litura-gmbh/remote-praktikum-lektorat-korrektorat-im-verlag-berlin-137362', '<p>Du studierst Germanistik, Literaturwissenschaft, Sprachwissenschaft oder ein ähnliches Fach und möchtest praktische Erfahrung im Verlagswesen sammeln?</p>\n<p>Dann ist dieses Praktikum eine gute Möglichkeit, echte Einblicke in die Arbeit eines modernen Sachbuchverlags zu bekommen. Du unterstützt uns bei der Prüfung und Bearbeitung von Manuskripten, arbeitest mit Sprache, Textstruktur und Stil und lernst, wie aus einem Manuskript Schritt für Schritt ein veröffentlichtes Buch wird.</p>\n<p>Das Praktikum findet remote statt und eignet sich besonders als Pflichtpraktikum im Rahmen deines Studiums.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Unterstützung bei der sprachlichen, stilistischen und orthografischen Prüfung von Manuskripten</li>\n<li>Erstellung strukturierter Feedback-Notizen für Autoren</li>\n<li>Mitarbeit bei redaktionellen Aufgaben rund um Buchprojekte</li>\n<li>Prüfung von Texten auf Verständlichkeit, Aufbau, Ausdruck und Lesbarkeit</li>\n<li>Unterstützung bei Recherchen und kleineren organisatorischen Aufgaben im Verlagsalltag</li>\n<li>Einblicke in weitere Bereiche der Buchveröffentlichung, z. B. Buchsatz, Cover, Titelentwicklung und Vermarktung</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Studium im Bereich Germanistik, Literaturwissenschaft, Sprachwissenschaft, Journalistik, Medienwissenschaft oder vergleichbar</li>\n<li>Sehr gutes Sprachgefühl und Freude an präziser Formulierung</li>\n<li>Sicherer Umgang mit Rechtschreibung, Grammatik und Zeichensetzung</li>\n<li>Guter Blick für Details und sprachliche Feinheiten</li>\n<li>Sorgfältige, zuverlässige und eigenverantwortliche Arbeitsweise</li>\n<li>Interesse an Büchern, Sachbuchthemen und Verlagsprozessen</li>\n<li>Praktikumsdauer: mindestens 3 Monate, idealerweise 5–6 Monate</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Remote-Praktikum mit flexibler Zeiteinteilung</li>\n<li>Einblicke in den gesamten Publikationsprozess eines Buches</li>\n<li>Mitarbeit an echten Buchprojekten statt künstlicher Übungsaufgaben</li>\n<li>Junges, motiviertes Team mit kurzen Kommunikationswegen</li>\n<li>Möglichkeit, eigene Ideen einzubringen</li>\n<li>Praktische Erfahrung im Lektorat, Korrektorat und in der Redaktion</li>\n<li>Persönliches Praktikumszeugnis nach Abschluss</li>\n</ul>\n<p>Wir freuen uns auf deine Bewerbung, schick uns einfach deinen Lebenslauf.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Du studierst Germanistik, Literaturwissenschaft, Sprachwissenschaft oder ein ähnliches Fach und möchtest praktische Erfahrung im Verlagswesen sammeln?</p>\n<p>Dann ist dieses Praktikum eine gute Möglichkeit, echte Einblicke in die Arbeit eines modernen Sachbuchverlags zu bekommen. Du unterstützt uns bei der Prüfung und Bearbeitung von Manuskripten, arbeitest mit Sprache, Textstruktur und Stil und lernst, wie aus einem Manuskript Schritt für Schritt ein veröffentlichtes Buch wird.</p>\n<p>Das Praktikum findet remote statt und eignet sich besonders als Pflichtpraktikum im Rahmen deines Studiums.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Unterstützung bei der sprachlichen, stilistischen und orthografischen Prüfung von Manuskripten</li>\n<li>Erstellung strukturierter Feedback-Notizen für Autoren</li>\n<li>Mitarbeit bei redaktionellen Aufgaben rund um Buchprojekte</li>\n<li>Prüfung von Texten auf Verständlichkeit, Aufbau, Ausdruck und Lesbarkeit</li>\n<li>Unterstützung bei Recherchen und kleineren organisatorischen Aufgaben im Verlagsalltag</li>\n<li>Einblicke in weitere Bereiche der Buchveröffentlichung, z. B. Buchsatz, Cover, Titelentwicklung und Vermarktung</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Studium im Bereich Germanistik, Literaturwissenschaft, Sprachwissenschaft, Journalistik, Medienwissenschaft oder vergleichbar</li>\n<li>Sehr gutes Sprachgefühl und Freude an präziser Formulierung</li>\n<li>Sicherer Umgang mit Rechtschreibung, Grammatik und Zeichensetzung</li>\n<li>Guter Blick für Details und sprachliche Feinheiten</li>\n<li>Sorgfältige, zuverlässige und eigenverantwortliche Arbeitsweise</li>\n<li>Interesse an Büchern, Sachbuchthemen und Verlagsprozessen</li>\n<li>Praktikumsdauer: mindestens 3 Monate, idealerweise 5–6 Monate</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Remote-Praktikum mit flexibler Zeiteinteilung</li>\n<li>Einblicke in den gesamten Publikationsprozess eines Buches</li>\n<li>Mitarbeit an echten Buchprojekten statt künstlicher Übungsaufgaben</li>\n<li>Junges, motiviertes Team mit kurzen Kommunikationswegen</li>\n<li>Möglichkeit, eigene Ideen einzubringen</li>\n<li>Praktische Erfahrung im Lektorat, Korrektorat und in der Redaktion</li>\n<li>Persönliches Praktikumszeugnis nach Abschluss</li>\n</ul>\n<p>Wir freuen uns auf deine Bewerbung, schick uns einfach deinen Lebenslauf.</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-05 01:40:40.086', '2026-07-05 01:40:40.086', '', '', 'Remote', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/litura-gmbh/remote-praktikum-lektorat-korrektorat-im-verlag-berlin-137362', 'https://www.arbeitnow.com/jobs/companies/litura-gmbh/remote-praktikum-lektorat-korrektorat-im-verlag-berlin-137362', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/litura-gmbh/remote-praktikum-lektorat-korrektorat-im-verlag-berlin-137362\",\"type\":\"applyUrl\"}]', 'pending', '', NULL);
INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(2225, NULL, 'api', NULL, 'Associate Recruitment & Human Capital Consulting', 'TJC Partners AG', 'Munich', 'https://www.arbeitnow.com/jobs/companies/tjc-partners-ag/associate-recruitment-human-capital-consulting-munich-212628', '<p><strong>Wer wir sind</strong></p>\n<p>TJC Partners AG wurde Anfang 2025 von zwei Partnern gegründet. Kein externes Kapital, keine Investoren. Was wir haben, ist eine klare Vorstellung davon, was wir aufbauen wollen und den Beweis, dass es funktioniert. Zu unseren Mandanten zählen sowohl große internationale Beratungshäuser und Kanzleien als auch spezialisierte Mittelständler und Spin-off-Boutiquen. Unsere Mandanten arbeiten mit uns im Kontext von Fusionen, Standorteröffnungen, Teamwechseln und Partnervermittlungen.</p>\n<p>Anderthalb Jahre später sind wir um 500% gewachsen, vollständig bootstrapped, von Anfang an profitabel und zählen zu den am schnellsten wachsenden Executive und C-Suite Personalberatungen im DACH-Raum. Der Fokus liegt heute auf der Personalvermittlung im Legal, Tax und Audit Markt und genau dort wollen wir in den nächsten Jahren eine marktführende Position einnehmen. Transaktions- und Nachfolgeberatung bauen wir parallel weiter aus, mit dem langfristigen Ziel, eines der führenden Vermittlungs- und Beratungshäuser Europas zu werden. Der nächste Schritt liegt hierbei in unserer Standorteröffnung und dem weiteren Teamausbau in München.</p>\n<p>Das ist der Plan und wir suchen Leute, die ihn mitbauen wollen.</p>\n<p><strong>Warum das der richtige Moment ist</strong></p>\n<p>Wir sind an dem Punkt, an dem die Grundlagen - unser Office in Zürich - stehen und das eigentliche Wachstum beginnt. Wer jetzt einsteigt, prägt mit, wie TJC Partners in fünf Jahren aussieht und hat die Möglichkeit, gemeinsam mit dem Unternehmen in unserem neuen Standort in München in eine Führungsrolle zu wachsen.</p>\n<p><strong>Was dich erwartet</strong></p>\n<p>Du lernst das Handwerk von Grund auf. Von der ersten Mandantenanfrage über die Kandidatensuche und Direktansprache bis hin zur strategischen Marktabdeckung und deinem ersten Abschluss. Keine Backoffice-Phase, kein Wartezimmer. Du bist vom ersten Tag an dabei, wirst schnell eigene Verantwortung übernehmen und lernst einen Markt kennen, der so viel Substanz hat wie kaum ein anderer im Professional-Services-Bereich.</p>\n<p>Und weil Performance sich lohnen soll, zählt jede Platzierung, jede aufgebaute Beziehung und jedes gewonnene Mandat auch für dich.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Kandidaten im Legal-, Tax- und Audit-Markt identifizieren, ansprechen und qualifizieren</li>\n<li>Suchaufträge von der Mandantenberatung bis zum erfolgreichen Abschluss eigenverantwortlich begleiten</li>\n<li>Beziehungen zu Kandidaten und Mandanten aufbauen, die über den einzelnen Auftrag hinaus halten</li>\n<li>Ein langfristiges Marktverständnis aufbauen, um strategische Wachstumspläne und Positionierungen ganzer Kanzleien sowie daraus resultierende Karriereentwicklungen und -chancen einzelner Kandidaten in einem ganzheitlichen Kontext einordnen zu können</li>\n<li>Die Marktwahrnehmung von TJC Partners durch deine Beratungsdienstleitungen nachhaltig positiv beeinflussen</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Ein abgeschlossenes Studium oder eine vergleichbare Qualifikation, wobei der Fachbereich zweitrangig ist</li>\n<li>Den Antrieb und die Lernbereitschaft, wirklich etwas aufzubauen, nicht nur dabei zu sein</li>\n<li>Die Fähigkeit, mit unterschiedlichen Menschen klar und auf Augenhöhe zu kommunizieren</li>\n<li>Eigenverantwortung und Struktur, auch wenn es mal stressig wird</li>\n<li>Lust auf ein kleines Team, in dem man füreinander einsteht</li>\n<li>Verhandlungssicheres Deutsch, Englisch ist ein Plus</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Direktes Mentoring durch die Gründer und den Niederlassungsleiter in München, die den Markt kennen und dir alles beibringen, was du brauchst</li>\n<li>Einen klaren Entwicklungspfad mit realem Führungspotenzial in einem Unternehmen, das schnell wächst</li>\n<li>Direkte Exposition gegenüber Mandanten und Kandidaten von Anfang an</li>\n<li>Solides Fixgehalt mit hoher leistungs- und abschlussbasierter Provision die zu herausragenden Verdienstmöglichkeiten zum Einstieg führen</li>\n<li>Ein Team, das bewiesen hat, dass es liefert</li>\n<li>Modernes Arbeitsumfeld in München</li>\n</ul>\n<p>Wir freuen uns von dir zu hören!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Wer wir sind</strong></p>\n<p>TJC Partners AG wurde Anfang 2025 von zwei Partnern gegründet. Kein externes Kapital, keine Investoren. Was wir haben, ist eine klare Vorstellung davon, was wir aufbauen wollen und den Beweis, dass es funktioniert. Zu unseren Mandanten zählen sowohl große internationale Beratungshäuser und Kanzleien als auch spezialisierte Mittelständler und Spin-off-Boutiquen. Unsere Mandanten arbeiten mit uns im Kontext von Fusionen, Standorteröffnungen, Teamwechseln und Partnervermittlungen.</p>\n<p>Anderthalb Jahre später sind wir um 500% gewachsen, vollständig bootstrapped, von Anfang an profitabel und zählen zu den am schnellsten wachsenden Executive und C-Suite Personalberatungen im DACH-Raum. Der Fokus liegt heute auf der Personalvermittlung im Legal, Tax und Audit Markt und genau dort wollen wir in den nächsten Jahren eine marktführende Position einnehmen. Transaktions- und Nachfolgeberatung bauen wir parallel weiter aus, mit dem langfristigen Ziel, eines der führenden Vermittlungs- und Beratungshäuser Europas zu werden. Der nächste Schritt liegt hierbei in unserer Standorteröffnung und dem weiteren Teamausbau in München.</p>\n<p>Das ist der Plan und wir suchen Leute, die ihn mitbauen wollen.</p>\n<p><strong>Warum das der richtige Moment ist</strong></p>\n<p>Wir sind an dem Punkt, an dem die Grundlagen - unser Office in Zürich - stehen und das eigentliche Wachstum beginnt. Wer jetzt einsteigt, prägt mit, wie TJC Partners in fünf Jahren aussieht und hat die Möglichkeit, gemeinsam mit dem Unternehmen in unserem neuen Standort in München in eine Führungsrolle zu wachsen.</p>\n<p><strong>Was dich erwartet</strong></p>\n<p>Du lernst das Handwerk von Grund auf. Von der ersten Mandantenanfrage über die Kandidatensuche und Direktansprache bis hin zur strategischen Marktabdeckung und deinem ersten Abschluss. Keine Backoffice-Phase, kein Wartezimmer. Du bist vom ersten Tag an dabei, wirst schnell eigene Verantwortung übernehmen und lernst einen Markt kennen, der so viel Substanz hat wie kaum ein anderer im Professional-Services-Bereich.</p>\n<p>Und weil Performance sich lohnen soll, zählt jede Platzierung, jede aufgebaute Beziehung und jedes gewonnene Mandat auch für dich.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Kandidaten im Legal-, Tax- und Audit-Markt identifizieren, ansprechen und qualifizieren</li>\n<li>Suchaufträge von der Mandantenberatung bis zum erfolgreichen Abschluss eigenverantwortlich begleiten</li>\n<li>Beziehungen zu Kandidaten und Mandanten aufbauen, die über den einzelnen Auftrag hinaus halten</li>\n<li>Ein langfristiges Marktverständnis aufbauen, um strategische Wachstumspläne und Positionierungen ganzer Kanzleien sowie daraus resultierende Karriereentwicklungen und -chancen einzelner Kandidaten in einem ganzheitlichen Kontext einordnen zu können</li>\n<li>Die Marktwahrnehmung von TJC Partners durch deine Beratungsdienstleitungen nachhaltig positiv beeinflussen</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Ein abgeschlossenes Studium oder eine vergleichbare Qualifikation, wobei der Fachbereich zweitrangig ist</li>\n<li>Den Antrieb und die Lernbereitschaft, wirklich etwas aufzubauen, nicht nur dabei zu sein</li>\n<li>Die Fähigkeit, mit unterschiedlichen Menschen klar und auf Augenhöhe zu kommunizieren</li>\n<li>Eigenverantwortung und Struktur, auch wenn es mal stressig wird</li>\n<li>Lust auf ein kleines Team, in dem man füreinander einsteht</li>\n<li>Verhandlungssicheres Deutsch, Englisch ist ein Plus</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>Direktes Mentoring durch die Gründer und den Niederlassungsleiter in München, die den Markt kennen und dir alles beibringen, was du brauchst</li>\n<li>Einen klaren Entwicklungspfad mit realem Führungspotenzial in einem Unternehmen, das schnell wächst</li>\n<li>Direkte Exposition gegenüber Mandanten und Kandidaten von Anfang an</li>\n<li>Solides Fixgehalt mit hoher leistungs- und abschlussbasierter Provision die zu herausragenden Verdienstmöglichkeiten zum Einstieg führen</li>\n<li>Ein Team, das bewiesen hat, dass es liefert</li>\n<li>Modernes Arbeitsumfeld in München</li>\n</ul>\n<p>Wir freuen uns von dir zu hören!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-05 01:40:48.106', '2026-07-05 01:40:48.106', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/tjc-partners-ag/associate-recruitment-human-capital-consulting-munich-212628', 'https://www.arbeitnow.com/jobs/companies/tjc-partners-ag/associate-recruitment-human-capital-consulting-munich-212628', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/tjc-partners-ag/associate-recruitment-human-capital-consulting-munich-212628\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2226, NULL, 'api', NULL, 'Sachbearbeiter *(gn) für die Abteilung Marktfolge Passiv', 'Volksbank Raiffeisenbank Fürstenfeldbruck eG', 'Germering', 'https://www.arbeitnow.com/jobs/companies/volksbank-raiffeisenbank-furstenfeldbruck-eg/sachbearbeiter-gn-fur-die-abteilung-marktfolge-passiv-germering-240461', '<p>Wir sind eine erfolgreiche, innovative Genossenschaftsbank im Landkreis Fürstenfeldbruck mit einer Bilanzsumme von ca. 2,1 Mrd. €, 13 Geschäftsstellen und 260 engagierten Mitarbeiterinnen und Mitarbeitern.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Abwicklung der kompletten Debit- und Kreditkartenbearbeitung</li>\n<li>Bearbeitung von Nachlassfällen</li>\n<li>Bearbeitung Kapitalertragssteuer (Freistellungen und NV-Bescheinigungen etc.)</li>\n<li>Bearbeitung von Adressänderungen/ -nachforschungen</li>\n<li>Bearbeitung Auslandssteuer (FATCA/CRS)</li>\n<li>Erstellung und Verwaltung von Kundenbestätigungen</li>\n<li>Bearbeitung der AWV-Meldung</li>\n<li>Bearbeitung von Kontoumschreibungen und Gläubigerwechseln</li>\n<li>Bearbeitung von Aufgaben in der Kunden- und Kontenverwaltung</li>\n<li>Vertretung Auslandsgeschäft</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Abgeschlossene Bankausbildung bzw. kaufmännische Ausbildung</li>\n<li>Selbstständige, systematische und effektive Arbeitsweise</li>\n<li>Teamfähigkeit und Belastbarkeit</li>\n<li>Bereitschaft zur Weiterbildung</li>\n<li>Selbstsicheres Auftreten ggü. anderer Abteilungen</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>ein interessantes und anspruchsvolles Aufgabengebiet</li>\n<li>attraktives Gehalt</li>\n<li>angenehmes Arbeitsumfeld</li>\n<li>gezielte Förderung und Weiterbildung</li>\n<li>eine langfristige Perspektive in einem innovativen und zukunftsorientierten Unternehmen</li>\n<li>attraktives Sozialleistungssystem (Sonderzahlung, betriebliche Altersvorsorge, Zusatzkrankenversicherung, Mitarbeiter-Benefit-System inkl. Bike-Leasing u.v.m.)</li>\n<li>Gruppenunfallversicherung auch für den privaten Bereich</li>\n<li>Firmenfitnessprogramm (Zugang zu vielen Sport-, Fitness- und Wellnesseinrichtungen sowie Onlinekursen)</li>\n</ul>\n<p>Interesse? Dann freuen wir uns über Ihre aussagekräftige Bewerbung mit Angabe Ihrer Gehaltsvorstellung sowie Ihrem möglichen Eintrittstermin.</p>\n<p>Haben Sie Fragen? Rufen Sie uns gerne an.</p>\n<p>Ihre Ansprechpartnerin: Ines Bauer, Telefon 08141 270-2240</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p>Wir sind eine erfolgreiche, innovative Genossenschaftsbank im Landkreis Fürstenfeldbruck mit einer Bilanzsumme von ca. 2,1 Mrd. €, 13 Geschäftsstellen und 260 engagierten Mitarbeiterinnen und Mitarbeitern.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Abwicklung der kompletten Debit- und Kreditkartenbearbeitung</li>\n<li>Bearbeitung von Nachlassfällen</li>\n<li>Bearbeitung Kapitalertragssteuer (Freistellungen und NV-Bescheinigungen etc.)</li>\n<li>Bearbeitung von Adressänderungen/ -nachforschungen</li>\n<li>Bearbeitung Auslandssteuer (FATCA/CRS)</li>\n<li>Erstellung und Verwaltung von Kundenbestätigungen</li>\n<li>Bearbeitung der AWV-Meldung</li>\n<li>Bearbeitung von Kontoumschreibungen und Gläubigerwechseln</li>\n<li>Bearbeitung von Aufgaben in der Kunden- und Kontenverwaltung</li>\n<li>Vertretung Auslandsgeschäft</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Abgeschlossene Bankausbildung bzw. kaufmännische Ausbildung</li>\n<li>Selbstständige, systematische und effektive Arbeitsweise</li>\n<li>Teamfähigkeit und Belastbarkeit</li>\n<li>Bereitschaft zur Weiterbildung</li>\n<li>Selbstsicheres Auftreten ggü. anderer Abteilungen</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>ein interessantes und anspruchsvolles Aufgabengebiet</li>\n<li>attraktives Gehalt</li>\n<li>angenehmes Arbeitsumfeld</li>\n<li>gezielte Förderung und Weiterbildung</li>\n<li>eine langfristige Perspektive in einem innovativen und zukunftsorientierten Unternehmen</li>\n<li>attraktives Sozialleistungssystem (Sonderzahlung, betriebliche Altersvorsorge, Zusatzkrankenversicherung, Mitarbeiter-Benefit-System inkl. Bike-Leasing u.v.m.)</li>\n<li>Gruppenunfallversicherung auch für den privaten Bereich</li>\n<li>Firmenfitnessprogramm (Zugang zu vielen Sport-, Fitness- und Wellnesseinrichtungen sowie Onlinekursen)</li>\n</ul>\n<p>Interesse? Dann freuen wir uns über Ihre aussagekräftige Bewerbung mit Angabe Ihrer Gehaltsvorstellung sowie Ihrem möglichen Eintrittstermin.</p>\n<p>Haben Sie Fragen? Rufen Sie uns gerne an.</p>\n<p>Ihre Ansprechpartnerin: Ines Bauer, Telefon 08141 270-2240</p>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-05 01:40:56.941', '2026-07-05 01:40:56.941', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/volksbank-raiffeisenbank-furstenfeldbruck-eg/sachbearbeiter-gn-fur-die-abteilung-marktfolge-passiv-germering-240461', 'https://www.arbeitnow.com/jobs/companies/volksbank-raiffeisenbank-furstenfeldbruck-eg/sachbearbeiter-gn-fur-die-abteilung-marktfolge-passiv-germering-240461', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/volksbank-raiffeisenbank-furstenfeldbruck-eg/sachbearbeiter-gn-fur-die-abteilung-marktfolge-passiv-germering-240461\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2227, NULL, 'api', NULL, 'Mitarbeiter *(gn) für die Abteilung EDV/Technik', 'Volksbank Raiffeisenbank Fürstenfeldbruck eG', 'Germering', 'https://www.arbeitnow.com/jobs/companies/volksbank-raiffeisenbank-furstenfeldbruck-eg/mitarbeiter-gn-fur-die-abteilung-edv-technik-germering-72233', '<p>Wir sind eine erfolgreiche, innovative Genossenschaftsbank im Landkreis Fürstenfeldbruck mit einer Bilanzsumme von ca. 2,1 Mrd. €, 13 Geschäftsstellen und 260 engagierten Mitarbeiterinnen und Mitarbeitern.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Unterstützung der Kollegen bei Fragen rund um Computer, Programme und Telefonie</li>\n<li>Support bei der Wartung unserer IT-Systeme</li>\n<li>Arbeiten mit Anwendungen wie Outlook, Teams und weiteren Microsoft-Programmen</li>\n<li>Unterstützung bei IT-Projekten und Systemoptimierungen</li>\n<li>Mitarbeit bei kleineren IT-Projekten (z. B. Systemeinführungen, Optimierungen, technische Umstellungen)</li>\n<li>Planung, Koordination und Abstimmung mit internen Fachbereichen sowie externen Dienstleistern (Atruvia)</li>\n<li>Nach erfolgreicher Einarbeitung wird mehr Verantwortung übernommen</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Grundlegendes Interesse an IT, Computern und digitalen Anwendungen (keine spezielle Ausbildung notwendig)</li>\n<li>Erste Erfahrungen und Interesse am Umgang mit Microsoft 365</li>\n<li>Bereitschaft sich in neue Themen einzuarbeiten</li>\n<li>Strukturierte, selbstständige Arbeitsweise</li>\n<li>soziale und kommunikative Kompetenz</li>\n<li>Lernfähigkeit und Flexibilität</li>\n<li>Stabilität und Belastbarkeit</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>ein interessantes und anspruchsvolles Aufgabengebiet</li>\n<li>attraktives Gehalt</li>\n<li>angenehmes Arbeitsumfeld</li>\n<li>gezielte Förderung und Weiterbildung</li>\n<li>eine langfristige Perspektive in einem innovativen und zukunftsorientierten Unternehmen</li>\n<li>attraktives Sozialleistungssystem (Sonderzahlung, betriebliche Altersvorsorge, Zusatzkrankenversicherung, Mitarbeiter-Benefit-System inkl. Bike-Leasing u.v.m.)</li>\n<li>Gruppenunfallversicherung auch für den privaten Bereich</li>\n<li>Firmenfitnessprogramm (Zugang zu vielen Sport-, Fitness- und Wellnesseinrichtungen sowie Onlinekursen)</li>\n</ul>\n<p>Interesse? Dann freuen wir uns über Ihre aussagekräftige Bewerbung mit Angabe Ihrer Gehaltsvorstellung sowie Ihrem möglichen Eintrittstermin.</p>\n<p>Haben Sie Fragen? Rufen Sie uns gerne an.</p>\n<p>Ihre Ansprechpartnerin: Ines Bauer, Telefon 08141 270-2240</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Wir sind eine erfolgreiche, innovative Genossenschaftsbank im Landkreis Fürstenfeldbruck mit einer Bilanzsumme von ca. 2,1 Mrd. €, 13 Geschäftsstellen und 260 engagierten Mitarbeiterinnen und Mitarbeitern.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Unterstützung der Kollegen bei Fragen rund um Computer, Programme und Telefonie</li>\n<li>Support bei der Wartung unserer IT-Systeme</li>\n<li>Arbeiten mit Anwendungen wie Outlook, Teams und weiteren Microsoft-Programmen</li>\n<li>Unterstützung bei IT-Projekten und Systemoptimierungen</li>\n<li>Mitarbeit bei kleineren IT-Projekten (z. B. Systemeinführungen, Optimierungen, technische Umstellungen)</li>\n<li>Planung, Koordination und Abstimmung mit internen Fachbereichen sowie externen Dienstleistern (Atruvia)</li>\n<li>Nach erfolgreicher Einarbeitung wird mehr Verantwortung übernommen</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Grundlegendes Interesse an IT, Computern und digitalen Anwendungen (keine spezielle Ausbildung notwendig)</li>\n<li>Erste Erfahrungen und Interesse am Umgang mit Microsoft 365</li>\n<li>Bereitschaft sich in neue Themen einzuarbeiten</li>\n<li>Strukturierte, selbstständige Arbeitsweise</li>\n<li>soziale und kommunikative Kompetenz</li>\n<li>Lernfähigkeit und Flexibilität</li>\n<li>Stabilität und Belastbarkeit</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li>ein interessantes und anspruchsvolles Aufgabengebiet</li>\n<li>attraktives Gehalt</li>\n<li>angenehmes Arbeitsumfeld</li>\n<li>gezielte Förderung und Weiterbildung</li>\n<li>eine langfristige Perspektive in einem innovativen und zukunftsorientierten Unternehmen</li>\n<li>attraktives Sozialleistungssystem (Sonderzahlung, betriebliche Altersvorsorge, Zusatzkrankenversicherung, Mitarbeiter-Benefit-System inkl. Bike-Leasing u.v.m.)</li>\n<li>Gruppenunfallversicherung auch für den privaten Bereich</li>\n<li>Firmenfitnessprogramm (Zugang zu vielen Sport-, Fitness- und Wellnesseinrichtungen sowie Onlinekursen)</li>\n</ul>\n<p>Interesse? Dann freuen wir uns über Ihre aussagekräftige Bewerbung mit Angabe Ihrer Gehaltsvorstellung sowie Ihrem möglichen Eintrittstermin.</p>\n<p>Haben Sie Fragen? Rufen Sie uns gerne an.</p>\n<p>Ihre Ansprechpartnerin: Ines Bauer, Telefon 08141 270-2240</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-05 01:41:05.647', '2026-07-05 01:41:05.647', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/volksbank-raiffeisenbank-furstenfeldbruck-eg/mitarbeiter-gn-fur-die-abteilung-edv-technik-germering-72233', 'https://www.arbeitnow.com/jobs/companies/volksbank-raiffeisenbank-furstenfeldbruck-eg/mitarbeiter-gn-fur-die-abteilung-edv-technik-germering-72233', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/volksbank-raiffeisenbank-furstenfeldbruck-eg/mitarbeiter-gn-fur-die-abteilung-edv-technik-germering-72233\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2228, NULL, 'api', NULL, 'Quereinsteiger: Redaktion, Marketing, Vertrieb (m/w/d)', 'GITO mbH Verlag', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/gito-mbh-verlag/quereinsteiger-redaktion-marketing-vertrieb-berlin-275111', '<p><strong>Abwechslungsreicher</strong> <strong>Job</strong> mit <strong>Entwicklungs-</strong> und <strong>Aufstiegsmöglichkeit.</strong></p>\n<p><strong>Motivierte und ambitionierte Quereinsteiger willkommen.</strong></p>\n<p><strong>Praktikum, Freelancer, Minijob oder Teilzeit</strong> möglich.<br>\nArbeiten Sie sorgfältig, schnell und gewissenhaft und sind lern- und wissbegierig? Interessieren Sie sich für die Zukunftsthemen Smart Factory und Industrie 4.0? Dann werden Sie Teil eines dynamischen Teams beim GITO Verlag in Berlin-Charlottenburg. Wir suchen Multitalente und Freelancer die unser Team unterstützen.</p>\n<h2>Aufgaben</h2>\n<ul>\n<li>Redaktionelle und organisatorische Aufgaben sowie Datenpflege</li>\n<li>Akquisition von Autoren und Anzeigenkunden</li>\n<li>Verwaltung, Zuarbeit für Steuerberatung, Stammdatenpflege, Reporting</li>\n<li>Zuarbeit für Online-Shop / Websites / Social Media</li>\n<li>Marketing, GEO / SEO / SEA Optimierungen</li>\n<li>Effiziente Erstellung und Umsetzung von Anzeigen für PRINT und ONLINE z.B. mit <a href=\"http://Admagica.ai\">Admagica.ai</a>, Creatopy, AdCreative, Midjourney, Kittl, Let\'s Enhance, Canva Magic Studio, Adobe Firefly / Photoshop etc.</li>\n<li>Kommunikation mit Geschäftspartnern (Deutsch/Englisch)</li>\n</ul>\n<h2>Qualifikation</h2>\n<p><strong>WAS WIR ERWARTEN</strong></p>\n<ul>\n<li>Schnelle Auffassungsgabe und in der Lage sich motiviert und selbständig in neue Themen und Anwenderprogramme einzuarbeiten</li>\n<li>Exzellente Deutschkenntnisse in Wort und Schrift</li>\n<li>Eigenverantwortliche selbstmotivierte Arbeitsweise</li>\n<li>Routinierte Erfahrung mit Office-Anwendungen</li>\n<li>Sorgfältige, gewissenhafte und effiziente Arbeitsweise</li>\n<li>100% zuverlässig, ehrlich und loyal</li>\n<li>Erfahrung mit CRM und Website Pflege</li>\n</ul>\n<p><strong>WAS ZEICHNET SIE AUS</strong></p>\n<ul>\n<li><strong>Lernen verstehen Sie als lebenslangen Prozess</strong></li>\n<li>Auf Sie kann man sich verlassen - Fristen, Termine und Aufgaben haben Sie im Griff und Reporting ist kein Fremdwort für Sie</li>\n<li>Mit vorbildlicher Organisation unterstützen Sie das Team und sorgen für reibungslose Abläufe</li>\n<li>Mit Wissen und Ideen optimieren Sie Prozesse und machen unsere Firma zukunftssicher</li>\n<li>Rechtschreibung und Grammatik beherrschen Sie und für Zahlen haben Sie ein gutes Verständnis</li>\n</ul>\n<h2>Benefits</h2>\n<ul>\n<li><strong>Abwechslungsreicher</strong> Job mit <strong>Entwicklungsmöglichkeiten</strong></li>\n<li><strong>Aufstiegsmöglichkeiten</strong> und Position mit <strong>langfristiger</strong> Perspektive</li>\n<li><strong>Quereinsteiger</strong> sehr willkommen (mit dem Willen und der <strong>Motivation</strong> sich fehlendes Wissen <strong>selbständig</strong> anzueignen)</li>\n<li>Ein Büro in <strong>BERLIN-CHARLOTTENBURG,</strong> im Herzen der Hauptstadt</li>\n<li>Optimale Erreichbarkeit, direkt am U-Bahnhof Kaiserdamm</li>\n<li>Modernes und bequemes Büro mit Kaffee, Tee und Getränken</li>\n</ul>\n<p>Wir freuen uns auf Ihre Bewerbung, bitte senden Sie folgende Unterlagen per E-Mail:</p>\n<ul>\n<li>Anschreiben und Lebenslauf</li>\n<li>Verdienstvorstellung</li>\n<li>Zeugnisse, Referenzen</li>\n<li>Mögliches Startdatum</li>\n<li>Verfügbarkeit</li>\n</ul>\n<p>Find <a href=\"https://www.arbeitnow.com/\">Jobs in Germany</a> on Arbeitnow</a>', '<p><strong>Abwechslungsreicher</strong> <strong>Job</strong> mit <strong>Entwicklungs-</strong> und <strong>Aufstiegsmöglichkeit.</strong></p>\n<p><strong>Motivierte und ambitionierte Quereinsteiger willkommen.</strong></p>\n<p><strong>Praktikum, Freelancer, Minijob oder Teilzeit</strong> möglich.<br>\nArbeiten Sie sorgfältig, schnell und gewissenhaft und sind lern- und wissbegierig? Inter