INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(2403, NULL, 'api', NULL, 'Junior Account Manager B2B', 'SalesViewer GmbH', 'Bochum', 'https://www.arbeitnow.com/jobs/companies/salesviewer-gmbh/junior-account-manager-b2b-bochum-444741', '<p>SalesViewer® verändert, wie B2B-Unternehmen neue Kunden gewinnen. Unsere<br>\nSales-Intelligence-Plattform macht sichtbar, welche Unternehmen sich<br>\nbereits für ein Produkt interessieren – bevor sie sich zu erkennen<br>\ngeben. Damit verwandeln wir anonymen Website-Traffic in konkrete<br>\nVertriebschancen und verschaffen Vertriebsteams einen strukturellen<br>\nVorsprung. Über 3.000 Unternehmen vertrauen bereits auf unsere<br>\nTechnologie – und wir stehen erst am Anfang.</p>\n<h2>Aufgaben</h2>\n<p>Diese Rolle richtet sich an Absolventen, die sich bewusst für eine Laufbahn im B2B-Vertrieb entschieden haben und das Handwerk von Grund auf lernen wollen: wie moderne Vertriebsorganisationen arbeiten, wie man Entscheider überzeugt und wie aus Interesse ein Abschluss wird. Du startest mit klar umrissenen Aufgaben, übernimmst Schritt für Schritt mehr Verantwortung – und wirst dabei eng von erfahrenen Kollegen begleitet.</p>\n<p>Dein Einstieg ist als strukturierte Lernkurve angelegt – mit wachsender Verantwortung von Anfang an:</p>\n<ul>\n<li>Du qualifizierst eingehende Anfragen und führst Deine ersten eigenen Erstgespräche – vorbereitet und begleitet durch Dein Team.</li>\n<li>Du lernst, Produktdemos zu halten, die auf die konkrete Situation<br>\ndes jeweiligen Unternehmens eingehen – und übernimmst sie zunehmend<br>\nselbständig.</li>\n<li>Du arbeitest Dich tief in unseren Markt ein: Sales Intelligence,<br>\nGo-to-Market-Strategien und die Vertriebslogik unterschiedlicher<br>\nBranchen.</li>\n<li>Du unterstützt erfahrene Kollegen in laufenden Verkaufsprozessen und<br>\nlernst dabei, wie Abschlüsse auf Entscheiderebene entstehen.</li>\n<li>Du pflegst Dein CRM von Beginn an – und entwickelst so das Fundament für verlässliche eigene Prognosen.</li>\n<li>Du begleitest uns auf Messen und Events und baust Dir Schritt für Schritt Dein eigenes Netzwerk auf.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Mehrjährige Berufserfahrung setzen wir nicht voraus – wohl aber eine bewusste Entscheidung für den Vertrieb und erste fundierte Berührungspunkte mit dem Thema:</p>\n<ul>\n<li>Ein abgeschlossenes Studium, idealerweise mit Bezug zu Sales<br>\nManagement, BWL, Wirtschaftswissenschaften oder einem verwandten Bereich.</li>\n<li>Nachweisbares Interesse an Vertrieb, Go-to-Market und digitalen Geschäftsmodellen – etwa durch Studienschwerpunkte, Praktika, Werkstudententätigkeiten oder eigene Projekte.</li>\n<li>Intellektuelle Neugier: Du willst verstehen, wie Unternehmen funktionieren, bevor Du ihnen etwas verkaufst.</li>\n<li>Kommunikationsstärke und die Bereitschaft, aktiv auf Menschen zuzugehen – auch auf Entscheiderebene.</li>\n<li>Den Anspruch, schnell zu lernen: Du suchst Feedback, hältst es aus und setzt es um.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Warum SalesViewer®</strong>?</p>\n<p>Du kommst in ein profitables, wachsendes Unternehmen mit einem<br>\nProdukt, das sich nachweislich verkauft – und startest Deine<br>\nVertriebslaufbahn dort, wo Du sie wirklich lernen kannst:</p>\n<ul>\n<li>Ein strukturierter Einstieg mit erfahrenen Kollegen an Deiner Seite – Du lernst am echten Geschäft, nicht in der Theorie.</li>\n<li>Echte Entwicklungsperspektive: Wer liefert, wächst bei uns in die volle Vertriebsverantwortung hinein.</li>\n<li>Ein Arbeitsplatz im Exzenterhaus, einem der markantesten Gebäude Bochums, mit moderner Ausstattung nach Deiner Wahl.</li>\n<li>Gezielte Investition in Deine Weiterentwicklung – fachlich wie finanziell.</li>\n<li>Zuschuss zum ÖPNV-Ticket sowie Zugang zu Corporate Benefits bei zahlreichen Marken.</li>\n<li>Eine Kultur, die auf Transparenz und Vertrauen baut – Erfolge werden gemeinsam erarbeitet und gemeinsam gefeiert.</li>\n</ul>\n<p><strong>Lust bekommen, mit uns den B2B-Vertrieb neu zu denken?</strong><br>\n<strong>Dann schick uns deine Bewerbung –</strong><br>\n<strong>wir freuen uns darauf, dich persönlich kennenzulernen!</strong></p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>SalesViewer® verändert, wie B2B-Unternehmen neue Kunden gewinnen. Unsere<br>\nSales-Intelligence-Plattform macht sichtbar, welche Unternehmen sich<br>\nbereits für ein Produkt interessieren – bevor sie sich zu erkennen<br>\ngeben. Damit verwandeln wir anonymen Website-Traffic in konkrete<br>\nVertriebschancen und verschaffen Vertriebsteams einen strukturellen<br>\nVorsprung. Über 3.000 Unternehmen vertrauen bereits auf unsere<br>\nTechnologie – und wir stehen erst am Anfang.</p>\n<h2>Aufgaben</h2>\n<p>Diese Rolle richtet sich an Absolventen, die sich bewusst für eine Laufbahn im B2B-Vertrieb entschieden haben und das Handwerk von Grund auf lernen wollen: wie moderne Vertriebsorganisationen arbeiten, wie man Entscheider überzeugt und wie aus Interesse ein Abschluss wird. Du startest mit klar umrissenen Aufgaben, übernimmst Schritt für Schritt mehr Verantwortung – und wirst dabei eng von erfahrenen Kollegen begleitet.</p>\n<p>Dein Einstieg ist als strukturierte Lernkurve angelegt – mit wachsender Verantwortung von Anfang an:</p>\n<ul>\n<li>Du qualifizierst eingehende Anfragen und führst Deine ersten eigenen Erstgespräche – vorbereitet und begleitet durch Dein Team.</li>\n<li>Du lernst, Produktdemos zu halten, die auf die konkrete Situation<br>\ndes jeweiligen Unternehmens eingehen – und übernimmst sie zunehmend<br>\nselbständig.</li>\n<li>Du arbeitest Dich tief in unseren Markt ein: Sales Intelligence,<br>\nGo-to-Market-Strategien und die Vertriebslogik unterschiedlicher<br>\nBranchen.</li>\n<li>Du unterstützt erfahrene Kollegen in laufenden Verkaufsprozessen und<br>\nlernst dabei, wie Abschlüsse auf Entscheiderebene entstehen.</li>\n<li>Du pflegst Dein CRM von Beginn an – und entwickelst so das Fundament für verlässliche eigene Prognosen.</li>\n<li>Du begleitest uns auf Messen und Events und baust Dir Schritt für Schritt Dein eigenes Netzwerk auf.</li>\n</ul>\n<h2>Qualifikation</h2>\n<p>Mehrjährige Berufserfahrung setzen wir nicht voraus – wohl aber eine bewusste Entscheidung für den Vertrieb und erste fundierte Berührungspunkte mit dem Thema:</p>\n<ul>\n<li>Ein abgeschlossenes Studium, idealerweise mit Bezug zu Sales<br>\nManagement, BWL, Wirtschaftswissenschaften oder einem verwandten Bereich.</li>\n<li>Nachweisbares Interesse an Vertrieb, Go-to-Market und digitalen Geschäftsmodellen – etwa durch Studienschwerpunkte, Praktika, Werkstudententätigkeiten oder eigene Projekte.</li>\n<li>Intellektuelle Neugier: Du willst verstehen, wie Unternehmen funktionieren, bevor Du ihnen etwas verkaufst.</li>\n<li>Kommunikationsstärke und die Bereitschaft, aktiv auf Menschen zuzugehen – auch auf Entscheiderebene.</li>\n<li>Den Anspruch, schnell zu lernen: Du suchst Feedback, hältst es aus und setzt es um.</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Warum SalesViewer®</strong>?</p>\n<p>Du kommst in ein profitables, wachsendes Unternehmen mit einem<br>\nProdukt, das sich nachweislich verkauft – und startest Deine<br>\nVertriebslaufbahn dort, wo Du sie wirklich lernen kannst:</p>\n<ul>\n<li>Ein strukturierter Einstieg mit erfahrenen Kollegen an Deiner Seite – Du lernst am echten Geschäft, nicht in der Theorie.</li>\n<li>Echte Entwicklungsperspektive: Wer liefert, wächst bei uns in die volle Vertriebsverantwortung hinein.</li>\n<li>Ein Arbeitsplatz im Exzenterhaus, einem der markantesten Gebäude Bochums, mit moderner Ausstattung nach Deiner Wahl.</li>\n<li>Gezielte Investition in Deine Weiterentwicklung – fachlich wie finanziell.</li>\n<li>Zuschuss zum ÖPNV-Ticket sowie Zugang zu Corporate Benefits bei zahlreichen Marken.</li>\n<li>Eine Kultur, die auf Transparenz und Vertrauen baut – Erfolge werden gemeinsam erarbeitet und gemeinsam gefeiert.</li>\n</ul>\n<p><strong>Lust bekommen, mit uns den B2B-Vertrieb neu zu denken?</strong><br>\n<strong>Dann schick uns deine Bewerbung –</strong><br>\n<strong>wir freuen uns darauf, dich persönlich kennenzulernen!</strong></p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', 'new', NULL, '2026-07-08 13:41:56.693', '2026-07-08 13:41:56.693', '', '', '', 'Europe', '', 'Arbeitnow', 'API', 'READY', '', '', '', 'api', 'https://www.arbeitnow.com/jobs/companies/salesviewer-gmbh/junior-account-manager-b2b-bochum-444741', 'https://www.arbeitnow.com/jobs/companies/salesviewer-gmbh/junior-account-manager-b2b-bochum-444741', '[{\"url\":\"https://www.arbeitnow.com/jobs/companies/salesviewer-gmbh/junior-account-manager-b2b-bochum-444741\",\"type\":\"applyUrl\"}]', 'pending', '', NULL),
(2404, NULL, 'api', NULL, 'Junior Coach - 100% Remote/Vollzeit', 'Erschaffe dich neu', 'Berlin', 'https://www.arbeitnow.com/jobs/companies/erschaffe-dich-neu/junior-coach-100-remote-vollzeit-berlin-409523', '<h2>Jobbeschreibung</h2>\n<p>Wir suchen eine*n Junior Coach mit Vertriebsfokus, der oder die sich einem der größten B2C Coaching Unternehmen im deutschsprachigen Raum anschließen, Rekorde brechen, Leben verändern und mit einem starken Sales Team jeden Tag Höchstleistung abliefern will.</p>\n<h2>Das erwartet dich bei Erschaffe dich neu:</h2>\n<ul>\n<li><strong>Leistungsbezogene Vergütung:</strong> 60.000€+ OTE, ohne Cap.</li>\n<li>​<strong>Remote-Work:</strong> Jeder im Team arbeitet zu <strong>100% remote</strong></li>\n<li><strong>​Warme Leads:</strong> Wir arbeiten ausschließlich mit Inbound Leads (5.000+ pro Jahr zusätzlich 10.000 - 20.000 Produktkäufer pro Jahr, die als Leads reinkommen)</li>\n<li>​<strong>Dominant im Markt:</strong> EDN besteht seit 10 Jahren und besitzt mit über 100 Mio organischer Views, 500.000+ Abos eine der größten Reichweiten im Online Marketing im Dach-Raum</li>\n<li>​<strong>High Performance Team:</strong> Langjährige Mitarbeiter, bestehende Systeme, Jahr für Jahr Millionenumsätze - keine Eintagsfliege</li>\n<li>​<strong>Hohe Autonomie:</strong> Wir stellen dich ein, damit DU aktiv mit Lösungen findest.</li>\n</ul>\n<p><strong>Die Rolle</strong></p>\n<p>Als Junior Coach mit Vertriebsfokus bei Erschaffe dich neu bist du der erste Kontaktpunkt für unsere Leads – und damit einer der wichtigsten Hebel für unseren Umsatz. Du qualifizierst Leads, baust echtes Commitment auf und sorgst dafür, dass nur die richtigen Menschen in die Calls mit unseren Closern gehen. Deine Arbeit umfasst dabei mehr als nur Terminsetzen: Du arbeitest warme Bewerbungen ab, die sich aktiv auf unser Coaching-Programm beworben haben, followst Leads konsequent nach und überzeugst gleichzeitig Buch- und Produktkäufer davon, den nächsten Schritt ins Coaching zu gehen. Dazu kommen Bestandskunden, bei denen du Potenzial für Folgeprodukte und mögliche Upsells erkennst und aktiv begleitest.</p>\n<p><strong>Anstellungsart:</strong> Festanstellung</p>\n<p>Das Gehalt ist eine Kombination aus Fixum + Provision. Das Modell belohnt echte Leistung – ohne versteckte Deckelung.</p>\n<ul>\n<li><strong>Fixum:</strong> EUR 2.000 / Monat – immer, egal wie der Monat lief <strong>+ Provision</strong></li>\n</ul>\n<h2>Realistisches Verdienstpotenzial: EUR 3.500 – 5.500 in einem normalen Monat. In einem starken Monat bis EUR 7.000+.</h2>\n<p><strong>Arbeitsumfang:</strong> Min. 40 Std. wöchentlich Mo–Fr, Bereitschaft auch am Wochenende wenn notwendig <strong>100 % Remote.</strong></p>\n<p>Deine Arbeitszeiten kannst du dabei weitgehend frei einteilen – wir arbeiten mit einer monatlichen Kapazitätenplanung, die dir Struktur gibt ohne dich starr einzuschränken. Wichtig ist jedoch, dass du in den umsatzstärksten Zeitfenstern erreichbar und aktiv bist, insbesondere in den Abendstunden zwischen 17 und 20 Uhr, wenn die meisten Leads verfügbar sind.</p>\n<p><strong>Die Situation</strong></p>\n<p>Unser Jahresumsatz lag bei knapp 4.000.000 € in 2025 – während viele im Coaching-Markt gestruggelt haben. Unser Ziel für 2026: die 6.000.000 € Booked Revenue knacken.</p>\n<ul>\n<li>600+ High-Ticket-Kunden pro Jahr + Bestandskundenumsatz</li>\n<li>Tausende Leads + 10.000–20.000 Kunden über kleinere Produkte wie Bücher, Kurse und Challenges</li>\n<li>Kurze Sales Cycles, hochgradig emotionaler Verkauf</li>\n<li>Zielgruppe: 20–35-jährige, größtenteils Männer</li>\n<li>ADV bei 5.000 €, Tickets von 3.000 € bis 15.000 €</li>\n<li>Monatliche oder zweimonatliche Events mit 300–400 Live-Teilnehmern</li>\n<li>Als CRM nutzen wir Salesforce, dazu Zoom, Slack und WhatsApp und Aircall</li>\n</ul>\n<h2>Die Aufgaben eines Junior Coache mit Vertriebsfokus bei Erschaffe dich neu</h2>\n<p><strong>Lead-Qualifizierung &#x26; Terminbuchung</strong></p>\n<ul>\n<li>Eingehende Leads schnell, strukturiert und verbindlich qualifizieren</li>\n<li>Termine mit echtem Commitment buchen</li>\n<li>Show-Rate aktiv managen: Bestätigung, Vorbereitung, Vorqualifizierung</li>\n<li>Leads sauber im CRM pflegen und dokumentieren (Salesforce)</li>\n</ul>\n<h2>Kommunikation &#x26; Aufbau von Verbindlichkeit</h2>\n<ul>\n<li>Ersten Kontakt per Telefon (Aircall) oder WhatsApp</li>\n<li>Echtes Interesse wecken, Einwände früh adressieren, Commitment aufbauen</li>\n<li>Den Übergabeprozess an Closer sauber und vollständig gestalten</li>\n</ul>\n<h2>Performance &#x26; Qualität</h2>\n<ul>\n<li>Eigene KPIs im Blick behalten: Show-Rate, Termine und Cash Collected</li>\n<li>Aktiv an der eigenen Weiterentwicklung arbeiten – Call-Feedback annehmen und umsetzen</li>\n<li>Teil einer High-Performance-Kultur sein, die Ergebnisse ernst nimmt</li>\n<li>Pipeline Pflege</li>\n<li>Sauberes Follow-Up</li>\n</ul>\n<h2>Wer wir sind</h2>\n<p><strong>Erschaffe dich neu</strong> ist eine der wachstumsstärksten Coaching-Marken im DACH-Raum im Bereich persönliche Weiterentwicklung. Wir haben mit die größten organische Reichweite (über 500.000 Abos) auf Social Media im Bereich Persönlichkeitsentwicklung, 100.000.000+ organische Views, einen konstanten AD-Spent von 500.000€+ auf Meta pro Jahr mit deutlich positivem ROI und sind nun seit über 10 Jahren am Markt, mit zehntausenden Kunden und veränderten Menschenleben.</p>\n<p>Du trittst nicht irgendeiner Firma bei, du wirst Teil eines Teams, welches die Branche bereits seit einem Jahrzehnt prägt. Unsere Vision: <strong>Bis 2050 das größte Unternehmen für persönliche Weiterentwicklung weltweit.</strong></p>\n<p>Wir leben:</p>\n<ul>\n<li><strong>Value, Value, Value – We Care for Results</strong></li>\n<li><strong>Open Critique &#x26; Honesty</strong></li>\n<li><strong>Constant &#x26; Massive Growth</strong></li>\n<li><strong>Extreme Ownership – Everybody is a Leader</strong></li>\n<li><strong>Hard, Hard Work</strong></li>\n</ul>\n<h2>Stellenanforderungen</h2>\n<p>Pflicht</p>\n<ul>\n<li>Nachweisbare Erfahrung im telefonischen oder digitalen Erstkontakt mit Kunden – ob als SDR, Setter, im Vertriebsinnendienst oder vergleichbar</li>\n<li>Starke Kommunikation: Du weißt, wie man Menschen abholt, Vertrauen aufbaut und Verbindlichkeit erzeugt</li>\n<li>Strukturierte, eigenverantwortliche Arbeitsweise</li>\n<li>Erfahrung mit CRM-Systemen (idealerweise Salesforce)</li>\n<li>Coaching-, Fitness-, Finanz- oder Online-Business-Hintergrund von Vorteil</li>\n<li>Zahlenaffin und performance-getrieben</li>\n</ul>\n<h2>Was Erfolg in dieser Rolle bedeutet</h2>\n<ul>\n<li>Deine Show-Rate liegt konstant bei 80 %+ – und du weißt genau, welche Stellschrauben du dafür drehen musst</li>\n<li>Über dich werden monatlich mindestems 25+ Closes generiert</li>\n<li>Du wirst ein integraler Bestandteil des Teams und wir können uns voll auf dich verlassen, dass kein Lead liegen bleibt und jeder Termin zählt</li>\n</ul>\n<p><strong>Lust mit uns die Welt zu verändern? Bewirb dich jetzt und werde Teil des Erschaffe dich neu Teams.</strong></p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<h2>Jobbeschreibung</h2>\n<p>Wir suchen eine*n Junior Coach mit Vertriebsfokus, der oder die sich einem der größten B2C Coaching Unternehmen im deutschsprachigen Raum anschließen, Rekorde brechen, Leben verändern und mit einem starken Sales Team jeden Tag Höchstleistung abliefern will.</p>\n<h2>Das erwartet dich bei Erschaffe dich neu:</h2>\n<ul>\n<li><strong>Leistungsbezogene Vergütung:</strong> 60.000€+ OTE, ohne Cap.</li>\n<li>​<strong>Remote-Work:</strong> Jeder im Team arbeitet zu <strong>100% remote</strong></li>\n<li><strong>​Warme Leads:</strong> Wir arbeiten ausschließlich mit Inbound Leads (5.000+ pro Jahr zusätzlich 10.000 - 20.000 Produktkäufer pro Jahr, die als Leads reinkommen)</li>\n<li>​<strong>Dominant im Markt:</strong> EDN besteht seit 10 Jahren und besitzt mit über