INSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(2440, NULL, 'api', NULL, 'Auszubildender zum Steuerfachangestellten (m/w/d)', 'Kohnle & Partner', 'Karlsruhe', 'https://www.arbeitnow.com/jobs/companies/kohnle-partner/auszubildender-zum-steuerfachangestellten-karlsruhe-356230', '<p>Kohnle &#x26; Partner, die etwas andere Steuerkanzlei.</p>\n<p>Modernste Technik, digitale Prozesse, dynamisches Wachstum, führende Experten, hochwertige Büros, überdurchschnittliche Bezahlung, ein hoch motiviertes Team und vieles mehr – wir reden nicht nur von Top-Arbeitsbedingungen, wir schaffen diese auch.</p>\n<p>Die besten Arbeitsbedingungen und unser dynamisches Team sind seit über 50 Jahren die Grundlage für den Erfolg unserer Kanzlei. Inzwischen sind wir eine der führenden Kanzleien in der Region Baden und stehen Unternehmen sowie Privatpersonen als kompetenter Partner, leidenschaftliche Problemlöser und innovative Zukunftsdenker zur Seite.</p>\n<p>Werde jetzt ein Teil unseres Teams an einem unserer Standorte in Karlsruhe, Weingarten, Offenburg oder Karlsbad.</p>\n<h2>Aufgaben</h2>\n<p>Als Steuerfachangestellter kannst du deutlich mehr, als nur mit Zahlen zu<br>\njonglieren. Im Zuge deiner Ausbildung unterstützen wir dich dabei, persönlich als auch fachlich den nächsten Schritt zu gehen, um unseren Mandanten künftig in steuerlichen und betriebswirtschaftlichen Themen vollumfänglich und kompetent zur Seite zu stehen.</p>\n<ul>\n<li>Erstellung von kleinen Steuererklärungen und abwechslungsreichen Finanzbuchhaltungen</li>\n<li>Vorbereitung und Unterstützung bei der Erstellung von Jahresabschlüssen</li>\n<li>Prüfung von Steuerbescheiden und Korrespondenz mit dem Finanzamt</li>\n<li>Durchführung von Recherchetätigkeiten</li>\n<li>Unterstützung bei der digitalen Transformation</li>\n<li>Weitere Themenbereiche, die dir Spaß bereiten und in denen du deine Stärken hast</li>\n</ul>\n<h2>Qualifikation</h2>\n<ul>\n<li>Du bist kommunikativ und arbeitest gerne mit Menschen</li>\n<li>Worten lässt du gerne Taten folgen</li>\n<li>Offenheit gegenüber Neuem und Veränderungen</li>\n<li>Du hast hohe Ansprüche an die Qualität deiner Arbeit</li>\n</ul>\n<p><strong>Wünschenswert wäre:</strong></p>\n<ul>\n<li>Fachhochschulreife / allgemeine Hochschulreife oder Realschulabschluss mit guten Noten</li>\n<li>Erste Erfahrung mit MS-Office Anwendungen, insbesondere Word und Excel</li>\n</ul>\n<h2>Benefits</h2>\n<p><strong>Warum Kohnle &#x26; Partner</strong></p>\n<p>Diese Frage haben wir auch unseren Mitarbeitern gestellt. In unserer jährlichen Mitarbeiterbefragung kam heraus, dass unsere Teammitglieder uns als Arbeitgeber nahezu ausnahmslos an Freunde und Bekannte weiterempfehlen würden und somit wirklich gerne bei uns arbeiten.</p>\n<p>Weitere Ergebnisse unserer Umfrage zeigen wir dir gerne in einem ersten persönlichen Kennenlerngespräch.</p>\n<p>Darüber hinaus kannst du dich bei uns auf die folgenden Benefits freuen:</p>\n<ul>\n<li>Überdurchschnittliche Bezahlung</li>\n<li>Zahlreiche Events (Sommerfest, Betriebsausflüge, Weihnachtsfeier und mehr)</li>\n<li>Flexible Arbeitszeiten</li>\n<li>Sorgfältige Einarbeitung</li>\n<li>Fortbildungsflatrate</li>\n<li>Kanzlei-eigenes Fitnessstudio oder Mitgliedschaft in<br>\neinem Studio (je nach Standort)</li>\n<li>Modernste Technik und digitale Prozesse</li>\n<li>Gesundheitsbenefits</li>\n<li>Hochwertige Büros &#x26; Einrichtung</li>\n<li>Eigene Parkplätze (je nach Standort)</li>\n<li>Klimatisierte Räumlichkeiten</li>\n<li>Social Areas (auch im Außenbereich)</li>\n</ul>\n<p>Wir freuen uns auf dich und deine Bewerbung!</p>\n<p>Find more <a href=\"https://www.arbeitnow.com/english-speaking-jobs\">English Speaking Jobs in Germany</a> on Arbeitnow</a>', '<p>Kohnle &#x26; Partner, die etwas andere Steuerkanzlei.</p>\n<p>Modernste Technik, digitale Prozesse, dynamisches Wachstum, führende Experten, hochwertige Büros, überdurchschnittliche Bezahlung, ein hoch motiviertes Team und vieles mehr – wir reden nicht nur von Top-Arbeitsbedingungen, wir schaffen diese auch.</p>\n<p>Die besten Ar