(2458, NULL, 'api', NULL, 'Compliance Market Surveillance Analyst', 'Crypto.com', 'Ø¯Ø¨Ù, Ø¯Ø¨Ù Ø¯Ø¨Ù Ø§ÙØ¥ÙINSERT INTO `job_posts` (`id`, `sourceId`, `sourceType`, `externalId`, `title`, `company`, `location`, `sourceUrl`, `description`, `rawContent`, `status`, `receivedAt`, `createdAt`, `updatedAt`, `emailSubject`, `jobType`, `workMode`, `region`, `experienceLevel`, `sourceName`, `importMethod`, `descriptionStatus`, `searchKeywordMatched`, `sourceEmail`, `sourceSubject`, `sourcePlatform`, `applyUrl`, `companyUrl`, `extractedUrls`, `contactDiscoveryStatus`, `contactDiscoveryError`, `lastContactDiscoveryAt`) VALUES
(2459, NULL, 'api', NULL, 'Human Resources Administrative Coordinator', 'Enstar Group', 'Florida, Florida, United States', 'https://remoteOK.com/remote-jobs/remote-human-resources-administrative-coordinator-enstar-group-1134583', '<p><strong>About you and the role:</strong></p><p>As part of the HR Shared Services Team, the HR Services Coordinator will deliver first-line support and day to day activities for the HR Team. The individual will respond to employee enquiries and leadership requests.</p><p><br></p><p><strong>What you will be doing: </strong></p><ul><li>Provide administrative support to the (US)</li><li>Maintain accurate and current electronic personnel files and documentation in compliance with applicable legal requirements and Company policies as well as country-specific legislation</li><li>Partner with the HR Business Partners and HR Centres of Expertise to support the delivery of HR Target Operating Model</li><li>Assist with onboarding by preparing contracts/offer letters, new joiner documentation, background screening and country-specific processes</li><li>Coordinate and deliver new hire orientation/onboarding activities</li><li>Assist with assigning and follow-up of mandatory training through Enstarâs Learning Management System</li><li>Provide first-line support and escalation for HR systems</li><li>Process changes to employee records within Enstarâs HRIS including new joiners, job changes and leavers</li><li>Prepare employee changes and termination paperwork, notifications and change forms</li><li>Answer frequently asked questions from employees concerning HR processes</li><li>Support inquiries and requests related to the HR department</li><li>Continuously remain up to date on global HR practices</li><li>Assist with HR projects as necessary, including but not limited to HR data audits, new policy and program development</li><li>All other duties as required</li></ul><p><strong> </strong></p><p><strong>What you will bring:</strong></p><ul><li>Self-directed individual with initiative, analytical and problem-solving skills</li><li>Customer focus, collaboration and teamwork. Key to this Competency is the ability to listen, prioritize and deliver accurate and speedy results.</li><li>Ability to exercise practical judgment, sensitivity, creativity to changing needs and situations</li><li>Ability to operate in a fast-paced organization and handle multiple projects simultaneously</li><li>Ability to work as part of a wider team and independently</li><li>Strong Microsoft Office skills in Outlook, Word, PowerPoint, and Excel</li><li>Experience using HR &amp; Payroll platforms</li><li>Initial experience gained within a HR department</li><li>Providing system support to users</li><li>Involvement in system development or enhancement</li><li>Proven ability in creating management information for the business</li><li>Strong organizational skills that reflect ability to perform and prioritize multiple tasks and a complex workload seamlessly with keen attention to detail and follow-up</li><li>Experience working in a fast-paced environment and ability to apply good work habits to effectively complete assigned tasks and contribute to the smooth operation of the department</li><li>Ability to work effectively in a team environment and to collaborate/work remotely with colleagues</li><li>Excellent verbal and written communication skills<strong> </strong></li></ul><p><strong> </strong></p><p><strong> Your Benefits: </strong></p><ul><li>Enstar offers best-in-class Medical, Dental, and Vision healthcare for single and family coverage.</li><li>Board-certified doctors and pediatricians are available virtually 24/7 for urgent care.</li><li>Access to Health Savings Account (HSA) or Flexible Spending Account (FSA).</li><li>Access to Dependent Care FSA to cover daycare expenses.</li><li>Access to Employee Assistance Programs (EAP) for health and well-being.</li><li>Optional Pet &amp; Home/Auto Insurance.</li><li>Wellness Reimbursement program (up to $600 annual reimbursement for wellness-related expenses, i.e., gym memberships, massage, etc.).</li><li>401K retirement plan (company matches up to 6% of employee contribution).</li><li>One paid annual volunteer day.</li></ul><p><strong> </strong></p><p><br></p><p><strong>General Info</strong></p><p>The target base salary pay range for this role is $70,000-$75,000*</p><p>*Target full-time equivalent base salary range is based on relevant market data. The actual salary offered will depend on applicable market data for hiring location and relevant candidate knowledge, skills/experience. This salary range is not inclusive of applicable discretionary incentives.</p><p><br></p><p><br></p><p><strong>Who we are:</strong></p><p>We are a trusted global re/insurance group and the leading provider of retrospective solutions, with specialist underwriting capabilities. We help our clients manage risk, unlock capital and create the financial freedom to grow. With operations across the worldâs major insurance hubs and a global network of close to 800 talented professionals, we bring expertise and fresh thinking to some of the industryâs biggest challenges.</p><p>For more information about Enstar, visit our website: <u>www.enstargroup.com</u>.</p><p>For more information about careers at Enstar, visit our LinkedIn Life page or visit our <u>careers site</u></p><p><br></p><p><br></p><p><strong>Why Enstar:</strong></p><p>Learning and development are a fundamental part of every employee\'s career journey with Enstar. Supporting growth and career progression is key to how we engage our people - helping them to learn, grow and succeed at Enstar.</p><p>We offer a range of initiatives and resources to support our people throughout their careers:</p><ul><li><strong>Professional Qualifications and Study Support: </strong>We support employees who wish to take professional qualifications aligned to their role and career development.</li><li><strong>Training, Conferences &amp; Seminars: </strong>As a global organisation, we work with many professional bodies to provide access to training programmes, conferences, seminars and continuing professional development (CPD) opportunities.</li><li><strong>Digital Learning Hub: </strong>Our digital learning hub, LinkedIn Learning, offers a wide range of self-serve resources, including courses, videos, eBooks, and audio books, to help employees build news skills and deepen their knowledge.</li></ul><p>We also invest in physical, mental and financial wellbeing initiatives for our employees. Supportive teams, inspiring work and a positive working environment all contribute to our collective wellbeing. Beyond the workplace, we strive to make a positive influence in our communities and to continuously reduce our impact on the environment.</p><p><strong> </strong></p><p><br></p><p><strong>Enstar Inclusivity Policy:</strong></p><p>Weâre an equal opportunity employer and believe that our inclusive environment creates an authentic working culture. We donât discriminate on the basis of age, physical or mental disability, gender reassignment, marriage and civil partnership, pregnancy and carer status, race (including colour, nationality, and ethnic or national origin), religion or belief, sex and sexual orientation. Enstar is committed in providing an accessible recruitment experience for all those interested in working with us. Please let your Enstar Recruitment Partner know if you require any reasonable accommodation during the application process due to a disability to enable you to fully participate in our recruitment process.</p><p><br></p><br/><br/>Please mention the word **UNFETTERED** and tag RMTU5LjE5OC42Ni4xNjM= when applying to show you read the job post completely (#RMTU5LjE5OC42Ni4xNjM=). This is a beta feature to avoid spam applicants. Companies can search these words to find applicants that read this and see they\'re human.', '<p><strong>About you and the role:</strong></p><p>As part of the HR Sh