INSERT INTO `Testimonial` (`id`, `name`, `content`, `image`, `company`, `position`, `stars`, `status`, `sortOrder`, `createdAt`, `updatedAt`) VALUES
(1, 'Ariana Blake', '<p>Shahanur delivered a clean, professional portfolio and business website that looked modern, loaded fast, and felt easy to manage. The planning was clear, the communication was direct, and every section was shaped around real business goals instead of just design decoration.</p>', '/uploads/1777278014286-1693308354244.jfif', 'NovaEdge Creative', 'Founder', 5, 1, 1, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(2, 'Michael Reed', '<p>The work stood out because it combined design sense with strong technical execution. Our pages became more responsive, the layout felt more premium, and the final delivery gave us confidence to present the brand professionally online.</p>', '/uploads/1777278088845-1710185562467.jfif', 'PixelCraft Agency', 'Creative Director', 5, 1, 2, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(3, 'Elena Petrova', '<p>He understood the requirements quickly and turned them into a practical web solution. The interface was clean, the user flow was simple, and the backend structure was prepared in a way that made future updates easier for our team.</p>', '/uploads/1777278127257-1745839669049.jfif', 'DataNest Solutions', 'Operations Manager', 5, 1, 3, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(4, 'James Wilson', '<p>From the first discussion to the final launch, the process felt structured and reliable. The final website had strong visual balance, better performance, and a professional finish that matched our expectations.</p>', '/uploads/1777278159941-1517442186760.jfif', 'CloudPeak Systems', 'CTO', 5, 1, 4, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(5, 'Nadia Rahman', '<p>Shahanur helped us improve our online store experience with a cleaner layout, better product presentation, and smoother navigation. The result felt more trustworthy for customers and easier for the business team to maintain.</p>', '/uploads/1777278188144-1712940482596.jfif', 'UrbanCart BD', 'E-commerce Manager', 5, 1, 5, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(6, 'Oliver Bennett', '<p>What impressed us most was the attention to detail. Small UI issues, mobile spacing, page speed, and admin usability were handled carefully, which made the final product feel polished rather than rushed.</p>', '/uploads/1777278216163-1516682049544.jfif', 'BrightFlow Digital', 'Product Strategist', 5, 1, 6, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(7, 'Priya Sharma', '<p>The project required both frontend design and backend thinking, and he handled both sides with confidence. The website became faster, more organized, and much easier for users to understand.</p>', '/uploads/1777278240692-1651764483886.jfif', 'GreenLeaf Commerce', 'Business Owner', 5, 1, 7, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(8, 'Lucas Morgan', '<p>We needed a developer who could listen, plan, and execute without overcomplicating the project. Shahanur delivered exactly that, with a modern interface and clean technical foundation.</p>', '/uploads/1777278262465-1614246790014.jfif', 'SwiftDesk SaaS', 'Product Manager', 5, 1, 8, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(9, 'Sofia Martinez', '<p>The final design gave our brand a more premium digital presence. Sections were arranged properly, animations were smooth, and the site worked well across desktop, tablet, and mobile.</p>', '/uploads/1777278286763-1684539334687.jfif', 'BlueOrbit Studio', 'Brand Consultant', 5, 1, 9, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(10, 'Ethan Brooks', '<p>He brought a practical mindset to the project. Instead of only focusing on visuals, he improved structure, usability, performance, and long-term maintainability.</p>', '/uploads/1777278312846-1656780260176.jfif', 'MarketPilot', 'Growth Lead', 5, 1, 10, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(11, 'Maya Thompson', '<p>Shahanur created a user experience that felt clear and professional. The design choices were modern, but still simple enough for visitors to navigate without confusion.</p>', '/uploads/1777278335832-1743709275541.jfif', 'VisionGrid Labs', 'UX Lead', 4, 1, 11, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(12, 'Noah Williams', '<p>The development quality was strong. Code structure, responsiveness, and deployment support were all handled properly, which made the launch smoother than expected.</p>', '/uploads/1777278364694-1526067015613.jfif', 'CoreStack IT', 'Technical Manager', 5, 1, 12, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(13, 'Liam Anderson', '<p>Our e-commerce pages became much easier to use after the redesign. Product cards, campaign sections, and customer flow were improved with a clear understanding of online shopping behavior.</p>', '/uploads/1777278393374-1697052541671.jfif', 'ShopRiver', 'Founder', 5, 1, 13, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(14, 'Emma Collins', '<p>The collaboration was smooth and honest. He explained technical points clearly, suggested better options when needed, and delivered a result that looked professional.</p>', '/uploads/1777278440458-1636844497511.jfif', 'Northline Media', 'Managing Director', 5, 1, 14, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(15, 'Daniel Evans', '<p>The portfolio section he designed helped us present achievements, services, and project work in a much stronger way. It looked modern without feeling overloaded.</p>', '/uploads/1777278470646-1715293524891.jfif', 'FinServe Pro', 'Business Analyst', 5, 1, 15, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(16, 'Grace Turner', '<p>Shahanur handled both design polish and technical debugging with patience. Problems that were slowing down the site were identified and fixed carefully.</p>', '/uploads/1777278496688-1666369477057.jfif', 'EduCore Academy', 'Program Coordinator', 5, 1, 16, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(17, 'Benjamin Scott', '<p>He delivered a clean website structure that works well for content, services, pricing, testimonials, and project showcases. Everything felt connected and easy to manage.</p>', '/uploads/1777278534836-1638806827963.jfif', 'AutoLink IoT', 'Project Lead', 5, 1, 17, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(18, 'Isabella Moore', '<p>The final result was more than a simple website. It became a complete online presentation system for our brand, with strong attention to responsive behavior and content clarity.</p>', '/uploads/1777278559534-1569659929879.jfif', 'HealthBridge Clinic', 'Admin Manager', 5, 1, 18, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(19, 'Henry Adams', '<p>He has a good eye for modern UI design and also understands the practical side of implementation. That balance made the final product useful and visually strong.</p>', '/uploads/1777278584049-1670297234028.jfif', 'CyberTrail Systems', 'Security Consultant', 5, 1, 19, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(20, 'Chloe Walker', '<p>We appreciated the way he translated vague ideas into clear sections, pages, and components. The finished site felt organized, professional, and ready for real users.</p>', '/uploads/1777278608266-1750772601732.jfif', 'DesignMint Studio', 'Art Director', 5, 1, 20, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(21, 'Samuel King', '<p>The project was completed with strong communication and a clear development process. Every major update improved the product in a visible and practical way.</p>', '/uploads/1777278630990-1738181559170.jfif', 'LaunchMate', 'Startup Founder', 5, 1, 21, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(22, 'Ava Lewis', '<p>Shahanur improved the layout, spacing, colors, and responsiveness of our interface. The website now feels more premium and easier to trust.</p>', '/uploads/1777278656754-1733744660936.jfif', 'TrendHive Commerce', 'Store Owner', 4, 1, 22, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(23, 'David Harris', '<p>He created a solution that matched our business needs instead of forcing a generic template. The result was clean, scalable, and easy to present to clients.</p>', '/uploads/1777278678365-1636037811482.jfif', 'SecureNode Labs', 'Engineering Lead', 5, 1, 23, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(24, 'Mila Carter', '<p>The work quality was consistent from start to finish. He paid attention to frontend details, backend logic, and deployment concerns, which helped the project move forward smoothly.</p>', '/uploads/1777278719005-1772552139711.jfif', 'QuickServe Apps', 'Operations Lead', 5, 1, 24, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(25, 'Leo Phillips', '<p>Our team needed a reliable developer for a fast launch, and Shahanur delivered with focus. The website looked professional and worked properly on different screen sizes.</p>', '/uploads/1777278745232-1765333312028.jfif', 'CodeHarbor', 'Software Architect', 5, 1, 25, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(26, 'Zara Ahmed', '<p>He made the technical process easier for non-technical team members. Explanations were simple, progress was clear, and the final handoff was easy to understand.</p>', '/uploads/1777278768842-1552054667971.jfif', 'DhakaStyle Mart', 'E-commerce Founder', 5, 1, 26, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(27, 'Ryan Cooper', '<p>The design felt modern, but what really mattered was how usable it became. Visitors could understand our services faster and move through the site more naturally.</p>', '/uploads/1777278791832-1741792998571.jfif', 'NextWave Digital', 'CEO', 5, 1, 27, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(28, 'Fatima Khan', '<p>Shahanur built a polished web experience with strong layout decisions, smooth interactions, and clean content structure. It gave our business a stronger digital identity.</p>', '/uploads/1777278816781-1690393940000.jfif', 'SkillPath Learning', 'Training Manager', 5, 1, 28, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(29, 'Arthur Wright', '<p>He handled changes professionally and improved the final outcome with practical suggestions. The site became cleaner, faster, and more focused.</p>', '/uploads/1777278836971-images.jfif', 'DroneVista Tech', 'Research Coordinator', 5, 1, 29, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(30, 'Emily Parker', '<p>The project required careful content placement and visual hierarchy. Shahanur arranged everything in a way that made the website look professional and easy to read.</p>', '/uploads/1777278856610-1694646235971.jfif', 'ContentHouse Media', 'Content Manager', 5, 1, 30, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(31, 'Zara Hassan', '<p>Working with him saved us time because he understood both design and development. The final result did not need endless corrections to become usable.</p>', '/uploads/1777278886306-1602706030879.jfif', 'PayLink Systems', 'Product Owner', 5, 1, 31, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(32, 'Victoria Hughes', '<p>He helped us turn a basic idea into a complete digital product presentation. The service pages, pricing section, and testimonial layout all became stronger.</p>', '/uploads/1777278921022-1758911618104.jfif', 'FrameWorks Studio', 'Design Manager', 5, 1, 32, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(33, 'Owen Kelly', '<p>The final delivery showed care, patience, and technical skill. The website is responsive, clean, and properly structured for future growth.</p>', '/uploads/1777278947892-1517484503537.jfif', 'LogiTrack Solutions', 'Logistics Lead', 4, 1, 33, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(34, 'Lara Hoffmann', '<p>Shahanur\'s work helped us improve trust with visitors. The design looked credible, the page flow was clearer, and the site felt more complete.</p>', '/uploads/1777278967205-1542356642616.jfif', 'Berlin Web Lab', 'Founder', 5, 1, 34, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(35, 'Chris Nelson', '<p>He was able to work through hosting, performance, and UI challenges without losing focus on the user experience. That made the project successful.</p>', '/uploads/1777278989596-1661462598000.jfif', 'BizPortal Group', 'Business Consultant', 5, 1, 35, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(36, 'Ayesha Siddika', '<p>The final website felt custom, not generic. It reflected our business goals and gave us a stronger way to explain our services online.</p>', '/uploads/1777279018795-1703134258197.jfif', 'SmartBuy Online', 'Marketplace Manager', 5, 1, 36, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(37, 'Thomas Clark', '<p>He created a professional layout that worked well with real content. The result was not only attractive but also practical for daily business use.</p>', '/uploads/1777279073262-1716436966201.jfif', 'BrightWare', 'Founder', 5, 1, 37, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(38, 'Julia Fischer', '<p>Shahanur delivered an excellent balance of clean visuals, responsive design, and working functionality. The process was smooth and the outcome was reliable.</p>', '/uploads/1777279093800-1715419577291.jfif', 'CloudRoom Hosting', 'Client Success Lead', 5, 1, 38, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(39, 'Nathan Young', '<p>His approach to problem-solving was clear and calm. Technical issues were handled step by step, and the final launch became much easier.</p>', '/uploads/1777279119049-1706185644764.jfif', 'AppBridge Mobile', 'Mobile Product Lead', 5, 1, 39, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(40, 'Olivia Hall', '<p>The website now presents our work with stronger credibility. The sections are clean, the spacing is better, and the overall experience feels more professional.</p>', '/uploads/1777279142650-1720734894526.jfif', 'TrustCore Security', 'Compliance Manager', 5, 1, 40, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(41, 'Aaron Mitchell', '<p>He improved the user interface in a way that made the product easier to understand. The design became more polished without making the site heavy.</p>', '/uploads/1777279165540-1743554418017.jfif', 'VisionAid Research', 'Project Coordinator', 5, 1, 41, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(42, 'Sophia Green', '<p>The collaboration was productive because he asked the right questions and focused on the real purpose of each section. The final result matched the direction we wanted.</p>', '/uploads/1777279190893-1725903520603.jfif', 'RetailPoint', 'Sales Director', 5, 1, 42, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(43, 'Ibrahim Hasan', '<p>Shahanur helped us build a web presence that feels modern and serious. It is easy to navigate, easy to read, and ready for business use.</p>', '/uploads/1777279212928-1604385939138.jfif', 'MetroCart BD', 'Operations Manager', 5, 1, 43, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(44, 'Rachel Wood', '<p>He turned our requirements into a clean technical solution with good attention to responsive design and admin-friendly structure.</p>', '/uploads/1777279239246-1770345647436.jfif', 'Studio Atlas', 'Creative Producer', 4, 1, 44, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(45, 'Kevin Roberts', '<p>The site performance and visual presentation both improved. Pages opened faster, content looked better organized, and the mobile experience became much smoother.</p>', '/uploads/1777279263583-images-1.jfif', 'FastLaunch Co.', 'Founder', 5, 1, 45, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(46, 'Nora Becker', '<p>We needed a developer who could work across design, code, and deployment. Shahanur handled the full process with professionalism.</p>', '/uploads/1777279291181-1723229578666.jfif', 'TechNova Europe', 'Product Director', 5, 1, 46, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(47, 'Ali Reza', '<p>The final product was clear, functional, and visually strong. It helped us communicate our value more effectively to customers.</p>', '/uploads/1777279316822-1665987384037.jfif', 'CourierLink', 'Logistics Supervisor', 5, 1, 47, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(48, 'Lily Robinson', '<p>He delivered a website that feels polished and stable. The design details, content layout, and technical setup all came together nicely.</p>', '/uploads/1777279337791-1757248062208.jfif', 'GlowBrand Studio', 'Marketing Lead', 5, 1, 48, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(49, 'George Miller', '<p>Shahanur understands how to make a portfolio or business website feel premium. The final design gave our brand a stronger first impression.</p>', '/uploads/1777279367829-1730463494106.jfif', 'EduSoft Platform', 'Academic Director', 5, 1, 49, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(50, 'Meera Das', '<p>The work was completed with care and consistency. The final website is responsive, easy to use, and built with a practical long-term structure.</p>', '/uploads/1777279398515-1666037758693.jfif', 'StyleHub Market', 'Founder', 5, 1, 50, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(51, 'Patrick Allen', '<p>He improved the presentation of our services and case studies with better hierarchy and clean visual design. The result felt more trustworthy.</p>', '/uploads/1777279430286-1543330242703.jfif', 'SecureGrid IT', 'Infrastructure Manager', 5, 1, 51, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(52, 'Hannah White', '<p>The development process was reliable, and the final handoff was clear. We could easily understand how to manage the content after delivery.</p>', '/uploads/1777279459765-1724086624860.jfif', 'FlowCRM', 'Customer Success Manager', 5, 1, 52, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(53, 'Jason Brown', '<p>Shahanur brought strong technical thinking to the project. The site was not only designed well, but also prepared for performance, scalability, and future updates.</p>', '/uploads/1777279562296-1709615851191.jfif', 'WebScale Partners', 'Managing Partner', 5, 1, 53, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(54, 'Diana Ross', '<p>The final result helped us look more professional online. It gave our brand a clean identity and made our services easier for clients to understand.</p>', '/uploads/1777279586806-1683208212278.jfif', 'InsightLab Analytics', 'Data Lead', 5, 1, 54, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(55, 'Israt Islam Lamia', '<p>He delivered exactly what we needed: a clean, responsive, professional website with strong attention to real business use.</p>', '/uploads/1777279638553-1666824917952.jfif', 'LocalShop BD', 'Owner', 4, 1, 55, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(56, 'Prasen', '<p>An exceptionally talented person with remarkable skills and clarity. Even a simple conversation with him brings great insight and understanding. If he delivers a product, you can be assured that the project will be excellent and executed flawlessly.</p>', '/DefaultUser.png', 'Startup', 'Ceo', 5, 1, 56, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(57, 'Ryhan Kabir', '<p>I had a highly positive experience working with Shagor Md. Shahanur Islam. He combines strong technical expertise with clear, professional communication and a client-first mindset. From project kickoff through delivery, Shagor demonstrated thoughtful problem-solving, attention to detail, and reliable follow-through, consistently meeting deadlines and producing polished results. He explains complex ideas in an accessible way, welcomes feedback, and iterates until the outcome aligns with goals. His professionalism, organization, and collaborative approach make him an excellent choice for projects that demand technical skill, creativity, and dependable execution. For additional testimonials, see his reviews page.</p>', '/uploads/1777464239275-img-20260219-212546-073.webp', 'Freelancer', 'Cyber Security Specialist with Kali Linux', 5, 1, 57, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(58, 'Austin', '<p>This man is extremely helpful and always willing to support the team. Their work is consistently excellent, showing attention to detail and a commitment to high-quality results. They make a positive impact on every project they touch.</p>', '/DefaultUser.png', 'Rainband_media', 'Graphic design', 5, 1, 58, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664'),
(59, 'MH Tushar', '<p>I have gained valuable experience through my academic and practical work, which has helped me develop both technical and problem-solving skills.</p>', '/DefaultUser.png', 'As student', 'Lerner', 5, 1, 59, '2026-04-30 13:32:36.664', '2026-04-30 13:32:36.664');
